import SpotTradingLayout from '@/pages/spot-trading/components/SpotTradingLayout';
import {
  dailyBillCompanyOptions,
  dailyBillMonths,
  dailyBillDates,
  dateTagMap,
  dailyBillMainTableData,
  type MainTableRow,
  forecastClearPriceData,
  spotPriceCurveData,
  contractPriceCurveData,
} from '@/mocks/dailyBillMainData';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
} from 'recharts';
import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';

const COLORS = {
  forecast: '#165DFF',
  dayAheadClear: '#FAAD14',
  realTimeClear: '#34D399',
  dayAheadAvg: '#165DFF',
  realTimeAvg: '#F53F3F',
  yearClear: '#165DFF',
  monthClear: '#FAAD14',
  matchClear: '#A78BFA',
  dayAheadClearContract: '#34D399',
  realTimeClearContract: '#F53F3F',
  contractAvg: '#EE6666',
  interProvAvg: '#5470C6',
};

export default function DailyBillPage() {
  const navigate = useNavigate();
  const [company, setCompany] = useState('hz');
  const [month, setMonth] = useState('2026-05');
  const [expandedGroups, setExpandedGroups] = useState<Record<string, boolean>>({
    交易电量: true,
    日前市场: true,
    实时市场: true,
    '实时市场结算均价': true,
    年度合约: true,
    月度合约: true,
    事合约: true,
    滚搓交易: true,
    省间绿电: true,
    省内绿电: true,
    合约汇总: true,
    结算电费合计: true,
  });

  const groupedData = useMemo(() => {
    const map = new Map<string, MainTableRow[]>();
    dailyBillMainTableData.forEach((row) => {
      if (!map.has(row.settlementType)) map.set(row.settlementType, []);
      map.get(row.settlementType)!.push(row);
    });
    return map;
  }, []);

  const toggleGroup = (group: string) => {
    setExpandedGroups((prev) => ({ ...prev, [group]: !prev[group] }));
  };

  const formatNum = (v: number) => {
    if (v === 0) return '—';
    if (Math.abs(v) >= 1000) return v.toLocaleString('en-US', { maximumFractionDigits: 2 });
    return v.toFixed(v % 1 === 0 ? 0 : 3);
  };

  const isNegative = (v: number) => v < 0;

  const handleDateClick = (date: string) => {
    navigate(`/spot-trading/analysis/daily-bill/detail?date=${date}`);
  };

  // Custom legend state for charts
  const [chart1Legend, setChart1Legend] = useState<Record<string, boolean>>({ 预计消分电价: true });
  const [chart2Legend, setChart2Legend] = useState<Record<string, boolean>>({
    日前结算电价: true, 实时结算电价: true, 现货市场结算均价: true,
  });
  const [chart3Legend, setChart3Legend] = useState<Record<string, boolean>>({
    年度结算电价: true, 月度结算电价: true, 即结算电价: true,
    即前结算电价: true, 实时结算电价: true, 合约结算均价: true, 省间绿电价: true,
  });

  return (
    <SpotTradingLayout>
      <div className="space-y-4">
        {/* 查询控制栏 */}
        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-3">
            <div className="flex flex-wrap items-center gap-3">
              {/* 售电公司 */}
              <div className="flex items-center gap-2">
                <label className="text-xs text-[#86909C]">售电公司：</label>
                <select
                  value={company}
                  onChange={(e) => setCompany(e.target.value)}
                  className="text-xs border border-[#E5E6EB] rounded px-2 py-1.5 bg-white text-[#1D2129] outline-none cursor-pointer"
                >
                  {dailyBillCompanyOptions.map((opt) => (
                    <option key={opt.value} value={opt.value}>{opt.label}</option>
                  ))}
                </select>
              </div>
              {/* 查询时间 */}
              <div className="flex items-center gap-2">
                <label className="text-xs text-[#86909C]">查询时间：</label>
                <input
                  type="month"
                  value={month}
                  onChange={(e) => setMonth(e.target.value)}
                  className="text-xs border border-[#E5E6EB] rounded px-2 py-1.5 bg-white text-[#1D2129] outline-none"
                />
              </div>
              {/* 图例说明 */}
              <div className="flex items-center gap-2 ml-2">
                <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] text-[#F53F3F] bg-[#FFE4E4]">法定节假日</span>
                <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] text-[#165DFF] bg-[#E8F0FF]">周六</span>
                <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] text-[#FAAD14] bg-[#FFF7E6]">周日</span>
                <span className="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] text-[#34D399] bg-[#E6FFF0]">调休放假</span>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-xs text-[#86909C]">计量单位：MWh，元/MWh，元</span>
              <button className="flex items-center gap-1 px-3 py-1.5 rounded bg-[#165DFF] text-white text-xs hover:bg-[#1450E0] transition-colors cursor-pointer whitespace-nowrap">
                <i className="ri-download-line" />
                导出
              </button>
            </div>
          </div>
        </div>

        {/* 日账单数据大表格 */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-[11px] border-collapse">
              <thead>
                <tr className="bg-[#F7F8FA]">
                  <th className="text-left py-2 px-2 font-medium text-[#86909C] border-b border-[#E5E6EB] sticky left-0 bg-[#F7F8FA] z-10 w-24">结算类型</th>
                  <th className="text-left py-2 px-2 font-medium text-[#86909C] border-b border-[#E5E6EB] sticky left-24 bg-[#F7F8FA] z-10 w-20">结算指标</th>
                  <th className="text-right py-2 px-2 font-medium text-[#86909C] border-b border-[#E5E6EB] w-20">合计</th>
                  {dailyBillDates.map((d) => {
                    const tag = dateTagMap[d];
                    return (
                      <th
                        key={d}
                        className="text-right py-2 px-1 font-medium border-b border-[#E5E6EB] min-w-[72px] cursor-pointer hover:bg-[#F2F3F5] transition-colors"
                        onClick={() => handleDateClick(d)}
                      >
                        <div className="flex flex-col items-end">
                          <span className={tag ? `text-[${tag.color}]` : 'text-[#1D2129]'}>{d.slice(5)}</span>
                          {tag && (
                            <span
                              className="text-[9px] px-1 rounded mt-0.5"
                              style={{ color: tag.color, backgroundColor: tag.bg }}
                            >
                              {tag.type}
                            </span>
                          )}
                        </div>
                      </th>
                    );
                  })}
                </tr>
              </thead>
              <tbody>
                {Array.from(groupedData.entries()).map(([groupName, rows], gIdx) => {
                  const isExpanded = expandedGroups[groupName] ?? true;
                  return (
                    <>
                      {/* 分组标题行 */}
                      <tr key={`group-${groupName}`} className="bg-[#F2F3F5]/50">
                        <td
                          colSpan={3 + dailyBillDates.length}
                          className="py-1.5 px-2 text-[11px] font-medium text-[#1D2129] border-b border-[#E5E6EB]/50 cursor-pointer select-none flex items-center gap-1"
                          onClick={() => toggleGroup(groupName)}
                        >
                          <span className="inline-flex items-center justify-center w-3.5 h-3.5 text-[10px] text-[#86909C]">
                            <i className={isExpanded ? 'ri-arrow-down-s-line' : 'ri-arrow-right-s-line'} />
                          </span>
                          {groupName}
                        </td>
                      </tr>
                      {/* 分组数据行 */}
                      {isExpanded && rows.map((row, rIdx) => (
                        <tr
                          key={`${groupName}-${row.indicator}-${rIdx}`}
                          className={`${rIdx % 2 === 0 ? 'bg-white' : 'bg-[#FAFBFC]'} hover:bg-[#F2F3F5]/60`}
                        >
                          <td className="py-1.5 px-2 text-[#1D2129] border-b border-[#E5E6EB]/40 sticky left-0 bg-inherit z-10">{row.settlementType}</td>
                          <td className="py-1.5 px-2 text-[#86909C] border-b border-[#E5E6EB]/40 sticky left-24 bg-inherit z-10">{row.indicator}</td>
                          <td className={`py-1.5 px-2 text-right border-b border-[#E5E6EB]/40 font-medium ${isNegative(row.total) ? 'text-[#F53F3F]' : 'text-[#1D2129]'}`}>
                            {formatNum(row.total)}
                          </td>
                          {dailyBillDates.map((d) => {
                            const val = row.dayValues[d] ?? 0;
                            return (
                              <td
                                key={d}
                                className={`py-1.5 px-1 text-right border-b border-[#E5E6EB]/40 ${isNegative(val) ? 'text-[#F53F3F]' : 'text-[#1D2129]'}`}
                              >
                                {formatNum(val)}
                              </td>
                            );
                          })}
                        </tr>
                      ))}
                    </>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        {/* 底部三个曲线图 */}
        <div className="space-y-4">
          {/* 图1：预计消分电价曲线 */}
          <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
            <div className="flex items-center gap-2 mb-3">
              <i className="ri-line-chart-line text-[#165DFF]" />
              <h3 className="text-sm font-bold text-[#1D2129]">预计消分电价曲线</h3>
            </div>
            <ResponsiveContainer width="100%" height={240}>
              <LineChart data={forecastClearPriceData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
                <XAxis dataKey="date" tick={{ fontSize: 10, fill: '#86909C' }} />
                <YAxis tick={{ fontSize: 10, fill: '#86909C' }} domain={['auto', 'auto']} />
                <Tooltip contentStyle={{ fontSize: 11, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB', color: '#1D2129' }} />
                <Line type="monotone" dataKey="value" name="预计消分电价" stroke={COLORS.forecast} strokeWidth={1.5} dot={false} hide={!chart1Legend['预计消分电价']} />
              </LineChart>
            </ResponsiveContainer>
            <div className="flex items-center justify-center gap-4 mt-2">
              <button
                className={`flex items-center gap-1 text-xs px-2 py-1 rounded transition-all cursor-pointer ${chart1Legend['预计消分电价'] ? 'text-[#165DFF]' : 'text-[#C9CDD4] line-through'}`}
                onClick={() => setChart1Legend((p) => ({ ...p, '预计消分电价': !p['预计消分电价'] }))}
              >
                <span className="w-3 h-0.5 rounded" style={{ backgroundColor: COLORS.forecast }} />
                预计消分电价
              </button>
            </div>
          </div>

          {/* 图2：现货电价曲线 */}
          <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
            <div className="flex items-center gap-2 mb-3">
              <i className="ri-line-chart-line text-[#165DFF]" />
              <h3 className="text-sm font-bold text-[#1D2129]">现货电价曲线</h3>
            </div>
            <ResponsiveContainer width="100%" height={240}>
              <LineChart data={spotPriceCurveData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
                <XAxis dataKey="date" tick={{ fontSize: 10, fill: '#86909C' }} />
                <YAxis tick={{ fontSize: 10, fill: '#86909C' }} domain={['auto', 'auto']} />
                <Tooltip contentStyle={{ fontSize: 11, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB', color: '#1D2129' }} />
                <Line type="monotone" dataKey="dayAheadClear" name="日前结算电价" stroke={COLORS.dayAheadClear} strokeWidth={1.5} dot={false} strokeDasharray="5 5" hide={!chart2Legend['日前结算电价']} />
                <Line type="monotone" dataKey="realTimeClear" name="实时结算电价" stroke={COLORS.realTimeClear} strokeWidth={1.5} dot={false} strokeDasharray="5 5" hide={!chart2Legend['实时结算电价']} />
                <Line type="monotone" dataKey="realTimeAvg" name="现货市场结算均价" stroke={COLORS.realTimeAvg} strokeWidth={1.5} dot={false} hide={!chart2Legend['现货市场结算均价']} />
              </LineChart>
            </ResponsiveContainer>
            <div className="flex items-center justify-center gap-4 mt-2 flex-wrap">
              {[
                { key: '日前结算电价', color: COLORS.dayAheadClear, dash: true },
                { key: '实时结算电价', color: COLORS.realTimeClear, dash: true },
                { key: '现货市场结算均价', color: COLORS.realTimeAvg, dash: false },
              ].map((item) => (
                <button
                  key={item.key}
                  className={`flex items-center gap-1 text-xs px-2 py-1 rounded transition-all cursor-pointer ${chart2Legend[item.key] ? 'text-[#1D2129]' : 'text-[#C9CDD4] line-through'}`}
                  onClick={() => setChart2Legend((p) => ({ ...p, [item.key]: !p[item.key] }))}
                >
                  <span className="w-3 h-0.5 rounded" style={{ backgroundColor: item.color, borderStyle: item.dash ? 'dashed' : 'solid', borderWidth: item.dash ? '1px 0' : 0 }} />
                  {item.key}
                </button>
              ))}
            </div>
          </div>

          {/* 图3：合约电价曲线 */}
          <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
            <div className="flex items-center gap-2 mb-3">
              <i className="ri-line-chart-line text-[#165DFF]" />
              <h3 className="text-sm font-bold text-[#1D2129]">合约电价曲线</h3>
            </div>
            <ResponsiveContainer width="100%" height={240}>
              <LineChart data={contractPriceCurveData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
                <XAxis dataKey="date" tick={{ fontSize: 10, fill: '#86909C' }} />
                <YAxis tick={{ fontSize: 10, fill: '#86909C' }} domain={['auto', 'auto']} />
                <Tooltip contentStyle={{ fontSize: 11, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB', color: '#1D2129' }} />
                <Line type="monotone" dataKey="yearClear" name="年度结算电价" stroke={COLORS.yearClear} strokeWidth={1.5} dot={false} strokeDasharray="5 5" hide={!chart3Legend['年度结算电价']} />
                <Line type="monotone" dataKey="monthClear" name="月度结算电价" stroke={COLORS.monthClear} strokeWidth={1.5} dot={false} strokeDasharray="5 5" hide={!chart3Legend['月度结算电价']} />
                <Line type="monotone" dataKey="matchClear" name="即结算电价" stroke={COLORS.matchClear} strokeWidth={1.5} dot={false} strokeDasharray="5 5" hide={!chart3Legend['即结算电价']} />
                <Line type="monotone" dataKey="dayAheadClear" name="即前结算电价" stroke={COLORS.dayAheadClearContract} strokeWidth={1.5} dot={false} strokeDasharray="5 5" hide={!chart3Legend['即前结算电价']} />
                <Line type="monotone" dataKey="realTimeClear" name="实时结算电价" stroke={COLORS.realTimeClearContract} strokeWidth={1.5} dot={false} strokeDasharray="5 5" hide={!chart3Legend['实时结算电价']} />
                <Line type="monotone" dataKey="contractAvg" name="合约结算均价" stroke={COLORS.contractAvg} strokeWidth={1.5} dot={false} hide={!chart3Legend['合约结算均价']} />
                <Line type="monotone" dataKey="interProvAvg" name="省间绿电价" stroke={COLORS.interProvAvg} strokeWidth={1.5} dot={false} hide={!chart3Legend['省间绿电价']} />
              </LineChart>
            </ResponsiveContainer>
            <div className="flex items-center justify-center gap-3 mt-2 flex-wrap">
              {[
                { key: '年度结算电价', color: COLORS.yearClear },
                { key: '月度结算电价', color: COLORS.monthClear },
                { key: '即结算电价', color: COLORS.matchClear },
                { key: '即前结算电价', color: COLORS.dayAheadClearContract },
                { key: '实时结算电价', color: COLORS.realTimeClearContract },
                { key: '合约结算均价', color: COLORS.contractAvg },
                { key: '省间绿电价', color: COLORS.interProvAvg },
              ].map((item) => (
                <button
                  key={item.key}
                  className={`flex items-center gap-1 text-xs px-1.5 py-1 rounded transition-all cursor-pointer ${chart3Legend[item.key] ? 'text-[#1D2129]' : 'text-[#C9CDD4] line-through'}`}
                  onClick={() => setChart3Legend((p) => ({ ...p, [item.key]: !p[item.key] }))}
                >
                  <span className="w-3 h-0.5 rounded" style={{ backgroundColor: item.color }} />
                  {item.key}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </SpotTradingLayout>
  );
}