 import { useState, useMemo } from 'react';
import {
  ComposedChart,
  Area,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  Brush,
} from 'recharts';
import type { TimePoint } from '@/hooks/useBidDecisionData';
import ConfirmModal from '@/components/ConfirmModal';

interface BidClearingAnalysisProps {
  data: TimePoint[];
}

interface ExtPoint {
  time: string;
  myDaSettled: number;
  myRtSettled: number;
  marketDaClearing: number;
  marketRtClearing: number;
  myDevRate: number;
  marketDevRate: number;
  daPrice: number;
  rtPrice: number;
}

function genExt(data: TimePoint[]): ExtPoint[] {
  return data.map((p) => {
    const base = p.daBid;
    const myDaSettled = Math.round((base * 37 + (Math.random() - 0.5) * 8) * 100) / 100;
    const myRtSettled = Math.round((base * 35 + (Math.random() - 0.5) * 10) * 100) / 100;
    const marketDaClearing = Math.round((base * 27000 + (Math.random() - 0.5) * 3000) * 100) / 100;
    const marketRtClearing = Math.round((base * 26000 + (Math.random() - 0.5) * 3500) * 100) / 100;
    const myDevRate = myDaSettled !== 0 ? Math.round(((myDaSettled - myRtSettled) / myDaSettled) * 1000) / 10 : 0;
    const marketDevRate = marketDaClearing !== 0 ? Math.round(((marketDaClearing - marketRtClearing) / marketDaClearing) * 1000) / 10 : 0;
    return {
      time: p.time,
      myDaSettled,
      myRtSettled,
      marketDaClearing,
      marketRtClearing,
      myDevRate,
      marketDevRate,
      daPrice: p.daPrice,
      rtPrice: p.rtClearing,
    };
  });
}

export default function BidClearingAnalysis({ data }: BidClearingAnalysisProps) {
  const [showFullscreen, setShowFullscreen] = useState(false);
  const cd = useMemo(() => genExt(data), [data]);
  const dateLabel = '2026-04-29';

  const commonTooltip = (
    <Tooltip
      contentStyle={{ fontSize: 10, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB', color: '#1D2129', padding: '8px 12px' }}
      itemStyle={{ fontSize: 10, padding: '2px 0' }}
      labelStyle={{ fontSize: 10, color: '#86909C', marginBottom: 4 }}
    />
  );

  const renderCharts = (isFullscreen: boolean) => {
    const h = isFullscreen ? 220 : 200;
    const fs = isFullscreen ? 10 : 9;
    const yw = isFullscreen ? 50 : 40;

    return (
      <div className="space-y-4">
        {/* 图表1：我的出清 */}
        <div>
          <div className="flex items-center gap-1.5 mb-1">
            <span className="text-[#165DFF] text-xs">◆</span>
            <span className="text-sm font-bold text-[#1D2129]">我的出清</span>
          </div>
          <div className="flex items-center justify-between text-[10px] text-[#86909C] px-1 mb-1">
            <span>电量（MWh）</span>
            <span>{dateLabel}</span>
            <span>电价（元/MWh）</span>
          </div>
          <div style={{ height: h }}>
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={cd} margin={{ top: 5, right: yw, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
                <XAxis dataKey="time" tick={{ fontSize: fs, fill: '#86909C' }} interval={11} axisLine={{ stroke: '#E5E6EB' }} tickLine={false} />
                <YAxis yAxisId="left" tick={{ fontSize: fs, fill: '#86909C' }} axisLine={false} tickLine={false} width={yw} />
                <YAxis yAxisId="right" orientation="right" tick={{ fontSize: fs, fill: '#86909C' }} axisLine={false} tickLine={false} width={yw} domain={[200, 650]} />
                {commonTooltip}
                <Legend wrapperStyle={{ fontSize: fs, paddingBottom: 0 }} iconSize={8} />
                <Area yAxisId="left" type="monotone" dataKey="myDaSettled" stroke="#93C5FD" fill="#DBEAFE" fillOpacity={0.7} strokeWidth={1} name="我的日前结算电量" />
                <Line yAxisId="left" type="monotone" dataKey="myRtSettled" stroke="#22C55E" strokeWidth={1.5} dot={false} name="我的实时结算电量" />
                <Line yAxisId="right" type="stepAfter" dataKey="daPrice" stroke="#3B82F6" strokeWidth={1} dot={false} name="日前电价" />
                <Line yAxisId="right" type="stepAfter" dataKey="rtPrice" stroke="#EF4444" strokeWidth={1} dot={false} name="实时电价" />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* 图表2：市场出清 */}
        <div>
          <div className="flex items-center gap-1.5 mb-1">
            <span className="text-[#165DFF] text-xs">◆</span>
            <span className="text-sm font-bold text-[#1D2129]">市场出清</span>
          </div>
          <div className="flex items-center justify-between text-[10px] text-[#86909C] px-1 mb-1">
            <span>电量（MWh）</span>
            <span>{dateLabel}</span>
            <span>电价（元/MWh）</span>
          </div>
          <div style={{ height: h }}>
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={cd} margin={{ top: 5, right: yw, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
                <XAxis dataKey="time" tick={{ fontSize: fs, fill: '#86909C' }} interval={11} axisLine={{ stroke: '#E5E6EB' }} tickLine={false} />
                <YAxis yAxisId="left" tick={{ fontSize: fs, fill: '#86909C' }} axisLine={false} tickLine={false} width={yw} />
                <YAxis yAxisId="right" orientation="right" tick={{ fontSize: fs, fill: '#86909C' }} axisLine={false} tickLine={false} width={yw} domain={[200, 650]} />
                {commonTooltip}
                <Legend wrapperStyle={{ fontSize: fs, paddingBottom: 0 }} iconSize={8} />
                <Area yAxisId="left" type="monotone" dataKey="marketDaClearing" stroke="#FBBF24" fill="#FEF3C7" fillOpacity={0.7} strokeWidth={1} name="市场日前出清电量" />
                <Line yAxisId="left" type="monotone" dataKey="marketRtClearing" stroke="#22C55E" strokeWidth={1.5} dot={false} name="市场实时出清电量" />
                <Line yAxisId="right" type="stepAfter" dataKey="daPrice" stroke="#3B82F6" strokeWidth={1} dot={false} name="日前电价" />
                <Line yAxisId="right" type="stepAfter" dataKey="rtPrice" stroke="#EF4444" strokeWidth={1} dot={false} name="实时电价" />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* 图表3：对比分析 */}
        <div>
          <div className="flex items-center gap-1.5 mb-1">
            <span className="text-[#165DFF] text-xs">◆</span>
            <span className="text-sm font-bold text-[#1D2129]">对比分析</span>
          </div>
          <div className="flex items-center justify-between text-[10px] text-[#86909C] px-1 mb-1">
            <span>偏差率（%）</span>
            <span>{dateLabel}</span>
            <span>电价（元/MWh）</span>
          </div>
          <div style={{ height: h }}>
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={cd} margin={{ top: 5, right: yw, left: 0, bottom: isFullscreen ? 0 : 20 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
                <XAxis dataKey="time" tick={{ fontSize: fs, fill: '#86909C' }} interval={11} axisLine={{ stroke: '#E5E6EB' }} tickLine={false} />
                <YAxis yAxisId="left" tick={{ fontSize: fs, fill: '#86909C' }} axisLine={false} tickLine={false} width={yw} />
                <YAxis yAxisId="right" orientation="right" tick={{ fontSize: fs, fill: '#86909C' }} axisLine={false} tickLine={false} width={yw} domain={[200, 650]} />
                {commonTooltip}
                <Legend wrapperStyle={{ fontSize: fs, paddingBottom: 0 }} iconSize={8} />
                <Line yAxisId="left" type="monotone" dataKey="myDevRate" stroke="#22C55E" strokeWidth={1.5} dot={false} name="我的报量偏差率" />
                <Line yAxisId="left" type="monotone" dataKey="marketDevRate" stroke="#F59E0B" strokeWidth={1.5} dot={false} name="市场报量偏差率" />
                <Line yAxisId="right" type="stepAfter" dataKey="daPrice" stroke="#3B82F6" strokeWidth={1} dot={false} name="日前电价" />
                <Line yAxisId="right" type="stepAfter" dataKey="rtPrice" stroke="#EF4444" strokeWidth={1} dot={false} name="实时电价" />
                {!isFullscreen && (
                  <Brush dataKey="time" height={20} stroke="#93C5FD" fill="#F7F8FA" travellerWidth={8} />
                )}
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="bg-white rounded-lg border border-[#E5E6EB] p-4 mb-4">
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-sm font-bold text-[#1D2129]">申报出清分析</h3>
        <div className="flex items-center gap-3 text-[#86909C]">
          <span className="flex items-center gap-1 text-xs cursor-pointer hover:text-[#94A3B8]">
            <i className="ri-download-line" />导出
          </span>
          <span onClick={() => setShowFullscreen(true)} className="flex items-center gap-1 text-xs cursor-pointer hover:text-[#94A3B8]">
            <i className="ri-fullscreen-line" />放大
          </span>
        </div>
      </div>

      {renderCharts(false)}

      {showFullscreen && (
        <ConfirmModal title="" message="" onConfirm={() => setShowFullscreen(false)} onCancel={() => setShowFullscreen(false)} showCancel={false} confirmText="关闭">
          <div className="w-full min-h-[400px] h-[80vh] overflow-auto">
            <div className="flex items-center justify-between mb-2">
              <h3 className="text-base font-bold text-[#1D2129]">申报出清分析</h3>
              <button onClick={() => setShowFullscreen(false)} className="w-8 h-8 flex items-center justify-center rounded hover:bg-[#F7F8FA] cursor-pointer">
                <i className="ri-close-line text-[#86909C]" />
              </button>
            </div>
            {renderCharts(true)}
          </div>
        </ConfirmModal>
      )}
    </div>
  );
}
