import { useState, useMemo } from 'react';
import type { TimePoint } from '@/hooks/useBidDecisionData';

interface DataListProps {
  data: TimePoint[];
}

interface RowDef {
  key: string;
  label: string;
  unit: 'qty' | 'price' | 'rate';
  values: number[];
  avg: number | string;
  max: number;
  min: number;
}

const COL_W = {
  date: 96,
  indicator: 128,
  avg: 80,
  max: 80,
  min: 80,
  time: 64,
};

export default function DataList({ data }: DataListProps) {
  const [activeDayType, setActiveDayType] = useState<'all' | 'rest' | 'holiday'>('all');

  // 48 个半时点：00:30, 01:00, 01:30 ... 24:00
  const timeCols = useMemo(() => {
    return Array.from({ length: 48 }, (_, i) => {
      const totalMins = (i + 1) * 30;
      const h = Math.floor(totalMins / 60);
      const m = totalMins % 60;
      return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
    });
  }, []);

  const rows = useMemo(() => {
    const ext = data.map((p) => {
      const base = p.daBid;
      const myDaSettled = base * 37 + (Math.random() - 0.5) * 8;
      const myRtSettled = base * 35 + (Math.random() - 0.5) * 10;
      const myActualUse = base * 36.2 + (Math.random() - 0.5) * 6;
      const marketDaClearing = base * 27000 + (Math.random() - 0.5) * 3000;
      const marketRtClearing = base * 26000 + (Math.random() - 0.5) * 3500;
      const marketActualUse = base * 26900 + (Math.random() - 0.5) * 2500;
      const myDevRate = myDaSettled !== 0 ? ((myDaSettled - myRtSettled) / myDaSettled) * 100 : 0;
      const marketDevRate = marketDaClearing !== 0 ? ((marketDaClearing - marketRtClearing) / marketDaClearing) * 100 : 0;
      return {
        myDaSettled,
        myRtSettled,
        myActualUse,
        marketDaClearing,
        marketRtClearing,
        marketActualUse,
        myDevRate,
        marketDevRate,
        daPrice: p.daPrice,
        rtPrice: p.rtClearing,
      };
    });

    const halfHour = Array.from({ length: 48 }, (_, i) => {
      const d1 = ext[i * 2];
      const d2 = ext[i * 2 + 1];
      if (!d1 || !d2) return d1 || d2 || {};
      return {
        myDaSettled: (d1.myDaSettled + d2.myDaSettled) / 2,
        myRtSettled: (d1.myRtSettled + d2.myRtSettled) / 2,
        myActualUse: (d1.myActualUse + d2.myActualUse) / 2,
        marketDaClearing: (d1.marketDaClearing + d2.marketDaClearing) / 2,
        marketRtClearing: (d1.marketRtClearing + d2.marketRtClearing) / 2,
        marketActualUse: (d1.marketActualUse + d2.marketActualUse) / 2,
        myDevRate: (d1.myDevRate + d2.myDevRate) / 2,
        marketDevRate: (d1.marketDevRate + d2.marketDevRate) / 2,
        daPrice: (d1.daPrice + d2.daPrice) / 2,
        rtPrice: (d1.rtPrice + d2.rtPrice) / 2,
      };
    });

    const makeRow = (
      key: string,
      label: string,
      unit: 'qty' | 'price' | 'rate',
      extractor: (x: typeof halfHour[0]) => number,
    ): RowDef => {
      const values = halfHour.map(extractor);
      const validVals = values.filter((v) => !Number.isNaN(v));
      const avg = unit === 'rate' ? '—' : validVals.reduce((a, b) => a + b, 0) / validVals.length;
      return {
        key,
        label,
        unit,
        values,
        avg,
        max: Math.max(...validVals),
        min: Math.min(...validVals),
      };
    };

    return [
      makeRow('myDa', '我的日前结算电量', 'qty', (x) => x.myDaSettled),
      makeRow('myRt', '我的实时结算电量', 'qty', (x) => x.myRtSettled),
      makeRow('myAct', '我的实际用电量', 'qty', (x) => x.myActualUse),
      makeRow('myDev', '我的报量偏差率', 'rate', (x) => x.myDevRate),
      makeRow('mktDa', '市场日前出清电量', 'qty', (x) => x.marketDaClearing),
      makeRow('mktRt', '市场实时出清电量', 'qty', (x) => x.marketRtClearing),
      makeRow('mktAct', '市场实际用电量', 'qty', (x) => x.marketActualUse),
      makeRow('mktDev', '市场报量偏差率', 'rate', (x) => x.marketDevRate),
      makeRow('daPrice', '日前价格', 'price', (x) => x.daPrice),
      makeRow('rtPrice', '实时价格', 'price', (x) => x.rtPrice),
    ];
  }, [data]);

  const fmt = (v: number, u: 'qty' | 'price' | 'rate') => {
    if (u === 'rate') return `${v > 0 ? '+' : ''}${v.toFixed(2)}%`;
    return v.toFixed(2);
  };

  // 偏差率：正数红色，负数绿色，0灰色
  const cellCls = (v: number, u: 'qty' | 'price' | 'rate') => {
    if (u === 'rate') {
      if (v > 0) return 'text-red-500';
      if (v < 0) return 'text-emerald-500';
      return 'text-[#86909C]';
    }
    // 价格异常值标红（超出 500 或低于 250）
    if (u === 'price' && (v > 500 || v < 250)) return 'text-red-500';
    return 'text-[#4E5969]';
  };

  const handleExport = () => {
    const header = ['日期', '指标', '日平均', '日最高', '日最低', ...timeCols].join(',');
    const body = rows.map((row) => {
      const avgStr = typeof row.avg === 'string' ? row.avg : row.avg.toFixed(2);
      return ['2026-04-29', row.label, avgStr, row.max.toFixed(2), row.min.toFixed(2), ...row.values.map((v) => v.toFixed(2))].join(',');
    }).join('\n');
    const csv = `\ufeff${header}\n${body}`;
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `数据列表_2026-04-29.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const dateVisible = activeDayType === 'all' || activeDayType === 'rest';

  const tabCls = (type: 'rest' | 'holiday') =>
    activeDayType === type
      ? 'px-2 py-0.5 rounded text-[10px] whitespace-nowrap cursor-pointer font-medium'
      : 'px-2 py-0.5 rounded text-[10px] whitespace-nowrap cursor-pointer text-[#86909C] border border-[#E5E6EB] bg-white hover:bg-[#F7F8FA]';

  const tabRestStyle = activeDayType === 'rest' ? { backgroundColor: '#FF7D00', color: '#fff' } : {};
  const tabHolidayStyle = activeDayType === 'holiday' ? { backgroundColor: '#00C48C', color: '#fff' } : {};

  return (
    <div className="bg-white rounded-lg border border-[#E5E6EB] p-4 mb-4">
      {/* 顶部 */}
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <h3 className="text-sm font-bold text-[#1D2129]">数据列表</h3>
          <button
            className={tabCls('rest')}
            style={tabRestStyle}
            onClick={() => setActiveDayType(activeDayType === 'rest' ? 'all' : 'rest')}
          >
            周六 | 调休放假
          </button>
          <button
            className={tabCls('holiday')}
            style={tabHolidayStyle}
            onClick={() => setActiveDayType(activeDayType === 'holiday' ? 'all' : 'holiday')}
          >
            周日 | 法定节假日
          </button>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-[10px] text-[#86909C] whitespace-nowrap">
            电量单位：MWh  电价单位：元/MWh
          </span>
          <button
            onClick={handleExport}
            className="px-3 py-1 rounded border border-[#165DFF] text-[#165DFF] text-xs hover:bg-[#165DFF]/5 cursor-pointer whitespace-nowrap"
          >
            导出
          </button>
        </div>
      </div>

      {/* 表格 */}
      <div className="overflow-x-auto" style={{ maxWidth: '100%' }}>
        <table className="text-xs border-collapse" style={{ minWidth: 'max-content' }}>
          <thead className="sticky top-0 z-[100]">
            <tr className="bg-[#F2F3F5]">
              <th
                className="py-2 text-center text-[#86909C] font-medium border border-[#E5E6EB] sticky left-0 z-[100]"
                style={{ width: COL_W.date, minWidth: COL_W.date, left: 0 }}
              >
                日期
              </th>
              <th
                className="py-2 text-center text-[#86909C] font-medium border border-[#E5E6EB] sticky z-[90]"
                style={{ width: COL_W.indicator, minWidth: COL_W.indicator, left: COL_W.date }}
              >
                指标
              </th>
              <th
                className="py-2 text-center text-[#86909C] font-medium border border-[#E5E6EB] sticky z-[80]"
                style={{ width: COL_W.avg, minWidth: COL_W.avg, left: COL_W.date + COL_W.indicator }}
              >
                日平均
              </th>
              <th
                className="py-2 text-center text-[#86909C] font-medium border border-[#E5E6EB] sticky z-[70]"
                style={{ width: COL_W.max, minWidth: COL_W.max, left: COL_W.date + COL_W.indicator + COL_W.avg }}
              >
                日最高
              </th>
              <th
                className="py-2 text-center text-[#86909C] font-medium border border-[#E5E6EB] sticky z-[60]"
                style={{ width: COL_W.min, minWidth: COL_W.min, left: COL_W.date + COL_W.indicator + COL_W.avg + COL_W.max }}
              >
                日最低
              </th>
              {timeCols.map((t) => (
                <th
                  key={t}
                  className="py-2 text-center text-[#86909C] font-medium border border-[#E5E6EB]"
                  style={{ width: COL_W.time, minWidth: COL_W.time }}
                >
                  {t}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {dateVisible && rows.map((row, ridx) => (
              <tr
                key={row.key}
                className={`${ridx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]'} hover:bg-[#EDF2FC] transition-colors`}
              >
                {ridx === 0 && (
                  <td
                    rowSpan={rows.length}
                    className="py-2 text-center text-[#1D2129] font-medium border border-[#E5E6EB] sticky left-0 z-[50] align-middle"
                    style={{ width: COL_W.date, minWidth: COL_W.date, left: 0 }}
                  >
                    2026-04-29
                  </td>
                )}
                <td
                  className={`px-2 py-1.5 text-[#1D2129] font-medium border border-[#E5E6EB] sticky z-[40] ${ridx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]'} hover:bg-[#EDF2FC]`}
                  style={{ width: COL_W.indicator, minWidth: COL_W.indicator, left: COL_W.date }}
                >
                  {row.label}
                </td>
                <td
                  className={`px-2 py-1.5 text-right font-mono border border-[#E5E6EB] sticky z-[30] ${ridx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]'} hover:bg-[#EDF2FC] ${typeof row.avg === 'string' ? 'text-[#86909C]' : cellCls(row.avg as number, row.unit)}`}
                  style={{ width: COL_W.avg, minWidth: COL_W.avg, left: COL_W.date + COL_W.indicator }}
                >
                  {typeof row.avg === 'string' ? row.avg : fmt(row.avg as number, row.unit)}
                </td>
                <td
                  className={`px-2 py-1.5 text-right font-mono border border-[#E5E6EB] sticky z-[20] ${ridx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]'} hover:bg-[#EDF2FC] ${cellCls(row.max, row.unit)}`}
                  style={{ width: COL_W.max, minWidth: COL_W.max, left: COL_W.date + COL_W.indicator + COL_W.avg }}
                >
                  {fmt(row.max, row.unit)}
                </td>
                <td
                  className={`px-2 py-1.5 text-right font-mono border border-[#E5E6EB] sticky z-[20] ${ridx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]'} hover:bg-[#EDF2FC] ${cellCls(row.min, row.unit)}`}
                  style={{ width: COL_W.min, minWidth: COL_W.min, left: COL_W.date + COL_W.indicator + COL_W.avg + COL_W.max }}
                >
                  {fmt(row.min, row.unit)}
                </td>
                {row.values.map((val, cidx) => (
                  <td
                    key={cidx}
                    className={`px-1 py-1.5 text-right font-mono border border-[#E5E6EB] ${cellCls(val, row.unit)}`}
                    style={{ width: COL_W.time, minWidth: COL_W.time }}
                  >
                    {fmt(val, row.unit)}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}