import { useState } from 'react';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip,
  ResponsiveContainer, Legend,
} from 'recharts';
import EnergySalesLayout from '../components/EnergySalesLayout';
import { dailyTradeList, type DailyTradeRecord } from '@/mocks/energySalesData';

export default function DailyTradePage() {
  const [searchName, setSearchName] = useState('');
  const [filterDate, setFilterDate] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  const filtered = dailyTradeList.filter(d => {
    const nameMatch = !searchName || d.userName.includes(searchName);
    const dateMatch = !filterDate || d.tradeDate === filterDate;
    return nameMatch && dateMatch;
  });

  const totalPages = Math.ceil(filtered.length / pageSize);
  const paged = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  // Chart data by date
  const chartData = [...new Set(filtered.map(d => d.tradeDate))].slice(0, 7).map(date => {
    const dayData = filtered.filter(d => d.tradeDate === date);
    return {
      date,
      totalBid: dayData.reduce((sum, d) => sum + d.dayAheadBid, 0) / 10000,
      totalClear: dayData.reduce((sum, d) => sum + d.dayAheadClear, 0) / 10000,
      avgPrice: dayData.reduce((sum, d) => sum + d.dayAheadPrice, 0) / dayData.length,
    };
  });

  return (
    <EnergySalesLayout>
      <div className="space-y-5 text-[#1D2129]">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">日交易数据管理</h1>
            <p className="text-sm text-[#86909C] mt-1">日前/实时交易数据导入、查询与分析</p>
          </div>
          <div className="flex items-center gap-2">
            <button className="flex items-center gap-1.5 px-4 py-2 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/90 transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-upload-2-line" />
              导入日交易数据
            </button>
            <button className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-download-2-line" />
              导出Excel
            </button>
          </div>
        </div>

        {/* Chart */}
        <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
          <h3 className="text-sm font-bold text-[#1D2129] mb-4">日交易电量趋势</h3>
          <ResponsiveContainer width="100%" height={260}>
            <LineChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
              <XAxis dataKey="date" tick={{ fontSize: 11, fill: '#86909C' }} />
              <YAxis tick={{ fontSize: 11, fill: '#86909C' }} />
              <Tooltip contentStyle={{ fontSize: 12, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB' }} />
              <Legend wrapperStyle={{ fontSize: 12 }} />
              <Line type="monotone" dataKey="totalBid" stroke="#165DFF" strokeWidth={2} dot={{ r: 3 }} name="日前申报电量(万MWh)" />
              <Line type="monotone" dataKey="totalClear" stroke="#00C48C" strokeWidth={2} dot={{ r: 3 }} strokeDasharray="4 4" name="日前出清电量(万MWh)" />
            </LineChart>
          </ResponsiveContainer>
        </div>

        {/* Filter */}
        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">用户名称</label>
              <input type="text" value={searchName} onChange={e => setSearchName(e.target.value)} placeholder="请输入用户名称" className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[180px]" />
            </div>
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">交易日期</label>
              <input type="date" value={filterDate} onChange={e => setFilterDate(e.target.value)} className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[150px]" />
            </div>
            <button className="flex items-center gap-1.5 px-4 py-2 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/90 transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-search-line" />
              查询
            </button>
            <button onClick={() => { setSearchName(''); setFilterDate(''); }} className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-refresh-line" />
              重置
            </button>
          </div>
        </div>

        {/* Table */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#F7F8FA]">
                <tr>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-0 bg-[#F7F8FA] z-10">序号</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-[48px] bg-[#F7F8FA] z-10">交易日期</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">用户名称</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">日前申报</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">日前出清</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">实时申报</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">实时出清</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">偏差率</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">日前电价</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">实时电价</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">结算电费</th>
                </tr>
              </thead>
              <tbody>
                {paged.map((d, idx) => (
                  <tr key={d.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : ''}`}>
                    <td className="px-4 py-3 sticky left-0 bg-white z-10">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="px-4 py-3 sticky left-[48px] bg-white z-10 font-medium">{d.tradeDate}</td>
                    <td className="px-4 py-3 text-[#4E5969]">{d.userName}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{d.dayAheadBid.toLocaleString()}</td>
                    <td className="px-4 py-3 text-right font-medium text-[#165DFF]">{d.dayAheadClear.toLocaleString()}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{d.realTimeBid.toLocaleString()}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{d.realTimeClear.toLocaleString()}</td>
                    <td className={`px-4 py-3 text-right font-medium ${d.deviationRate > 0 ? 'text-[#F53F3F]' : 'text-[#00C48C]'}`}>
                      {d.deviationRate > 0 ? '+' : ''}{d.deviationRate}%
                    </td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{d.dayAheadPrice.toFixed(3)}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{d.realTimePrice.toFixed(3)}</td>
                    <td className="px-4 py-3 text-right font-medium text-[#1D2129]">{d.settlementAmount.toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="flex items-center justify-between px-4 py-3 border-t border-[#E5E6EB]">
            <span className="text-xs text-[#86909C]">共 {filtered.length} 条，每页 {pageSize} 条</span>
            <div className="flex items-center gap-1">
              <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"><i className="ri-arrow-left-s-line" /></button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
                <button key={p} onClick={() => setCurrentPage(p)} className={`px-3 py-1 text-xs rounded cursor-pointer ${p === currentPage ? 'bg-[#165DFF] text-white' : 'border border-[#E5E6EB] hover:border-[#165DFF]'}`}>{p}</button>
              ))}
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"><i className="ri-arrow-right-s-line" /></button>
            </div>
          </div>
        </div>
      </div>
    </EnergySalesLayout>
  );
}