import { useState, useMemo, useCallback } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import SpotTradingLayout from '@/pages/spot-trading/components/SpotTradingLayout';
import { gasClearingDailyData, type GasClearingPoint } from '@/mocks/dataMgmtData';
import ConfirmModal from '@/components/ConfirmModal';
import Toast from '@/components/Toast';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
  Bar,
  ComposedChart,
} from 'recharts';

const TIME_POINTS = Array.from({ length: 96 }, (_, i) => {
  const hour = Math.floor(i / 4);
  const minute = (i % 4) * 15;
  return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
});

function getInitialPoints(date: string): GasClearingPoint[] {
  const found = gasClearingDailyData.find(d => d.date === date);
  if (found) {
    return found.points.map(p => ({
      ...p,
      totalClearing: Math.round((p.coalUnitQty + p.gasUnitQty) * 100) / 100,
      extrapolatedQty: Math.round((p.coalUnitQty + p.gasUnitQty) * 100) / 100,
    }));
  }
  return TIME_POINTS.map(time => ({
    time,
    totalClearing: 0,
    coalUnitQty: 0,
    coalUnitCount: 0,
    gasUnitQty: 0,
    gasUnitCount: 0,
    weightedPrice: 0,
    reserveMatch: '是',
    extrapolatedQty: 0,
    manualGasQty: 0,
  }));
}

export default function GasClearingDetailPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const date = searchParams.get('date') || '2026-05-07';
  const mode = searchParams.get('mode') || 'view';
  const isEdit = mode === 'edit';
  const isBlank = searchParams.get('blank') === 'true';

  const [points, setPoints] = useState<GasClearingPoint[]>(() => {
    if (isBlank) {
      return TIME_POINTS.map(time => ({
        time,
        totalClearing: 0,
        coalUnitQty: 0,
        coalUnitCount: 0,
        gasUnitQty: 0,
        gasUnitCount: 0,
        weightedPrice: 0,
        reserveMatch: '是',
        extrapolatedQty: 0,
        manualGasQty: 0,
      }));
    }
    return getInitialPoints(date);
  });
  const [hasChanges, setHasChanges] = useState(false);

  // Batch edit
  const [selectedPoints, setSelectedPoints] = useState<Set<number>>(new Set());
  const [batchField, setBatchField] = useState<'gasUnitQty'>('gasUnitQty');
  const [batchValue, setBatchValue] = useState('');
  const [batchError, setBatchError] = useState('');
  const [showBatchPanel, setShowBatchPanel] = useState(false);

  const [pointErrors, setPointErrors] = useState<Record<number, string>>({});
  const [showCancelModal, setShowCancelModal] = useState(false);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  // Recalculate total and extrapolated when base fields change
  const recalc = (prev: GasClearingPoint[]): GasClearingPoint[] => {
    return prev.map(p => ({
      ...p,
      totalClearing: Math.round((p.coalUnitQty + p.gasUnitQty) * 100) / 100,
      extrapolatedQty: Math.round((p.coalUnitQty + p.gasUnitQty) * 100) / 100,
    }));
  };

  // Stats
  const stats = useMemo(() => {
    const totals = points.map(p => p.totalClearing);
    const coalTotals = points.map(p => p.coalUnitQty);
    const gasTotals = points.map(p => p.gasUnitQty);
    const prices = points.map(p => p.weightedPrice);
    return {
      totalSum: Math.round(totals.reduce((s, v) => s + v, 0)),
      totalMax: Math.max(...totals),
      totalMin: Math.min(...totals),
      totalAvg: Math.round(totals.reduce((s, v) => s + v, 0) / totals.length * 10) / 10,
      coalSum: Math.round(coalTotals.reduce((s, v) => s + v, 0)),
      gasSum: Math.round(gasTotals.reduce((s, v) => s + v, 0)),
      avgPrice: prices.length > 0 ? Math.round(prices.reduce((s, v) => s + v, 0) / prices.length * 10) / 10 : 0,
      maxPrice: Math.max(...prices),
      minPrice: Math.min(...prices),
    };
  }, [points]);

  // Chart data
  const chartData = useMemo(() =>
    points.map((p, idx) => ({
      idx: idx + 1,
      time: p.time,
      totalClearing: p.totalClearing,
      coalUnitQty: p.coalUnitQty,
      gasUnitQty: p.gasUnitQty,
      weightedPrice: p.weightedPrice,
    })),
    [points]
  );

  const validateValue = (val: number, field: string): string | null => {
    if (val < 0) return '不可为负数';
    if ((field === 'coalUnitCount' || field === 'gasUnitCount') && val % 1 !== 0) return '台数须为整数';
    return null;
  };

  const handleFieldChange = useCallback((index: number, field: keyof GasClearingPoint, valueStr: string) => {
    const val = parseFloat(valueStr);
    if (isNaN(val)) return;
    const err = validateValue(val, field);
    setPointErrors(prev => {
      const next = { ...prev };
      if (err) next[index] = err;
      else delete next[index];
      return next;
    });
    setPoints(prev => {
      const next = [...prev];
      next[index] = { ...next[index], [field]: val };
      return recalc(next);
    });
    setHasChanges(true);
  }, []);

  const handleReserveMatchChange = useCallback((index: number, value: '是' | '否') => {
    setPoints(prev => {
      const next = [...prev];
      next[index] = { ...next[index], reserveMatch: value };
      return next;
    });
    setHasChanges(true);
  }, []);

  const togglePointSelect = (index: number) => {
    setSelectedPoints(prev => {
      const next = new Set(prev);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      return next;
    });
  };

  const selectAllPoints = () => {
    if (selectedPoints.size === 96) {
      setSelectedPoints(new Set());
    } else {
      setSelectedPoints(new Set(Array.from({ length: 96 }, (_, i) => i)));
    }
  };

  const applyBatchEdit = () => {
    const val = parseFloat(batchValue);
    if (isNaN(val)) { setBatchError('请输入有效数值'); return; }
    if (val < 0) { setBatchError('不可为负数'); return; }
    if ((batchField === 'coalUnitCount' || batchField === 'gasUnitCount') && val % 1 !== 0) { setBatchError('台数须为整数'); return; }
    if (selectedPoints.size === 0) { setBatchError('请先勾选至少一个时段'); return; }
    setBatchError('');
    setPoints(prev => {
      const next = [...prev];
      selectedPoints.forEach(idx => {
        next[idx] = { ...next[idx], [batchField]: val };
      });
      return recalc(next);
    });
    setPointErrors(prev => {
      const next = { ...prev };
      selectedPoints.forEach(idx => delete next[idx]);
      return next;
    });
    setHasChanges(true);
    setToast({ message: `已成功批量修改 ${selectedPoints.size} 个时段`, type: 'success' });
  };

  const handleSave = () => {
    if (pointErrors && Object.keys(pointErrors).length > 0) {
      setToast({ message: '存在数据错误，请修正后再保存', type: 'error' });
      return;
    }
    setShowSaveConfirm(true);
  };

  const confirmSave = () => {
    setShowSaveConfirm(false);
    setHasChanges(false);
    setToast({ message: '保存成功，数据已生效并同步至上游模块', type: 'success' });
    setTimeout(() => {
      navigate('/spot-trading/data-mgmt/gas-clearing');
    }, 1500);
  };

  const handleCancel = () => {
    if (hasChanges) {
      setShowCancelModal(true);
    } else {
      navigate('/spot-trading/data-mgmt/gas-clearing');
    }
  };

  const confirmCancel = () => {
    setShowCancelModal(false);
    navigate('/spot-trading/data-mgmt/gas-clearing');
  };

  const editableFields: { key: keyof GasClearingPoint; label: string; unit: string; width: string; isNumber: boolean }[] = [
    { key: 'gasUnitQty', label: '燃气机组出清电量', unit: 'MW', width: 'w-28', isNumber: true },
  ];

  const readOnlyFields: { key: keyof GasClearingPoint; label: string; unit: string }[] = [
    { key: 'coalUnitQty', label: '燃煤机组出清电量', unit: 'MW' },
    { key: 'coalUnitCount', label: '燃煤机组台数', unit: '台' },
    { key: 'gasUnitCount', label: '燃气机组台数', unit: '台' },
    { key: 'weightedPrice', label: '市场化加权电价', unit: '元' },
  ];

  return (
    <SpotTradingLayout>
      <div className="w-full max-w-full space-y-4">
        {/* Top bar */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button onClick={() => navigate('/spot-trading/data-mgmt/gas-clearing')} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-arrow-left-line" />返回列表
            </button>
            <h1 className="text-lg font-bold text-[#1D2129]">
              燃机出清详情<span className="text-sm font-normal text-[#86909C] ml-1">（{date}）</span>
              <span className={`ml-2 text-[10px] px-2 py-0.5 rounded-full ${isEdit ? 'bg-[#FF7D00]/10 text-[#FF7D00]' : 'bg-[#00C48C]/10 text-[#00C48C]'}`}>{isEdit ? '可编辑' : '只读'}</span>
            </h1>
          </div>
          {isEdit && (
            <div className="flex items-center gap-2">
              <button onClick={handleCancel} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"><i className="ri-close-line" />取消</button>
              <button onClick={handleSave} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-blue-600 transition-colors cursor-pointer whitespace-nowrap"><i className="ri-check-line" />保存</button>
            </div>
          )}
        </div>

        {/* Formula hint */}
        <div className="flex items-center gap-4 bg-[#FF7D00]/5 border border-[#FF7D00]/15 rounded-lg px-3 py-2 flex-wrap">
          <span className="text-[11px] text-[#FF7D00]"><i className="ri-calculator-line mr-1" />计算公式：</span>
          <span className="text-[11px] text-[#86909C]">总出清电量 = 市场化燃煤机组出清电量 + 市场化燃气机组出清电量</span>
          <span className="text-[11px] text-[#86909C]">外推燃机出清电力值 = 总出清电量</span>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
          <div className="bg-white rounded-xl border border-[#E5E6EB] p-3">
            <div className="text-[11px] text-[#86909C] mb-1">总出清电量</div>
            <div className="text-sm font-bold text-[#1D2129]">{stats.totalSum.toLocaleString()} <span className="text-[10px] font-normal text-[#86909C]">MWh</span></div>
          </div>
          <div className="bg-white rounded-xl border border-[#E5E6EB] p-3">
            <div className="text-[11px] text-[#86909C] mb-1">燃煤 / 燃气 出清</div>
            <div className="text-sm font-bold text-[#1D2129]">{stats.coalSum.toLocaleString()} / {stats.gasSum.toLocaleString()} <span className="text-[10px] font-normal text-[#86909C]">MWh</span></div>
          </div>
          <div className="bg-white rounded-xl border border-[#E5E6EB] p-3">
            <div className="text-[11px] text-[#86909C] mb-1">加权均价</div>
            <div className="text-sm font-bold text-[#FF7D00]">{stats.avgPrice.toLocaleString()} <span className="text-[10px] font-normal text-[#86909C]">元/MWh</span></div>
          </div>
          <div className="bg-white rounded-xl border border-[#E5E6EB] p-3">
            <div className="text-[11px] text-[#86909C] mb-1">最大/最小 出清</div>
            <div className="text-sm font-bold text-[#1D2129]">{stats.totalMax.toLocaleString()} / {stats.totalMin.toLocaleString()} <span className="text-[10px] font-normal text-[#86909C]">MW</span></div>
          </div>
        </div>

        {/* Chart */}
        <div className="bg-white rounded-xl border border-[#E5E6EB] p-4">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-bold text-[#1D2129]">燃机出清电量与电价分时曲线（96点段）</h3>
            <div className="flex items-center gap-3 text-xs">
              <span className="flex items-center gap-1"><span className="w-3 h-2 bg-[#165DFF] rounded-sm" />燃煤出清</span>
              <span className="flex items-center gap-1"><span className="w-3 h-2 bg-[#FF7D00] rounded-sm" />燃气出清</span>
              <span className="flex items-center gap-1"><span className="w-3 h-1 bg-[#00C48C] rounded-full" />加权电价</span>
            </div>
          </div>
          <ResponsiveContainer width="100%" height={280}>
            <ComposedChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
              <XAxis dataKey="time" tick={{ fontSize: 10, fill: '#86909C' }} interval={11} axisLine={{ stroke: '#E5E6EB' }} tickLine={false} />
              <YAxis yAxisId="power" tick={{ fontSize: 10, fill: '#165DFF' }} axisLine={{ stroke: '#165DFF' }} tickLine={false} width={60} />
              <YAxis yAxisId="price" orientation="right" tick={{ fontSize: 10, fill: '#00C48C' }} axisLine={{ stroke: '#00C48C' }} tickLine={false} width={50} />
              <Tooltip contentStyle={{ fontSize: 12, borderRadius: 8, backgroundColor: '#fff', border: '1px solid #E5E6EB', color: '#1D2129', padding: '8px 12px' }} />
              <Legend wrapperStyle={{ fontSize: 12 }} />
              <Bar yAxisId="power" dataKey="coalUnitQty" stackId="a" fill="#165DFF" name="燃煤出清" />
              <Bar yAxisId="power" dataKey="gasUnitQty" stackId="a" fill="#FF7D00" name="燃气出清" />
              <Line yAxisId="price" type="monotone" dataKey="weightedPrice" stroke="#00C48C" strokeWidth={1.5} dot={false} activeDot={{ r: 3 }} name="加权电价" />
            </ComposedChart>
          </ResponsiveContainer>
        </div>

        {/* 96-point table */}
        <div className="bg-white rounded-xl border border-[#E5E6EB] p-4">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-bold text-[#1D2129]">燃机出清分时明细（96点段）</h3>
            {isEdit && (
              <div className="flex items-center gap-2">
                <button onClick={() => setShowBatchPanel(v => !v)} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">
                  <i className={`ri-${showBatchPanel ? 'close' : 'checkbox-multiple'}-line`} />{showBatchPanel ? '关闭批量' : '批量修改'}
                </button>
                <span className="text-[11px] text-[#86909C]">已选 {selectedPoints.size} 个时段</span>
              </div>
            )}
          </div>

          {isEdit && showBatchPanel && (
            <div className="flex items-center gap-3 mb-4 p-3 bg-[#F7F8FA] rounded-lg flex-wrap">
              <span className="text-xs text-[#4E5969]">批量设置：</span>
              <select value={batchField} onChange={(e) => setBatchField(e.target.value as typeof batchField)} className="text-xs px-2 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]">
                {editableFields.map(f => (
                  <option key={f.key} value={f.key}>{f.label}</option>
                ))}
              </select>
              <input type="number" step={batchField === 'coalUnitCount' || batchField === 'gasUnitCount' ? '1' : '0.1'} value={batchValue} onChange={(e) => { setBatchValue(e.target.value); setBatchError(''); }} placeholder="数值" className="w-24 text-xs px-2 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]" />
              <span className="text-[10px] text-[#86909C]">{editableFields.find(f => f.key === batchField)?.unit}</span>
              <button onClick={applyBatchEdit} className="flex items-center gap-1 px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-blue-600 transition-colors cursor-pointer whitespace-nowrap"><i className="ri-check-line" />一键应用</button>
              {batchError && <span className="text-[11px] text-[#F53F3F]">{batchError}</span>}
            </div>
          )}

          <div className="overflow-x-auto" style={{ overflowX: 'auto' }}>
            <table className="w-full text-xs" style={{ minWidth: 'max-content' }}>
              <thead>
                <tr className="border-b border-[#E5E6EB] bg-[#F7F8FA]">
                  {isEdit && showBatchPanel && (
                    <th className="text-center py-2 px-2 font-medium text-[#86909C] w-8 sticky left-0 bg-[#F7F8FA] z-10">
                      <input type="checkbox" checked={selectedPoints.size === 96} onChange={selectAllPoints} className="cursor-pointer" />
                    </th>
                  )}
                  <th className="text-center py-2 px-2 font-medium text-[#86909C] sticky left-0 bg-[#F7F8FA] z-10">序号</th>
                  <th className="text-center py-2 px-2 font-medium text-[#86909C] sticky left-0 bg-[#F7F8FA] z-10">时点</th>
                  <th className="text-right py-2 px-2 font-medium text-[#86909C]">总出清电量 (MW)</th>
                  {editableFields.map(f => (
                    <th key={f.key} className="text-right py-2 px-2 font-medium text-[#86909C]">{f.label} ({f.unit})</th>
                  ))}
                  {readOnlyFields.map(f => (
                    <th key={f.key} className="text-right py-2 px-2 font-medium text-[#86909C]">{f.label} ({f.unit})</th>
                  ))}
                  <th className="text-center py-2 px-2 font-medium text-[#86909C]">备用符合需求</th>
                </tr>
              </thead>
              <tbody>
                {points.map((point, idx) => (
                  <tr key={idx} className={`border-b border-[#E5E6EB]/50 ${isEdit && selectedPoints.has(idx) ? 'bg-[#165DFF]/5' : 'hover:bg-[#F7F8FA]/60'}`}>
                    {isEdit && showBatchPanel && (
                      <td className="py-1.5 px-2 text-center sticky left-0 bg-white z-10">
                        <input type="checkbox" checked={selectedPoints.has(idx)} onChange={() => togglePointSelect(idx)} className="cursor-pointer" />
                      </td>
                    )}
                    <td className="py-1.5 px-2 text-center text-[#86909C] sticky left-0 bg-white z-10">{idx + 1}</td>
                    <td className="py-1.5 px-2 text-center text-[#1D2129] whitespace-nowrap sticky left-0 bg-white z-10 font-medium">{point.time}</td>
                    <td className="py-1.5 px-2 text-right text-[#1D2129] font-bold">{point.totalClearing.toLocaleString()}</td>
                    {editableFields.map(f => (
                      <td key={f.key} className="py-1.5 px-2 text-right">
                        {isEdit ? (
                          <div className="flex items-center justify-end gap-1">
                            <input
                              type="number"
                              step={f.key === 'coalUnitCount' || f.key === 'gasUnitCount' ? '1' : '0.1'}
                              value={point[f.key]}
                              onChange={(e) => handleFieldChange(idx, f.key, e.target.value)}
                              className={`${f.width} text-xs px-2 py-1 rounded-md border text-right outline-none focus:border-[#165DFF] ${pointErrors[idx] ? 'border-[#F53F3F] bg-red-50' : 'border-[#E5E6EB] bg-white'} text-[#1D2129]`}
                            />
                            <span className="text-[10px] text-[#86909C]">{f.unit}</span>
                          </div>
                        ) : (
                          <span className="text-[#1D2129] font-medium">{(point[f.key] as number).toLocaleString()}</span>
                        )}
                      </td>
                    ))}
                    {readOnlyFields.map(f => (
                      <td key={f.key} className="py-1.5 px-2 text-right text-[#1D2129] font-medium">
                        {(point[f.key] as number).toLocaleString()}
                        <span className="text-[10px] text-[#86909C] ml-1">{f.unit}</span>
                      </td>
                    ))}
                    <td className="py-1.5 px-2 text-center">
                      <span className={`text-[10px] px-2 py-0.5 rounded-full ${point.reserveMatch === '是' ? 'bg-[#00C48C]/10 text-[#00C48C]' : 'bg-[#F53F3F]/10 text-[#F53F3F]'}`}>{point.reserveMatch}</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {showCancelModal && <ConfirmModal title="确认离开" message="未保存的修改将丢失，是否确认离开？" onConfirm={confirmCancel} onCancel={() => setShowCancelModal(false)} />}
      {showSaveConfirm && <ConfirmModal title="保存确认" message="数据校验通过，确认保存并生效？保存后将同步至上游模块。" onConfirm={confirmSave} onCancel={() => setShowSaveConfirm(false)} />}
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </SpotTradingLayout>
  );
}