import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import SystemNav from './SystemNav';
import ConfirmModal from './ConfirmModal';

interface SystemPageProps {
  systemName: string;
}

export default function SystemPage({ systemName }: SystemPageProps) {
  const navigate = useNavigate();
  const [showLogout, setShowLogout] = useState(false);

  const handleLogout = () => {
    localStorage.removeItem('hn_user');
    setShowLogout(false);
    navigate('/');
  };

  return (
    <div className="min-h-screen bg-gradient-main">
      <SystemNav systemName={systemName} onLogoutClick={() => setShowLogout(true)} />
      <div className="pt-24 flex flex-col items-center justify-center min-h-screen px-4">
        <div className="bg-white rounded-card p-10 md:p-12 shadow-lg text-center max-w-lg">
          <div className="w-16 h-16 bg-hn-blue/10 rounded-full flex items-center justify-center mx-auto mb-6">
            <i className="ri-settings-3-line text-3xl text-hn-blue" />
          </div>
          <h2 className="text-xl font-bold text-hn-text mb-2">{systemName}</h2>
          <p className="text-sm text-hn-text-secondary">该系统正在建设中，敬请期待...</p>
        </div>
      </div>
      {showLogout && (
        <ConfirmModal
          title="确认退出"
          message="确定要退出登录吗？"
          onConfirm={handleLogout}
          onCancel={() => setShowLogout(false)}
        />
      )}
    </div>
  );
}
