function gen(count: number, min: number, max: number): number[] {
  return new Array(count).fill(0).map(() => Number((min + Math.random() * (max - min)).toFixed(3)));
}

function step48(base: number, steps: number[]): number[] {
  const out: number[] = [];
  for (let i = 0; i < 48; i++) {
    const idx = Math.min(Math.floor(i / (48 / steps.length)), steps.length - 1);
    out.push(Number((base + steps[idx]).toFixed(3)));
  }
  return out;
}

