export interface SpotCurvePoint {
  time: string;
  dayAheadQty: number;
  realTimeQty: number;
  dayAheadPrice: number;
  realTimePrice: number;
  avgPrice: number;
}
export const spotCurveData: SpotCurvePoint[] = detailTimeSlots.map((time, i) => {
  const t = i;
  const dayAheadQty = Math.max(0, Number((10 + Math.sin(t/3)*8 + Math.random()*3).toFixed(2)));
  const realTimeQty = Math.max(0, Number((8 + Math.sin(t/3)*6 + Math.random()*4).toFixed(2)));
  const dayAheadPrice = Number((400 + Math.sin(t/2.5)*350 + (t<12?200:-100) + Math.random()*50).toFixed(2));
  const realTimePrice = Number((dayAheadPrice + (Math.random()*60-30)).toFixed(2));
  const avgPrice = Number((dayAheadPrice + realTimePrice)/2 + Math.random()*20-10);
  return { time, dayAheadQty, realTimeQty, dayAheadPrice, realTimePrice, avgPrice };
});

