// 合约电价曲线（上图）
export interface ContractPriceCurvePoint {
  time: string;
  yearPrice: number;
  monthPrice: number;
  tenPrice: number;
  rollingPrice: number;
  contractAvg: number;
  localGreenPrice: number;
}
export const contractPriceCurveData: ContractPriceCurvePoint[] = detailTimeSlots.map((time, i) => {
  const t = i;
  return {
    time,
    yearPrice: Number((-430 + Math.sin(t/6)*5).toFixed(2)),
    monthPrice: Number((-425 + Math.sin(t/5)*8).toFixed(2)),
    tenPrice: t < 20 ? Number((-420 + Math.random()*10).toFixed(2)) : 0,
    rollingPrice: t < 30 ? Number((-415 + Math.random()*15).toFixed(2)) : 0,
    contractAvg: Number((300 + (t>28&&t<35 ? 8000 : 0)).toFixed(2)),
    localGreenPrice: Number((85 + Math.random()*5).toFixed(2)),
  };
});

// 合约电量曲线（下图堆叠面积）
export interface ContractQtyCurvePoint {
  time: string;
  yearQty: number;
  monthQty: number;
  tenQty: number;
  rollingBuyQty: number;
  rollingSellQty: number;
  localGreenQty: number;
}
export const contractQtyCurveData: ContractQtyCurvePoint[] = detailTimeSlots.map((time, i) => {
  const t = i;
  const yearQty = Math.max(0, Number((12 + Math.sin(t/4)*3).toFixed(2)));
  const monthQty = Math.max(0, Number((5 + Math.sin(t/3)*2).toFixed(2)));
  const tenQty = t < 25 ? Math.max(0, Number((1 + Math.random()).toFixed(2))) : 0;
  const rollingBuyQty = t > 30 && t < 40 ? Math.max(0, Number((-15 + Math.random()*5).toFixed(2))) : 0;
  const rollingSellQty = t > 35 && t < 42 ? Math.max(0, Number((-8 + Math.random()*4).toFixed(2))) : 0;
  const localGreenQty = Math.max(0, Number((1.5 + Math.sin(t/5)).toFixed(2)));
  return { time, yearQty, monthQty, tenQty, rollingBuyQty, rollingSellQty, localGreenQty };
});

