export interface DeviationCurvePoint {
  time: string;
  realTimeQty: number;
  excessQty: number;
  priceDiff: number;
}
export const deviationCurveData: DeviationCurvePoint[] = detailTimeSlots.map((time, i) => {
  const t = i;
  const realTimeQty = Number((Math.sin(t/3)*2).toFixed(2));
  const excessQty = Math.max(0, Number((Math.abs(Math.sin(t/2.5)*2.5)).toFixed(2)));
  const priceDiff = Number((-100 + Math.sin(t/2)*200 + (t>20&&t<30?-150:0)).toFixed(2));
  return { time, realTimeQty, excessQty, priceDiff };
});