import { useState } from 'react';
import SpotTradingLayout from '@/pages/spot-trading/components/SpotTradingLayout';
import PositionDetailDrawer from './components/PositionDetailDrawer';
import { positionAnalysisRows } from '@/mocks/positionAnalysisData';

export default function PositionAnalysisPage() {
  const [queryMonth, setQueryMonth] = useState('2026-05');
  const [detailDate, setDetailDate] = useState<string | null>(null);

  const getWeekday = (dateStr: string) => {
    const date = new Date(dateStr);
    const days = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];
    return days[date.getDay()];
  };

  const isHoliday = (dateStr: string) => {
    const date = new Date(dateStr);
    const day = date.getDay();
    return day === 0 || day === 6;
  };

  return (
    <SpotTradingLayout>
      <div className="space-y-4">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-lg font-bold text-[#1D2129]">持仓分析</h1>
            <p className="text-xs text-[#86909C] mt-1">每日全量持仓结构与偏差分析</p>
          </div>
        </div>

        {/* Query Bar */}
        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB] flex items-center gap-4">
          <div className="flex items-center gap-2">
            <span className="text-xs text-[#4E5969]">查询时间</span>
            <input
              type="month"
              value={queryMonth}
              onChange={(e) => setQueryMonth(e.target.value)}
              className="px-3 py-1.5 text-xs border border-[#E5E6EB] rounded bg-white text-[#1D2129] outline-none focus:border-[#165DFF]"
            />
          </div>
          <div className="flex items-center gap-2 text-xs text-[#86909C]">
            <span className="text-[#F53F3F]">周六</span>
            <span>|</span>
            <span>调休放假</span>
            <span>|</span>
            <span>周日</span>
            <span>|</span>
            <span>法定节假日</span>
          </div>
          <div className="flex-1" />
          <div className="flex items-center gap-2">
            <span className="text-xs text-[#86909C]">电量单位：MWh</span>
            <button className="flex items-center gap-1.5 px-3 py-1.5 rounded border border-[#165DFF] text-[#165DFF] text-xs hover:bg-[#165DFF]/5 transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-download-line" />
              导出
            </button>
          </div>
        </div>

        {/* Data Table */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-[11px]">
              <thead>
                <tr className="bg-[#F7F8FA]">
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB] sticky left-0 bg-[#F7F8FA] z-10">序号</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB] sticky left-[40px] bg-[#F7F8FA] z-10">日期</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">年度电量</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">月度电量</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">省内绿电电量</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">省间绿电电量<br/><span className="text-[10px] text-[#86909C]">（不计入合约）</span></th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">中长期<br/>合约电量</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">滚搓<br/>买入电量</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">滚搓<br/>卖出电量</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">滚搓<br/>合约电量</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">事后电量</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">实际电量</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">合约占比</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">现货报量</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">偏差量</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB]">偏差率</th>
                  <th className="text-center py-2.5 px-2 font-medium text-[#1D2129] border-b border-[#E5E6EB] sticky right-0 bg-[#F7F8FA] z-10">操作</th>
                </tr>
              </thead>
              <tbody>
                {positionAnalysisRows.map((row, idx) => (
                  <tr
                    key={row.date}
                    className={`border-b border-[#E5E6EB]/50 ${idx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]/50'} ${isHoliday(row.date) ? 'text-[#F53F3F]' : ''}`}
                  >
                    <td className={`py-2.5 px-2 text-center sticky left-0 z-10 ${idx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]/50'}`}>
                      {idx + 1}
                    </td>
                    <td className={`py-2.5 px-2 text-center sticky left-[40px] z-10 ${idx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]/50'} ${isHoliday(row.date) ? 'text-[#F53F3F]' : 'text-[#1D2129]'}`}>
                      <div className="flex items-center justify-center gap-1">
                        <span>{row.date}</span>
                        <span className="text-[10px] text-[#86909C]">{getWeekday(row.date)}</span>
                      </div>
                    </td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.yearQty}</td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.monthQty}</td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.intraGreenQty}</td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.interGreenQty}</td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.midLongContractQty}</td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.rollingBuyQty}</td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.rollingSellQty}</td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.rollingContractQty}</td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.postEventQty}</td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.actualQty || '-'}</td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.contractRatio}</td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.spotBidQty || '-'}</td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.deviationQty || '-'}</td>
                    <td className="py-2.5 px-2 text-center text-[#4E5969]">{row.deviationRate}</td>
                    <td className={`py-2.5 px-2 text-center sticky right-0 z-10 ${idx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]/50'}`}>
                      <button
                        onClick={() => setDetailDate(row.date)}
                        className="text-[#165DFF] hover:underline cursor-pointer text-[11px] whitespace-nowrap"
                      >
                        详情
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Detail Drawer */}
      {detailDate && (
        <PositionDetailDrawer date={detailDate} onClose={() => setDetailDate(null)} />
      )}
    </SpotTradingLayout>
  );
}