import { useState } from 'react';
import {
  RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis,
  Radar, ResponsiveContainer, Tooltip,
} from 'recharts';
import EnergySalesLayout from '../components/EnergySalesLayout';
import { userPortraitList, portraitConfig } from '@/mocks/energySalesData';

export default function UserPortraitPage() {
  const [selectedUser, setSelectedUser] = useState(userPortraitList[0]);
  const [configOpen, setConfigOpen] = useState(false);

  const radarData = [
    { subject: '合同电量得分', A: selectedUser.contractScore, fullMark: 20 },
    { subject: '用户粘性得分', A: selectedUser.loyaltyScore, fullMark: 18 },
    { subject: '绿电量得分', A: selectedUser.greenScore, fullMark: 18 },
    { subject: '度电收益得分', A: selectedUser.benefitScore, fullMark: 17 },
    { subject: '绿电比例得分', A: selectedUser.greenRatioScore, fullMark: 16 },
    { subject: '偏差比例得分', A: selectedUser.deviationScore, fullMark: 15 },
  ];

  const getRatingColor = (r: string) => {
    if (r.startsWith('A')) return 'text-[#00C48C]';
    if (r.startsWith('B')) return 'text-[#165DFF]';
    return 'text-[#FF7D00]';
  };

  const getRatingBg = (r: string) => {
    if (r.startsWith('A')) return 'bg-[#00C48C]/10';
    if (r.startsWith('B')) return 'bg-[#165DFF]/10';
    return 'bg-[#FF7D00]/10';
  };

  return (
    <EnergySalesLayout>
      <div className="space-y-5 text-[#1D2129]">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">用户画像管理</h1>
            <p className="text-sm text-[#86909C] mt-1">用户综合评分与多维度画像分析</p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setConfigOpen(true)}
              className="flex items-center gap-1.5 px-4 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-settings-3-line" />
              评分配置
            </button>
            <button className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-download-2-line" />
              导出Excel
            </button>
          </div>
        </div>

        {/* User List + Radar Chart */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">
          {/* User List */}
          <div className="bg-white rounded-lg p-5 border border-[#E5E6EB] lg:col-span-1">
            <h3 className="text-sm font-bold text-[#1D2129] mb-4">用户列表</h3>
            <div className="space-y-2 max-h-[500px] overflow-y-auto">
              {userPortraitList.map(user => (
                <button
                  key={user.id}
                  onClick={() => setSelectedUser(user)}
                  className={`w-full flex items-center gap-3 p-3 rounded-lg border text-left transition-all cursor-pointer ${
                    selectedUser.id === user.id
                      ? 'border-[#165DFF] bg-[#165DFF]/5'
                      : 'border-[#E5E6EB] hover:border-[#C9CDD4]'
                  }`}
                >
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-medium text-[#1D2129] truncate">{user.userName}</p>
                    <p className="text-[10px] text-[#86909C] mt-0.5">{user.userType} · {user.hasPpa ? '有PPA' : '无PPA'}</p>
                  </div>
                  <div className="flex items-center gap-2 flex-shrink-0">
                    <span className={`text-sm font-bold ${getRatingColor(user.rating)}`}>{user.totalScore}</span>
                    <span className={`px-2 py-0.5 rounded-full text-[10px] ${getRatingBg(user.rating)} ${getRatingColor(user.rating)}`}>{user.rating}</span>
                  </div>
                </button>
              ))}
            </div>
          </div>

          {/* Radar + Detail */}
          <div className="lg:col-span-2 space-y-5">
            {/* Radar Chart */}
            <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-sm font-bold text-[#1D2129]">{selectedUser.userName} — 多维度得分雷达图</h3>
                <div className="flex items-center gap-2">
                  <span className={`text-lg font-bold ${getRatingColor(selectedUser.rating)}`}>{selectedUser.totalScore}</span>
                  <span className={`px-2 py-0.5 rounded-full text-xs ${getRatingBg(selectedUser.rating)} ${getRatingColor(selectedUser.rating)}`}>{selectedUser.rating}</span>
                </div>
              </div>
              <ResponsiveContainer width="100%" height={320}>
                <RadarChart data={radarData}>
                  <PolarGrid stroke="#E5E6EB" />
                  <PolarAngleAxis dataKey="subject" tick={{ fontSize: 11, fill: '#4E5969' }} />
                  <PolarRadiusAxis angle={30} domain={[0, 20]} tick={{ fontSize: 9, fill: '#86909C' }} />
                  <Radar name="得分" dataKey="A" stroke="#165DFF" fill="#165DFF" fillOpacity={0.25} strokeWidth={2} />
                  <Tooltip contentStyle={{ fontSize: 12, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB' }} />
                </RadarChart>
              </ResponsiveContainer>
            </div>

            {/* Score Breakdown */}
            <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
              <h3 className="text-sm font-bold text-[#1D2129] mb-4">得分明细</h3>
              <div className="grid grid-cols-2 lg:grid-cols-3 gap-4">
                {[
                  { label: '合同电量得分', value: selectedUser.contractScore, weight: portraitConfig.weights.contractScore, desc: '权重' },
                  { label: '用户粘性得分', value: selectedUser.loyaltyScore, weight: portraitConfig.weights.loyaltyScore, desc: '权重' },
                  { label: '绿电量得分', value: selectedUser.greenScore, weight: portraitConfig.weights.greenScore, desc: '权重', enabled: portraitConfig.greenEnabled },
                  { label: '度电收益得分', value: selectedUser.benefitScore, weight: portraitConfig.weights.benefitScore, desc: '权重' },
                  { label: '绿电比例得分', value: selectedUser.greenRatioScore, weight: portraitConfig.weights.greenRatioScore, desc: '权重', enabled: portraitConfig.greenRatioEnabled },
                  { label: '偏差比例得分', value: selectedUser.deviationScore, weight: portraitConfig.weights.deviationScore, desc: '权重' },
                ].map((item) => (
                  <div key={item.label} className="bg-[#F7F8FA] rounded-lg p-4">
                    <div className="flex items-center justify-between mb-2">
                      <span className="text-xs text-[#4E5969]">{item.label}</span>
                      {'enabled' in item && !item.enabled && <span className="text-[10px] px-1.5 py-0.5 bg-[#86909C]/10 text-[#86909C] rounded">已禁用</span>}
                    </div>
                    <div className="flex items-baseline gap-2">
                      <span className="text-xl font-bold text-[#1D2129]">{item.value}</span>
                      <span className="text-[10px] text-[#86909C]">/ {item.weight}分 · {item.desc}</span>
                    </div>
                    <div className="w-full bg-[#E5E6EB] rounded-full h-1.5 mt-2">
                      <div className="bg-[#165DFF] h-1.5 rounded-full" style={{ width: `${(item.value / item.weight) * 100}%` }} />
                    </div>
                  </div>
                ))}
              </div>
              {/* Bonus */}
              <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mt-4">
                {[
                  { label: '品牌效益加分', value: selectedUser.brandBonus },
                  { label: '综合用能服务加分', value: selectedUser.serviceBonus },
                  { label: '框架协议加分', value: selectedUser.agreementBonus },
                  { label: '用户推荐加分', value: selectedUser.recommendBonus },
                ].map(b => (
                  <div key={b.label} className="bg-[#F7F8FA] rounded-lg p-3 text-center">
                    <p className="text-[10px] text-[#86909C]">{b.label}</p>
                    <p className="text-lg font-bold text-[#00C48C] mt-1">+{b.value}</p>
                  </div>
                ))}
              </div>
            </div>

            {/* Key Metrics */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
              {[
                { label: '现货比例', value: `${selectedUser.spotRatio}%`, icon: 'ri-percent-line' },
                { label: '绿电量', value: `${selectedUser.greenVolume} MWh`, icon: 'ri-leaf-line' },
                { label: '绿电比例', value: `${selectedUser.greenRatio}%`, icon: 'ri-bar-chart-grouped-line' },
                { label: '用户类型', value: selectedUser.userType, icon: 'ri-building-line' },
              ].map(m => (
                <div key={m.label} className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
                  <div className="flex items-center gap-2 mb-2">
                    <i className={`${m.icon} text-[#165DFF] text-sm`} />
                    <span className="text-xs text-[#86909C]">{m.label}</span>
                  </div>
                  <p className="text-base font-bold text-[#1D2129]">{m.value}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Config Modal */}
      {configOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
          <div className="bg-white rounded-lg w-[500px] p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-base font-bold text-[#1D2129]">用户画像评分配置</h3>
              <button onClick={() => setConfigOpen(false)} className="p-1 text-[#86909C] hover:text-[#1D2129] cursor-pointer"><i className="ri-close-line text-lg" /></button>
            </div>
            <div className="space-y-4">
              <div>
                <h4 className="text-sm font-medium text-[#1D2129] mb-3">维度权重配置</h4>
                {Object.entries(portraitConfig.weights).map(([key, value]) => (
                  <div key={key} className="flex items-center justify-between py-2">
                    <span className="text-xs text-[#4E5969]">{key === 'contractScore' ? '合同电量得分' : key === 'loyaltyScore' ? '用户粘性得分' : key === 'greenScore' ? '绿电量得分' : key === 'benefitScore' ? '度电收益得分' : key === 'greenRatioScore' ? '绿电比例得分' : '偏差比例得分'}</span>
                    <div className="flex items-center gap-2">
                      <input type="range" min={0} max={30} value={value} className="w-24" readOnly />
                      <span className="text-xs font-medium w-8 text-right">{value}%</span>
                    </div>
                  </div>
                ))}
              </div>
              <div>
                <h4 className="text-sm font-medium text-[#1D2129] mb-3">启用配置</h4>
                <div className="flex items-center justify-between py-2">
                  <span className="text-xs text-[#4E5969]">绿电量得分参与计算</span>
                  <div className={`w-10 h-5 rounded-full relative cursor-pointer ${portraitConfig.greenEnabled ? 'bg-[#165DFF]' : 'bg-[#E5E6EB]'}`}>
                    <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full shadow transition-all ${portraitConfig.greenEnabled ? 'left-5' : 'left-0.5'}`} />
                  </div>
                </div>
                <div className="flex items-center justify-between py-2">
                  <span className="text-xs text-[#4E5969]">绿电比例得分参与计算</span>
                  <div className={`w-10 h-5 rounded-full relative cursor-pointer ${portraitConfig.greenRatioEnabled ? 'bg-[#165DFF]' : 'bg-[#E5E6EB]'}`}>
                    <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full shadow transition-all ${portraitConfig.greenRatioEnabled ? 'left-5' : 'left-0.5'}`} />
                  </div>
                </div>
              </div>
            </div>
            <div className="flex justify-end gap-2 mt-6">
              <button onClick={() => setConfigOpen(false)} className="px-4 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] cursor-pointer">取消</button>
              <button onClick={() => setConfigOpen(false)} className="px-4 py-2 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/90 cursor-pointer">保存配置</button>
            </div>
          </div>
        </div>
      )}
    </EnergySalesLayout>
  );
}