import { useState, useMemo, useCallback } from 'react';
import SpotTradingLayout from '@/pages/spot-trading/components/SpotTradingLayout';
import { reserveInfoDailyData, type ReserveInfoPoint } from '@/mocks/dataMgmtData';
import ConfirmModal from '@/components/ConfirmModal';
import Toast from '@/components/Toast';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
} from 'recharts';

const TIME_POINTS = Array.from({ length: 96 }, (_, i) => {
  const hour = Math.floor(i / 4);
  const minute = (i % 4) * 15;
  return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
});

function getInitialPoints(date: string): ReserveInfoPoint[] {
  const found = reserveInfoDailyData.find(d => d.date === date);
  if (found) return found.points.map(p => ({ ...p }));
  return TIME_POINTS.map(time => ({ time, powerValue: 0, clearingPrice: 0 }));
}

export default function ReservePage() {
  const [searchDate, setSearchDate] = useState('2026-05-07');
  const [isEdit, setIsEdit] = useState(false);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [showCancelConfirm, setShowCancelConfirm] = useState(false);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);
  const [errors, setErrors] = useState<Record<number, string>>({});

  const [points, setPoints] = useState<ReserveInfoPoint[]>(() => getInitialPoints('2026-05-07'));
  const [hasChanges, setHasChanges] = useState(false);

  // Batch edit
  const [selectedPoints, setSelectedPoints] = useState<Set<number>>(new Set());
  const [batchField, setBatchField] = useState<'powerValue'>('powerValue');
  const [batchValue, setBatchValue] = useState('');
  const [batchError, setBatchError] = useState('');
  const [showBatchPanel, setShowBatchPanel] = useState(false);

  const currentRecord = useMemo(() => {
    return reserveInfoDailyData.find(d => d.date === searchDate) || reserveInfoDailyData[0];
  }, [searchDate]);

  const handleQuery = () => {
    const found = reserveInfoDailyData.find(d => d.date === searchDate);
    if (!found) {
      setToast({ message: `未找到 ${searchDate} 的备用信息数据`, type: 'error' });
      return;
    }
    setPoints(found.points.map(p => ({ ...p })));
    setIsEdit(false);
    setErrors({});
    setSelectedPoints(new Set());
    setHasChanges(false);
  };

  const validate = (val: number): string | null => {
    if (val < 0) return '不可为负数';
    return null;
  };

  const handleFieldChange = useCallback((index: number, field: keyof ReserveInfoPoint, valueStr: string) => {
    const val = parseFloat(valueStr);
    if (isNaN(val)) return;
    const err = validate(val);
    setErrors(prev => {
      const next = { ...prev };
      if (err) next[index] = err;
      else delete next[index];
      return next;
    });
    setPoints(prev => {
      const next = [...prev];
      next[index] = { ...next[index], [field]: val };
      return next;
    });
    setHasChanges(true);
  }, []);

  const togglePointSelect = (index: number) => {
    setSelectedPoints(prev => {
      const next = new Set(prev);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      return next;
    });
  };

  const selectAllPoints = () => {
    if (selectedPoints.size === 96) {
      setSelectedPoints(new Set());
    } else {
      setSelectedPoints(new Set(Array.from({ length: 96 }, (_, i) => i)));
    }
  };

  const applyBatchEdit = () => {
    const val = parseFloat(batchValue);
    if (isNaN(val)) { setBatchError('请输入有效数值'); return; }
    if (val < 0) { setBatchError('不可为负数'); return; }
    if (selectedPoints.size === 0) { setBatchError('请先勾选至少一个时段'); return; }
    setBatchError('');
    setPoints(prev => {
      const next = [...prev];
      selectedPoints.forEach(idx => {
        next[idx] = { ...next[idx], [batchField]: val };
      });
      return next;
    });
    setErrors(prev => {
      const next = { ...prev };
      selectedPoints.forEach(idx => delete next[idx]);
      return next;
    });
    setHasChanges(true);
    setToast({ message: `已成功批量修改 ${selectedPoints.size} 个时段`, type: 'success' });
  };

  const handleSave = () => {
    if (Object.keys(errors).length > 0) {
      setToast({ message: '数据校验未通过，请检查红色提示', type: 'error' });
      return;
    }
    setShowSaveConfirm(true);
  };

  const confirmSave = () => {
    setIsEdit(false);
    setShowSaveConfirm(false);
    setHasChanges(false);
    setSelectedPoints(new Set());
    setShowBatchPanel(false);
    setToast({ message: '保存成功，数据已同步至上游模块', type: 'success' });
  };

  const handleCancel = () => {
    if (isEdit && hasChanges) {
      setShowCancelConfirm(true);
    } else {
      setIsEdit(false);
      handleQuery();
    }
  };

  const confirmCancel = () => {
    const found = reserveInfoDailyData.find(d => d.date === searchDate) || reserveInfoDailyData[0];
    setPoints(found.points.map(p => ({ ...p })));
    setIsEdit(false);
    setErrors({});
    setSelectedPoints(new Set());
    setShowBatchPanel(false);
    setHasChanges(false);
    setShowCancelConfirm(false);
  };

  const handleEdit = () => { setIsEdit(true); };

  const handleExport = () => { setToast({ message: '导出成功：备用信息明细', type: 'success' }); };
  const handleImport = () => { setToast({ message: 'Excel导入功能暂未接入后端', type: 'error' }); };
  const handleTemplateDownload = () => { setToast({ message: '模板下载成功', type: 'success' }); };

  // Stats
  const stats = useMemo(() => {
    const powers = points.map(p => p.powerValue);
    const prices = points.map(p => p.clearingPrice);
    return {
      totalPower: Math.round(powers.reduce((s, v) => s + v, 0)),
      maxPower: Math.max(...powers),
      minPower: Math.min(...powers),
      avgPower: Math.round(powers.reduce((s, v) => s + v, 0) / powers.length * 10) / 10,
      avgPrice: Math.round(prices.reduce((s, v) => s + v, 0) / prices.length * 10) / 10,
      maxPrice: Math.max(...prices),
      minPrice: Math.min(...prices),
    };
  }, [points]);

  // Chart data
  const chartData = useMemo(() =>
    points.map((p, idx) => ({ idx: idx + 1, time: p.time, powerValue: p.powerValue, clearingPrice: p.clearingPrice })),
    [points]
  );

  return (
    <SpotTradingLayout>
      <div className="w-full max-w-full space-y-4">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-lg font-bold text-[#1D2129]">备用信息维护</h1>
            <p className="text-xs text-[#86909C] mt-1">备用电力值与出清价格 96点15分钟粒度维护</p>
          </div>
        </div>

        {/* Filter & Status */}
        <div className="bg-white rounded-xl p-4 border border-[#E5E6EB]">
          <div className="flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-2">
              <span className="text-xs text-[#86909C]">日期</span>
              <input type="date" value={searchDate} onChange={(e) => setSearchDate(e.target.value)} className="text-xs px-2.5 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]" />
            </div>
            <button onClick={handleQuery} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-blue-600 transition-colors cursor-pointer whitespace-nowrap"><i className="ri-search-line" />查询</button>

            <div className="ml-auto flex items-center gap-3">
              <span className="text-xs text-[#86909C]">当前日期：</span>
              <span className="text-xs font-medium text-[#1D2129]">{currentRecord.date}</span>
              <span className={`text-[10px] px-2 py-0.5 rounded-full ${isEdit ? 'bg-[#FF7D00]/10 text-[#FF7D00]' : 'bg-[#165DFF]/10 text-[#165DFF]'}`}>{isEdit ? '编辑中' : '只读'}</span>
              <span className={`text-[10px] px-2 py-0.5 rounded-full ${currentRecord.dataSource === '系统同步' ? 'bg-[#165DFF]/10 text-[#165DFF]' : 'bg-[#FF7D00]/10 text-[#FF7D00]'}`}>{currentRecord.dataSource}</span>
            </div>
          </div>
        </div>

        {/* Actions */}
        <div className="flex items-center gap-2">
          {!isEdit ? (
            <button onClick={handleEdit} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#FF7D00]/15 text-[#FF7D00] text-xs hover:bg-amber-100 transition-colors cursor-pointer whitespace-nowrap"><i className="ri-edit-line" />编辑</button>
          ) : (
            <>
              <button onClick={handleSave} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#00C48C]/15 text-[#00C48C] text-xs hover:bg-emerald-100 transition-colors cursor-pointer whitespace-nowrap"><i className="ri-save-line" />保存</button>
              <button onClick={handleCancel} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"><i className="ri-close-line" />取消</button>
            </>
          )}
          <button onClick={handleImport} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF]/15 text-[#165DFF] text-xs hover:bg-[#165DFF]/25 transition-colors cursor-pointer whitespace-nowrap"><i className="ri-file-upload-line" />Excel导入</button>
          <button onClick={handleExport} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF]/15 text-[#165DFF] text-xs hover:bg-[#165DFF]/25 transition-colors cursor-pointer whitespace-nowrap"><i className="ri-download-line" />导出</button>
          <button onClick={handleTemplateDownload} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"><i className="ri-file-list-line" />模板下载</button>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
          <div className="bg-white rounded-xl border border-[#E5E6EB] p-3">
            <div className="text-[11px] text-[#86909C] mb-1">电力值总量</div>
            <div className="text-sm font-bold text-[#1D2129]">{stats.totalPower.toLocaleString()} <span className="text-[10px] font-normal text-[#86909C]">MW</span></div>
          </div>
          <div className="bg-white rounded-xl border border-[#E5E6EB] p-3">
            <div className="text-[11px] text-[#86909C] mb-1">电力值 均/最大/最小</div>
            <div className="text-sm font-bold text-[#1D2129]">{stats.avgPower.toLocaleString()} / {stats.maxPower.toLocaleString()} / {stats.minPower.toLocaleString()} <span className="text-[10px] font-normal text-[#86909C]">MW</span></div>
          </div>
          <div className="bg-white rounded-xl border border-[#E5E6EB] p-3">
            <div className="text-[11px] text-[#86909C] mb-1">出清均价</div>
            <div className="text-sm font-bold text-[#FF7D00]">{stats.avgPrice.toLocaleString()} <span className="text-[10px] font-normal text-[#86909C]">元/MWh</span></div>
          </div>
          <div className="bg-white rounded-xl border border-[#E5E6EB] p-3">
            <div className="text-[11px] text-[#86909C] mb-1">出清价格 最大/最小</div>
            <div className="text-sm font-bold text-[#1D2129]">{stats.maxPrice.toLocaleString()} / {stats.minPrice.toLocaleString()} <span className="text-[10px] font-normal text-[#86909C]">元/MWh</span></div>
          </div>
        </div>

        {/* Chart */}
        <div className="bg-white rounded-xl border border-[#E5E6EB] p-4">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-bold text-[#1D2129]">备用信息与价格分时曲线（96点段）</h3>
            <div className="flex items-center gap-3 text-xs">
              <span className="flex items-center gap-1"><span className="w-3 h-1 bg-[#165DFF] rounded-full" />电力值 (MW)</span>
              <span className="flex items-center gap-1"><span className="w-3 h-1 bg-[#FF7D00] rounded-full" />出清价格 (元/MWh)</span>
            </div>
          </div>
          <ResponsiveContainer width="100%" height={260}>
            <LineChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
              <XAxis dataKey="time" tick={{ fontSize: 10, fill: '#86909C' }} interval={11} axisLine={{ stroke: '#E5E6EB' }} tickLine={false} />
              <YAxis yAxisId="power" tick={{ fontSize: 10, fill: '#165DFF' }} axisLine={{ stroke: '#165DFF' }} tickLine={false} width={50} />
              <YAxis yAxisId="price" orientation="right" tick={{ fontSize: 10, fill: '#FF7D00' }} axisLine={{ stroke: '#FF7D00' }} tickLine={false} width={50} />
              <Tooltip contentStyle={{ fontSize: 12, borderRadius: 8, backgroundColor: '#fff', border: '1px solid #E5E6EB', color: '#1D2129', padding: '8px 12px' }} />
              <Legend wrapperStyle={{ fontSize: 12 }} />
              <Line yAxisId="power" type="monotone" dataKey="powerValue" stroke="#165DFF" strokeWidth={1.5} dot={false} activeDot={{ r: 3 }} name="电力值" />
              <Line yAxisId="price" type="monotone" dataKey="clearingPrice" stroke="#FF7D00" strokeWidth={1.5} dot={false} activeDot={{ r: 3 }} name="出清价格" />
            </LineChart>
          </ResponsiveContainer>
        </div>

        {/* 96-point table */}
        <div className="bg-white rounded-xl border border-[#E5E6EB] p-4">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-bold text-[#1D2129]">备用信息分时明细（96点段）</h3>
            {isEdit && (
              <div className="flex items-center gap-2">
                <button onClick={() => setShowBatchPanel(v => !v)} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">
                  <i className={`ri-${showBatchPanel ? 'close' : 'checkbox-multiple'}-line`} />{showBatchPanel ? '关闭批量' : '批量修改'}
                </button>
                <span className="text-[11px] text-[#86909C]">已选 {selectedPoints.size} 个时段</span>
              </div>
            )}
          </div>

          {isEdit && showBatchPanel && (
            <div className="flex items-center gap-3 mb-4 p-3 bg-[#F7F8FA] rounded-lg flex-wrap">
              <span className="text-xs text-[#4E5969]">批量设置：</span>
              <select value={batchField} onChange={(e) => setBatchField(e.target.value as typeof batchField)} className="text-xs px-2 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]">
                <option value="powerValue">电力值</option>
              </select>
              <input type="number" value={batchValue} onChange={(e) => { setBatchValue(e.target.value); setBatchError(''); }} placeholder="数值" className="w-24 text-xs px-2 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]" />
              <span className="text-[10px] text-[#86909C]">{batchField === 'powerValue' ? 'MW' : '元/MWh'}</span>
              <button onClick={applyBatchEdit} className="flex items-center gap-1 px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-blue-600 transition-colors cursor-pointer whitespace-nowrap"><i className="ri-check-line" />一键应用</button>
              {batchError && <span className="text-[11px] text-[#F53F3F]">{batchError}</span>}
            </div>
          )}

          <div className="overflow-x-auto" style={{ overflowX: 'auto' }}>
            <table className="w-full text-xs" style={{ minWidth: 'max-content' }}>
              <thead>
                <tr className="border-b border-[#E5E6EB] bg-[#F7F8FA]">
                  {isEdit && showBatchPanel && (
                    <th className="text-center py-2 px-2 font-medium text-[#86909C] w-8 sticky left-0 bg-[#F7F8FA] z-10">
                      <input type="checkbox" checked={selectedPoints.size === 96} onChange={selectAllPoints} className="cursor-pointer" />
                    </th>
                  )}
                  <th className="text-center py-2 px-2 font-medium text-[#86909C] sticky left-0 bg-[#F7F8FA] z-10">序号</th>
                  <th className="text-center py-2 px-2 font-medium text-[#86909C] sticky left-0 bg-[#F7F8FA] z-10">时点</th>
                  <th className="text-right py-2 px-3 font-medium text-[#86909C]">电力值 (MW)</th>
                  <th className="text-right py-2 px-3 font-medium text-[#86909C]">出清价格 (元/MWh)</th>
                </tr>
              </thead>
              <tbody>
                {points.map((point, idx) => (
                  <tr key={idx} className={`border-b border-[#E5E6EB]/50 ${isEdit && selectedPoints.has(idx) ? 'bg-[#165DFF]/5' : 'hover:bg-[#F7F8FA]/60'}`}>
                    {isEdit && showBatchPanel && (
                      <td className="py-1.5 px-2 text-center sticky left-0 bg-white z-10">
                        <input type="checkbox" checked={selectedPoints.has(idx)} onChange={() => togglePointSelect(idx)} className="cursor-pointer" />
                      </td>
                    )}
                    <td className="py-1.5 px-2 text-center text-[#86909C] sticky left-0 bg-white z-10">{idx + 1}</td>
                    <td className="py-1.5 px-2 text-center text-[#1D2129] whitespace-nowrap sticky left-0 bg-white z-10 font-medium">{point.time}</td>
                    <td className="py-1.5 px-3 text-right">
                      {isEdit ? (
                        <div className="flex items-center justify-end gap-1">
                          <input type="number" step="0.1" value={point.powerValue} onChange={(e) => handleFieldChange(idx, 'powerValue', e.target.value)} className={`w-24 text-xs px-2 py-1 rounded-md border text-right outline-none focus:border-[#165DFF] ${errors[idx] ? 'border-[#F53F3F] bg-red-50' : 'border-[#E5E6EB] bg-white'} text-[#1D2129]`} />
                          <span className="text-[10px] text-[#86909C]">MW</span>
                        </div>
                      ) : (
                        <span className="text-[#1D2129] font-medium">{point.powerValue.toLocaleString()}</span>
                      )}
                    </td>
                    <td className="py-1.5 px-3 text-right text-[#1D2129] font-medium">
                      {point.clearingPrice.toLocaleString()}
                      <span className="text-[10px] text-[#86909C] ml-1">元</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {showSaveConfirm && <ConfirmModal title="确认保存" message="保存后数据将同步至上游计算公式，是否确认？" onConfirm={confirmSave} onCancel={() => setShowSaveConfirm(false)} />}
      {showCancelConfirm && <ConfirmModal title="确认取消" message="未保存的修改将丢失，是否确认取消？" onConfirm={confirmCancel} onCancel={() => setShowCancelConfirm(false)} />}
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </SpotTradingLayout>
  );
}