import { useState } from 'react';
import EnergySalesLayout from '../components/EnergySalesLayout';
import ConfirmModal from '@/components/ConfirmModal';
import { userInfoList, type UserInfo } from '@/mocks/energySalesData';

export default function UserInfoPage() {
  const [searchName, setSearchName] = useState('');
  const [searchCredit, setSearchCredit] = useState('');
  const [filterStatus, setFilterStatus] = useState<'all' | 'active' | 'inactive'>('all');
  const [showDelete, setShowDelete] = useState(false);
  const [deleteId, setDeleteId] = useState<number | null>(null);
  const [showAdd, setShowAdd] = useState(false);
  const [showEdit, setShowEdit] = useState(false);
  const [editData, setEditData] = useState<UserInfo | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  const filtered = userInfoList.filter(u => {
    const nameMatch = !searchName || u.name.includes(searchName);
    const creditMatch = !searchCredit || u.creditCode.includes(searchCredit);
    const statusMatch = filterStatus === 'all' || u.status === filterStatus;
    return nameMatch && creditMatch && statusMatch;
  });

  const totalPages = Math.ceil(filtered.length / pageSize);
  const paged = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const getStatusStyle = (s: string) => {
    return s === 'active'
      ? 'bg-[#00C48C]/10 text-[#00C48C]'
      : 'bg-[#F53F3F]/10 text-[#F53F3F]';
  };

  const getSyncStyle = (s: string) => {
    switch (s) {
      case 'synced': return 'bg-[#00C48C]/10 text-[#00C48C]';
      case 'pending': return 'bg-[#FF7D00]/10 text-[#FF7D00]';
      default: return 'bg-[#F53F3F]/10 text-[#F53F3F]';
    }
  };

  const handleDelete = (id: number) => {
    setDeleteId(id);
    setShowDelete(true);
  };

  const confirmDelete = () => {
    if (deleteId) {
      // In real app, call API
    }
    setShowDelete(false);
    setDeleteId(null);
  };

  return (
    <EnergySalesLayout>
      <div className="space-y-5 text-[#1D2129]">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">用户信息管理</h1>
            <p className="text-sm text-[#86909C] mt-1">零售用户信息维护与同步管理</p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setShowAdd(true)}
              className="flex items-center gap-1.5 px-4 py-2 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/90 transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-add-line" />
              新增用户
            </button>
            <button className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-upload-2-line" />
              批量导入
            </button>
            <button className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-download-2-line" />
              导出Excel
            </button>
          </div>
        </div>

        {/* Filter */}
        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">用户名称</label>
              <input
                type="text"
                value={searchName}
                onChange={e => setSearchName(e.target.value)}
                placeholder="请输入用户名称"
                className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[180px]"
              />
            </div>
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">统一社会信用代码</label>
              <input
                type="text"
                value={searchCredit}
                onChange={e => setSearchCredit(e.target.value)}
                placeholder="请输入信用代码"
                className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[200px]"
              />
            </div>
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">用户状态</label>
              <select
                value={filterStatus}
                onChange={e => setFilterStatus(e.target.value as 'all' | 'active' | 'inactive')}
                className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[120px]"
              >
                <option value="all">全部</option>
                <option value="active">启用</option>
                <option value="inactive">禁用</option>
              </select>
            </div>
            <button className="flex items-center gap-1.5 px-4 py-2 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/90 transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-search-line" />
              查询
            </button>
            <button
              onClick={() => { setSearchName(''); setSearchCredit(''); setFilterStatus('all'); }}
              className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-refresh-line" />
              重置
            </button>
          </div>
        </div>

        {/* Table */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#F7F8FA]">
                <tr>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-0 bg-[#F7F8FA] z-10">序号</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-[48px] bg-[#F7F8FA] z-10">用户名称</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">信用代码</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">对接人A</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">对接人B</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">合作方式</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">集团标记</th>
                  <th className="px-4 py-3 text-center font-medium text-[#4E5969]">状态</th>
                  <th className="px-4 py-3 text-center font-medium text-[#4E5969]">同步状态</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">创建时间</th>
                  <th className="px-4 py-3 text-center font-medium text-[#4E5969] sticky right-0 bg-[#F7F8FA] z-10">操作</th>
                </tr>
              </thead>
              <tbody>
                {paged.map((user, idx) => (
                  <tr key={user.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : ''}`}>
                    <td className="px-4 py-3 sticky left-0 bg-white z-10">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="px-4 py-3 sticky left-[48px] bg-white z-10 font-medium">{user.name}</td>
                    <td className="px-4 py-3 text-[#4E5969]">{user.creditCode}</td>
                    <td className="px-4 py-3 text-[#4E5969]">{user.contactA}</td>
                    <td className="px-4 py-3 text-[#4E5969]">{user.contactB || '-'}</td>
                    <td className="px-4 py-3 text-[#4E5969]">{user.cooperation}</td>
                    <td className="px-4 py-3">
                      {user.groupTag ? (
                        <span className="px-2 py-0.5 bg-[#165DFF]/10 text-[#165DFF] rounded-full text-[10px]">{user.groupTag}</span>
                      ) : '-'}
                    </td>
                    <td className="px-4 py-3 text-center">
                      <span className={`px-2 py-0.5 rounded-full text-[10px] ${getStatusStyle(user.status)}`}>
                        {user.status === 'active' ? '启用' : '禁用'}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-center">
                      <span className={`px-2 py-0.5 rounded-full text-[10px] ${getSyncStyle(user.syncStatus)}`}>
                        {user.syncStatus === 'synced' ? '已同步' : user.syncStatus === 'pending' ? '待同步' : '同步失败'}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-[#86909C]">{user.createTime}</td>
                    <td className="px-4 py-3 text-center sticky right-0 bg-white z-10">
                      <div className="flex items-center gap-1 justify-center">
                        <button
                          onClick={() => { setEditData(user); setShowEdit(true); }}
                          className="p-1 text-[#165DFF] hover:bg-[#165DFF]/10 rounded transition-colors cursor-pointer"
                          title="编辑"
                        >
                          <i className="ri-edit-line" />
                        </button>
                        <button
                          onClick={() => handleDelete(user.id)}
                          className="p-1 text-[#F53F3F] hover:bg-[#F53F3F]/10 rounded transition-colors cursor-pointer"
                          title="删除"
                        >
                          <i className="ri-delete-bin-line" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          <div className="flex items-center justify-between px-4 py-3 border-t border-[#E5E6EB]">
            <span className="text-xs text-[#86909C]">共 {filtered.length} 条，每页 {pageSize} 条</span>
            <div className="flex items-center gap-1">
              <button
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"
              >
                <i className="ri-arrow-left-s-line" />
              </button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
                <button
                  key={p}
                  onClick={() => setCurrentPage(p)}
                  className={`px-3 py-1 text-xs rounded cursor-pointer ${
                    p === currentPage ? 'bg-[#165DFF] text-white' : 'border border-[#E5E6EB] hover:border-[#165DFF]'
                  }`}
                >
                  {p}
                </button>
              ))}
              <button
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
                className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"
              >
                <i className="ri-arrow-right-s-line" />
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Delete Confirm */}
      {showDelete && (
        <ConfirmModal
          title="确认删除"
          message="删除用户后将无法恢复，是否确认删除？"
          onConfirm={confirmDelete}
          onCancel={() => { setShowDelete(false); setDeleteId(null); }}
        />
      )}
    </EnergySalesLayout>
  );
}