interface ConfirmModalProps {
  title: string;
  message: string;
  onConfirm: () => void;
  onCancel: () => void;
  children?: React.ReactNode;
  showCancel?: boolean;
  confirmText?: string;
  cancelText?: string;
}

export default function ConfirmModal({
  title,
  message,
  onConfirm,
  onCancel,
  children,
  showCancel = true,
  confirmText = '确认',
  cancelText = '取消',
}: ConfirmModalProps) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
      <div className="bg-white rounded-lg p-6 w-full max-w-lg mx-4 shadow-xl animate-scale-in max-h-[85vh] overflow-auto">
        {title && (
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-base font-bold text-[#1D2129]">{title}</h3>
            <button onClick={onCancel} className="w-7 h-7 flex items-center justify-center rounded hover:bg-[#F7F8FA] cursor-pointer">
              <i className="ri-close-line text-[#86909C]" />
            </button>
          </div>
        )}
        {message && <p className="text-sm text-[#86909C] mb-4">{message}</p>}
        {children && <div className="mb-4">{children}</div>}
        <div className="flex gap-3 justify-end">
          {showCancel && (
            <button
              onClick={onCancel}
              className="px-4 py-2 rounded-md border border-[#E5E6EB] text-sm text-[#1D2129] hover:bg-[#F7F8FA] transition-colors whitespace-nowrap cursor-pointer"
            >
              {cancelText}
            </button>
          )}
          <button
            onClick={onConfirm}
            className="px-4 py-2 rounded-md bg-[#165DFF] text-white text-sm hover:bg-[#165DFF]/80 transition-colors whitespace-nowrap cursor-pointer"
          >
            {confirmText}
          </button>
        </div>
      </div>
    </div>
  );
}
