import { useState } from 'react';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
} from 'recharts';
import type { TimePoint } from '@/hooks/useBidDecisionData';
import ConfirmModal from '@/components/ConfirmModal';

interface CombinedAnalysisChartProps {
  data: TimePoint[];
}

export default function CombinedAnalysisChart({ data }: CombinedAnalysisChartProps) {
  const [showFullscreen, setShowFullscreen] = useState(false);
  const [hiddenLines, setHiddenLines] = useState<Set<string>>(new Set());

  const toggleLine = (key: string) => {
    setHiddenLines(prev => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  };

  const chartContent = (h: number | string) => (
    <ResponsiveContainer width="100%" height={h}>
      <LineChart data={data} margin={{ top: 5, right: 20, left: 10, bottom: 5 }}>
        <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
        <XAxis dataKey="time" tick={{ fontSize: 9, fill: '#64748B' }} interval={7} />
        <YAxis
          yAxisId="diff"
          tick={{ fontSize: 10, fill: '#64748B' }}
          label={{ value: '价差(元/MWh)', angle: -90, position: 'insideLeft', style: { fontSize: 10, fill: '#64748B' } }}
        />
        <YAxis
          yAxisId="prob"
          orientation="right"
          domain={[0, 100]}
          tick={{ fontSize: 10, fill: '#64748B' }}
          label={{ value: '概率(%)', angle: 90, position: 'insideRight', style: { fontSize: 10, fill: '#64748B' } }}
        />
        <YAxis
          yAxisId="qty"
          orientation="right"
          domain={[0, 20]}
          tick={{ fontSize: 10, fill: '#64748B' }}
          label={{ value: '电量(MWh)', angle: 90, position: 'insideRight', style: { fontSize: 10, fill: '#64748B' } }}
        />
        <Tooltip
          contentStyle={{ fontSize: 10, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB', color: '#1D2129' }}
          formatter={(value: number, name: string) => {
            if (name === '日前大于实时价差概率') return [`${Number(value).toFixed(1)}%`, name];
            if (['真实价差', '预测价差'].includes(name)) return [`${Number(value).toFixed(2)} 元/MWh`, name];
            return [`${Number(value).toFixed(3)} MWh`, name];
          }}
        />
        <Legend
          wrapperStyle={{ fontSize: 10, color: '#94A3B8' }}
          onClick={(e: any) => toggleLine(e.dataKey)}
        />

        {/* 价差曲线 — 左侧Y轴 */}
        {!hiddenLines.has('diffReal') && (
          <Line yAxisId="diff" type="monotone" dataKey="diffReal" stroke="#F44336" strokeWidth={1.5} dot={false} name="真实价差" />
        )}
        {!hiddenLines.has('diffForecast') && (
          <Line yAxisId="diff" type="monotone" dataKey="diffForecast" stroke="#2196F3" strokeWidth={1.5} dot={false} strokeDasharray="5 3" name="预测价差" />
        )}

        {/* 概率 — 右侧Y轴(prob) */}
        {!hiddenLines.has('probDiff') && (
          <Line yAxisId="prob" type="monotone" dataKey="probDiff" stroke="#4CAF50" strokeWidth={1.5} dot={false} name="日前大于实时价差概率" />
        )}

        {/* 电量曲线 — 右侧Y轴(qty) */}
        {!hiddenLines.has('daBid') && (
          <Line yAxisId="qty" type="monotone" dataKey="daBid" stroke="#FF9800" strokeWidth={1.5} dot={false} name="日前申报电量" />
        )}
        {!hiddenLines.has('actualUse') && (
          <Line yAxisId="qty" type="monotone" dataKey="actualUse" stroke="#9C27B0" strokeWidth={1.5} dot={false} name="实际用电量" />
        )}
        {!hiddenLines.has('actual80') && (
          <Line yAxisId="qty" type="monotone" dataKey="actual80" stroke="#00BCD4" strokeWidth={1} dot={false} strokeDasharray="4 4" name="实际用电量*80%" />
        )}
        {!hiddenLines.has('actual120') && (
          <Line yAxisId="qty" type="monotone" dataKey="actual120" stroke="#E91E63" strokeWidth={1} dot={false} strokeDasharray="4 4" name="实际用电量*120%" />
        )}
      </LineChart>
    </ResponsiveContainer>
  );

  return (
    <div className="bg-white rounded-lg border border-[#E5E6EB] p-4 mb-4">
      <div className="flex items-center justify-between mb-2">
        <h3 className="text-sm font-bold text-[#1D2129]">实时-日前价差与电量综合分析</h3>
        <div className="flex items-center gap-3 text-[#86909C]">
          <span className="flex items-center gap-1 text-xs cursor-pointer hover:text-[#94A3B8]">
            <i className="ri-download-line" />导出
          </span>
          <span onClick={() => setShowFullscreen(true)} className="flex items-center gap-1 text-xs cursor-pointer hover:text-[#94A3B8]">
            <i className="ri-fullscreen-line" />放大
          </span>
        </div>
      </div>
      <p className="text-xs text-[#86909C] mb-2">价差、概率与电量多维度综合展示</p>

      <div className="h-[320px]">
        {chartContent(320)}
      </div>

      <p className="text-[10px] text-[#86909C] mt-1 text-right">点击图例可隐藏/显示曲线 · 拖动底部滑块缩放时间轴</p>

      {showFullscreen && (
        <ConfirmModal title="" message="" onConfirm={() => setShowFullscreen(false)} onCancel={() => setShowFullscreen(false)} showCancel={false} confirmText="关闭">
          <div className="w-full h-[60vh] min-h-[400px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="text-base font-bold text-[#1D2129]">实时-日前价差与电量综合分析</h3>
              <button onClick={() => setShowFullscreen(false)} className="w-8 h-8 flex items-center justify-center rounded hover:bg-[#F7F8FA] cursor-pointer">
                <i className="ri-close-line text-[#86909C]" />
              </button>
            </div>
            {chartContent('100%')}
          </div>
        </ConfirmModal>
      )}
    </div>
  );
}