// =================== 备用信息 ===================
export interface ReserveInfoPoint {
  time: string;
  powerValue: number; // 电力值(MW)
  clearingPrice: number; // 出清价格(元/MWh)
}

export interface ReserveInfoDaily {
  date: string;
  points: ReserveInfoPoint[];
  dataSource: '系统同步' | '人工修改';
  updatedAt: string;
  updatedBy: string;
}

function genReserveInfoPoints(): ReserveInfoPoint[] {
  const points: ReserveInfoPoint[] = [];
  for (let i = 0; i < 96; i++) {
    const hour = Math.floor(i / 4);
    const minute = (i % 4) * 15;
    const time = `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
    // Peak hours have higher reserve requirement
    const isPeak = hour >= 9 && hour <= 21;
    const basePower = isPeak ? 450 + Math.random() * 100 : 200 + Math.random() * 80;
    const basePrice = isPeak ? 380 + Math.random() * 60 : 280 + Math.random() * 40;
    points.push({
      time,
      powerValue: Math.round(basePower * 10) / 10,
      clearingPrice: Math.round(basePrice * 10) / 10,
    });
  }
  return points;
}

