function genReservePoints(baseTotal: number, variance: number): number[] {
  const points: number[] = [];
  for (let i = 0; i < 96; i++) {
    const hour = Math.floor(i / 4);
    const isPeak = hour >= 9 && hour <= 21;
    const peakMultiplier = isPeak ? 1.1 : 0.85;
    const val = Math.round((baseTotal / 96) * peakMultiplier + (Math.random() - 0.5) * variance);
    points.push(Math.max(0, val));
  }
  return points;
}

function sum(arr: number[]): number {
  return Math.round(arr.reduce((a, b) => a + b, 0));
}

function calcMax(arr: number[]): number {
  return Math.max(...arr);
}

function calcAvg(arr: number[]): number {
  return Math.round(sum(arr) / arr.length);
}

