function genGasUnitPoints(capacity: number, baseLoad: number): number[] {
  const points: number[] = [];
  for (let i = 0; i < 96; i++) {
    const hour = Math.floor(i / 4);
    const isPeak = hour >= 9 && hour <= 21;
    const peakMul = isPeak ? 0.88 : 0.55;
    const val = Math.round(baseLoad * peakMul * capacity + (Math.random() - 0.5) * 30);
    points.push(Math.max(0, Math.min(Math.round(capacity), val)));
  }
  return points;
}

function genGasUnitPrices(): number[] {
  const points: number[] = [];
  for (let i = 0; i < 96; i++) {
    const hour = Math.floor(i / 4);
    const isPeak = hour >= 9 && hour <= 21;
    const base = isPeak ? 480 : 380;
    const val = Math.round(base + (Math.random() - 0.5) * 40);
    points.push(Math.max(200, Math.min(500, val)));
  }
  return points;
}

