export function getGasClearingDetail(date: string, marketType: '日前' | '日内' = '日前'): GasClearingDetail {
  const units: GasUnitData[] = GAS_UNIT_NAMES.map((name, idx) => ({
    name,
    capacity: GAS_UNIT_CAPACITIES[idx],
    points: genGasUnitPoints(GAS_UNIT_CAPACITIES[idx], 0.7 + Math.random() * 0.15),
    prices: genGasUnitPrices(),
  }));
  return {
    date,
    marketType,
    units,
    dataSource: '系统同步',
    updatedAt: `${date} 10:05`,
    updatedBy: '系统',
  };
}

