import { useState, useCallback, useMemo } from 'react';

export interface TimePoint {
  time: string;
  i: number;
  diffReal: number;
  diffForecast: number;
  probDiff: number;
  daPrice: number;
  rtClearing: number;
  daClearing: number;
  daBid: number;
  actualUse: number;
  actual80: number;
  actual120: number;
  recoveryFee: number;
  recoveryQty: number;
  fee: number;
  forecastLoad: number;
  operator: '+' | '-' | '*' | '/';
  coefficient: number;
  calcBid: number;
  myClearingQty: number;
  myClearingPrice: number;
  marketClearingQty: number;
  marketClearingPrice: number;
  deviationQty: number;
  deviationPrice: number;
}

export function isTradingDay(dateStr: string): boolean {
  const d = new Date(dateStr);
  const day = d.getDay();
  if (day === 0 || day === 6) return false;
  const month = d.getMonth() + 1;
  const date = d.getDate();
  const holidays = [
    '01-01', '05-01', '05-02', '05-03', '10-01', '10-02', '10-03',
    '10-04', '10-05', '10-06', '10-07',
  ];
  const md = `${month.toString().padStart(2, '0')}-${date.toString().padStart(2, '0')}`;
  return !holidays.includes(md);
}

export function getNextTradingDay(base: string): string {
  let d = new Date(base);
  d.setDate(d.getDate() + 1);
  while (!isTradingDay(d.toISOString().split('T')[0])) {
    d.setDate(d.getDate() + 1);
  }
  return d.toISOString().split('T')[0];
}

export function getPrevTradingDay(base: string): string {
  let d = new Date(base);
  d.setDate(d.getDate() - 1);
  while (!isTradingDay(d.toISOString().split('T')[0])) {
    d.setDate(d.getDate() - 1);
  }
  return d.toISOString().split('T')[0];
}

export function gen96Points(seed: number): TimePoint[] {
  const data: TimePoint[] = [];
  for (let i = 0; i < 96; i++) {
    const h = Math.floor(i / 4);
    const m = (i % 4) * 15;
    const t = `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
    const baseLoad = 800 + Math.sin((i - 20) * 0.08) * 500 + (i > 32 && i < 72 ? 300 : 0);
    const load = Math.round(baseLoad + Math.random() * 40 - 20);
    const daBid = Math.round((load * (0.85 + Math.random() * 0.15)) / 100) / 10;
    data.push({
      time: t,
      i,
      diffReal: Math.round(Math.sin((i - 30 + seed) * 0.06) * 60 + (Math.random() - 0.5) * 15),
      diffForecast: Math.round(Math.sin((i - 28 + seed) * 0.06) * 55 + (Math.random() - 0.5) * 12),
      probDiff: Math.max(0, Math.min(100, 50 + Math.sin((i - 26 + seed) * 0.06) * 35 + (Math.random() - 0.5) * 8)),
      daPrice: Math.round(360 + Math.sin((i - 30 + seed) * 0.06) * 60 + (Math.random() - 0.5) * 20),
      rtClearing: Math.round(350 + Math.sin((i - 28 + seed) * 0.06) * 70 + (Math.random() - 0.5) * 25),
      daClearing: Math.round(370 + Math.sin((i - 32 + seed) * 0.06) * 50 + (Math.random() - 0.5) * 18),
      daBid: Math.round(daBid * 1000) / 1000,
      actualUse: Math.round((daBid + (Math.random() - 0.5) * 1.5) * 1000) / 1000,
      actual80: Math.round(daBid * 0.8 * 1000) / 1000,
      actual120: Math.round(daBid * 1.2 * 1000) / 1000,
      recoveryFee: Math.round(Math.max(0, (daBid - (daBid + (Math.random() - 0.5) * 1.5)) * 15)),
      recoveryQty: Math.round(Math.max(0, daBid - (daBid + (Math.random() - 0.5) * 1.5)) * 10) / 10,
      fee: Math.round(Math.max(0, (daBid - (daBid + (Math.random() - 0.5) * 1.5)) * 360)),
      forecastLoad: load,
      coefficient: 0.92,
      operator: '*' as const,
      calcBid: Math.round(load * 0.92) / 100,
      myClearingQty: Math.round((daBid + (Math.random() - 0.5) * 0.3) * 100) / 100,
      myClearingPrice: Math.round(360 + Math.sin((i - 30 + seed) * 0.06) * 60 + (Math.random() - 0.5) * 20),
      marketClearingQty: Math.round((daBid + (Math.random() - 0.5) * 0.5) * 100) / 100,
      marketClearingPrice: Math.round(355 + Math.sin((i - 28 + seed) * 0.06) * 65 + (Math.random() - 0.5) * 22),
      deviationQty: Math.round(((Math.random() - 0.5) * 0.8) * 100) / 100,
      deviationPrice: Math.round(((Math.random() - 0.5) * 15) * 100) / 100,
    });
  }
  return data;
}

export function getTradingDaysInMonth(year: number, month: number): number[] {
  const days: number[] = [];
  const d = new Date(year, month - 1, 1);
  while (d.getMonth() === month - 1) {
    const ds = d.toISOString().split('T')[0];
    if (isTradingDay(ds)) days.push(d.getDate());
    d.setDate(d.getDate() + 1);
  }
  return days;
}

export function useBidDecisionData() {
  const today = new Date().toISOString().split('T')[0];
  const defaultDate = getPrevTradingDay(today);

  const [targetDate, setTargetDate] = useState(defaultDate);

  const chartData = useMemo(() => {
    const seed = new Date(targetDate).getTime() % 1000;
    return gen96Points(seed);
  }, [targetDate]);

  const [coefficients, setCoefficients] = useState<Record<string, number[]>>();
  const [operators, setOperators] = useState<Record<string, Array<'+' | '-' | '*' | '/'>>>();
  const [hasUnsavedCoeffs, setHasUnsavedCoeffs] = useState(false);

  const savedCoeffs = coefficients?.[targetDate] || new Array(96).fill(0.92);
  const savedOperators = operators?.[targetDate] || new Array(96).fill('*');

  const dataWithCoeff = useMemo(() => {
    return chartData.map((p, idx) => {
      const coeff = savedCoeffs[idx];
      const op = savedOperators[idx];
      let calcBid: number;
      switch (op) {
        case '+': calcBid = Math.round((p.forecastLoad + coeff) * 100) / 100; break;
        case '-': calcBid = Math.round((p.forecastLoad - coeff) * 100) / 100; break;
        case '/': calcBid = coeff !== 0 ? Math.round((p.forecastLoad / coeff) * 100) / 100 : 0; break;
        case '*':
        default: calcBid = Math.round(p.forecastLoad * coeff) / 100; break;
      }
      return {
        ...p,
        coefficient: coeff,
        operator: op,
        calcBid,
      };
    });
  }, [chartData, savedCoeffs, savedOperators]);

  const updateCoefficient = useCallback((idx: number, value: number) => {
    setHasUnsavedCoeffs(true);
    setCoefficients(prev => {
      const copy = { ...prev };
      if (!copy[targetDate]) copy[targetDate] = new Array(96).fill(0.92);
      copy[targetDate] = [...copy[targetDate]];
      copy[targetDate][idx] = value;
      return copy;
    });
  }, [targetDate]);

  const updateOperator = useCallback((idx: number, value: '+' | '-' | '*' | '/') => {
    setHasUnsavedCoeffs(true);
    setOperators(prev => {
      const copy = { ...prev };
      if (!copy[targetDate]) copy[targetDate] = new Array(96).fill('*');
      copy[targetDate] = [...copy[targetDate]];
      copy[targetDate][idx] = value;
      return copy;
    });
  }, [targetDate]);

  const saveCoefficients = useCallback(() => {
    setHasUnsavedCoeffs(false);
  }, []);

  return {
    targetDate,
    setTargetDate,
    chartData: dataWithCoeff,
    coefficients: savedCoeffs,
    hasUnsavedCoeffs,
    updateCoefficient,
    updateOperator,
    saveCoefficients,
  };
}
