import { useState, useMemo } from 'react';
import AdminLayout from '../../components/AdminLayout';
import { systemLogs } from '@/mocks/adminData';

export default function SystemLogPage() {
  const [filterLevel, setFilterLevel] = useState('全部');
  const [filterModule, setFilterModule] = useState('全部');
  const [searchMsg, setSearchMsg] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  const levels = ['全部', '错误', '警告', '信息', '调试'];
  const modules = ['全部', '数据同步', '用户认证', '系统调度', '系统监控', '交易引擎', '系统启动', '数据备份', '用户会话'];

  const levelMap: Record<string, string> = { '错误': 'error', '警告': 'warn', '信息': 'info', '调试': 'debug' };

  const filteredLogs = useMemo(() => {
    let result = systemLogs;
    if (filterLevel !== '全部') result = result.filter(l => l.level === levelMap[filterLevel]);
    if (filterModule !== '全部') result = result.filter(l => l.module === filterModule);
    if (searchMsg) result = result.filter(l => l.message.includes(searchMsg) || (l.traceId && l.traceId.includes(searchMsg)));
    return result;
  }, [filterLevel, filterModule, searchMsg]);

  const totalPages = Math.ceil(filteredLogs.length / pageSize);
  const pagedLogs = filteredLogs.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const getLevelStyle = (level: string) => {
    switch (level) {
      case 'error': return 'bg-[#F53F3F]/10 text-[#F53F3F]';
      case 'warn': return 'bg-[#FF7D00]/10 text-[#FF7D00]';
      case 'info': return 'bg-[#00B4FF]/10 text-[#00B4FF]';
      case 'debug': return 'bg-[#86909C]/10 text-[#86909C]';
      default: return 'bg-[#F7F8FA] text-[#86909C]';
    }
  };

  const getLevelLabel = (level: string) => {
    switch (level) {
      case 'error': return '错误';
      case 'warn': return '警告';
      case 'info': return '信息';
      case 'debug': return '调试';
      default: return level;
    }
  };

  const exportLogs = () => {
    const csv = [
      ['序号', '时间', '日志级别', '模块', '日志内容', 'TraceID'],
      ...filteredLogs.map((l, i) => [i + 1, l.time, getLevelLabel(l.level), l.module, l.message, l.traceId || '-']),
    ].map(row => row.join(',')).join('\n');
    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `系统运行日志_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  };

  return (
    <AdminLayout>
      <div className="space-y-4 text-[#1D2129]">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">系统运行日志</h1>
            <p className="text-sm text-[#86909C] mt-1">系统接口调用、数据同步、异常报错日志，快速定位系统问题</p>
          </div>
          <button onClick={exportLogs} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">
            <i className="ri-download-line" />
            导出
          </button>
        </div>

        {/* Filter */}
        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex flex-wrap items-end gap-3">
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">日志级别</label>
              <select value={filterLevel} onChange={e => setFilterLevel(e.target.value)} className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[100px] bg-white">
                {levels.map(l => <option key={l} value={l}>{l}</option>)}
              </select>
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">系统模块</label>
              <select value={filterModule} onChange={e => setFilterModule(e.target.value)} className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[140px] bg-white">
                {modules.map(m => <option key={m} value={m}>{m}</option>)}
              </select>
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">搜索内容/TraceID</label>
              <input type="text" value={searchMsg} onChange={e => setSearchMsg(e.target.value)} placeholder="请输入关键词" className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[200px]" />
            </div>
            <div className="flex gap-2 ml-auto">
              <button onClick={() => { setFilterLevel('全部'); setFilterModule('全部'); setSearchMsg(''); }} className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">重置</button>
              <button onClick={() => setCurrentPage(1)} className="px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/80 transition-colors cursor-pointer whitespace-nowrap">查询</button>
            </div>
          </div>
        </div>

        {/* Table */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#F7F8FA] sticky top-0">
                <tr>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">序号</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">时间</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">级别</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">模块</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">日志内容</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">TraceID</th>
                </tr>
              </thead>
              <tbody>
                {pagedLogs.map((log, idx) => (
                  <tr key={log.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : 'bg-white'}`}>
                    <td className="px-3 py-3 text-[#4E5969]">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="px-3 py-3 text-[#86909C]">{log.time}</td>
                    <td className="px-3 py-3">
                      <span className={`text-[10px] px-2 py-0.5 rounded-full ${getLevelStyle(log.level)}`}>
                        {getLevelLabel(log.level)}
                      </span>
                    </td>
                    <td className="px-3 py-3 text-[#4E5969]">{log.module}</td>
                    <td className="px-3 py-3 text-[#1D2129]">{log.message}</td>
                    <td className="px-3 py-3 text-[#86909C] font-mono">{log.traceId || '-'}</td>
                  </tr>
                ))}
                {pagedLogs.length === 0 && <tr><td colSpan={6} className="px-3 py-8 text-center text-[#86909C]">暂无数据</td></tr>}
              </tbody>
            </table>
          </div>
          <div className="flex items-center justify-between px-3 py-3 border-t border-[#E5E6EB]">
            <span className="text-xs text-[#86909C]">共 {filteredLogs.length} 条，每页 {pageSize} 条</span>
            <div className="flex items-center gap-1">
              <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="px-2 py-1 rounded text-xs border border-[#E5E6EB] hover:bg-[#F7F8FA] disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer">上一页</button>
              {Array.from({ length: Math.min(5, totalPages) }, (_, i) => (
                <button key={i + 1} onClick={() => setCurrentPage(i + 1)} className={`w-7 h-7 rounded text-xs cursor-pointer ${currentPage === i + 1 ? 'bg-[#165DFF] text-white' : 'border border-[#E5E6EB] hover:bg-[#F7F8FA]'}`}>{i + 1}</button>
              ))}
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages || totalPages === 0} className="px-2 py-1 rounded text-xs border border-[#E5E6EB] hover:bg-[#F7F8FA] disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer">下一页</button>
            </div>
          </div>
        </div>
      </div>
    </AdminLayout>
  );
}