import { useState, useMemo, useCallback } from 'react';
import SpotTradingLayout from '@/pages/spot-trading/components/SpotTradingLayout';
import CurveChart from './components/CurveChart';
import AddReferenceModal from './components/AddReferenceModal';
import {
  referenceDays, predictionResult, dayTypeMap, weekDayMap,
  type ReferenceDay,
} from '@/mocks/consumptionForecastData';

function buildCurveData(selectedDates: string[], predictionData: number[], labels: string[]) {
  const colors = ['#2196F3', '#4CAF50', '#FF9800', '#F44336', '#9C27B0', '#00BCD4', '#795548', '#607D8B'];
  const series: { key: string; label: string; color: string; dash?: string; data: number[] }[] = [];

  selectedDates.forEach((date, idx) => {
    const day = referenceDays.find(d => d.date === date);
    if (day) {
      series.push({
        key: `ref_${date}`,
        label: date,
        color: colors[idx % colors.length],
        dash: '5 5',
        data: day.halfHourly,
      });
    }
  });

  series.push({
    key: 'prediction',
    label: '预测电量',
    color: '#F44336',
    data: predictionData,
  });

  return series;
}

export default function ConsumptionForecastPage() {
  const [predictionDate, setPredictionDate] = useState('2026-05-07');
  const [refDays, setRefDays] = useState(4);
  const [maxTempDiff, setMaxTempDiff] = useState(5);
  const [minTempDiff, setMinTempDiff] = useState(5);
  const [dayType, setDayType] = useState<'all' | 'workday' | 'rest' | 'saturday' | 'sunday' | 'holiday'>('all');
  const [adjustedDates, setAdjustedDates] = useState<string[]>([
    '2026-04-30', '2026-04-29', '2026-04-27', '2026-04-20', '2026-04-10', '2026-04-09',
  ]);
  const [modalVisible, setModalVisible] = useState(false);
  const [selectedRows, setSelectedRows] = useState<Set<string>>(new Set());
  const [deleteConfirm, setDeleteConfirm] = useState<{ visible: boolean; dates: string[] }>({ visible: false, dates: [] });

  const halfHourLabels = useMemo(() => {
    const arr: string[] = [];
    for (let i = 0; i < 48; i++) {
      const hour = Math.floor(i / 2);
      const minute = (i % 2) * 30;
      arr.push(`${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`);
    }
    return arr;
  }, []);

  const filteredDays = useMemo(() => {
    let list = referenceDays;
    if (dayType !== 'all') {
      list = list.filter(d => {
        if (dayType === 'workday') return d.dayType === 'workday';
        if (dayType === 'rest') return d.dayType === 'rest';
        if (dayType === 'holiday') return d.dayType === 'holiday';
        if (dayType === 'saturday') {
          const wd = weekDayMap[d.date];
          return wd === '周六';
        }
        if (dayType === 'sunday') {
          const wd = weekDayMap[d.date];
          return wd === '周日';
        }
        return true;
      });
    }
    // Filter by temp diff
    list = list.filter(d => {
      const pMax = predictionResult.maxTemp;
      const pMin = predictionResult.minTemp;
      return Math.abs(d.maxTemp - pMax) <= maxTempDiff && Math.abs(d.minTemp - pMin) <= minTempDiff;
    });
    return list;
  }, [dayType, maxTempDiff, minTempDiff]);

  const activeDates = adjustedDates;

  const adjustedCurveSeries = useMemo(() => {
    const remainingDays = referenceDays.filter(d => adjustedDates.includes(d.date));
    let avgData: number[];
    if (remainingDays.length === 0) {
      avgData = new Array(48).fill(0);
    } else {
      avgData = new Array(48).fill(0);
      for (let i = 0; i < 48; i++) {
        let sum = 0;
        remainingDays.forEach(d => { sum += d.halfHourly[i]; });
        avgData[i] = Math.round(sum / remainingDays.length);
      }
    }
    return buildCurveData(adjustedDates, avgData, halfHourLabels);
  }, [adjustedDates, halfHourLabels]);

  const handleAddReference = useCallback((dates: string[]) => {
    setAdjustedDates(dates);
  }, []);

  const handleDeleteReference = useCallback((date: string) => {
    setDeleteConfirm({ visible: true, dates: [date] });
  }, []);

  const confirmDelete = useCallback(() => {
    setAdjustedDates(prev => prev.filter(d => !deleteConfirm.dates.includes(d)));
    setSelectedRows(prev => {
      const next = new Set(prev);
      deleteConfirm.dates.forEach(d => next.delete(d));
      return next;
    });
    setDeleteConfirm({ visible: false, dates: [] });
  }, [deleteConfirm.dates]);

  const cancelDelete = useCallback(() => {
    setDeleteConfirm({ visible: false, dates: [] });
  }, []);

  const toggleRowSelection = useCallback((date: string) => {
    setSelectedRows(prev => {
      const next = new Set(prev);
      if (next.has(date)) next.delete(date);
      else next.add(date);
      return next;
    });
  }, []);

  const toggleSelectAllRows = useCallback(() => {
    const allSelected = adjustedDates.every(d => selectedRows.has(d));
    if (allSelected) {
      setSelectedRows(new Set());
    } else {
      setSelectedRows(new Set(adjustedDates));
    }
  }, [adjustedDates, selectedRows]);

  const handleBatchDelete = useCallback(() => {
    const selected = adjustedDates.filter(d => selectedRows.has(d));
    if (selected.length > 0) {
      setDeleteConfirm({ visible: true, dates: selected });
    }
  }, [adjustedDates, selectedRows]);

  const dayTypeTabs: { key: typeof dayType; label: string }[] = [
    { key: 'all', label: '全部' },
    { key: 'workday', label: '工作日' },
    { key: 'rest', label: '调休/上班' },
    { key: 'saturday', label: '周六' },
    { key: 'sunday', label: '周日' },
    { key: 'holiday', label: '法定节假日' },
  ];

  return (
    <SpotTradingLayout>
      <div className="space-y-4">
        {/* Breadcrumb */}
        <div className="flex items-center gap-1.5 text-xs text-[#86909C]">
          <span className="hover:text-[#1D2129] cursor-pointer">首页</span>
          <i className="ri-arrow-right-s-line text-[#86909C]" />
          <span className="hover:text-[#1D2129] cursor-pointer">用电量预测与报量策略</span>
          <i className="ri-arrow-right-s-line text-[#86909C]" />
          <span className="text-[#1D2129] font-medium">用电量预测</span>
        </div>

        {/* Top Control Bar */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] p-4">
          <div className="flex flex-wrap items-center gap-4">
            {/* Prediction Date */}
            <div className="flex items-center gap-2">
              <span className="text-xs text-[#86909C] whitespace-nowrap">预测日选择</span>
              <div className="flex items-center gap-1.5 border border-[#E5E6EB] rounded px-2 py-1">
                <i className="ri-calendar-line text-[#86909C] text-xs" />
                <input
                  type="date"
                  value={predictionDate}
                  onChange={e => setPredictionDate(e.target.value)}
                  className="text-xs text-[#86909C] outline-none bg-transparent w-28"
                />
              </div>
            </div>

            {/* Reference Days */}
            <div className="flex items-center gap-2">
              <span className="text-xs text-[#86909C] whitespace-nowrap">参考日数</span>
              <input
                type="number"
                value={refDays}
                onChange={e => setRefDays(Number(e.target.value))}
                className="text-xs px-2 py-1.5 w-12 rounded border border-[#E5E6EB] bg-white text-[#1D2129] outline-none text-center"
              />
            </div>

            {/* Temp Diff */}
            <div className="flex items-center gap-2">
              <span className="text-xs text-[#F53F3F] whitespace-nowrap">* 最高温差</span>
              <input
                type="number"
                value={maxTempDiff}
                onChange={e => setMaxTempDiff(Number(e.target.value))}
                className="text-xs px-2 py-1.5 w-12 rounded border border-[#E5E6EB] bg-white text-[#1D2129] outline-none text-center"
              />
              <span className="text-xs text-[#86909C]">°C</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-xs text-[#F53F3F] whitespace-nowrap">* 最低温差</span>
              <input
                type="number"
                value={minTempDiff}
                onChange={e => setMinTempDiff(Number(e.target.value))}
                className="text-xs px-2 py-1.5 w-12 rounded border border-[#E5E6EB] bg-white text-[#1D2129] outline-none text-center"
              />
              <span className="text-xs text-[#86909C]">°C</span>
            </div>

            {/* Predict Button */}
            <button className="ml-auto px-5 py-1.5 rounded bg-[#165DFF] text-[#1D2129] text-xs hover:bg-[#165DFF]/80 transition-colors cursor-pointer whitespace-nowrap">
              预测
            </button>
          </div>
        </div>

        {/* Summary Row */}
        <div className="flex flex-wrap items-center gap-6 text-xs">
          <div className="flex items-center gap-2">
            <span className="text-[#165DFF]">日期：</span>
            <span className="text-[#1D2129]">{predictionDate}</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-[#165DFF]">天气：</span>
            <span className="text-[#1D2129]">{predictionResult.weather}</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-[#165DFF]">平均温度（°C）：</span>
            <span className="text-[#1D2129]">{predictionResult.avgTemp.toFixed(2)}</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-[#165DFF]">最高温度（°C）：</span>
            <span className="text-[#1D2129]">{predictionResult.maxTemp.toFixed(2)}</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-[#165DFF]">最低温度（°C）：</span>
            <span className="text-[#1D2129]">{predictionResult.minTemp.toFixed(2)}</span>
          </div>
        </div>

        {/* Day Type Tabs */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-1 bg-[#F7F8FA] rounded-md p-0.5">
            {dayTypeTabs.map(tab => (
              <button
                key={tab.key}
                onClick={() => setDayType(tab.key)}
                className={`px-3 py-1.5 text-xs rounded transition-colors cursor-pointer whitespace-nowrap ${
                  dayType === tab.key
                    ? 'bg-[#165DFF]/10 text-[#165DFF] shadow-sm font-medium'
                    : 'text-[#86909C] hover:text-[#1D2129]'
                }`}
              >
                {tab.label}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-2 text-xs text-[#86909C]">
            <span>计量单位：°C, kWh</span>
            <button
              onClick={() => setModalVisible(true)}
              className="flex items-center gap-1 px-3 py-1.5 rounded border border-[#165DFF]/40 text-[#165DFF] hover:bg-[#165DFF]/10 transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-add-line" />
              增选
            </button>
            <button className="flex items-center gap-1 px-3 py-1.5 rounded bg-[#165DFF] text-[#1D2129] hover:bg-[#165DFF]/80 transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-check-line" />
              保存
            </button>
          </div>
        </div>

        {/* Data Table */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="px-4 py-3 border-b border-[#E5E6EB] flex items-center justify-between">
            <div className="flex items-center gap-2">
              <div className="w-6 h-6 flex items-center justify-center">
                <i className="ri-table-line text-[#165DFF] text-sm" />
              </div>
              <h3 className="text-sm font-bold text-[#1D2129]">参考日列表</h3>
              <span className="text-[10px] px-2 py-0.5 rounded-full bg-[#165DFF]/10 text-[#165DFF]">
                {adjustedDates.length} 天
              </span>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-xs text-[#86909C]">
                已选择 <span className="text-[#165DFF] font-bold">{selectedRows.size}</span> 项
              </span>
              <button
                onClick={toggleSelectAllRows}
                className="text-xs text-[#165DFF] hover:text-[#00B4FF] cursor-pointer whitespace-nowrap"
              >
                {adjustedDates.length > 0 && adjustedDates.every(d => selectedRows.has(d)) ? '取消全选' : '全选'}
              </button>
              <button
                onClick={handleBatchDelete}
                disabled={selectedRows.size === 0}
                className={`flex items-center gap-1 px-3 py-1.5 rounded text-xs transition-colors cursor-pointer whitespace-nowrap ${
                  selectedRows.size > 0
                    ? 'bg-[#F53F3F] text-white hover:bg-[#F53F3F]/80'
                    : 'bg-[#F2F3F5] text-[#86909C] cursor-not-allowed'
                }`}
              >
                <i className="ri-delete-bin-line" />
                批量删除
              </button>
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-[11px]">
              <thead>
                <tr className="border-b border-[#334155] bg-[#F7F8FA]">
                  <th className="py-2.5 px-3 text-center w-10">
                    <input
                      type="checkbox"
                      checked={adjustedDates.length > 0 && adjustedDates.every(d => selectedRows.has(d))}
                      onChange={toggleSelectAllRows}
                      className="cursor-pointer"
                    />
                  </th>
                  <th className="py-2.5 px-3 text-left font-medium text-[#94A3B8] whitespace-nowrap">日期</th>
                  <th className="py-2.5 px-3 text-left font-medium text-[#94A3B8] whitespace-nowrap">天气</th>
                  <th className="py-2.5 px-3 text-right font-medium text-[#94A3B8] whitespace-nowrap">相似指数</th>
                  <th className="py-2.5 px-3 text-right font-medium text-[#94A3B8] whitespace-nowrap">日均温</th>
                  <th className="py-2.5 px-3 text-right font-medium text-[#94A3B8] whitespace-nowrap">最高温</th>
                  <th className="py-2.5 px-3 text-right font-medium text-[#94A3B8] whitespace-nowrap">最低温</th>
                  <th className="py-2.5 px-3 text-right font-medium text-[#94A3B8] whitespace-nowrap">用电量</th>
                  {halfHourLabels.slice(0, 18).map(h => (
                    <th key={h} className="py-2.5 px-1.5 text-right font-medium text-[#94A3B8] whitespace-nowrap">{h}</th>
                  ))}
                  <th className="py-2.5 px-3 text-center font-medium text-[#94A3B8] whitespace-nowrap">操作</th>
                </tr>
              </thead>
              <tbody>
                {adjustedDates.map((date, idx) => {
                  const day = referenceDays.find(d => d.date === date);
                  if (!day) return null;
                  const isSelected = selectedRows.has(date);
                  return (
                    <tr
                      key={date}
                      className={`border-b border-[#334155]/50 transition-colors ${
                        isSelected ? 'bg-[#165DFF]/10' : idx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]'
                      }`}
                    >
                      <td className="py-2.5 px-3 text-center">
                        <input
                          type="checkbox"
                          checked={isSelected}
                          onChange={() => toggleRowSelection(date)}
                          className="cursor-pointer"
                        />
                      </td>
                      <td className="py-2.5 px-3 text-[#1D2129] font-medium whitespace-nowrap">{day.date}</td>
                      <td className="py-2.5 px-3 text-[#94A3B8] whitespace-nowrap">{day.weather}</td>
                      <td className="py-2.5 px-3 text-right text-[#1D2129] font-medium whitespace-nowrap">{day.similarity}</td>
                      <td className="py-2.5 px-3 text-right text-[#1D2129]">{day.avgTemp.toFixed(2)}</td>
                      <td className="py-2.5 px-3 text-right text-[#F53F3F]">{day.maxTemp.toFixed(2)}</td>
                      <td className="py-2.5 px-3 text-right text-[#165DFF]">{day.minTemp.toFixed(2)}</td>
                      <td className="py-2.5 px-3 text-right text-[#1D2129] font-medium">{day.consumption.toLocaleString()}</td>
                      {day.halfHourly.slice(0, 18).map((v, i) => (
                        <td key={i} className="py-2.5 px-1.5 text-right text-[#94A3B8]">{v.toLocaleString()}</td>
                      ))}
                      <td className="py-2.5 px-3 text-center">
                        <button
                          onClick={() => handleDeleteReference(date)}
                          className="w-6 h-6 flex items-center justify-center rounded hover:bg-[#F53F3F]/10 text-[#86909C] hover:text-[#F53F3F] transition-colors cursor-pointer"
                          title="删除"
                        >
                          <i className="ri-delete-bin-line text-xs" />
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          {adjustedDates.length === 0 && (
            <div className="py-8 text-center">
              <div className="w-10 h-10 flex items-center justify-center mx-auto mb-2 rounded-full bg-[#F7F8FA]">
                <i className="ri-inbox-line text-[#86909C] text-lg" />
              </div>
              <p className="text-xs text-[#86909C]">暂无参考日数据</p>
            </div>
          )}
        </div>

        {/* Curve Charts */}
        <div className="space-y-4">
          <CurveChart
            title="参考日电量曲线"
            subtitle=""
            series={adjustedCurveSeries}
            yAxisLabel="电量(kWh)"
          />
        </div>
        {/* Delete Confirm Modal */}
        {deleteConfirm.visible && (
          <div className="fixed inset-0 z-50 flex items-center justify-center">
            <div className="absolute inset-0 bg-black/60" onClick={cancelDelete} />
            <div className="relative bg-white rounded-xl shadow-2xl w-[400px] max-w-[90vw] border border-[#E5E6EB] p-6">
              <div className="flex items-center gap-3 mb-4">
                <div className="w-10 h-10 rounded-full bg-[#F53F3F]/10 flex items-center justify-center">
                  <i className="ri-error-warning-line text-[#F53F3F] text-lg" />
                </div>
                <div>
                  <h3 className="text-sm font-bold text-[#1D2129]">确认删除</h3>
                  <p className="text-xs text-[#86909C] mt-0.5">
                    确定要删除选中的 {deleteConfirm.dates.length} 个参考日期吗？
                  </p>
                </div>
              </div>
              <p className="text-xs text-[#94A3B8] mb-5 bg-[#F7F8FA] rounded-lg p-3">
                删除后，曲线将根据保留的参考日期自动重新计算平均值并更新。
              </p>
              <div className="flex items-center justify-end gap-3">
                <button
                  onClick={cancelDelete}
                  className="px-4 py-2 rounded-lg border border-[#E5E6EB] text-xs text-[#86909C] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
                >
                  取消
                </button>
                <button
                  onClick={confirmDelete}
                  className="px-4 py-2 rounded-lg bg-[#F53F3F] text-white text-xs hover:bg-[#F53F3F]/80 transition-colors cursor-pointer whitespace-nowrap"
                >
                  确认删除
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Modal */}
      <AddReferenceModal
        visible={modalVisible}
        selected={adjustedDates}
        onClose={() => setModalVisible(false)}
        onConfirm={handleAddReference}
      />
    </SpotTradingLayout>
  );
}