import { useState } from 'react';
import EnergySalesLayout from '../../components/EnergySalesLayout';
import ConfirmModal from '@/components/ConfirmModal';
import { costSpreadList, type CostSpread } from '@/mocks/energySalesData';

export default function CostSpreadPage() {
  const [searchMonth, setSearchMonth] = useState('');
  const [showDelete, setShowDelete] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  const filtered = costSpreadList.filter(c => !searchMonth || c.month.includes(searchMonth));
  const totalPages = Math.ceil(filtered.length / pageSize);
  const paged = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  return (
    <EnergySalesLayout>
      <div className="space-y-5 text-[#1D2129]">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">月度成本价差管理</h1>
            <p className="text-sm text-[#86909C] mt-1">按月维护国网成本价与售电公司成本价差数据</p>
          </div>
          <div className="flex items-center gap-2">
            <button className="flex items-center gap-1.5 px-4 py-2 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/90 transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-add-line" />
              新增价差
            </button>
            <button className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-upload-2-line" />
              批量导入
            </button>
            <button className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-download-2-line" />
              导出Excel
            </button>
          </div>
        </div>

        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">月份</label>
              <input type="month" value={searchMonth} onChange={e => setSearchMonth(e.target.value)} className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[140px]" />
            </div>
            <button className="flex items-center gap-1.5 px-4 py-2 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/90 transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-search-line" />
              查询
            </button>
            <button onClick={() => setSearchMonth('')} className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-refresh-line" />
              重置
            </button>
          </div>
        </div>

        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#F7F8FA]">
                <tr>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-0 bg-[#F7F8FA] z-10">序号</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-[48px] bg-[#F7F8FA] z-10">月份</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">国网成本价</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">国网历史偏折价</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">售电公司成本价</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">华能历史偏折价</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">价差</th>
                  <th className="px-4 py-3 text-center font-medium text-[#4E5969] sticky right-0 bg-[#F7F8FA] z-10">操作</th>
                </tr>
              </thead>
              <tbody>
                {paged.map((c, idx) => (
                  <tr key={c.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : ''}`}>
                    <td className="px-4 py-3 sticky left-0 bg-white z-10">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="px-4 py-3 sticky left-[48px] bg-white z-10 font-medium">{c.month}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{c.gridCostPrice.toFixed(3)}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{c.gridHistoryDeviation.toFixed(3)}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{c.salesCostPrice.toFixed(3)}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{c.huanengHistoryDeviation.toFixed(3)}</td>
                    <td className="px-4 py-3 text-right font-medium text-[#00C48C]">{(c.gridCostPrice + c.gridHistoryDeviation - c.salesCostPrice - c.huanengHistoryDeviation).toFixed(3)}</td>
                    <td className="px-4 py-3 text-center sticky right-0 bg-white z-10">
                      <div className="flex items-center gap-1 justify-center">
                        <button className="p-1 text-[#165DFF] hover:bg-[#165DFF]/10 rounded transition-colors cursor-pointer" title="编辑"><i className="ri-edit-line" /></button>
                        <button onClick={() => setShowDelete(true)} className="p-1 text-[#F53F3F] hover:bg-[#F53F3F]/10 rounded transition-colors cursor-pointer" title="删除"><i className="ri-delete-bin-line" /></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="flex items-center justify-between px-4 py-3 border-t border-[#E5E6EB]">
            <span className="text-xs text-[#86909C]">共 {filtered.length} 条，每页 {pageSize} 条</span>
            <div className="flex items-center gap-1">
              <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"><i className="ri-arrow-left-s-line" /></button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
                <button key={p} onClick={() => setCurrentPage(p)} className={`px-3 py-1 text-xs rounded cursor-pointer ${p === currentPage ? 'bg-[#165DFF] text-white' : 'border border-[#E5E6EB] hover:border-[#165DFF]'}`}>{p}</button>
              ))}
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"><i className="ri-arrow-right-s-line" /></button>
            </div>
          </div>
        </div>
      </div>

      {showDelete && <ConfirmModal title="确认删除" message="删除后无法恢复，是否确认？" onConfirm={() => setShowDelete(false)} onCancel={() => setShowDelete(false)} />}
    </EnergySalesLayout>
  );
}