import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip,
  ResponsiveContainer, Legend,
} from 'recharts';
import AdminLayout from '../components/AdminLayout';
import {
  dashboardIndicators, userActivityTrend,
  todoItems, systemWarnings, recentLogs, quickEntries,
} from '@/mocks/adminData';
import type { TodoItem } from '@/mocks/adminData';

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);
  const [todoFilter, setTodoFilter] = useState<'all' | 'approval' | 'warning'>('all');

  const filteredTodos = todoFilter === 'all'
    ? todoItems
    : todoItems.filter(t => t.type === todoFilter);

  const getTrendIcon = (t: string) => {
    switch (t) {
      case 'up': return <i className="ri-arrow-up-line text-xs text-[#00C48C]" />;
      case 'down': return <i className="ri-arrow-down-line text-xs text-[#F53F3F]" />;
      default: return <i className="ri-subtract-line text-xs text-[#86909C]" />;
    }
  };

  const getPriorityStyle = (p: string) => {
    switch (p) {
      case 'high': return 'bg-[#F53F3F]/10 text-[#F53F3F]';
      case 'medium': return 'bg-[#FF7D00]/10 text-[#FF7D00]';
      default: return 'bg-[#F7F8FA] text-[#86909C]';
    }
  };

  const getWarningStyle = (l: string) => {
    switch (l) {
      case 'critical': return 'bg-[#F53F3F]/10 text-[#F53F3F] border-[#F53F3F]/20';
      case 'warning': return 'bg-[#FF7D00]/10 text-[#FF7D00] border-[#FF7D00]/20';
      default: return 'bg-[#00B4FF]/10 text-[#00B4FF] border-[#00B4FF]/20';
    }
  };

  const getLogResultIcon = (r: string) => {
    return r === 'success'
      ? <i className="ri-checkbox-circle-line text-[#00C48C]" />
      : <i className="ri-close-circle-line text-[#F53F3F]" />;
  };

  return (
    <AdminLayout>
      <div className="space-y-5 text-[#1D2129]">
        {/* Page Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">管理控制台</h1>
            <p className="text-sm text-[#86909C] mt-1">实时监控平台运行状态与待办事项</p>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-xs text-[#86909C]">数据更新：2026-05-08 10:30:00</span>
            <button
              onClick={() => window.location.reload()}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF]/15 text-[#165DFF] text-xs hover:bg-[#165DFF]/25 transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-refresh-line" />
              刷新
            </button>
          </div>
        </div>

        {/* Key Indicators */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
          {dashboardIndicators.map((item, idx) => (
            <div
              key={item.label}
              onMouseEnter={() => setHoveredIdx(idx)}
              onMouseLeave={() => setHoveredIdx(null)}
              className={`bg-white rounded-lg p-4 border transition-all duration-300 cursor-pointer ${
                hoveredIdx === idx ? 'border-[#165DFF] shadow-md' : 'border-[#E5E6EB]'
              }`}
            >
              <div className="flex items-center gap-2 mb-2">
                <div className="w-2 h-2 rounded-full" style={{ backgroundColor: item.color }} />
                <p className="text-xs text-[#86909C]">{item.label}</p>
              </div>
              <div className="flex items-baseline gap-1">
                <span className="text-xl font-bold text-[#1D2129]">{item.value}</span>
                <span className="text-xs text-[#86909C]">{item.unit}</span>
              </div>
              <div className="flex items-center gap-1 mt-2">
                {getTrendIcon(item.trend)}
                <span className="text-xs text-[#86909C]">{item.change}</span>
              </div>
            </div>
          ))}
        </div>

        {/* Charts + Right Panel */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">
          {/* User Activity Trend */}
          <div className="bg-white rounded-lg p-5 border border-[#E5E6EB] lg:col-span-2">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-sm font-bold text-[#1D2129]">平台用户活跃度与交易申报趋势（近7天）</h3>
              <div className="flex items-center gap-3 text-xs">
                <span className="flex items-center gap-1"><span className="w-3 h-1 bg-[#165DFF] rounded-full" />活跃用户数</span>
                <span className="flex items-center gap-1"><span className="w-3 h-1 bg-[#00C48C] rounded-full" />交易申报数</span>
              </div>
            </div>
            <ResponsiveContainer width="100%" height={260}>
              <LineChart data={userActivityTrend}>
                <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
                <XAxis dataKey="date" tick={{ fontSize: 11, fill: '#86909C' }} />
                <YAxis tick={{ fontSize: 11, fill: '#86909C' }} yAxisId="left" />
                <YAxis tick={{ fontSize: 11, fill: '#86909C' }} yAxisId="right" orientation="right" />
                <Tooltip contentStyle={{ fontSize: 12, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB' }} />
                <Legend wrapperStyle={{ fontSize: 12 }} />
                <Line type="monotone" dataKey="activeUsers" stroke="#165DFF" strokeWidth={2} dot={{ r: 3 }} name="活跃用户数" yAxisId="left" />
                <Line type="monotone" dataKey="trades" stroke="#00C48C" strokeWidth={2} dot={{ r: 3 }} strokeDasharray="4 4" name="交易申报数" yAxisId="right" />
              </LineChart>
            </ResponsiveContainer>
          </div>

          {/* Todo & Warning */}
          <div className="bg-white rounded-lg p-5 border border-[#E5E6EB] flex flex-col">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-sm font-bold text-[#1D2129]">待办与预警</h3>
              <div className="flex gap-1">
                {(['all', 'approval', 'warning'] as const).map(f => (
                  <button
                    key={f}
                    onClick={() => setTodoFilter(f)}
                    className={`text-[10px] px-2 py-0.5 rounded-full cursor-pointer transition-colors whitespace-nowrap ${
                      todoFilter === f
                        ? 'bg-[#165DFF] text-white'
                        : 'bg-[#F7F8FA] text-[#86909C] hover:text-[#1D2129]'
                    }`}
                  >
                    {f === 'all' ? '全部' : f === 'approval' ? '审批' : '告警'}
                  </button>
                ))}
              </div>
            </div>
            <div className="flex-1 overflow-y-auto space-y-2 max-h-[260px]">
              {filteredTodos.map(item => (
                <div key={item.id} className="flex items-start gap-2.5 p-2.5 rounded-md border border-[#E5E6EB] hover:border-[#C9CDD4] transition-colors">
                  <div className={`w-2 h-2 rounded-full mt-1 flex-shrink-0 ${
                    item.priority === 'high' ? 'bg-[#F53F3F]' : item.priority === 'medium' ? 'bg-[#FF7D00]' : 'bg-[#86909C]'
                  }`} />
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-[#1D2129] truncate">{item.title}</p>
                    <p className="text-[10px] text-[#86909C] mt-0.5">{item.time}</p>
                  </div>
                  <span className={`text-[10px] px-1.5 py-0.5 rounded-full flex-shrink-0 ${getPriorityStyle(item.priority)}`}>
                    {item.priority === 'high' ? '高' : item.priority === 'medium' ? '中' : '低'}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Warnings + Recent Logs */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
          {/* System Warnings */}
          <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-sm font-bold text-[#1D2129]">系统异常告警</h3>
              <span className="text-xs px-2 py-0.5 bg-[#F53F3F]/10 text-[#F53F3F] rounded-full">{systemWarnings.filter(w => w.level === 'critical').length} 严重</span>
            </div>
            <div className="space-y-2 max-h-[240px] overflow-y-auto">
              {systemWarnings.map(w => (
                <div key={w.id} className={`flex items-center gap-3 p-2.5 rounded-md border ${getWarningStyle(w.level)}`}>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-[#1D2129] truncate">{w.title}</p>
                    <div className="flex items-center gap-2 mt-0.5">
                      <span className="text-[10px] text-[#86909C]">{w.module}</span>
                      <span className="text-[10px] text-[#86909C]">{w.time}</span>
                    </div>
                  </div>
                  <span className={`text-[10px] px-1.5 py-0.5 rounded-full flex-shrink-0 ${
                    w.level === 'critical' ? 'bg-[#F53F3F] text-white' : w.level === 'warning' ? 'bg-[#FF7D00] text-white' : 'bg-[#00B4FF] text-white'
                  }`}>
                    {w.level === 'critical' ? '严重' : w.level === 'warning' ? '警告' : '提示'}
                  </span>
                </div>
              ))}
            </div>
          </div>

          {/* Recent Operation Logs */}
          <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-sm font-bold text-[#1D2129]">最近操作日志</h3>
              <button
                onClick={() => navigate('/admin/logs/audit')}
                className="text-xs text-[#165DFF] hover:underline cursor-pointer whitespace-nowrap"
              >
                查看更多
              </button>
            </div>
            <div className="space-y-2 max-h-[240px] overflow-y-auto">
              {recentLogs.map(log => (
                <div key={log.id} className="flex items-center gap-3 p-2.5 rounded-md border border-[#E5E6EB] hover:border-[#C9CDD4] transition-colors">
                  <div className="w-5 h-5 flex items-center justify-center flex-shrink-0">
                    {getLogResultIcon(log.result)}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-[#1D2129] truncate">{log.action}</p>
                    <div className="flex items-center gap-2 mt-0.5">
                      <span className="text-[10px] text-[#86909C]">{log.operator}</span>
                      <span className="text-[10px] text-[#86909C]">{log.module}</span>
                    </div>
                  </div>
                  <span className="text-[10px] text-[#86909C] flex-shrink-0">{log.time}</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Quick Entries */}
        <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
          <h3 className="text-sm font-bold text-[#1D2129] mb-4">快捷功能入口</h3>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
            {quickEntries.map(entry => (
              <button
                key={entry.id}
                onClick={() => navigate(entry.path)}
                className="flex items-center gap-3 p-4 rounded-lg border border-[#E5E6EB] hover:border-[#165DFF]/40 hover:shadow-sm transition-all duration-200 cursor-pointer text-left"
              >
                <div className={`w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0 ${entry.color}`}>
                  <i className={`${entry.icon} text-lg`} />
                </div>
                <span className="text-sm font-medium text-[#1D2129]">{entry.name}</span>
              </button>
            ))}
          </div>
        </div>
      </div>
    </AdminLayout>
  );
}