/* ========== 工具函数 ========== */
const fmt = (v: number) => {
  if (Number.isNaN(v)) return '—';
  if (v === 0) return '0';
  if (Math.abs(v) >= 10000) return v.toLocaleString('en-US', { maximumFractionDigits: 2 });
  if (Math.abs(v) >= 1000) return v.toFixed(2);
  return v.toFixed(3);
};

const isNeg = (v: number) => v < 0;

