/* ========== 公共表格组件 ========== */

interface TableColDef {
  key: string;
  title: string;
  width?: number;
  fixed?: boolean;
  fixedLeft?: number;
  align?: 'left' | 'right' | 'center';
}

interface TableRowData {
  [key: string]: unknown;
  group?: string;
  indicator: string;
  total: number;
  slots: number[];
  groupSpan?: number;
  groupRowIdx?: number;
}

function BaseDataTable({
  columns,
  data,
  timeSlots,
  groupColKey = 'group',
  showGroupMerge = true,
  stickyLeftCols = 3,
}: {
  columns: TableColDef[];
  data: TableRowData[];
  timeSlots: string[];
  groupColKey?: string;
  showGroupMerge?: boolean;
  stickyLeftCols?: number;
}) {
  return (
    <div className="overflow-x-auto overflow-y-auto" style={{ maxHeight: 320 }}>
      <table className="border-collapse" style={{ fontSize: 12, tableLayout: 'fixed', minWidth: 'max-content' }}>
        <thead className="sticky top-0 z-20">
          <tr className="bg-[#F2F3F5]">
            {columns.map((col, idx) => (
              <th
                key={col.key}
                className="font-semibold text-[#1D2129] border border-[#E5E6EB]"
                style={{
                  width: col.width,
                  minWidth: col.width,
                  textAlign: col.align || 'center',
                  padding: '4px 6px',
                  position: idx < stickyLeftCols ? 'sticky' : undefined,
                  left: col.fixedLeft,
                  backgroundColor: idx < stickyLeftCols ? '#F2F3F5' : undefined,
                  zIndex: idx < stickyLeftCols ? 21 : 20,
                  whiteSpace: 'nowrap',
                }}
              >
                {col.title}
              </th>
            ))}
            {timeSlots.map((t) => (
              <th
                key={t}
                className="font-semibold text-[#1D2129] border border-[#E5E6EB] text-center"
                style={{ padding: '4px 4px', whiteSpace: 'nowrap', width: 52, minWidth: 52 }}
              >
                {t}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {data.map((row, rIdx) => (
            <tr
              key={rIdx}
              style={{ height: 26 }}
            >
              {columns.map((col, cIdx) => {
                if (showGroupMerge && col.key === groupColKey && row.groupSpan) {
                  if (row.groupRowIdx === 0) {
                    return (
                      <td
                        key={col.key}
                        rowSpan={row.groupSpan}
                        className="border border-[#E5E6EB] text-[#1D2129] font-medium"
                        style={{
                          textAlign: col.align || 'center',
                          padding: '2px 6px',
                          position: cIdx < stickyLeftCols ? 'sticky' : undefined,
                          left: col.fixedLeft,
                          backgroundColor: '#fff',
                          zIndex: cIdx < stickyLeftCols ? 11 : 10,
                          verticalAlign: 'middle',
                          whiteSpace: 'nowrap',
                        }}
                      >
                        {String(row[col.key] ?? '')}
                      </td>
                    );
                  }
                  return null;
                }

                const cellKey = col.key;
                const val = row[cellKey];
                const isNum = typeof val === 'number';
                const isTotalCol = cellKey === 'total';

                return (
                  <td
                    key={col.key}
                    className={`border border-[#E5E6EB] ${isTotalCol && isNum && isNeg(val as number) ? 'text-[#F53F3F]' : 'text-[#1D2129]'}`}
                    style={{
                      textAlign: col.align || 'center',
                      padding: '2px 6px',
                      position: cIdx < stickyLeftCols ? 'sticky' : undefined,
                      left: col.fixedLeft,
                      backgroundColor: '#fff',
                      zIndex: cIdx < stickyLeftCols ? 11 : 10,
                      whiteSpace: 'nowrap',
                      fontWeight: isTotalCol ? 500 : 400,
                    }}
                  >
                    {isNum ? fmt(val as number) : String(val ?? '')}
                  </td>
                );
              })}

              {row.slots.map((val, i) => (
                <td
                  key={i}
                  className={`border border-[#E5E6EB] text-right ${isNeg(val as number) ? 'text-[#F53F3F]' : 'text-[#1D2129]'}`}
                  style={{ padding: '2px 4px', whiteSpace: 'nowrap', width: 52, minWidth: 52 }}
                >
                  {fmt(val as number)}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

