import { useState } from 'react';
import SpotTradingLayout from '@/pages/spot-trading/components/SpotTradingLayout';
import { useBidDecisionData } from '@/hooks/useBidDecisionData';
import BidDecisionToolbar from './components/BidDecisionToolbar';
import CombinedAnalysisChart from './components/CombinedAnalysisChart';
import CoefficientAdjust from './components/CoefficientAdjust';
import BidClearingAnalysis from './components/BidClearingAnalysis';
import DataList from './components/DataList';
import ConfirmModal from '@/components/ConfirmModal';

export default function BidDecisionPage() {
  const [showUnsavedConfirm, setShowUnsavedConfirm] = useState(false);
  const [pendingAction, setPendingAction] = useState<(() => void) | null>(null);

  const {
    targetDate,
    setTargetDate,
    chartData,
    coefficients,
    hasUnsavedCoeffs,
    updateCoefficient,
    updateOperator,
    saveCoefficients,
  } = useBidDecisionData();

  const handleUnsavedConfirm = (fn: () => void) => {
    if (hasUnsavedCoeffs) {
      setPendingAction(() => fn);
      setShowUnsavedConfirm(true);
    } else {
      fn();
    }
  };

  const handleConfirmSwitch = () => {
    if (pendingAction) {
      pendingAction();
      setPendingAction(null);
    }
    setShowUnsavedConfirm(false);
  };

  const handleCancelSwitch = () => {
    setPendingAction(null);
    setShowUnsavedConfirm(false);
  };

  const runDate = new Date(targetDate).toLocaleDateString('zh-CN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).replace(/\//g, '/');

  return (
    <SpotTradingLayout>
      {/* 模块1：面包屑导航 */}
      <div className="flex items-center gap-1.5 text-xs text-[#94A3B8] mb-4">
        <span className="hover:text-[#165DFF] cursor-pointer">首页</span>
        <i className="ri-arrow-right-s-line text-[#86909C]" />
        <span className="hover:text-[#165DFF] cursor-pointer">交易决策依据</span>
        <i className="ri-arrow-right-s-line text-[#86909C]" />
        <span className="text-[#1D2129] font-medium">报量决策依据</span>
      </div>

      {/* 模块2：全局筛选与操作栏 */}
      <BidDecisionToolbar
        targetDate={targetDate}
        onDateChange={(d) => handleUnsavedConfirm(() => setTargetDate(d))}
        runDateText={runDate}
      />

      {/* 模块3：实时-日前价差与电量综合分析 */}
      <CombinedAnalysisChart data={chartData} />

      {/* 模块4：系数调整 */}
      <CoefficientAdjust
        data={chartData}
        coefficients={coefficients}
        onUpdateCoefficient={updateCoefficient}
        onUpdateOperator={updateOperator}
        onSave={saveCoefficients}
        hasUnsaved={hasUnsavedCoeffs}
      />

      {/* 模块5：申报出清分析（图一） */}
      <BidClearingAnalysis data={chartData} />

      {/* 模块6：数据列表（图二） */}
      <DataList data={chartData} />

      {/* 模块7：页面底部版权区 - 已在 SpotTradingLayout 中 */}

      {/* 未保存系数确认弹窗 */}
      {showUnsavedConfirm && (
        <ConfirmModal
          title="未保存的系数修改"
          message="您有未保存的系数修改，切换后将丢失，是否确认继续？"
          onConfirm={handleConfirmSwitch}
          onCancel={handleCancelSwitch}
          confirmText="确认继续"
        />
      )}
    </SpotTradingLayout>
  );
}