import { useState } from 'react';
import EnergySalesLayout from '../components/EnergySalesLayout';
import ConfirmModal from '@/components/ConfirmModal';
import { contractInfoList, type ContractInfo } from '@/mocks/energySalesData';

export default function ContractInfoPage() {
  const [searchCompany, setSearchCompany] = useState('');
  const [filterStatus, setFilterStatus] = useState<'all' | 'active' | 'expired' | 'pending'>('all');
  const [showDelete, setShowDelete] = useState(false);
  const [showDetail, setShowDetail] = useState(false);
  const [detailData, setDetailData] = useState<ContractInfo | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  const filtered = contractInfoList.filter(c => {
    const nameMatch = !searchCompany || c.companyName.includes(searchCompany);
    const statusMatch = filterStatus === 'all' || c.contractStatus === filterStatus;
    return nameMatch && statusMatch;
  });

  const totalPages = Math.ceil(filtered.length / pageSize);
  const paged = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const getStatusStyle = (s: string) => {
    switch (s) {
      case 'active': return 'bg-[#00C48C]/10 text-[#00C48C]';
      case 'expired': return 'bg-[#86909C]/10 text-[#86909C]';
      default: return 'bg-[#FF7D00]/10 text-[#FF7D00]';
    }
  };

  const months = ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月'];

  return (
    <EnergySalesLayout>
      <div className="space-y-5 text-[#1D2129]">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">合同信息管理</h1>
            <p className="text-sm text-[#86909C] mt-1">零售合同全量管理与交易中心自动同步</p>
          </div>
          <div className="flex items-center gap-2">
            <button className="flex items-center gap-1.5 px-4 py-2 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/90 transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-refresh-line" />
              手动同步
            </button>
            <button className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-download-2-line" />
              导出Excel
            </button>
          </div>
        </div>

        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">企业名称</label>
              <input
                type="text"
                value={searchCompany}
                onChange={e => setSearchCompany(e.target.value)}
                placeholder="请输入企业名称"
                className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[200px]"
              />
            </div>
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">合同状态</label>
              <select
                value={filterStatus}
                onChange={e => setFilterStatus(e.target.value as 'all' | 'active' | 'expired' | 'pending')}
                className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[120px]"
              >
                <option value="all">全部</option>
                <option value="active">生效中</option>
                <option value="expired">已到期</option>
                <option value="pending">待生效</option>
              </select>
            </div>
            <button className="flex items-center gap-1.5 px-4 py-2 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/90 transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-search-line" />
              查询
            </button>
            <button
              onClick={() => { setSearchCompany(''); setFilterStatus('all'); }}
              className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-refresh-line" />
              重置
            </button>
          </div>
        </div>

        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#F7F8FA]">
                <tr>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-0 bg-[#F7F8FA] z-10">序号</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-[48px] bg-[#F7F8FA] z-10">企业名称</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">信用代码</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">绑定时间</th>
                  <th className="px-4 py-3 text-center font-medium text-[#4E5969]">状态</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">结算电价</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">现货份额</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">非PPA价格</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">PPA价格</th>
                  <th className="px-4 py-3 text-center font-medium text-[#4E5969]">数据完整</th>
                  <th className="px-4 py-3 text-center font-medium text-[#4E5969] sticky right-0 bg-[#F7F8FA] z-10">操作</th>
                </tr>
              </thead>
              <tbody>
                {paged.map((c, idx) => (
                  <tr key={c.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : ''}`}>
                    <td className="px-4 py-3 sticky left-0 bg-white z-10">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="px-4 py-3 sticky left-[48px] bg-white z-10 font-medium">{c.companyName}</td>
                    <td className="px-4 py-3 text-[#4E5969]">{c.creditCode}</td>
                    <td className="px-4 py-3 text-[#86909C]">{c.bindTime}</td>
                    <td className="px-4 py-3 text-center">
                      <span className={`px-2 py-0.5 rounded-full text-[10px] ${getStatusStyle(c.contractStatus)}`}>
                        {c.contractStatus === 'active' ? '生效中' : c.contractStatus === 'expired' ? '已到期' : '待生效'}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{c.settlementPrice.toFixed(3)}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{c.spotShare}%</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{c.nonPpaPrice.toFixed(3)}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{c.ppaPrice.toFixed(3)}</td>
                    <td className="px-4 py-3 text-center">
                      <span className={`px-2 py-0.5 rounded-full text-[10px] ${c.dataComplete ? 'bg-[#00C48C]/10 text-[#00C48C]' : 'bg-[#F53F3F]/10 text-[#F53F3F]'}`}>
                        {c.dataComplete ? '完整' : '缺失'}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-center sticky right-0 bg-white z-10">
                      <div className="flex items-center gap-1 justify-center">
                        <button
                          onClick={() => { setDetailData(c); setShowDetail(true); }}
                          className="p-1 text-[#165DFF] hover:bg-[#165DFF]/10 rounded transition-colors cursor-pointer"
                          title="详情"
                        >
                          <i className="ri-eye-line" />
                        </button>
                        <button
                          onClick={() => setShowDelete(true)}
                          className="p-1 text-[#F53F3F] hover:bg-[#F53F3F]/10 rounded transition-colors cursor-pointer"
                          title="删除"
                        >
                          <i className="ri-delete-bin-line" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="flex items-center justify-between px-4 py-3 border-t border-[#E5E6EB]">
            <span className="text-xs text-[#86909C]">共 {filtered.length} 条，每页 {pageSize} 条</span>
            <div className="flex items-center gap-1">
              <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"><i className="ri-arrow-left-s-line" /></button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
                <button key={p} onClick={() => setCurrentPage(p)} className={`px-3 py-1 text-xs rounded cursor-pointer ${p === currentPage ? 'bg-[#165DFF] text-white' : 'border border-[#E5E6EB] hover:border-[#165DFF]'}`}>{p}</button>
              ))}
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"><i className="ri-arrow-right-s-line" /></button>
            </div>
          </div>
        </div>
      </div>

      {showDelete && <ConfirmModal title="确认删除" message="删除合同后将无法恢复，是否确认删除？" onConfirm={() => setShowDelete(false)} onCancel={() => setShowDelete(false)} />}

      {/* Detail Modal */}
      {showDetail && detailData && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
          <div className="bg-white rounded-lg w-[700px] max-h-[80vh] overflow-y-auto p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-base font-bold text-[#1D2129]">合同详情</h3>
              <button onClick={() => setShowDetail(false)} className="p-1 text-[#86909C] hover:text-[#1D2129] cursor-pointer"><i className="ri-close-line text-lg" /></button>
            </div>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs text-[#86909C]">企业名称</label><p className="text-sm font-medium mt-1">{detailData.companyName}</p></div>
                <div><label className="text-xs text-[#86909C]">信用代码</label><p className="text-sm font-medium mt-1">{detailData.creditCode}</p></div>
                <div><label className="text-xs text-[#86909C]">绑定时间</label><p className="text-sm font-medium mt-1">{detailData.bindTime}</p></div>
                <div><label className="text-xs text-[#86909C]">结算电价</label><p className="text-sm font-medium mt-1">{detailData.settlementPrice} 元/MWh</p></div>
              </div>
              <div>
                <label className="text-xs text-[#86909C] mb-2 block">分月绑定电量（MWh）</label>
                <div className="grid grid-cols-6 gap-2">
                  {detailData.bindVolume.map((v, i) => (
                    <div key={i} className="bg-[#F7F8FA] rounded-md p-2 text-center">
                      <p className="text-[10px] text-[#86909C]">{months[i]}</p>
                      <p className="text-xs font-medium text-[#1D2129] mt-0.5">{v}</p>
                    </div>
                  ))}
                </div>
              </div>
              <div className="grid grid-cols-3 gap-4">
                <div><label className="text-xs text-[#86909C]">现货结算份额</label><p className="text-sm font-medium mt-1">{detailData.spotShare}%</p></div>
                <div><label className="text-xs text-[#86909C]">场外溯源电能服务价格</label><p className="text-sm font-medium mt-1">{detailData.offsiteTracePrice} 元/MWh</p></div>
                <div><label className="text-xs text-[#86909C]">场内融合电能服务价格</label><p className="text-sm font-medium mt-1">{detailData.onsiteFusionPrice} 元/MWh</p></div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="text-xs text-[#86909C]">超用偏差考核比例</label><p className="text-sm font-medium mt-1">{detailData.deviationOverRatio}%</p></div>
                <div><label className="text-xs text-[#86909C]">少用偏差考核比例</label><p className="text-sm font-medium mt-1">{detailData.deviationUnderRatio}%</p></div>
              </div>
            </div>
            <div className="flex justify-end gap-2 mt-6">
              <button onClick={() => setShowDetail(false)} className="px-4 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] cursor-pointer">关闭</button>
            </div>
          </div>
        </div>
      )}
    </EnergySalesLayout>
  );
}