import { useState } from 'react';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip,
  ResponsiveContainer, Legend, PieChart, Pie, Cell,
} from 'recharts';
import EnergySalesLayout from '../../components/EnergySalesLayout';
import { deviationRecordList, type DeviationRecord } from '@/mocks/energySalesData';

export default function DeviationBoardPage() {
  const [searchName, setSearchName] = useState('');
  const [filterType, setFilterType] = useState<'all' | 'single' | 'multi'>('all');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  const filtered = deviationRecordList.filter(d => {
    const nameMatch = !searchName || d.userName.includes(searchName);
    const typeMatch = filterType === 'all' || (filterType === 'single' ? d.userType.includes('单主体') : d.userType.includes('多主体'));
    return nameMatch && typeMatch;
  });

  const totalPages = Math.ceil(filtered.length / pageSize);
  const paged = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  // Charts data
  const benefitChartData = filtered.slice(0, 10).map(d => ({
    name: d.userName.slice(0, 6) + '...',
    unitBenefit: d.unitBenefit,
    deviationRatio: d.deviationRatio,
  }));

  const greenRatioData = [
    { name: '绿电比例>30%', value: filtered.filter(d => d.greenRatio > 30).length, color: '#00C48C' },
    { name: '绿电比例10-30%', value: filtered.filter(d => d.greenRatio >= 10 && d.greenRatio <= 30).length, color: '#165DFF' },
    { name: '绿电比例<10%', value: filtered.filter(d => d.greenRatio < 10).length, color: '#FF7D00' },
    { name: '无绿电', value: filtered.filter(d => d.greenRatio === 0).length, color: '#86909C' },
  ];

  const avgDeviation = filtered.length > 0 ? (filtered.reduce((sum, d) => sum + d.deviationRatio, 0) / filtered.length).toFixed(2) : '0';
  const avgBenefit = filtered.length > 0 ? (filtered.reduce((sum, d) => sum + d.unitBenefit, 0) / filtered.length).toFixed(3) : '0';
  const totalGreenRatio = filtered.length > 0 ? (filtered.reduce((sum, d) => sum + d.greenRatio, 0) / filtered.length).toFixed(1) : '0';

  return (
    <EnergySalesLayout>
      <div className="space-y-5 text-[#1D2129]">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">偏差考核分析看板</h1>
            <p className="text-sm text-[#86909C] mt-1">偏差考核、度电收益、绿电指标多维度可视化</p>
          </div>
          <button className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
            <i className="ri-download-2-line" />
            导出Excel
          </button>
        </div>

        {/* Summary */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          {[
            { label: '平均偏差率', value: `${avgDeviation > 0 ? '+' : ''}${avgDeviation}%`, color: '#F53F3F' },
            { label: '平均度电收益', value: `${avgBenefit} 元/MWh`, color: '#165DFF' },
            { label: '平均绿电比例', value: `${totalGreenRatio}%`, color: '#00C48C' },
            { label: '分析用户数', value: `${filtered.length} 户`, color: '#FF7D00' },
          ].map(card => (
            <div key={card.label} className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
              <p className="text-xs text-[#86909C]">{card.label}</p>
              <p className="text-xl font-bold mt-1" style={{ color: card.color }}>{card.value}</p>
            </div>
          ))}
        </div>

        {/* Charts */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
          <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
            <h3 className="text-sm font-bold text-[#1D2129] mb-4">度电收益与偏差率对比</h3>
            <ResponsiveContainer width="100%" height={280}>
              <BarChart data={benefitChartData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
                <XAxis dataKey="name" tick={{ fontSize: 10, fill: '#86909C' }} />
                <YAxis yAxisId="left" tick={{ fontSize: 10, fill: '#86909C' }} />
                <YAxis yAxisId="right" orientation="right" tick={{ fontSize: 10, fill: '#86909C' }} />
                <Tooltip contentStyle={{ fontSize: 12, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB' }} />
                <Legend wrapperStyle={{ fontSize: 12 }} />
                <Bar yAxisId="left" dataKey="unitBenefit" fill="#165DFF" radius={[4, 4, 0, 0]} name="度电收益" />
                <Bar yAxisId="right" dataKey="deviationRatio" fill="#F53F3F" radius={[4, 4, 0, 0]} name="偏差率(%)" />
              </BarChart>
            </ResponsiveContainer>
          </div>

          <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
            <h3 className="text-sm font-bold text-[#1D2129] mb-4">绿电比例分布</h3>
            <ResponsiveContainer width="100%" height={280}>
              <PieChart>
                <Pie data={greenRatioData} cx="50%" cy="50%" innerRadius={60} outerRadius={100} paddingAngle={4} dataKey="value">
                  {greenRatioData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip contentStyle={{ fontSize: 12, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB' }} />
                <Legend wrapperStyle={{ fontSize: 12 }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Filter */}
        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">用户名称</label>
              <input type="text" value={searchName} onChange={e => setSearchName(e.target.value)} placeholder="请输入用户名称" className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[180px]" />
            </div>
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">用户类型</label>
              <select value={filterType} onChange={e => setFilterType(e.target.value as 'all' | 'single' | 'multi')} className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[120px]">
                <option value="all">全部</option>
                <option value="single">单主体</option>
                <option value="multi">多主体</option>
              </select>
            </div>
            <button className="flex items-center gap-1.5 px-4 py-2 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/90 transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-search-line" />
              查询
            </button>
            <button onClick={() => { setSearchName(''); setFilterType('all'); }} className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-refresh-line" />
              重置
            </button>
          </div>
        </div>

        {/* Table */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#F7F8FA]">
                <tr>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-0 bg-[#F7F8FA] z-10">序号</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-[48px] bg-[#F7F8FA] z-10">用户名称</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">月份</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">用户类型</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">实际用电量</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">合同电量</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">偏差率</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">绿电量</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">绿电比例</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">度电收益</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">不含PPA绿电比例</th>
                </tr>
              </thead>
              <tbody>
                {paged.map((d, idx) => (
                  <tr key={d.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : ''}`}>
                    <td className="px-4 py-3 sticky left-0 bg-white z-10">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="px-4 py-3 sticky left-[48px] bg-white z-10 font-medium">{d.userName}</td>
                    <td className="px-4 py-3 text-[#4E5969]">{d.month}</td>
                    <td className="px-4 py-3">
                      <span className="px-2 py-0.5 bg-[#165DFF]/10 text-[#165DFF] rounded-full text-[10px]">{d.userType}</span>
                    </td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{d.actualPower?.toLocaleString() || '-'}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{d.contractPower?.toLocaleString() || '-'}</td>
                    <td className={`px-4 py-3 text-right font-medium ${d.deviationRatio > 0 ? 'text-[#F53F3F]' : 'text-[#00C48C]'}`}>
                      {d.deviationRatio > 0 ? '+' : ''}{d.deviationRatio}%
                    </td>
                    <td className="px-4 py-3 text-right text-[#00C48C]">{(d.greenRatio * d.actualPower / 100)?.toFixed(0) || '-'}</td>
                    <td className="px-4 py-3 text-right text-[#00C48C]">{d.greenRatio}%</td>
                    <td className="px-4 py-3 text-right font-bold text-[#165DFF]">{d.unitBenefit.toFixed(3)}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{d.nonPpaGreenRatio.toFixed(1)}%</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="flex items-center justify-between px-4 py-3 border-t border-[#E5E6EB]">
            <span className="text-xs text-[#86909C]">共 {filtered.length} 条，每页 {pageSize} 条</span>
            <div className="flex items-center gap-1">
              <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"><i className="ri-arrow-left-s-line" /></button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
                <button key={p} onClick={() => setCurrentPage(p)} className={`px-3 py-1 text-xs rounded cursor-pointer ${p === currentPage ? 'bg-[#165DFF] text-white' : 'border border-[#E5E6EB] hover:border-[#165DFF]'}`}>{p}</button>
              ))}
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"><i className="ri-arrow-right-s-line" /></button>
            </div>
          </div>
        </div>
      </div>
    </EnergySalesLayout>
  );
}