import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip,
  ResponsiveContainer, BarChart, Bar, Legend,
} from 'recharts';
import EnergySalesLayout from './components/EnergySalesLayout';
import {
  dashboardIndicators, contractTrend, userCompletionRate, benefitTrend,
  todoItems, contractWarnings, syncWarnings,
  userRatingTop, userRatingBottom, quickEntries,
} from '@/mocks/energySalesData';

export default function EnergySalesDashboard() {
  const navigate = useNavigate();
  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);
  const [todoFilter, setTodoFilter] = useState<'all' | 'approval' | 'warning'>('all');

  const filteredTodos = todoFilter === 'all'
    ? todoItems
    : todoItems.filter(t => t.type === todoFilter);

  const getTrendIcon = (t: string) => {
    switch (t) {
      case 'up': return <i className="ri-arrow-up-line text-xs text-[#00C48C]" />;
      case 'down': return <i className="ri-arrow-down-line text-xs text-[#F53F3F]" />;
      default: return <i className="ri-subtract-line text-xs text-[#86909C]" />;
    }
  };

  const getPriorityStyle = (p: string) => {
    switch (p) {
      case 'high': return 'bg-[#F53F3F]/10 text-[#F53F3F]';
      case 'medium': return 'bg-[#FF7D00]/10 text-[#FF7D00]';
      default: return 'bg-[#F7F8FA] text-[#86909C]';
    }
  };

  const getSyncLevelStyle = (l: string) => {
    switch (l) {
      case 'critical': return 'bg-[#F53F3F]/10 text-[#F53F3F] border-[#F53F3F]/20';
      case 'warning': return 'bg-[#FF7D00]/10 text-[#FF7D00] border-[#FF7D00]/20';
      default: return 'bg-[#00B4FF]/10 text-[#00B4FF] border-[#00B4FF]/20';
    }
  };

  const getContractLevel = (days: number) => {
    if (days <= 60) return { badge: 'bg-[#F53F3F] text-white', label: '紧急' };
    if (days <= 90) return { badge: 'bg-[#FF7D00] text-white', label: '即将' };
    return { badge: 'bg-[#86909C] text-white', label: '正常' };
  };

  const getRatingColor = (score: number) => {
    if (score >= 90) return 'text-[#00C48C]';
    if (score >= 80) return 'text-[#165DFF]';
    if (score >= 70) return 'text-[#FF7D00]';
    return 'text-[#F53F3F]';
  };

  return (
    <EnergySalesLayout>
      <div className="space-y-5 text-[#1D2129]">
        {/* Page Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">经营战情室</h1>
            <p className="text-sm text-[#86909C] mt-1">全业务经营数据概览与核心指标监控</p>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-xs text-[#86909C]">数据更新：2026-05-08 10:30:00</span>
            <button
              onClick={() => window.location.reload()}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF]/15 text-[#165DFF] text-xs hover:bg-[#165DFF]/25 transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-refresh-line" />
              刷新
            </button>
          </div>
        </div>

        {/* 8 Key Indicators */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-8 gap-4">
          {dashboardIndicators.map((item, idx) => (
            <div
              key={item.label}
              onMouseEnter={() => setHoveredIdx(idx)}
              onMouseLeave={() => setHoveredIdx(null)}
              className={`bg-white rounded-lg p-4 border transition-all duration-300 cursor-pointer ${
                hoveredIdx === idx ? 'border-[#165DFF] shadow-md' : 'border-[#E5E6EB]'
              }`}
            >
              <div className="flex items-center gap-2 mb-2">
                <div className="w-2 h-2 rounded-full" style={{ backgroundColor: item.color }} />
                <p className="text-xs text-[#86909C] truncate">{item.label}</p>
              </div>
              <div className="flex items-baseline gap-1">
                <span className="text-lg font-bold text-[#1D2129]">{item.value}</span>
                <span className="text-xs text-[#86909C]">{item.unit}</span>
              </div>
              <div className="flex items-center gap-1 mt-2">
                {getTrendIcon(item.trend)}
                <span className="text-xs text-[#86909C]">{item.change}</span>
              </div>
            </div>
          ))}
        </div>

        {/* Charts + Right Panel */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">
          {/* Left Charts - 2/3 width */}
          <div className="lg:col-span-2 space-y-5">
            {/* Contract Trend */}
            <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-sm font-bold text-[#1D2129]">月度签约电量趋势（近12个月）</h3>
                <div className="flex items-center gap-3 text-xs">
                  <span className="flex items-center gap-1"><span className="w-3 h-1 bg-[#165DFF] rounded-full" />签约户数</span>
                  <span className="flex items-center gap-1"><span className="w-3 h-1 bg-[#00C48C] rounded-full" />完成户数</span>
                  <span className="flex items-center gap-1"><span className="w-3 h-1 bg-[#FF7D00] rounded-full" />节约电费(万元)</span>
                </div>
              </div>
              <ResponsiveContainer width="100%" height={240}>
                <LineChart data={contractTrend}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
                  <XAxis dataKey="month" tick={{ fontSize: 10, fill: '#86909C' }} />
                  <YAxis yAxisId="left" tick={{ fontSize: 10, fill: '#86909C' }} />
                  <YAxis yAxisId="right" orientation="right" tick={{ fontSize: 10, fill: '#86909C' }} />
                  <Tooltip contentStyle={{ fontSize: 12, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB' }} />
                  <Legend wrapperStyle={{ fontSize: 12 }} />
                  <Line yAxisId="left" type="monotone" dataKey="signed" stroke="#165DFF" strokeWidth={2} dot={{ r: 3 }} name="签约户数" />
                  <Line yAxisId="left" type="monotone" dataKey="completed" stroke="#00C48C" strokeWidth={2} dot={{ r: 3 }} strokeDasharray="4 4" name="完成户数" />
                  <Line yAxisId="right" type="monotone" dataKey="benefit" stroke="#FF7D00" strokeWidth={2} dot={{ r: 3 }} name="节约电费" />
                </LineChart>
              </ResponsiveContainer>
            </div>

            {/* User Completion + Benefit Trend */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
              {/* User Completion Rate */}
              <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-bold text-[#1D2129]">用户电量完成率 TOP10</h3>
                </div>
                <ResponsiveContainer width="100%" height={220}>
                  <BarChart data={userCompletionRate} layout="vertical">
                    <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
                    <XAxis type="number" domain={[0, 100]} tick={{ fontSize: 10, fill: '#86909C' }} tickFormatter={(v: number) => `${v}%`} />
                    <YAxis type="category" dataKey="user" tick={{ fontSize: 9, fill: '#86909C' }} width={80} />
                    <Tooltip contentStyle={{ fontSize: 12, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB' }} formatter={(value: number) => [`${value}%`, '完成率']} />
                    <Bar dataKey="rate" fill="#165DFF" radius={[0, 4, 4, 0]} name="完成率" />
                  </BarChart>
                </ResponsiveContainer>
              </div>

              {/* Benefit Trend */}
              <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-sm font-bold text-[#1D2129]">度电收益趋势（近12个月）</h3>
                </div>
                <ResponsiveContainer width="100%" height={220}>
                  <LineChart data={benefitTrend}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
                    <XAxis dataKey="month" tick={{ fontSize: 10, fill: '#86909C' }} />
                    <YAxis tick={{ fontSize: 10, fill: '#86909C' }} domain={[0.1, 0.16]} />
                    <Tooltip contentStyle={{ fontSize: 12, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB' }} formatter={(value: number) => [`${value} 元/MWh`, '度电收益']} />
                    <Line type="monotone" dataKey="benefit" stroke="#00C48C" strokeWidth={2} dot={{ r: 3 }} name="度电收益" />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>

          {/* Right Panel - 1/3 width */}
          <div className="space-y-5">
            {/* Todo List */}
            <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-sm font-bold text-[#1D2129]">待办事项</h3>
                <div className="flex gap-1">
                  {(['all', 'approval', 'warning'] as const).map(f => (
                    <button
                      key={f}
                      onClick={() => setTodoFilter(f)}
                      className={`text-[10px] px-2 py-0.5 rounded-full cursor-pointer transition-colors whitespace-nowrap ${
                        todoFilter === f
                          ? 'bg-[#165DFF] text-white'
                          : 'bg-[#F7F8FA] text-[#86909C] hover:text-[#1D2129]'
                      }`}
                    >
                      {f === 'all' ? '全部' : f === 'approval' ? '审批' : '告警'}
                    </button>
                  ))}
                </div>
              </div>
              <div className="space-y-2 max-h-[200px] overflow-y-auto">
                {filteredTodos.map(item => (
                  <div key={item.id} className="flex items-start gap-2.5 p-2.5 rounded-md border border-[#E5E6EB] hover:border-[#C9CDD4] transition-colors">
                    <div className={`w-2 h-2 rounded-full mt-1 flex-shrink-0 ${
                      item.priority === 'high' ? 'bg-[#F53F3F]' : item.priority === 'medium' ? 'bg-[#FF7D00]' : 'bg-[#86909C]'
                    }`} />
                    <div className="flex-1 min-w-0">
                      <p className="text-xs text-[#1D2129] truncate">{item.title}</p>
                      <p className="text-[10px] text-[#86909C] mt-0.5">截止：{item.deadline}</p>
                    </div>
                    <span className={`text-[10px] px-1.5 py-0.5 rounded-full flex-shrink-0 ${getPriorityStyle(item.priority)}`}>
                      {item.priority === 'high' ? '高' : item.priority === 'medium' ? '中' : '低'}
                    </span>
                  </div>
                ))}
              </div>
            </div>

            {/* Contract Warnings */}
            <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-sm font-bold text-[#1D2129]">合同到期预警</h3>
                <span className="text-xs px-2 py-0.5 bg-[#F53F3F]/10 text-[#F53F3F] rounded-full">{contractWarnings.filter(w => w.daysLeft <= 60).length} 紧急</span>
              </div>
              <div className="space-y-2 max-h-[180px] overflow-y-auto">
                {contractWarnings.map(w => {
                  const level = getContractLevel(w.daysLeft);
                  return (
                    <div key={w.id} className="flex items-center gap-2 p-2.5 rounded-md border border-[#E5E6EB] hover:border-[#C9CDD4] transition-colors">
                      <div className="flex-1 min-w-0">
                        <p className="text-xs text-[#1D2129] truncate">{w.user}</p>
                        <p className="text-[10px] text-[#86909C] mt-0.5">{w.daysLeft} 天后到期</p>
                      </div>
                      <span className={`text-[10px] px-1.5 py-0.5 rounded-full flex-shrink-0 ${level.badge}`}>{level.label}</span>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Sync Warnings */}
            <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-sm font-bold text-[#1D2129]">同步异常告警</h3>
              </div>
              <div className="space-y-2 max-h-[160px] overflow-y-auto">
                {syncWarnings.map(w => (
                  <div key={w.id} className={`flex items-center gap-2 p-2.5 rounded-md border ${getSyncLevelStyle(w.level)}`}>
                    <div className="flex-1 min-w-0">
                      <p className="text-xs text-[#1D2129] truncate">{w.title}</p>
                      <div className="flex items-center gap-2 mt-0.5">
                        <span className="text-[10px] text-[#86909C]">{w.module}</span>
                        <span className="text-[10px] text-[#86909C]">{w.time}</span>
                      </div>
                    </div>
                    <span className={`text-[10px] px-1.5 py-0.5 rounded-full flex-shrink-0 ${
                      w.level === 'critical' ? 'bg-[#F53F3F] text-white' : w.level === 'warning' ? 'bg-[#FF7D00] text-white' : 'bg-[#00B4FF] text-white'
                    }`}>
                      {w.level === 'critical' ? '严重' : w.level === 'warning' ? '警告' : '提示'}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* User Rating Board */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
          {/* Top 10 */}
          <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-sm font-bold text-[#1D2129]">用户评级 TOP10</h3>
              <span className="text-xs text-[#86909C]">综合评分排名</span>
            </div>
            <div className="space-y-2">
              {userRatingTop.map((user, idx) => (
                <div key={user.id} className="flex items-center gap-3 p-2.5 rounded-md border border-[#E5E6EB] hover:border-[#C9CDD4] transition-colors">
                  <span className={`w-6 h-6 flex items-center justify-center rounded-full text-[10px] font-bold flex-shrink-0 ${
                    idx < 3 ? 'bg-[#165DFF] text-white' : 'bg-[#F7F8FA] text-[#86909C]'
                  }`}>{idx + 1}</span>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-[#1D2129] truncate">{user.userName}</p>
                    <p className="text-[10px] text-[#86909C]">{user.type}</p>
                  </div>
                  <span className={`text-sm font-bold flex-shrink-0 ${getRatingColor(user.score)}`}>{user.score}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Bottom 10 */}
          <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-sm font-bold text-[#1D2129]">用户评级末位10</h3>
              <span className="text-xs text-[#86909C]">需关注用户</span>
            </div>
            <div className="space-y-2">
              {userRatingBottom.map((user, idx) => (
                <div key={user.id} className="flex items-center gap-3 p-2.5 rounded-md border border-[#E5E6EB] hover:border-[#C9CDD4] transition-colors">
                  <span className="w-6 h-6 flex items-center justify-center rounded-full text-[10px] font-bold flex-shrink-0 bg-[#F53F3F]/10 text-[#F53F3F]">{idx + 1}</span>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-[#1D2129] truncate">{user.userName}</p>
                    <p className="text-[10px] text-[#86909C]">{user.type}</p>
                  </div>
                  <span className={`text-sm font-bold flex-shrink-0 ${getRatingColor(user.score)}`}>{user.score}</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Quick Entries */}
        <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
          <h3 className="text-sm font-bold text-[#1D2129] mb-4">核心业务快捷入口</h3>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
            {quickEntries.map(entry => (
              <button
                key={entry.id}
                onClick={() => navigate(entry.path)}
                className="flex items-center gap-3 p-4 rounded-lg border border-[#E5E6EB] hover:border-[#165DFF]/40 hover:shadow-sm transition-all duration-200 cursor-pointer text-left"
              >
                <div className={`w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0 ${entry.color}`}>
                  <i className={`${entry.icon} text-lg`} />
                </div>
                <span className="text-sm font-medium text-[#1D2129]">{entry.name}</span>
              </button>
            ))}
          </div>
        </div>
      </div>
    </EnergySalesLayout>
  );
}