import { useState, useEffect, useRef } from 'react';
import { helpCenterSections, getPageHelpId, type HelpItem } from '@/mocks/helpCenterData';

interface HelpCenterModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentPath: string;
}

export default function HelpCenterModal({ isOpen, onClose, currentPath }: HelpCenterModalProps) {
  const initialId = getPageHelpId(currentPath);
  const [activeSection, setActiveSection] = useState<string>('');
  const [activeItem, setActiveItem] = useState<string>(initialId);
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({});
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOpen) {
      const id = getPageHelpId(currentPath);
      setActiveItem(id);
      // Expand the section containing the active item
      for (const section of helpCenterSections) {
        if (section.items.some(item => item.id === id)) {
          setActiveSection(section.id);
          setExpandedSections(prev => ({ ...prev, [section.id]: true }));
          break;
        }
      }
      // Lock body scroll
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => { document.body.style.overflow = ''; };
  }, [isOpen, currentPath]);

  const toggleSection = (id: string) => {
    setExpandedSections(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const currentItem = (() => {
    for (const section of helpCenterSections) {
      const item = section.items.find(i => i.id === activeItem);
      if (item) return item;
    }
    return helpCenterSections[0]?.items[0];
  })() as HelpItem;

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/40" onClick={onClose} />

      {/* Modal */}
      <div className="relative bg-white rounded-xl shadow-2xl w-[1000px] h-[700px] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-200">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-[#E5E6EB]">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-[#165DFF]/10 rounded-lg flex items-center justify-center">
              <i className="ri-book-open-line text-[#165DFF]" />
            </div>
            <div>
              <h2 className="text-base font-bold text-[#1D2129]">帮助中心与公式说明</h2>
              <p className="text-xs text-[#86909C]">关于电力交易辅助决策系统各项指标的推算逻辑、数据来源及计算公式详细说明</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-[#F7F8FA] transition-colors cursor-pointer"
          >
            <i className="ri-close-line text-lg text-[#86909C]" />
          </button>
        </div>

        {/* Body */}
        <div className="flex flex-1 overflow-hidden">
          {/* Left Sidebar */}
          <div className="w-[220px] bg-[#FAFBFC] border-r border-[#E5E6EB] flex flex-col">
            <div className="px-4 py-3 text-xs font-medium text-[#86909C] uppercase tracking-wide">
              目录
            </div>
            <div className="flex-1 overflow-y-auto px-2 pb-4">
              {helpCenterSections.map(section => (
                <div key={section.id} className="mb-1">
                  <button
                    onClick={() => toggleSection(section.id)}
                    className={`w-full flex items-center justify-between px-3 py-2 text-xs rounded-md transition-colors cursor-pointer ${
                      activeSection === section.id ? 'text-[#165DFF] font-medium bg-[#165DFF]/5' : 'text-[#4E5969] hover:bg-[#F2F3F5]'
                    }`}
                  >
                    <span>{section.name}</span>
                    <i className={`ri-arrow-down-s-line transition-transform ${expandedSections[section.id] ? 'rotate-180' : ''}`} />
                  </button>
                  {expandedSections[section.id] && (
                    <div className="mt-0.5">
                      {section.items.map(item => (
                        <button
                          key={item.id}
                          onClick={() => {
                            setActiveItem(item.id);
                            setActiveSection(section.id);
                            contentRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
                          }}
                          className={`w-full text-left px-3 py-1.5 text-xs rounded-md transition-colors cursor-pointer ml-2 ${
                            activeItem === item.id
                              ? 'bg-[#165DFF]/10 text-[#165DFF] font-medium'
                              : 'text-[#86909C] hover:text-[#4E5969] hover:bg-[#F2F3F5]'
                          }`}
                        >
                          {item.title}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>

          {/* Right Content */}
          <div ref={contentRef} className="flex-1 overflow-y-auto bg-white">
            {currentItem && (
              <div className="p-6">
                {/* Title */}
                <div className="flex items-center gap-2 mb-3">
                  <span className="px-2 py-0.5 bg-[#165DFF]/10 text-[#165DFF] text-xs rounded font-medium">
                    {(() => {
                      for (const section of helpCenterSections) {
                        if (section.items.some(i => i.id === activeItem)) {
                          return section.name;
                        }
                      }
                      return '核心指标';
                    })()}
                  </span>
                  <span className="text-xs text-[#86909C]">{currentItem.title}指标说明</span>
                </div>

                {/* Description */}
                <p className="text-sm text-[#4E5969] mb-6 leading-relaxed">
                  {currentItem.description}
                </p>

                {/* Formulas */}
                {currentItem.formulas.map((formula, idx) => (
                  <div key={idx} className="mb-5">
                    <h4 className="text-sm font-bold text-[#1D2129] mb-2">{formula.name}</h4>
                    <p className="text-xs text-[#86909C] mb-2">{formula.note}</p>
                    <div className="bg-[#F7F8FA] rounded-lg p-3 border border-[#E5E6EB]">
                      <code className="text-xs text-[#165DFF] font-mono leading-relaxed block whitespace-pre-wrap">
                        {formula.expression}
                      </code>
                    </div>
                  </div>
                ))}

                {/* Fields Table */}
                <div className="mb-5">
                  <h4 className="text-sm font-bold text-[#1D2129] mb-3">字段说明</h4>
                  <div className="border border-[#E5E6EB] rounded-lg overflow-hidden">
                    <table className="w-full text-xs">
                      <thead className="bg-[#F7F8FA]">
                        <tr>
                          <th className="text-left px-3 py-2 text-[#4E5969] font-medium w-[35%]">字段名称</th>
                          <th className="text-left px-3 py-2 text-[#4E5969] font-medium w-[20%]">单位</th>
                          <th className="text-left px-3 py-2 text-[#4E5969] font-medium">说明</th>
                        </tr>
                      </thead>
                      <tbody>
                        {currentItem.fields.map((field, idx) => (
                          <tr key={idx} className={idx % 2 === 1 ? 'bg-[#FAFBFC]' : ''}>
                            <td className="px-3 py-2 text-[#1D2129] font-medium">{field.name}</td>
                            <td className="px-3 py-2 text-[#F53F3F] font-mono">{field.unit}</td>
                            <td className="px-3 py-2 text-[#86909C]">{field.description}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>

                {/* Data Source */}
                {currentItem.dataSource && (
                  <div className="flex items-start gap-2 p-3 bg-[#00B4FF]/5 rounded-lg border border-[#00B4FF]/20">
                    <i className="ri-database-2-line text-[#00B4FF] text-sm mt-0.5" />
                    <div>
                      <span className="text-xs font-medium text-[#00B4FF]">数据来源：</span>
                      <span className="text-xs text-[#4E5969]">{currentItem.dataSource}</span>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}