import { useEffect } from 'react';

interface ToastProps {
  message: string;
  type: 'success' | 'error';
  onClose: () => void;
}

export default function Toast({ message, type, onClose }: ToastProps) {
  useEffect(() => {
    const timer = setTimeout(onClose, 3000);
    return () => clearTimeout(timer);
  }, [onClose]);

  const bgColor = type === 'success' ? 'bg-emerald-500' : 'bg-red-500';
  const icon = type === 'success' ? 'ri-checkbox-circle-line' : 'ri-error-warning-line';

  return (
    <div
      className={`fixed top-6 left-1/2 -translate-x-1/2 z-50 flex items-center gap-2 px-6 py-3 rounded-lg text-white shadow-lg ${bgColor} animate-fade-in`}
    >
      <i className={`${icon} text-lg w-5 h-5 flex items-center justify-center`} />
      <span className="text-sm font-medium">{message}</span>
    </div>
  );
}
