import { useState, useMemo } from 'react';
import type { ReconPoint } from '@/mocks/bidAnalysisMock';

interface DetailTableProps {
  data: ReconPoint[];
}

type SortKey = 'idx' | 'forecastQty' | 'adjustRatio' | 'bidQty' | 'adjustQty' | 'dayAheadPrice' | 'realTimePrice' | 'adjustRevenue' | 'spotRevenueBefore' | 'spotRevenueAfter' | 'forecastDeviation';
type SortDir = 'asc' | 'desc';

export default function DetailTable({ data }: DetailTableProps) {
  const [sortKey, setSortKey] = useState<SortKey>('idx');
  const [sortDir, setSortDir] = useState<SortDir>('asc');
  const [showRiskOnly, setShowRiskOnly] = useState(false);
  const [searchTime, setSearchTime] = useState('');

  const toggleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortDir(prev => prev === 'asc' ? 'desc' : 'asc');
    } else {
      setSortKey(key);
      setSortDir('desc');
    }
  };

  const sortedData = useMemo(() => {
    let filtered = [...data];
    if (showRiskOnly) filtered = filtered.filter(d => Math.abs(d.forecastDeviation) > 10);
    if (searchTime) filtered = filtered.filter(d => d.time.includes(searchTime));

    return filtered.sort((a, b) => {
      const aVal = a[sortKey];
      const bVal = b[sortKey];
      if (typeof aVal === 'number' && typeof bVal === 'number') {
        return sortDir === 'asc' ? aVal - bVal : bVal - aVal;
      }
      if (typeof aVal === 'string' && typeof bVal === 'string') {
        return sortDir === 'asc' ? aVal.localeCompare(bVal) : bVal.localeCompare(aVal);
      }
      return 0;
    });
  }, [data, sortKey, sortDir, showRiskOnly, searchTime]);

  const exportCSV = () => {
    const headers = ['时间','预测值(MWh)','调整比例','日前申报值(MWh)','调整电量(MWh)','日前电价(元/MWh)','实时电价(元/MWh)','调整收益(元)','调整前现货收益(元)','调整后现货收益(元)','能销日前结算(MWh)','能销实时结算(MWh)','预测偏差(%)'];
    const rows = sortedData.map(d => [
      d.time,
      d.forecastQty.toFixed(3),
      `${(d.adjustRatio * 100).toFixed(2)}%`,
      d.bidQty.toFixed(3),
      d.adjustQty.toFixed(3),
      d.dayAheadPrice.toFixed(2),
      d.realTimePrice.toFixed(2),
      d.adjustRevenue.toFixed(2),
      d.spotRevenueBefore.toFixed(2),
      d.spotRevenueAfter.toFixed(2),
      d.settleDayAheadQty.toFixed(3),
      d.settleRealTimeQty.toFixed(3),
      `${d.forecastDeviation.toFixed(2)}%`,
    ]);
    const csv = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `日前复盘_${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const SortIcon = ({ colKey }: { colKey: SortKey }) => {
    const active = sortKey === colKey;
    return (
      <i className={`ri-arrow-up-down-line text-[10px] ml-1 ${active ? 'text-[#165DFF]' : 'text-[#86909C]'}`} />
    );
  };

  const isHighRisk = (d: ReconPoint) => Math.abs(d.forecastDeviation) > 10;

  return (
    <div className="bg-white rounded-lg border border-[#E5E6EB]">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between px-4 py-3 border-b border-[#E5E6EB] gap-2">
        <div>
          <h3 className="text-sm font-bold text-[#1D2129]">详细数据表</h3>
          <p className="text-[10px] text-[#86909C] mt-0.5">96点15分钟粒度复盘数据 | 电量：MWh | 价格：元/MWh | 收益：元</p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <input
            type="text"
            value={searchTime}
            onChange={e => setSearchTime(e.target.value)}
            placeholder="搜索时间..."
            className="text-xs px-2.5 py-1.5 rounded border border-[#E5E6EB] bg-white text-[#1D2129] focus:border-[#165DFF] focus:outline-none w-[100px]"
          />
          <button
            onClick={() => setShowRiskOnly(!showRiskOnly)}
            className={`px-3 py-1.5 rounded text-xs cursor-pointer whitespace-nowrap transition-colors ${
              showRiskOnly ? 'bg-[#F53F3F] text-white' : 'border border-[#E5E6EB] text-[#4E5969] hover:border-[#165DFF]'
            }`}
          >
            {showRiskOnly ? '显示全部' : '仅高风险'}
          </button>
          <button
            onClick={exportCSV}
            className="flex items-center gap-1 px-3 py-1.5 rounded border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap"
          >
            <i className="ri-download-line" /> 导出数据
          </button>
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-[11px]">
          <thead>
            <tr className="border-b border-[#E5E6EB] bg-[#F7F8FA]">
              <th className="text-center py-2.5 px-2 font-medium text-[#4E5969] cursor-pointer whitespace-nowrap" onClick={() => toggleSort('idx')}>
                时间 <SortIcon colKey="idx" />
              </th>
              <th className="text-right py-2.5 px-2 font-medium text-[#4E5969] cursor-pointer whitespace-nowrap" onClick={() => toggleSort('forecastQty')}>
                预测值 <SortIcon colKey="forecastQty" />
              </th>
              <th className="text-right py-2.5 px-2 font-medium text-[#4E5969] cursor-pointer whitespace-nowrap" onClick={() => toggleSort('adjustRatio')}>
                调整比例 <SortIcon colKey="adjustRatio" />
              </th>
              <th className="text-right py-2.5 px-2 font-medium text-[#4E5969] cursor-pointer whitespace-nowrap" onClick={() => toggleSort('bidQty')}>
                日前申报值 <SortIcon colKey="bidQty" />
              </th>
              <th className="text-right py-2.5 px-2 font-medium text-[#4E5969] cursor-pointer whitespace-nowrap" onClick={() => toggleSort('adjustQty')}>
                调整电量 <SortIcon colKey="adjustQty" />
              </th>
              <th className="text-right py-2.5 px-2 font-medium text-[#4E5969] cursor-pointer whitespace-nowrap" onClick={() => toggleSort('dayAheadPrice')}>
                日前电价 <SortIcon colKey="dayAheadPrice" />
              </th>
              <th className="text-right py-2.5 px-2 font-medium text-[#4E5969] cursor-pointer whitespace-nowrap" onClick={() => toggleSort('realTimePrice')}>
                实时电价 <SortIcon colKey="realTimePrice" />
              </th>
              <th className="text-right py-2.5 px-2 font-medium text-[#4E5969] cursor-pointer whitespace-nowrap" onClick={() => toggleSort('adjustRevenue')}>
                调整收益 <SortIcon colKey="adjustRevenue" />
              </th>
              <th className="text-right py-2.5 px-2 font-medium text-[#4E5969] cursor-pointer whitespace-nowrap" onClick={() => toggleSort('spotRevenueBefore')}>
                调整前现货收益 <SortIcon colKey="spotRevenueBefore" />
              </th>
              <th className="text-right py-2.5 px-2 font-medium text-[#4E5969] cursor-pointer whitespace-nowrap" onClick={() => toggleSort('spotRevenueAfter')}>
                调整后现货收益 <SortIcon colKey="spotRevenueAfter" />
              </th>
              <th className="text-right py-2.5 px-2 font-medium text-[#4E5969]">能销日前结算</th>
              <th className="text-right py-2.5 px-2 font-medium text-[#4E5969]">能销实时结算</th>
              <th className="text-right py-2.5 px-2 font-medium text-[#4E5969] cursor-pointer whitespace-nowrap" onClick={() => toggleSort('forecastDeviation')}>
                预测偏差 <SortIcon colKey="forecastDeviation" />
              </th>
            </tr>
          </thead>
          <tbody>
            {sortedData.map((row, idx) => (
              <tr
                key={idx}
                className={`border-b border-[#E5E6EB]/60 ${idx % 2 === 0 ? 'bg-[#F7F8FA]' : ''} ${isHighRisk(row) ? 'bg-[#F53F3F]/5' : ''} hover:bg-[#165DFF]/5 transition-colors`}
              >
                <td className="py-2 px-2 text-center font-medium text-[#1D2129]">
                  <div className="flex items-center justify-center gap-1">
                    {isHighRisk(row) && <span className="w-1.5 h-1.5 rounded-full bg-[#F53F3F]" />}
                    {row.time}
                  </div>
                </td>
                <td className="py-2 px-2 text-right text-[#165DFF] font-medium">{row.forecastQty.toFixed(3)}</td>
                <td className={`py-2 px-2 text-right font-medium ${row.adjustRatio !== 0 ? 'text-[#FF7D00]' : 'text-[#86909C]'}`}>
                  {row.adjustRatio > 0 ? '+' : ''}{(row.adjustRatio * 100).toFixed(2)}%
                </td>
                <td className="py-2 px-2 text-right text-[#00C48C] font-medium">{row.bidQty.toFixed(3)}</td>
                <td className={`py-2 px-2 text-right font-medium ${row.adjustQty > 0 ? 'text-[#F53F3F]' : row.adjustQty < 0 ? 'text-[#165DFF]' : 'text-[#86909C]'}`}>
                  {row.adjustQty > 0 ? '+' : ''}{row.adjustQty.toFixed(3)}
                </td>
                <td className="py-2 px-2 text-right text-[#4E5969]">{row.dayAheadPrice.toFixed(2)}</td>
                <td className="py-2 px-2 text-right text-[#4E5969]">{row.realTimePrice.toFixed(2)}</td>
                <td className={`py-2 px-2 text-right font-medium ${row.adjustRevenue >= 0 ? 'text-[#165DFF]' : 'text-[#F53F3F]'}`}>
                  {row.adjustRevenue > 0 ? '+' : ''}{row.adjustRevenue.toLocaleString()}
                </td>
                <td className={`py-2 px-2 text-right font-medium ${row.spotRevenueBefore >= 0 ? 'text-[#165DFF]' : 'text-[#F53F3F]'}`}>
                  {row.spotRevenueBefore > 0 ? '+' : ''}{row.spotRevenueBefore.toLocaleString()}
                </td>
                <td className={`py-2 px-2 text-right font-bold ${row.spotRevenueAfter >= 0 ? 'text-[#00C48C]' : 'text-[#F53F3F]'}`}>
                  {row.spotRevenueAfter > 0 ? '+' : ''}{row.spotRevenueAfter.toLocaleString()}
                </td>
                <td className="py-2 px-2 text-right text-[#4E5969]">{row.settleDayAheadQty.toFixed(3)}</td>
                <td className="py-2 px-2 text-right text-[#4E5969]">{row.settleRealTimeQty.toFixed(3)}</td>
                <td className={`py-2 px-2 text-right font-bold ${Math.abs(row.forecastDeviation) > 10 ? 'text-[#F53F3F]' : 'text-[#4E5969]'}`}>
                  {row.forecastDeviation > 0 ? '+' : ''}{row.forecastDeviation.toFixed(1)}%
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="px-4 py-3 border-t border-[#E5E6EB] flex items-center justify-between">
        <p className="text-[11px] text-[#86909C]">
          共 {sortedData.length} 条记录 {showRiskOnly ? '（仅高风险时段）' : ''}
        </p>
        <p className="text-[11px] text-[#86909C]">
          数据日期：2026-05-18 | 数据来源于日前复盘系统
        </p>
      </div>
    </div>
  );
}