import { useState, useMemo } from 'react';
import SpotTradingLayout from '@/pages/spot-trading/components/SpotTradingLayout';
import {
  buildReconData,
  buildReconSummary,
} from '@/mocks/bidAnalysisMock';
import KpiCards from '@/pages/spot-trading/analysis/bid/components/KpiCards';
import RevenueChart from '@/pages/spot-trading/analysis/bid/components/RevenueChart';
import DetailTable from '@/pages/spot-trading/analysis/bid/components/DetailTable';

type RevenueFilter = 'all' | 'adjusted' | 'price' | 'deviation' | 'profit';

export default function BidAnalysisPage() {
  const [date, setDate] = useState('2026-05-18');
  const [revenueFilter, setRevenueFilter] = useState<RevenueFilter>('all');
  const [collapsedSections, setCollapsedSections] = useState<Record<string, boolean>>({
    revenue: false,
    detail: false,
  });

  const reconData = useMemo(() => buildReconData(), []);
  const summary = useMemo(() => buildReconSummary(reconData), [reconData]);

  const toggleSection = (key: string) => {
    setCollapsedSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <SpotTradingLayout>
      <div className="space-y-4">
        {/* Top Control Bar */}
        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB] flex items-center gap-3 flex-wrap">
          <div className="flex items-center gap-2">
            <span className="text-xs text-[#4E5969]">日期选择：</span>
            <input
              type="date"
              value={date}
              onChange={e => setDate(e.target.value)}
              className="text-xs px-2.5 py-1.5 rounded border border-[#E5E6EB] bg-white text-[#1D2129] focus:border-[#165DFF] focus:outline-none"
            />
          </div>
          <button className="flex items-center gap-1 px-3 py-1.5 rounded bg-[#165DFF] text-white text-xs hover:bg-[#1247cc] transition-colors cursor-pointer whitespace-nowrap">
            <i className="ri-search-line" /> 搜索
          </button>
          <button className="flex items-center gap-1 px-3 py-1.5 rounded border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
            <i className="ri-refresh-line" /> 重置
          </button>
          <div className="ml-auto flex items-center gap-3 text-[11px] text-[#86909C]">
            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-[#165DFF]" /> 调整前</span>
            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-[#00C48C]" /> 调整后</span>
            <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-[#F53F3F]" /> 亏损</span>
          </div>
        </div>

        {/* KPI Area */}
        <KpiCards summary={summary} data={reconData} />

        {/* Core Revenue Chart */}
        <div className="bg-white rounded-lg border border-[#E5E6EB]">
          <button
            onClick={() => toggleSection('revenue')}
            className="w-full flex items-center justify-between px-4 py-3 cursor-pointer hover:bg-[#F7F8FA] transition-colors"
          >
            <div className="flex items-center gap-2">
              <div className="w-7 h-7 rounded-md bg-[#165DFF]/10 flex items-center justify-center">
                <i className="ri-bar-chart-line text-xs text-[#165DFF]" />
              </div>
              <span className="text-sm font-bold text-[#1D2129]">每小时收益对比</span>
              <span className="text-[11px] text-[#86909C]">调整前 vs 调整后现货收益 + 电价曲线</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="flex items-center gap-1">
                {[
                  { key: 'all', label: '全部' },
                  { key: 'adjusted', label: '已调整' },
                  { key: 'price', label: '价差大' },
                  { key: 'deviation', label: '高风险' },
                  { key: 'profit', label: '盈利' },
                ].map(f => (
                  <button
                    key={f.key}
                    onClick={(e) => { e.stopPropagation(); setRevenueFilter(f.key as RevenueFilter); }}
                    className={`px-2.5 py-0.5 rounded text-[11px] cursor-pointer whitespace-nowrap transition-colors ${
                      revenueFilter === f.key
                        ? 'bg-[#165DFF] text-white'
                        : 'border border-[#E5E6EB] text-[#4E5969] hover:border-[#165DFF]'
                    }`}
                  >
                    {f.label}
                  </button>
                ))}
              </div>
              <i className={`ri-arrow-down-s-line text-[#86909C] transition-transform ${collapsedSections.revenue ? 'rotate-180' : ''}`} />
            </div>
          </button>
          {!collapsedSections.revenue && (
            <div className="p-4 border-t border-[#E5E6EB]">
              <RevenueChart data={reconData} filter={revenueFilter} />
            </div>
          )}
        </div>

        {/* Detail Data Table */}
        <div className="bg-white rounded-lg border border-[#E5E6EB]">
          <button
            onClick={() => toggleSection('detail')}
            className="w-full flex items-center justify-between px-4 py-3 cursor-pointer hover:bg-[#F7F8FA] transition-colors"
          >
            <div className="flex items-center gap-2">
              <div className="w-7 h-7 rounded-md bg-[#00C48C]/10 flex items-center justify-center">
                <i className="ri-table-2 text-xs text-[#00C48C]" />
              </div>
              <span className="text-sm font-bold text-[#1D2129]">详细数据表</span>
              <span className="text-[11px] text-[#86909C]">96点复盘完整数据 | 支持排序、筛选、导出</span>
            </div>
            <i className={`ri-arrow-down-s-line text-[#86909C] transition-transform ${collapsedSections.detail ? 'rotate-180' : ''}`} />
          </button>
          {!collapsedSections.detail && (
            <div className="border-t border-[#E5E6EB]">
              <DetailTable data={reconData} />
            </div>
          )}
        </div>
      </div>
    </SpotTradingLayout>
  );
}