import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import SpotTradingLayout from '@/pages/spot-trading/components/SpotTradingLayout';
import { interprovincialForecastData } from '@/mocks/dataMgmtData';
import ConfirmModal from '@/components/ConfirmModal';
import Toast from '@/components/Toast';

export default function InterprovincialDataPage() {
  const navigate = useNavigate();

  // Filters
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [filterDirection, setFilterDirection] = useState('');

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  // Modals
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [deleteItemDate, setDeleteItemDate] = useState<string | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [showSimilarModal, setShowSimilarModal] = useState(false);
  const [newDate, setNewDate] = useState('');
  const [similarDate, setSimilarDate] = useState('');
  const [selectedSimilarDay, setSelectedSimilarDay] = useState<string | null>(null);

  // Toast
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  const todayStr = '2026-05-07';
  const isFuture = (date: string) => date >= todayStr;

  // Filtered data
  const filteredData = useMemo(() => {
    let data = [...interprovincialForecastData];
    if (startDate) data = data.filter(item => item.date >= startDate);
    if (endDate) data = data.filter(item => item.date <= endDate);
    if (filterDirection) data = data.filter(item => item.direction === filterDirection);
    return data;
  }, [startDate, endDate, filterDirection]);

  const totalPages = Math.ceil(filteredData.length / pageSize);
  const pageData = filteredData.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const handleSearch = () => { setCurrentPage(1); };
  const handleReset = () => { setStartDate(''); setEndDate(''); setFilterDirection(''); setCurrentPage(1); };

  const handleDelete = (date: string) => {
    if (!isFuture(date)) return;
    setDeleteItemDate(date);
    setShowDeleteModal(true);
  };

  const confirmDelete = () => {
    if (deleteItemDate) {
      setToast({ message: `已删除 ${deleteItemDate} 的维护记录`, type: 'success' });
      setDeleteItemDate(null);
    }
    setShowDeleteModal(false);
  };

  const handleExport = () => { setToast({ message: 'Excel 导出成功', type: 'success' }); };
  const handleImport = () => { setToast({ message: 'Excel 导入功能暂未接入后端', type: 'error' }); };
  const handleTemplateDownload = () => { setToast({ message: '模板下载成功', type: 'success' }); };

  const handleAdd = () => { setNewDate(''); setShowAddModal(true); };
  const confirmAdd = () => {
    if (!newDate) { setToast({ message: '请先选择日期', type: 'error' }); return; }
    setShowAddModal(false);
    navigate(`/spot-trading/data-mgmt/interprovincial/detail?date=${newDate}&mode=edit&blank=true`);
  };

  // Similar day logic
  const handleSimilarAdd = () => { setSimilarDate(''); setSelectedSimilarDay(null); setShowSimilarModal(true); };

  const similarMatches = useMemo(() => {
    if (!similarDate) return [];
    // Mock 3 similar days based on the selected date
    return [
      { date: '2026-04-28', similarity: '94%', reason: '天气类型/温度区间/工作日匹配' },
      { date: '2026-04-30', similarity: '92%', reason: '温度区间/节假日属性匹配' },
      { date: '2026-04-25', similarity: '90%', reason: '天气类型/工作日类型匹配' },
    ];
  }, [similarDate]);

  const confirmSimilarAdd = () => {
    if (!similarDate) { setToast({ message: '请先选择预测日期', type: 'error' }); return; }
    if (!selectedSimilarDay) { setToast({ message: '请选择一个相似日', type: 'error' }); return; }
    setShowSimilarModal(false);
    navigate(`/spot-trading/data-mgmt/interprovincial/detail?date=${similarDate}&mode=edit&similarDay=${selectedSimilarDay}`);
  };

  const handleView = (date: string) => {
    navigate(`/spot-trading/data-mgmt/interprovincial/detail?date=${date}&mode=view`);
  };

  const handleEdit = (date: string) => {
    navigate(`/spot-trading/data-mgmt/interprovincial/detail?date=${date}&mode=edit`);
  };

  return (
    <SpotTradingLayout>
      <div className="w-full max-w-full">
        {/* Header */}
        <div className="flex items-center justify-between mb-5">
          <div>
            <h1 className="text-lg font-bold text-[#1D2129]">省间现货预测维护</h1>
            <p className="text-xs text-[#86909C] mt-1">按日更新省间现货预测数据，支持相似日匹配</p>
          </div>
        </div>

        {/* Filter + Action bar */}
        <div className="bg-white rounded-xl p-4 border border-[#E5E6EB] mb-4">
          <div className="flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-2">
              <span className="text-xs text-[#86909C]">起始日期</span>
              <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="text-xs px-2.5 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]" />
            </div>
            <div className="flex items-center gap-2">
              <span className="text-xs text-[#86909C]">结束日期</span>
              <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="text-xs px-2.5 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]" />
            </div>
            <div className="flex items-center gap-2">
              <span className="text-xs text-[#86909C]">交易方向</span>
              <select value={filterDirection} onChange={(e) => setFilterDirection(e.target.value)} className="text-xs px-2.5 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]">
                <option value="">全部</option>
                <option value="购电">购电</option>
                <option value="售电">售电</option>
              </select>
            </div>
            <button onClick={handleSearch} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-blue-600 transition-colors cursor-pointer whitespace-nowrap"><i className="ri-search-line" />查询</button>
            <button onClick={handleReset} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"><i className="ri-refresh-line" />重置</button>

            <div className="ml-auto flex items-center gap-2">
              <button onClick={handleAdd} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#00C48C]/15 text-[#00C48C] text-xs hover:bg-emerald-100 transition-colors cursor-pointer whitespace-nowrap"><i className="ri-add-line" />新增</button>
              <button onClick={handleSimilarAdd} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#FF7D00]/15 text-[#FF7D00] text-xs hover:bg-orange-100 transition-colors cursor-pointer whitespace-nowrap"><i className="ri-calendar-event-line" />相似日新增</button>
              <button onClick={handleImport} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF]/15 text-[#165DFF] text-xs hover:bg-[#165DFF]/25 transition-colors cursor-pointer whitespace-nowrap"><i className="ri-file-upload-line" />Excel导入</button>
              <button onClick={handleExport} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF]/15 text-[#165DFF] text-xs hover:bg-[#165DFF]/25 transition-colors cursor-pointer whitespace-nowrap"><i className="ri-download-line" />导出</button>
              <button onClick={handleTemplateDownload} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"><i className="ri-file-list-line" />模板下载</button>
            </div>
          </div>
        </div>

        {/* Table */}
        <div className="bg-white rounded-xl border border-[#E5E6EB] overflow-x-auto" style={{ overflowX: 'auto' }}>
          <table className="w-full text-xs" style={{ minWidth: 'max-content' }}>
            <thead>
              <tr className="border-b border-[#E5E6EB] bg-[#F7F8FA]">
                <th className="text-center py-2.5 px-2 font-medium text-[#86909C] w-10">序号</th>
                <th className="text-left py-2.5 px-3 font-medium text-[#86909C]">日期</th>
                <th className="text-center py-2.5 px-3 font-medium text-[#86909C]">交易方向</th>
                <th className="text-right py-2.5 px-3 font-medium text-[#86909C]">总电量 (MWh)</th>
                <th className="text-right py-2.5 px-3 font-medium text-[#86909C]">加权均价 (元/MWh)</th>
                <th className="text-center py-2.5 px-3 font-medium text-[#86909C]">数据来源</th>
                <th className="text-left py-2.5 px-3 font-medium text-[#86909C]">更新时间</th>
                <th className="text-center py-2.5 px-3 font-medium text-[#86909C]">操作</th>
              </tr>
            </thead>
            <tbody>
              {pageData.map((item, idx) => {
                const future = isFuture(item.date);
                return (
                  <tr key={item.date} className="border-b border-[#E5E6EB]/50 hover:bg-[#F7F8FA]/60">
                    <td className="py-2 px-2 text-center text-[#86909C]">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="py-2 px-3 text-[#1D2129] font-medium whitespace-nowrap">{item.date}</td>
                    <td className="py-2 px-3 text-center">
                      <span className={`text-[10px] px-2 py-0.5 rounded-full ${item.direction === '购电' ? 'bg-[#165DFF]/10 text-[#165DFF]' : 'bg-[#FF7D00]/10 text-[#FF7D00]'}`}>{item.direction}</span>
                    </td>
                    <td className="py-2 px-3 text-right text-[#1D2129] font-bold">{item.total.toLocaleString()}</td>
                    <td className="py-2 px-3 text-right text-[#1D2129]">{item.avgPrice}</td>
                    <td className="py-2 px-3 text-center">
                      <span className={`text-[10px] px-2 py-0.5 rounded-full ${item.dataSource === '系统同步' ? 'bg-[#165DFF]/10 text-[#165DFF]' : 'bg-[#FF7D00]/10 text-[#FF7D00]'}`}>{item.dataSource}</span>
                    </td>
                    <td className="py-2 px-3 text-[#86909C] whitespace-nowrap">{item.updatedAt}</td>
                    <td className="py-2 px-3 text-center">
                      <div className="flex items-center justify-center gap-2">
                        <button onClick={() => handleView(item.date)} className="text-[#165DFF] hover:text-blue-600 transition-colors cursor-pointer" title="查看"><i className="ri-eye-line" /></button>
                        <button onClick={() => handleEdit(item.date)} className="text-amber-500 hover:text-amber-600 transition-colors cursor-pointer" title="编辑"><i className="ri-edit-line" /></button>
                        <button onClick={() => handleDelete(item.date)} disabled={!future} title={future ? '删除' : '历史数据不可删除'} className={`transition-colors ${future ? 'text-[#F53F3F] hover:text-red-600 cursor-pointer' : 'text-gray-300 cursor-not-allowed'}`}><i className="ri-delete-bin-line" /></button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>

          {totalPages > 1 && (
            <div className="flex items-center justify-between px-4 py-3 border-t border-[#E5E6EB]">
              <span className="text-[11px] text-[#86909C]">共 {filteredData.length} 条，第 {currentPage} / {totalPages} 页</span>
              <div className="flex items-center gap-1">
                <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="w-7 h-7 flex items-center justify-center rounded-md border border-[#E5E6EB] text-[#4E5969] hover:bg-[#F7F8FA] disabled:text-gray-300 disabled:cursor-not-allowed cursor-pointer transition-colors"><i className="ri-arrow-left-s-line" /></button>
                {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                  <button key={page} onClick={() => setCurrentPage(page)} className={`w-7 h-7 flex items-center justify-center rounded-md text-[11px] cursor-pointer transition-colors ${page === currentPage ? 'bg-[#165DFF] text-white' : 'border border-[#E5E6EB] text-[#4E5969] hover:bg-[#F7F8FA]'}`}>{page}</button>
                ))}
                <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="w-7 h-7 flex items-center justify-center rounded-md border border-[#E5E6EB] text-[#4E5969] hover:bg-[#F7F8FA] disabled:text-gray-300 disabled:cursor-not-allowed cursor-pointer transition-colors"><i className="ri-arrow-right-s-line" /></button>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Delete modal */}
      {showDeleteModal && <ConfirmModal title="确认删除" message="删除后数据不可恢复，是否确认删除？" onConfirm={confirmDelete} onCancel={() => { setShowDeleteModal(false); setDeleteItemDate(null); }} />}

      {/* Add modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
          <div className="bg-white rounded-xl p-6 w-full max-w-sm mx-4 shadow-xl">
            <h3 className="text-sm font-bold text-[#1D2129] mb-4">新增维护记录</h3>
            <div className="mb-5">
              <label className="block text-xs text-[#86909C] mb-1.5">选择日期</label>
              <input type="date" value={newDate} onChange={(e) => setNewDate(e.target.value)} className="w-full text-xs px-3 py-2 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]" />
              <p className="text-[11px] text-[#86909C] mt-1.5">生成空白编辑页，用户可手动录入数据</p>
            </div>
            <div className="flex gap-3 justify-end">
              <button onClick={() => setShowAddModal(false)} className="px-4 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">取消</button>
              <button onClick={confirmAdd} className="px-4 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-blue-600 transition-colors cursor-pointer whitespace-nowrap">确认</button>
            </div>
          </div>
        </div>
      )}

      {/* Similar day modal */}
      {showSimilarModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
          <div className="bg-white rounded-xl p-6 w-full max-w-md mx-4 shadow-xl">
            <h3 className="text-sm font-bold text-[#1D2129] mb-4">相似日新增</h3>
            <div className="mb-4">
              <label className="block text-xs text-[#86909C] mb-1.5">选择预测日期</label>
              <input type="date" value={similarDate} onChange={(e) => { setSimilarDate(e.target.value); setSelectedSimilarDay(null); }} className="w-full text-xs px-3 py-2 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]" />
            </div>
            {similarDate && similarMatches.length > 0 && (
              <div className="mb-4">
                <label className="block text-xs text-[#86909C] mb-2">系统匹配的相似历史日期（请选择其一）</label>
                <div className="space-y-2">
                  {similarMatches.map((match) => (
                    <div key={match.date} onClick={() => setSelectedSimilarDay(match.date)} className={`flex items-center justify-between p-3 rounded-lg border cursor-pointer transition-colors ${selectedSimilarDay === match.date ? 'border-[#165DFF] bg-[#165DFF]/5' : 'border-[#E5E6EB] hover:bg-[#F7F8FA]'}`}>
                      <div className="flex items-center gap-3">
                        <input type="radio" checked={selectedSimilarDay === match.date} onChange={() => setSelectedSimilarDay(match.date)} className="cursor-pointer" />
                        <div>
                          <span className="text-xs font-medium text-[#1D2129]">{match.date}</span>
                          <p className="text-[11px] text-[#86909C] mt-0.5">{match.reason}</p>
                        </div>
                      </div>
                      <span className="text-xs font-bold text-[#00C48C]">{match.similarity}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
            {similarDate && similarMatches.length === 0 && (
              <div className="mb-4 p-3 bg-[#F7F8FA] rounded-lg">
                <p className="text-xs text-[#86909C]">未找到符合条件的相似历史日期，请手动选择历史日期或取消操作。</p>
              </div>
            )}
            <div className="flex gap-3 justify-end">
              <button onClick={() => setShowSimilarModal(false)} className="px-4 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">取消</button>
              <button onClick={confirmSimilarAdd} disabled={!selectedSimilarDay} className={`px-4 py-1.5 rounded-md text-xs transition-colors whitespace-nowrap ${selectedSimilarDay ? 'bg-[#165DFF] text-white hover:bg-blue-600 cursor-pointer' : 'bg-gray-200 text-gray-400 cursor-not-allowed'}`}>确认</button>
            </div>
          </div>
        </div>
      )}

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </SpotTradingLayout>
  );
}
