import { useMemo } from 'react';
import type { ReconPoint } from '@/mocks/bidAnalysisMock';

interface RevenueChartProps {
  data: ReconPoint[];
  filter: 'all' | 'adjusted' | 'price' | 'deviation' | 'profit';
}

export default function RevenueChart({ data, filter }: RevenueChartProps) {
  // 按小时聚合
  const hourlyData = useMemo(() => {
    const map = new Map<number, ReconPoint[]>();
    data.forEach(d => {
      if (!map.has(d.hour)) map.set(d.hour, []);
      map.get(d.hour)!.push(d);
    });
    return Array.from(map.entries()).map(([hour, items]) => {
      const spotBefore = items.reduce((s, d) => s + d.spotRevenueBefore, 0);
      const spotAfter = items.reduce((s, d) => s + d.spotRevenueAfter, 0);
      const dapAvg = items.reduce((s, d) => s + d.dayAheadPrice, 0) / items.length;
      const rtpAvg = items.reduce((s, d) => s + d.realTimePrice, 0) / items.length;
      const adjustQty = items.reduce((s, d) => s + d.adjustQty, 0);
      const maxDev = Math.max(...items.map(d => Math.abs(d.forecastDeviation)));
      return {
        hour,
        label: `${hour.toString().padStart(2, '0')}:00`,
        spotBefore,
        spotAfter,
        dapAvg,
        rtpAvg,
        adjustQty,
        isHighRisk: maxDev > 10,
      };
    });
  }, [data]);

  const filtered = useMemo(() => {
    if (filter === 'all') return hourlyData;
    if (filter === 'adjusted') return hourlyData.filter(d => d.adjustQty !== 0);
    if (filter === 'price') return hourlyData.filter(d => Math.abs(d.rtpAvg - d.dapAvg) > 50);
    if (filter === 'deviation') return hourlyData.filter(d => d.isHighRisk);
    if (filter === 'profit') return hourlyData.filter(d => d.spotAfter > 0);
    return hourlyData;
  }, [hourlyData, filter]);

  const maxAbs = useMemo(() => {
    const vals = filtered.flatMap(d => [Math.abs(d.spotBefore), Math.abs(d.spotAfter)]);
    return vals.length > 0 ? Math.max(...vals, 1) : 1;
  }, [filtered]);

  const maxPrice = useMemo(() => {
    const vals = filtered.flatMap(d => [d.dapAvg, d.rtpAvg]);
    return vals.length > 0 ? Math.max(...vals, 1) : 1;
  }, [filtered]);

  const barW = Math.max(8, Math.min(28, Math.floor(700 / filtered.length)));

  return (
    <div>
      <div className="relative h-[260px] mt-4 px-2">
        <svg width="100%" height="100%" viewBox="0 0 900 260" preserveAspectRatio="none">
          {/* Grid */}
          {[0, 1, 2, 3, 4, 5].map(i => (
            <line key={`g${i}`} x1="40" y1={30 + i * 36} x2="880" y2={30 + i * 36} stroke="#F2F3F5" strokeWidth="1" />
          ))}
          {/* Zero line for revenue */}
          <line x1="40" y1="138" x2="880" y2="138" stroke="#E5E6EB" strokeWidth="1" strokeDasharray="4 4" />

          {/* Revenue bars (bottom half) */}
          {filtered.map((d, i) => {
            const gap = 840 / filtered.length;
            const x = 40 + i * gap;
            const h1 = Math.min(100, Math.max(2, (Math.abs(d.spotBefore) / maxAbs) * 100));
            const h2 = Math.min(100, Math.max(2, (Math.abs(d.spotAfter) / maxAbs) * 100));
            const y1 = d.spotBefore >= 0 ? 138 - h1 : 138;
            const y2 = d.spotAfter >= 0 ? 138 - h2 : 138;

            return (
              <g key={i}>
                {/* Before bar */}
                <rect x={x + 2} y={y1} width={barW * 0.45} height={h1} rx={2}
                  fill={d.spotBefore >= 0 ? '#165DFF' : '#F53F3F'} opacity={0.5} />
                {/* After bar */}
                <rect x={x + 2 + barW * 0.5} y={y2} width={barW * 0.45} height={h2} rx={2}
                  fill={d.spotAfter >= 0 ? '#00C48C' : '#F53F3F'} />
              </g>
            );
          })}

          {/* Price lines (top overlay) */}
          <polyline
            fill="none" stroke="#FF7D00" strokeWidth="2" opacity={0.8}
            points={filtered.map((d, i) => {
              const x = 40 + i * (840 / filtered.length) + barW / 2;
              const y = 30 + (1 - d.dapAvg / maxPrice) * 80;
              return `${x},${y}`;
            }).join(' ')}
          />
          <polyline
            fill="none" stroke="#86909C" strokeWidth="2" strokeDasharray="5 3" opacity={0.8}
            points={filtered.map((d, i) => {
              const x = 40 + i * (840 / filtered.length) + barW / 2;
              const y = 30 + (1 - d.rtpAvg / maxPrice) * 80;
              return `${x},${y}`;
            }).join(' ')}
          />

          {/* X labels */}
          {filtered.filter((_, i) => i % Math.max(1, Math.floor(filtered.length / 12)) === 0).map((d, i) => (
            <text key={i} x={40 + i * Math.max(1, Math.floor(filtered.length / 12)) * (840 / filtered.length) + barW / 2}
              y="255" fontSize="9" fill="#86909C" textAnchor="middle">{d.label}</text>
          ))}
        </svg>

        {/* Hover tooltips via overlay divs */}
        <div className="absolute inset-0 flex items-end" style={{ left: 40, right: 20, top: 30, bottom: 30 }}>
          {filtered.map((d, i) => {
            const gap = (840 / 900) * 100;
            return (
              <div key={i} className="group relative flex-1 h-full cursor-pointer">
                <div className="absolute bottom-full mb-1 left-1/2 -translate-x-1/2 hidden group-hover:block z-10 w-[220px]">
                  <div className="bg-white border border-[#E5E6EB] rounded-md p-3 text-[11px]">
                    <p className="font-bold text-[#1D2129] mb-1.5">{d.label} 复盘详情</p>
                    <div className="space-y-1">
                      <div className="flex justify-between"><span className="text-[#86909C]">日前电价</span><span className="text-[#FF7D00] font-medium">{d.dapAvg.toFixed(2)} 元/MWh</span></div>
                      <div className="flex justify-between"><span className="text-[#86909C]">实时电价</span><span className="text-[#86909C] font-medium">{d.rtpAvg.toFixed(2)} 元/MWh</span></div>
                      <div className="flex justify-between"><span className="text-[#86909C]">调整电量</span><span className="text-[#4E5969] font-medium">{d.adjustQty > 0 ? '+' : ''}{d.adjustQty.toFixed(1)} MWh</span></div>
                      <div className="border-t border-[#E5E6EB] my-1 pt-1" />
                      <div className="flex justify-between"><span className="text-[#86909C]">调整前收益</span><span className={d.spotBefore >= 0 ? 'text-[#165DFF] font-medium' : 'text-[#F53F3F] font-medium'}>{d.spotBefore > 0 ? '+' : ''}{d.spotBefore.toFixed(0)} 元</span></div>
                      <div className="flex justify-between"><span className="text-[#86909C]">调整后收益</span><span className={d.spotAfter >= 0 ? 'text-[#00C48C] font-medium' : 'text-[#F53F3F] font-medium'}>{d.spotAfter > 0 ? '+' : ''}{d.spotAfter.toFixed(0)} 元</span></div>
                      <div className="flex justify-between font-bold"><span className="text-[#1D2129]">收益变动</span><span className={(d.spotAfter - d.spotBefore) >= 0 ? 'text-[#00C48C]' : 'text-[#F53F3F]'}>{(d.spotAfter - d.spotBefore) > 0 ? '+' : ''}{(d.spotAfter - d.spotBefore).toFixed(0)} 元</span></div>
                    </div>
                    {d.isHighRisk && (
                      <div className="mt-1.5 px-2 py-0.5 rounded bg-[#F53F3F]/10 text-[#F53F3F] text-[10px] font-medium inline-block">
                        预测偏差超过阈值
                      </div>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="flex items-center justify-between mt-3 px-2">
        <div className="flex items-center gap-4 text-[10px] text-[#86909C]">
          <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-sm bg-[#165DFF] opacity-50" />调整前</span>
          <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-sm bg-[#00C48C]" />调整后</span>
          <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-sm bg-[#F53F3F]" />亏损</span>
          <span className="flex items-center gap-1"><span className="w-4 h-0.5 bg-[#FF7D00] rounded-full" />日前电价</span>
          <span className="flex items-center gap-1"><span className="w-4 h-0.5 bg-[#86909C] rounded-full" />实时电价</span>
        </div>
        <p className="text-[10px] text-[#86909C]">共 {filtered.length} 小时 | 鼠标悬停查看详情</p>
      </div>
    </div>
  );
}