import { useState } from 'react';
import AdminLayout from '../../components/AdminLayout';
import ConfirmModal from '@/components/ConfirmModal';
import Toast from '@/components/Toast';
import { syncConfigs, syncRecords } from '@/mocks/adminData';
import type { SyncConfig, SyncRecord } from '@/mocks/adminData';

export default function SyncConfigPage() {
  const [configs, setConfigs] = useState<SyncConfig[]>(syncConfigs);
  const [records] = useState<SyncRecord[]>(syncRecords);
  const [activeTab, setActiveTab] = useState<'config' | 'record'>('config');
  const [showEditModal, setShowEditModal] = useState(false);
  const [showTriggerModal, setShowTriggerModal] = useState(false);
  const [showRetryModal, setShowRetryModal] = useState(false);
  const [selectedConfig, setSelectedConfig] = useState<SyncConfig | null>(null);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  const [formData, setFormData] = useState({
    name: '', source: '', frequency: '', syncTimeRange: '', dataItems: '',
  });

  const showToast = (message: string, type: 'success' | 'error') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const getStatusStyle = (status: string) => {
    switch (status) {
      case 'running': return 'bg-[#00C48C]/10 text-[#00C48C]';
      case 'paused': return 'bg-[#FF7D00]/10 text-[#FF7D00]';
      case 'error': return 'bg-[#F53F3F]/10 text-[#F53F3F]';
      default: return 'bg-[#F7F8FA] text-[#86909C]';
    }
  };

  const getStatusLabel = (status: string) => {
    switch (status) {
      case 'running': return '运行中';
      case 'paused': return '已暂停';
      case 'error': return '异常';
      default: return status;
    }
  };

  const getRecordStatusStyle = (status: string) => {
    switch (status) {
      case 'success': return 'bg-[#00C48C]/10 text-[#00C48C]';
      case 'fail': return 'bg-[#F53F3F]/10 text-[#F53F3F]';
      case 'running': return 'bg-[#00B4FF]/10 text-[#00B4FF]';
      default: return 'bg-[#F7F8FA] text-[#86909C]';
    }
  };

  const getRecordStatusLabel = (status: string) => {
    switch (status) {
      case 'success': return '成功';
      case 'fail': return '失败';
      case 'running': return '执行中';
      default: return status;
    }
  };

  const openEdit = (config: SyncConfig) => {
    setSelectedConfig(config);
    setFormData({
      name: config.name, source: config.source, frequency: config.frequency,
      syncTimeRange: config.syncTimeRange, dataItems: config.dataItems.join('、'),
    });
    setShowEditModal(true);
  };

  const handleEdit = () => {
    if (!selectedConfig) return;
    setConfigs(prev => prev.map(c => c.id === selectedConfig.id ? {
      ...c, name: formData.name, source: formData.source, frequency: formData.frequency,
      syncTimeRange: formData.syncTimeRange, dataItems: formData.dataItems.split('、').filter(Boolean),
    } : c));
    setShowEditModal(false);
    showToast('配置修改成功', 'success');
  };

  const handleTrigger = () => {
    if (!selectedConfig) return;
    setConfigs(prev => prev.map(c => c.id === selectedConfig.id ? { ...c, lastSync: '2026-05-08 10:30', lastResult: 'success', status: 'running' as const } : c));
    setShowTriggerModal(false);
    showToast('手动同步已触发', 'success');
  };

  const handleRetry = () => {
    if (!selectedConfig) return;
    setConfigs(prev => prev.map(c => c.id === selectedConfig.id ? { ...c, status: 'running' as const, retryCount: 0, lastSync: '2026-05-08 10:30', lastResult: 'success' } : c));
    setShowRetryModal(false);
    showToast('同步失败重试已触发', 'success');
  };

  const toggleStatus = (config: SyncConfig) => {
    const newStatus = config.status === 'running' ? 'paused' : 'running';
    setConfigs(prev => prev.map(c => c.id === config.id ? { ...c, status: newStatus } : c));
    showToast(`同步任务已${newStatus === 'running' ? '启动' : '暂停'}`, 'success');
  };

  return (
    <AdminLayout>
      <div className="space-y-4 text-[#1D2129]">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">数据同步配置</h1>
            <p className="text-sm text-[#86909C] mt-1">配置上海电力交易中心、调度机构接口同步规则</p>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-0 bg-white rounded-lg border border-[#E5E6EB] overflow-hidden w-fit">
          <button
            onClick={() => setActiveTab('config')}
            className={`px-4 py-2 text-xs font-medium cursor-pointer whitespace-nowrap transition-colors ${
              activeTab === 'config' ? 'bg-[#165DFF] text-white' : 'text-[#4E5969] hover:text-[#165DFF] hover:bg-[#F7F8FA]'
            }`}
          >
            同步配置
          </button>
          <button
            onClick={() => setActiveTab('record')}
            className={`px-4 py-2 text-xs font-medium cursor-pointer whitespace-nowrap transition-colors ${
              activeTab === 'record' ? 'bg-[#165DFF] text-white' : 'text-[#4E5969] hover:text-[#165DFF] hover:bg-[#F7F8FA]'
            }`}
          >
            同步记录
          </button>
        </div>

        {/* Config Tab */}
        {activeTab === 'config' && (
          <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-xs">
                <thead className="bg-[#F7F8FA] sticky top-0">
                  <tr>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">序号</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">同步任务名称</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">数据源</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">同步频率</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">同步时段</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">同步数据项</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">状态</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">最后同步</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">下次同步</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">重试次数</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">操作</th>
                  </tr>
                </thead>
                <tbody>
                  {configs.map((config, idx) => (
                    <tr key={config.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : 'bg-white'}`}>
                      <td className="px-3 py-3 text-[#4E5969]">{idx + 1}</td>
                      <td className="px-3 py-3 text-[#1D2129] font-medium">{config.name}</td>
                      <td className="px-3 py-3 text-[#4E5969]">{config.source}</td>
                      <td className="px-3 py-3 text-[#4E5969]">{config.frequency}</td>
                      <td className="px-3 py-3 text-[#86909C]">{config.syncTimeRange}</td>
                      <td className="px-3 py-3 text-[#4E5969] max-w-[150px] truncate" title={config.dataItems.join('、')}>{config.dataItems.join('、')}</td>
                      <td className="px-3 py-3">
                        <span className={`text-[10px] px-2 py-0.5 rounded-full ${getStatusStyle(config.status)}`}>
                          {getStatusLabel(config.status)}
                        </span>
                      </td>
                      <td className="px-3 py-3 text-[#86909C]">{config.lastSync}</td>
                      <td className="px-3 py-3 text-[#86909C]">{config.nextSync}</td>
                      <td className="px-3 py-3 text-[#4E5969]">{config.retryCount}</td>
                      <td className="px-3 py-3">
                        <div className="flex items-center gap-1">
                          <button onClick={() => openEdit(config)} className="p-1 rounded hover:bg-[#165DFF]/10 text-[#86909C] hover:text-[#165DFF] cursor-pointer" title="编辑">
                            <i className="ri-edit-line text-xs" />
                          </button>
                          <button
                            onClick={() => { setSelectedConfig(config); setShowTriggerModal(true); }}
                            className="p-1 rounded hover:bg-[#00C48C]/10 text-[#86909C] hover:text-[#00C48C] cursor-pointer"
                            title="手动同步"
                          >
                            <i className="ri-refresh-line text-xs" />
                          </button>
                          <button onClick={() => toggleStatus(config)} className="p-1 rounded hover:bg-[#FF7D00]/10 text-[#86909C] hover:text-[#FF7D00] cursor-pointer" title={config.status === 'running' ? '暂停' : '启动'}>
                            <i className={config.status === 'running' ? 'ri-pause-line text-xs' : 'ri-play-line text-xs'} />
                          </button>
                          {config.status === 'error' && (
                            <button onClick={() => { setSelectedConfig(config); setShowRetryModal(true); }} className="p-1 rounded hover:bg-[#F53F3F]/10 text-[#86909C] hover:text-[#F53F3F] cursor-pointer" title="重试">
                              <i className="ri-restart-line text-xs" />
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Record Tab */}
        {activeTab === 'record' && (
          <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-xs">
                <thead className="bg-[#F7F8FA] sticky top-0">
                  <tr>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">序号</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">同步任务</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">触发时间</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">完成时间</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">执行状态</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">同步条数</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">耗时</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">触发方式</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">操作人</th>
                    <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">错误信息</th>
                  </tr>
                </thead>
                <tbody>
                  {records.map((record, idx) => (
                    <tr key={record.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : 'bg-white'}`}>
                      <td className="px-3 py-3 text-[#4E5969]">{idx + 1}</td>
                      <td className="px-3 py-3 text-[#1D2129] font-medium">{record.configName}</td>
                      <td className="px-3 py-3 text-[#86909C]">{record.triggerTime}</td>
                      <td className="px-3 py-3 text-[#86909C]">{record.completeTime || '-'}</td>
                      <td className="px-3 py-3">
                        <span className={`text-[10px] px-2 py-0.5 rounded-full ${getRecordStatusStyle(record.status)}`}>
                          {getRecordStatusLabel(record.status)}
                        </span>
                      </td>
                      <td className="px-3 py-3 text-[#4E5969]">{record.recordsCount}</td>
                      <td className="px-3 py-3 text-[#86909C]">{record.duration}</td>
                      <td className="px-3 py-3">
                        <span className={`text-[10px] px-2 py-0.5 rounded-full ${record.triggerType === 'auto' ? 'bg-[#00B4FF]/10 text-[#00B4FF]' : 'bg-[#165DFF]/10 text-[#165DFF]'}`}>
                          {record.triggerType === 'auto' ? '自动' : '手动'}
                        </span>
                      </td>
                      <td className="px-3 py-3 text-[#4E5969]">{record.operator || '-'}</td>
                      <td className="px-3 py-3 text-[#F53F3F] max-w-[200px] truncate" title={record.errorMsg || ''}>{record.errorMsg || '-'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      {/* Edit Modal */}
      {showEditModal && selectedConfig && (
        <ConfirmModal title="编辑同步配置" message="" onConfirm={handleEdit} onCancel={() => setShowEditModal(false)}>
          <div className="grid grid-cols-2 gap-3">
            <div className="col-span-2">
              <label className="text-xs text-[#1D2129] block mb-1">任务名称</label>
              <input value={formData.name} onChange={e => setFormData(p => ({ ...p, name: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" />
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">数据源</label>
              <input value={formData.source} onChange={e => setFormData(p => ({ ...p, source: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" />
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">同步频率</label>
              <input value={formData.frequency} onChange={e => setFormData(p => ({ ...p, frequency: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" placeholder="例如：每15分钟" />
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">同步时段</label>
              <input value={formData.syncTimeRange} onChange={e => setFormData(p => ({ ...p, syncTimeRange: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" placeholder="例如：00:00-24:00" />
            </div>
            <div className="col-span-2">
              <label className="text-xs text-[#1D2129] block mb-1">同步数据项（用"、"分隔）</label>
              <input value={formData.dataItems} onChange={e => setFormData(p => ({ ...p, dataItems: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" />
            </div>
          </div>
        </ConfirmModal>
      )}

      {/* Trigger Modal */}
      {showTriggerModal && selectedConfig && (
        <ConfirmModal
          title="手动触发同步"
          message={`确定要手动触发 "${selectedConfig.name}" 的数据同步任务吗？此操作将立即执行同步，不影响原有定时任务。`}
          onConfirm={handleTrigger}
          onCancel={() => setShowTriggerModal(false)}
        />
      )}

      {/* Retry Modal */}
      {showRetryModal && selectedConfig && (
        <ConfirmModal
          title="同步失败重试"
          message={`确定要重试 "${selectedConfig.name}" 的同步任务吗？当前已累计失败 ${selectedConfig.retryCount} 次。`}
          onConfirm={handleRetry}
          onCancel={() => setShowRetryModal(false)}
        />
      )}

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </AdminLayout>
  );
}