import { useState } from 'react';
import EnergySalesLayout from '../../components/EnergySalesLayout';
import ConfirmModal from '@/components/ConfirmModal';
import { settlementRecordList, type SettlementRecord } from '@/mocks/energySalesData';

export default function UploadMgmtPage() {
  const [searchName, setSearchName] = useState('');
  const [filterMonth, setFilterMonth] = useState('2026-04');
  const [filterType, setFilterType] = useState<'all' | 'thermal' | 'green' | 'capacity'>('all');
  const [showDelete, setShowDelete] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  const filtered = settlementRecordList.filter(s => {
    const nameMatch = !searchName || s.userName.includes(searchName);
    const monthMatch = s.month === filterMonth;
    const typeMatch = filterType === 'all' || s.powerType === filterType;
    return nameMatch && monthMatch && typeMatch;
  });

  const totalPages = Math.ceil(filtered.length / pageSize);
  const paged = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const getTypeStyle = (t: string) => {
    switch (t) {
      case 'thermal': return 'bg-[#FF7D00]/10 text-[#FF7D00]';
      case 'green': return 'bg-[#00C48C]/10 text-[#00C48C]';
      default: return 'bg-[#165DFF]/10 text-[#165DFF]';
    }
  };

  const getStatusStyle = (s: string) => {
    switch (s) {
      case 'valid': return 'bg-[#00C48C]/10 text-[#00C48C]';
      case 'invalid': return 'bg-[#F53F3F]/10 text-[#F53F3F]';
      default: return 'bg-[#FF7D00]/10 text-[#FF7D00]';
    }
  };

  return (
    <EnergySalesLayout>
      <div className="space-y-5 text-[#1D2129]">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">结算单上传管理</h1>
            <p className="text-sm text-[#86909C] mt-1">按月导入月度交易结算明细数据</p>
          </div>
          <div className="flex items-center gap-2">
            <button className="flex items-center gap-1.5 px-4 py-2 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/90 transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-upload-cloud-2-line" />
              导入结算单
            </button>
            <button className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-download-2-line" />
              导出Excel
            </button>
          </div>
        </div>

        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">用户名称</label>
              <input type="text" value={searchName} onChange={e => setSearchName(e.target.value)} placeholder="请输入用户名称" className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[180px]" />
            </div>
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">月份</label>
              <input type="month" value={filterMonth} onChange={e => setFilterMonth(e.target.value)} className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[140px]" />
            </div>
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">电量类型</label>
              <select value={filterType} onChange={e => setFilterType(e.target.value as 'all' | 'thermal' | 'green' | 'capacity')} className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[120px]">
                <option value="all">全部</option>
                <option value="thermal">火电</option>
                <option value="green">绿电</option>
                <option value="capacity">容量</option>
              </select>
            </div>
            <button className="flex items-center gap-1.5 px-4 py-2 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/90 transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-search-line" />
              查询
            </button>
            <button onClick={() => { setSearchName(''); setFilterMonth('2026-04'); setFilterType('all'); }} className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-refresh-line" />
              重置
            </button>
          </div>
        </div>

        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#F7F8FA]">
                <tr>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-0 bg-[#F7F8FA] z-10">序号</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-[48px] bg-[#F7F8FA] z-10">结算科目</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">用户名称</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">实际用电量</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">合同电量</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">结算电量</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">结算电价</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">结算电费</th>
                  <th className="px-4 py-3 text-center font-medium text-[#4E5969]">电量类型</th>
                  <th className="px-4 py-3 text-center font-medium text-[#4E5969]">数据状态</th>
                  <th className="px-4 py-3 text-center font-medium text-[#4E5969] sticky right-0 bg-[#F7F8FA] z-10">操作</th>
                </tr>
              </thead>
              <tbody>
                {paged.map((s, idx) => (
                  <tr key={s.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : ''}`}>
                    <td className="px-4 py-3 sticky left-0 bg-white z-10">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="px-4 py-3 sticky left-[48px] bg-white z-10">
                      <div>
                        <p className="font-medium">{s.subjectName}</p>
                        <p className="text-[10px] text-[#86909C]">{s.subjectCode}</p>
                      </div>
                    </td>
                    <td className="px-4 py-3 text-[#4E5969]">{s.userName}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{s.actualPower.toLocaleString()}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{s.contractPower.toLocaleString()}</td>
                    <td className="px-4 py-3 text-right font-medium text-[#165DFF]">{s.settlementPower.toLocaleString()}</td>
                    <td className="px-4 py-3 text-right text-[#4E5969]">{s.settlementPrice.toFixed(3)}</td>
                    <td className="px-4 py-3 text-right font-medium text-[#1D2129]">{(s.settlementAmount / 10000).toFixed(2)}</td>
                    <td className="px-4 py-3 text-center">
                      <span className={`px-2 py-0.5 rounded-full text-[10px] ${getTypeStyle(s.powerType)}`}>
                        {s.powerType === 'thermal' ? '火电' : s.powerType === 'green' ? '绿电' : '容量'}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-center">
                      <span className={`px-2 py-0.5 rounded-full text-[10px] ${getStatusStyle(s.dataStatus)}`}>
                        {s.dataStatus === 'valid' ? '正常' : s.dataStatus === 'invalid' ? '异常' : '警告'}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-center sticky right-0 bg-white z-10">
                      <div className="flex items-center gap-1 justify-center">
                        <button className="p-1 text-[#165DFF] hover:bg-[#165DFF]/10 rounded transition-colors cursor-pointer" title="编辑"><i className="ri-edit-line" /></button>
                        <button onClick={() => setShowDelete(true)} className="p-1 text-[#F53F3F] hover:bg-[#F53F3F]/10 rounded transition-colors cursor-pointer" title="删除"><i className="ri-delete-bin-line" /></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="flex items-center justify-between px-4 py-3 border-t border-[#E5E6EB]">
            <span className="text-xs text-[#86909C]">共 {filtered.length} 条，每页 {pageSize} 条</span>
            <div className="flex items-center gap-1">
              <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"><i className="ri-arrow-left-s-line" /></button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
                <button key={p} onClick={() => setCurrentPage(p)} className={`px-3 py-1 text-xs rounded cursor-pointer ${p === currentPage ? 'bg-[#165DFF] text-white' : 'border border-[#E5E6EB] hover:border-[#165DFF]'}`}>{p}</button>
              ))}
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"><i className="ri-arrow-right-s-line" /></button>
            </div>
          </div>
        </div>
      </div>

      {showDelete && <ConfirmModal title="确认删除" message="删除后无法恢复，是否确认？" onConfirm={() => setShowDelete(false)} onCancel={() => setShowDelete(false)} />}
    </EnergySalesLayout>
  );
}