import { useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { generateCaptcha } from '@/mocks/captcha';
import Toast from '@/components/Toast';

interface FormErrors {
  account?: string;
  password?: string;
  captcha?: string;
}

export default function LoginPage() {
  const navigate = useNavigate();
  const [account, setAccount] = useState('');
  const [password, setPassword] = useState('');
  const [captchaInput, setCaptchaInput] = useState('');
  const [captchaCode, setCaptchaCode] = useState(generateCaptcha);
  const [errors, setErrors] = useState<FormErrors>({});
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  const refreshCaptcha = useCallback(() => {
    setCaptchaCode(generateCaptcha());
    setCaptchaInput('');
  }, []);

  const validate = (): boolean => {
    const newErrors: FormErrors = {};
    if (!account.trim()) {
      newErrors.account = '请输入登录账号';
    }
    if (!password.trim()) {
      newErrors.password = '请输入登录密码';
    }
    if (!captchaInput.trim()) {
      newErrors.captcha = '请输入验证码';
    } else if (captchaInput.trim().toUpperCase() !== captchaCode) {
      newErrors.captcha = '验证码错误';
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleLogin = () => {
    if (!validate()) {
      setToast({ message: '请检查表单填写内容', type: 'error' });
      return;
    }

    // 模拟登录成功
    setToast({ message: '登录成功', type: 'success' });
    localStorage.setItem('hn_user', account);
    setTimeout(() => {
      navigate('/dashboard');
    }, 1000);
  };

  const isDisabled = !account.trim() || !password.trim() || !captchaInput.trim();

  return (
    <div className="min-h-screen bg-gradient-main flex flex-col items-center justify-center px-4 py-8 relative">
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          onClose={() => setToast(null)}
        />
      )}

      <div className="bg-white rounded-card shadow-lg w-full max-w-md p-8 md:p-10">
        {/* Logo & Title */}
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-hn-blue/10 rounded-full flex items-center justify-center mx-auto mb-4">
            <i className="ri-flashlight-line text-3xl text-hn-blue" />
          </div>
          <h1 className="text-lg font-bold text-hn-text">上海华能电力交易系统</h1>
        </div>

        {/* Form */}
        <div className="space-y-5">
          {/* Account */}
          <div>
            <div className="relative">
              <i className="ri-user-line absolute left-4 top-1/2 -translate-y-1/2 text-hn-text-secondary text-lg w-5 h-5 flex items-center justify-center" />
              <input
                type="text"
                value={account}
                onChange={(e) => {
                  setAccount(e.target.value);
                  setErrors((prev) => ({ ...prev, account: undefined }));
                }}
                placeholder="请输入登录账号"
                className="w-full pl-12 pr-4 py-3 rounded-xl border border-gray-200 text-sm text-hn-text placeholder:text-gray-400 focus:outline-none focus:border-hn-blue focus:ring-1 focus:ring-hn-blue transition-colors"
              />
            </div>
            {errors.account && (
              <p className="mt-1.5 text-xs text-red-500">{errors.account}</p>
            )}
          </div>

          {/* Password */}
          <div>
            <div className="relative">
              <i className="ri-lock-line absolute left-4 top-1/2 -translate-y-1/2 text-hn-text-secondary text-lg w-5 h-5 flex items-center justify-center" />
              <input
                type="password"
                value={password}
                onChange={(e) => {
                  setPassword(e.target.value);
                  setErrors((prev) => ({ ...prev, password: undefined }));
                }}
                placeholder="请输入登录密码"
                className="w-full pl-12 pr-4 py-3 rounded-xl border border-gray-200 text-sm text-hn-text placeholder:text-gray-400 focus:outline-none focus:border-hn-blue focus:ring-1 focus:ring-hn-blue transition-colors"
              />
            </div>
            {errors.password && (
              <p className="mt-1.5 text-xs text-red-500">{errors.password}</p>
            )}
          </div>

          {/* Captcha */}
          <div>
            <div className="flex gap-3">
              <div className="relative flex-1">
                <i className="ri-shield-check-line absolute left-4 top-1/2 -translate-y-1/2 text-hn-text-secondary text-lg w-5 h-5 flex items-center justify-center" />
                <input
                  type="text"
                  value={captchaInput}
                  onChange={(e) => {
                    setCaptchaInput(e.target.value);
                    setErrors((prev) => ({ ...prev, captcha: undefined }));
                  }}
                  placeholder="请输入验证码"
                  maxLength={4}
                  className="w-full pl-12 pr-4 py-3 rounded-xl border border-gray-200 text-sm text-hn-text placeholder:text-gray-400 focus:outline-none focus:border-hn-blue focus:ring-1 focus:ring-hn-blue transition-colors"
                />
              </div>
              <button
                onClick={refreshCaptcha}
                className="shrink-0 w-[100px] h-[46px] rounded-lg bg-gray-100 flex items-center justify-center gap-1 text-sm font-mono font-bold tracking-wider text-hn-text cursor-pointer hover:bg-gray-200 transition-colors select-none"
                title="点击刷新验证码"
              >
                {captchaCode}
                <i className="ri-refresh-line text-xs text-hn-text-secondary" />
              </button>
            </div>
            {errors.captcha && (
              <p className="mt-1.5 text-xs text-red-500">{errors.captcha}</p>
            )}
          </div>

          {/* Login Button */}
          <button
            onClick={handleLogin}
            disabled={isDisabled}
            className={`w-full py-3 rounded-xl text-sm font-medium transition-all cursor-pointer whitespace-nowrap ${
              isDisabled
                ? 'bg-gray-300 text-white cursor-not-allowed'
                : 'bg-hn-blue text-white hover:bg-blue-600 active:scale-[0.98]'
            }`}
          >
            登录
          </button>
        </div>

        {/* Footer */}
        <p className="text-center text-xs text-gray-400 mt-8">
          &copy; 上海华能 版权所有
        </p>
      </div>
    </div>
  );
}