function genHours(fn1: (h: number) => number, fn2?: (h: number) => number, fn3?: (h: number) => number, fn4?: (h: number) => number, fn5?: (h: number) => number) {
  return Array.from({ length: 24 }, (_, h) => {
    const point: Record<string, number | string> = { time: `${h.toString().padStart(2, '0')}:00` };
    point.v1 = Math.round(fn1(h));
    if (fn2) point.v2 = Math.round(fn2(h));
    if (fn3) point.v3 = Math.round(fn3(h));
    if (fn4) point.v4 = Math.round(fn4(h));
    if (fn5) point.v5 = Math.round(fn5(h));
    return point;
  });
}

