import { useState, useMemo, useCallback } from 'react';
import { referenceDays, type ReferenceDay } from '@/mocks/consumptionForecastData';

interface AddReferenceModalProps {
  visible: boolean;
  selected: string[];
  onClose: () => void;
  onConfirm: (dates: string[]) => void;
}

export default function AddReferenceModal({ visible, selected, onClose, onConfirm }: AddReferenceModalProps) {
  const [currentSelected, setCurrentSelected] = useState<Set<string>>(new Set(selected));
  const [startMonth, setStartMonth] = useState('2026-04');
  const [endMonth, setEndMonth] = useState('2026-05');

  const handleToggle = useCallback((date: string) => {
    setCurrentSelected(prev => {
      const next = new Set(prev);
      if (next.has(date)) {
        next.delete(date);
      } else {
        next.add(date);
      }
      return next;
    });
  }, []);

  const handleSelectAll = useCallback(() => {
    const allDates = new Set(filteredDays.map(d => d.date));
    setCurrentSelected(allDates);
  }, []);

  const handleClear = useCallback(() => {
    setCurrentSelected(new Set());
  }, []);

  const handleConfirm = useCallback(() => {
    onConfirm(Array.from(currentSelected));
    onClose();
  }, [currentSelected, onConfirm, onClose]);

  const filteredDays = useMemo(() => {
    const start = startMonth;
    const end = endMonth;
    return referenceDays.filter(d => d.date >= `${start}-01` && d.date <= `${end}-31`);
  }, [startMonth, endMonth]);

  const halfHourHeaders = useMemo(() => {
    const arr: string[] = [];
    for (let i = 0; i < 6; i++) {
      const hour = i;
      const minute = (i % 2) * 30;
      arr.push(`${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`);
    }
    // Actually show first 6 columns like in image
    const full: string[] = [];
    for (let i = 0; i < 48; i++) {
      const hour = Math.floor(i / 2);
      const minute = (i % 2) * 30;
      full.push(`${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`);
    }
    return full.slice(0, 6);
  }, []);

  if (!visible) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/60" onClick={onClose} />
      <div className="relative bg-white rounded-xl shadow-2xl w-[1000px] max-w-[95vw] max-h-[90vh] flex flex-col border border-[#E5E6EB]">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-[#E5E6EB]">
          <div className="flex items-center gap-2">
            <div className="w-5 h-5 rounded-full bg-[#00C48C] flex items-center justify-center">
              <i className="ri-add-line text-white text-xs" />
            </div>
            <span className="text-sm font-bold text-[#1D2129]">增选设置</span>
          </div>
          <button onClick={onClose} className="w-7 h-7 flex items-center justify-center rounded hover:bg-[#F7F8FA] text-[#86909C] hover:text-[#1D2129] cursor-pointer">
            <i className="ri-close-line" />
          </button>
        </div>

        {/* Month Range Selector */}
        <div className="px-5 py-3 border-b border-[#E5E6EB] flex items-center gap-4">
          <span className="text-xs text-[#94A3B8]">预测日参考日范围</span>
          <div className="flex items-center gap-2">
            <div className="flex items-center gap-1.5 border border-[#E5E6EB] rounded px-2 py-1">
              <i className="ri-calendar-line text-[#64748B] text-xs" />
              <input
                type="month"
                value={startMonth}
                onChange={e => setStartMonth(e.target.value)}
                className="text-xs text-[#94A3B8] outline-none bg-transparent w-20"
              />
            </div>
            <span className="text-[#64748B]">-</span>
            <div className="flex items-center gap-1.5 border border-[#E5E6EB] rounded px-2 py-1">
              <i className="ri-calendar-line text-[#64748B] text-xs" />
              <input
                type="month"
                value={endMonth}
                onChange={e => setEndMonth(e.target.value)}
                className="text-xs text-[#94A3B8] outline-none bg-transparent w-20"
              />
            </div>
          </div>
          <span className="ml-auto text-xs text-[#64748B]">计量单位：°C, kWh</span>
        </div>

        {/* Selection Summary */}
        <div className="px-5 py-2 bg-[#165DFF]/10 flex items-center gap-3">
          <div className="w-5 h-5 rounded-full bg-[#165DFF] flex items-center justify-center">
            <i className="ri-information-line text-[#86909C] text-xs" />
          </div>
          <span className="text-xs text-[#94A3B8]">
            已选择 <span className="text-[#165DFF] font-bold">{currentSelected.size}</span> 项
          </span>
          <button
            onClick={handleSelectAll}
            className="text-xs text-[#165DFF] hover:text-[#00B4FF] ml-2 cursor-pointer"
          >
            全选
          </button>
          <button
            onClick={handleClear}
            className="text-xs text-[#165DFF] hover:text-[#00B4FF] cursor-pointer"
          >
            清空
          </button>
        </div>

        {/* Table */}
        <div className="flex-1 overflow-auto px-5 py-2">
          <table className="w-full text-[11px]">
            <thead>
              <tr className="border-b border-[#E5E6EB]">
                <th className="py-2 px-2 text-center w-10">
                  <input
                    type="checkbox"
                    checked={filteredDays.length > 0 && filteredDays.every(d => currentSelected.has(d.date))}
                    onChange={() => {
                      if (filteredDays.every(d => currentSelected.has(d.date))) {
                        handleClear();
                      } else {
                        handleSelectAll();
                      }
                    }}
                    className="cursor-pointer"
                  />
                </th>
                <th className="py-2 px-2 text-left font-medium text-[#94A3B8]">日期</th>
                <th className="py-2 px-2 text-left font-medium text-[#94A3B8]">天气</th>
                <th className="py-2 px-2 text-right font-medium text-[#94A3B8]">相似指数</th>
                <th className="py-2 px-2 text-right font-medium text-[#94A3B8]">日均温</th>
                <th className="py-2 px-2 text-right font-medium text-[#94A3B8]">最高温</th>
                <th className="py-2 px-2 text-right font-medium text-[#94A3B8]">最低温</th>
                <th className="py-2 px-2 text-right font-medium text-[#94A3B8]">用电量</th>
                {halfHourHeaders.map(h => (
                  <th key={h} className="py-2 px-1 text-right font-medium text-[#94A3B8] whitespace-nowrap">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filteredDays.map((day, idx) => {
                const isSelected = currentSelected.has(day.date);
                return (
                  <tr
                    key={day.date}
                    className={`border-b border-[#E5E6EB]/50 transition-colors cursor-pointer ${
                      isSelected ? 'bg-[#165DFF]/10' : idx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]'
                    }`}
                    onClick={() => handleToggle(day.date)}
                  >
                    <td className="py-2 px-2 text-center" onClick={e => e.stopPropagation()}>
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={() => handleToggle(day.date)}
                        className="cursor-pointer"
                      />
                    </td>
                    <td className="py-2 px-2 text-[#1D2129] font-medium">{day.date}</td>
                    <td className="py-2 px-2 text-[#94A3B8]">{day.weather}</td>
                    <td className="py-2 px-2 text-right text-[#1D2129] font-medium">{day.similarity}</td>
                    <td className="py-2 px-2 text-right text-[#1D2129]">{day.avgTemp.toFixed(2)}</td>
                    <td className="py-2 px-2 text-right text-[#F53F3F]">{day.maxTemp.toFixed(2)}</td>
                    <td className="py-2 px-2 text-right text-[#165DFF]">{day.minTemp.toFixed(2)}</td>
                    <td className="py-2 px-2 text-right text-[#1D2129]">{day.consumption.toLocaleString()}</td>
                    {day.halfHourly.slice(0, 6).map((v, i) => (
                      <td key={i} className="py-2 px-1 text-right text-[#94A3B8]">{v.toLocaleString()}</td>
                    ))}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        {/* Footer */}
        <div className="px-5 py-4 border-t border-[#E5E6EB] flex items-center justify-end gap-3">
          <button
            onClick={onClose}
            className="px-4 py-2 rounded-lg border border-[#E5E6EB] text-xs text-[#86909C] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
          >
            取消
          </button>
          <button
            onClick={handleConfirm}
            className="px-4 py-2 rounded-lg bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/80 transition-colors cursor-pointer whitespace-nowrap"
          >
            确定
          </button>
          <button
            onClick={handleConfirm}
            className="px-4 py-2 rounded-lg bg-[#00C48C] text-white text-xs hover:bg-[#00C48C]/80 transition-colors cursor-pointer whitespace-nowrap"
          >
            导出
          </button>
        </div>
      </div>
    </div>
  );
}