import { useState, useMemo } from 'react';
import {
  ComposedChart,
  Line,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import { buildPositionDetailChart, buildPositionDetailTable, type PositionDetailTableRow } from '@/mocks/positionAnalysisData';

interface PositionDetailDrawerProps {
  date: string;
  onClose: () => void;
}

const SERIES_META = [
  { key: 'yearContractQty', name: '年度合约电量', color: '#165DFF', type: 'area' as const },
  { key: 'monthContractQty', name: '月度合约电量', color: '#00C48C', type: 'area' as const },
  { key: 'intraGreenQty', name: '省内绿电合约电量', color: '#F7BA1E', type: 'area' as const },
  { key: 'interGreenQty', name: '省间绿电合约电量', color: '#14C9C9', type: 'area' as const },
  { key: 'rollingBuyQty', name: '滚搓买入汇总电量', color: '#F53F3F', type: 'area' as const },
  { key: 'rollingSellQty', name: '滚搓卖出汇总电量', color: '#722ED1', type: 'area' as const },
  { key: 'postEventQty', name: '事后电量', color: '#FF7D00', type: 'line' as const },
] as const;

const PRICE_META = [
  { key: 'dayAheadPrice', name: '日前电价', color: '#F7BA1E' },
  { key: 'postEventPrice', name: '事后电价', color: '#FF7D00' },
  { key: 'yearContractPrice', name: '年度合约电价', color: '#165DFF' },
  { key: 'monthContractPrice', name: '月度合约电价', color: '#00C48C' },
  { key: 'interGreenPrice', name: '省间绿电电量电价', color: '#14C9C9' },
  { key: 'intraGreenPrice', name: '省内绿电电量电价', color: '#F7BA1E' },
  { key: 'rollingSellPrice', name: '滚搓卖出均价', color: '#722ED1' },
  { key: 'rollingBuyPrice', name: '滚搓买入均价', color: '#165DFF' },
] as const;

export default function PositionDetailDrawer({ date, onClose }: PositionDetailDrawerProps) {
  const chartData = useMemo(() => buildPositionDetailChart(), []);
  const tableData = useMemo(() => buildPositionDetailTable(), []);

  const [hiddenQty, setHiddenQty] = useState<Record<string, boolean>>({});
  const [hiddenPrice, setHiddenPrice] = useState<Record<string, boolean>>({});

  const timeLabels = useMemo(
    () =>
      Array.from({ length: 96 }, (_, i) => {
        const hour = Math.floor(i / 4);
        const minute = (i % 4) * 15;
        return `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
      }),
    []
  );

  const toggleQty = (key: string) => setHiddenQty((prev) => ({ ...prev, [key]: !prev[key] }));
  const togglePrice = (key: string) => setHiddenPrice((prev) => ({ ...prev, [key]: !prev[key] }));

  const renderCustomQtyLegend = () => (
    <ul className="flex flex-wrap gap-3 justify-center text-[11px] mt-2">
      {SERIES_META.map((s) => {
        const hidden = hiddenQty[s.key];
        return (
          <li
            key={s.key}
            className={`flex items-center gap-1 cursor-pointer select-none transition-opacity ${hidden ? 'opacity-40' : 'opacity-100'}`}
            onClick={() => toggleQty(s.key)}
          >
            <span
              className="inline-block w-3 h-3 rounded-sm"
              style={{ backgroundColor: s.color }}
            />
            <span className="text-[#4E5969]">{s.name}</span>
          </li>
        );
      })}
    </ul>
  );

  const renderCustomPriceLegend = () => (
    <ul className="flex flex-wrap gap-3 justify-center text-[11px] mt-2">
      {PRICE_META.map((s) => {
        const hidden = hiddenPrice[s.key];
        return (
          <li
            key={s.key}
            className={`flex items-center gap-1 cursor-pointer select-none transition-opacity ${hidden ? 'opacity-40' : 'opacity-100'}`}
            onClick={() => togglePrice(s.key)}
          >
            <span
              className="inline-block w-3 h-3 rounded-sm"
              style={{ backgroundColor: s.color }}
            />
            <span className="text-[#4E5969]">{s.name}</span>
          </li>
        );
      })}
    </ul>
  );

  return (
    <div className="fixed inset-0 z-50 flex">
      {/* Backdrop */}
      <div className="flex-1 bg-black/20" onClick={onClose} />

      {/* Drawer */}
      <div className="w-[92%] max-w-[1300px] bg-[#F2F3F5] h-full overflow-y-auto shadow-xl flex flex-col">
        {/* Header */}
        <div className="bg-white px-5 py-3 border-b border-[#E5E6EB] flex items-center justify-between sticky top-0 z-10">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-[#165DFF]/10 rounded flex items-center justify-center">
              <i className="ri-line-chart-line text-[#165DFF]" />
            </div>
            <div>
              <h2 className="text-sm font-bold text-[#1D2129]">持仓详情</h2>
              <span className="text-xs text-[#86909C]">交易标的日：{date}</span>
            </div>
          </div>
          <button
            onClick={onClose}
            className="w-7 h-7 flex items-center justify-center rounded hover:bg-[#F2F3F5] text-[#86909C] hover:text-[#1D2129] transition-colors cursor-pointer"
          >
            <i className="ri-close-line" />
          </button>
        </div>

        {/* Content */}
        <div className="p-4 space-y-4">
          {/* Chart 1: 电量 */}
          <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
            <div className="text-xs text-[#86909C] mb-2">电量 (MWh)</div>
            <ResponsiveContainer width="100%" height={320}>
              <ComposedChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#E5E6EB" />
                <XAxis dataKey="time" tick={{ fontSize: 10, fill: '#86909C' }} interval={11} />
                <YAxis tick={{ fontSize: 10, fill: '#86909C' }} />
                <Tooltip
                  contentStyle={{
                    fontSize: 11,
                    borderRadius: 6,
                    backgroundColor: '#fff',
                    border: '1px solid #E5E6EB',
                    color: '#1D2129',
                  }}
                />

                {SERIES_META.filter((s) => s.type === 'area').map((s) => (
                  <Area
                    key={s.key}
                    type="monotone"
                    dataKey={s.key}
                    stackId="qty"
                    stroke={s.color}
                    fill={s.color}
                    fillOpacity={hiddenQty[s.key] ? 0 : 0.3}
                    strokeOpacity={hiddenQty[s.key] ? 0 : 1}
                    strokeWidth={1}
                    dot={false}
                    name={s.name}
                    hide={!!hiddenQty[s.key]}
                  />
                ))}

                <Line
                  type="monotone"
                  dataKey="postEventQty"
                  stroke="#FF7D00"
                  strokeOpacity={hiddenQty['postEventQty'] ? 0 : 1}
                  strokeWidth={hiddenQty['postEventQty'] ? 0 : 2}
                  dot={false}
                  name="事后电量"
                  hide={!!hiddenQty['postEventQty']}
                />
              </ComposedChart>
            </ResponsiveContainer>
            {renderCustomQtyLegend()}
          </div>

          {/* Chart 2: 电价 */}
          <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
            <div className="text-xs text-[#86909C] mb-2">电价 (元/MWh)</div>
            <ResponsiveContainer width="100%" height={320}>
              <ComposedChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#E5E6EB" />
                <XAxis dataKey="time" tick={{ fontSize: 10, fill: '#86909C' }} interval={11} />
                <YAxis tick={{ fontSize: 10, fill: '#86909C' }} />
                <Tooltip
                  contentStyle={{
                    fontSize: 11,
                    borderRadius: 6,
                    backgroundColor: '#fff',
                    border: '1px solid #E5E6EB',
                    color: '#1D2129',
                  }}
                />
                {PRICE_META.map((s) => (
                  <Line
                    key={s.key}
                    type="monotone"
                    dataKey={s.key}
                    stroke={s.color}
                    strokeOpacity={hiddenPrice[s.key] ? 0 : 1}
                    strokeWidth={hiddenPrice[s.key] ? 0 : 1.5}
                    dot={false}
                    name={s.name}
                    hide={!!hiddenPrice[s.key]}
                  />
                ))}
              </ComposedChart>
            </ResponsiveContainer>
            {renderCustomPriceLegend()}
          </div>

          {/* Table — always shown below charts */}
          <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
            <div className="flex items-center justify-between px-4 py-3 border-b border-[#E5E6EB]">
              <span className="text-xs text-[#86909C]">计量单位：元/MWh、MWh</span>
              <button className="flex items-center gap-1 px-3 py-1.5 rounded border border-[#E5E6EB] text-xs text-[#4E5969] hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
                <i className="ri-download-line" />
                导出
              </button>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-[11px]">
                <thead>
                  <tr className="bg-[#F7F8FA]">
                    <th className="text-left py-2 px-3 font-medium text-[#1D2129] border-b border-[#E5E6EB] sticky left-0 bg-[#F7F8FA] z-10 min-w-[200px]">
                      参数名
                    </th>
                    {timeLabels.map((t) => (
                      <th
                        key={t}
                        className="text-center py-2 px-1.5 font-medium text-[#1D2129] border-b border-[#E5E6EB] min-w-[62px]"
                      >
                        {t}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {tableData.map((row: PositionDetailTableRow, idx: number) => (
                    <tr
                      key={row.name}
                      className={`${idx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]/50'} border-b border-[#E5E6EB]/50`}
                    >
                      <td
                        className={`py-2 px-3 font-medium sticky left-0 ${idx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]/50'} z-10 text-[#1D2129] whitespace-nowrap ${row.isHighlight && row.highlightColor === 'red' ? 'text-[#F53F3F]' : row.isHighlight && row.highlightColor === 'blue' ? 'text-[#165DFF]' : ''}`}
                      >
                        {row.name}
                      </td>
                      {row.values.map((v, vIdx) => (
                        <td key={vIdx} className="text-center py-2 px-1.5 text-[#4E5969] whitespace-nowrap">
                          {v === '' || v === null || v === undefined
                            ? '-'
                            : typeof v === 'number'
                              ? v.toLocaleString()
                              : v}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
