// ======== 生成24小时数据 ========
function genHours(fn: (h: number) => number) {
  return Array.from({ length: 24 }, (_, h) => ({
    time: `${h.toString().padStart(2, '0')}:00`,
    h,
    value: Math.round(fn(h)),
  }));
}

function genMulti(fnMap: Record<string, (h: number) => number>) {
  return Array.from({ length: 24 }, (_, h) => {
    const point: Record<string, number | string> = { time: `${h.toString().padStart(2, '0')}:00`, h };
    Object.entries(fnMap).forEach(([k, f]) => { point[k] = Math.round(f(h)); });
    return point;
  });
}

