// 模块2数据 - 电价预测与关系对比图
const module2Data = genMulti({
  rtDaProb: h => {
    const base = 45 + Math.sin((h - 10) * Math.PI / 8) * 30;
    return Math.max(0, Math.min(100, base + (Math.random() - 0.5) * 10));
  },
  rtPriceActual: h => 320 + Math.sin((h - 10) * Math.PI / 8) * 200 + (Math.random() - 0.5) * 40,
  rtPriceForecast: h => 315 + Math.sin((h - 10) * Math.PI / 8) * 195 + (Math.random() - 0.5) * 38,
  daPriceActual: h => 300 + Math.sin((h - 9) * Math.PI / 8) * 180 + (Math.random() - 0.5) * 35,
  daPriceForecast: h => 295 + Math.sin((h - 9) * Math.PI / 8) * 175 + (Math.random() - 0.5) * 33,
  positiveDiff: h => {
    const val = Math.sin((h - 10) * Math.PI / 8) * 60 + (Math.random() - 0.5) * 15;
    return val > 0 ? val : 0;
  },
  realDiff: h => Math.sin((h - 10) * Math.PI / 8) * 60 + (Math.random() - 0.5) * 15,
  negativeDiff: h => {
    const val = Math.sin((h - 10) * Math.PI / 8) * 60 + (Math.random() - 0.5) * 15;
    return val < 0 ? Math.abs(val) : 0;
  },
  barBase: h => 40 + Math.abs(Math.sin((h - 8) * Math.PI / 12) * 30),
});

