import { useState, useRef, useEffect } from 'react';
import { getTradingDaysInMonth, isTradingDay, getPrevTradingDay, getNextTradingDay } from '@/hooks/useBidDecisionData';

interface BidDecisionToolbarProps {
  targetDate: string;
  onDateChange: (date: string) => void;
  runDateText: string;
}

export default function BidDecisionToolbar({
  targetDate, onDateChange, runDateText,
}: BidDecisionToolbarProps) {
  const [showCalendar, setShowCalendar] = useState(false);
  const [calYear, setCalYear] = useState(new Date().getFullYear());
  const [calMonth, setCalMonth] = useState(new Date().getMonth() + 1);
  const calRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClick(e: MouseEvent) {
      if (calRef.current && !calRef.current.contains(e.target as Node)) {
        setShowCalendar(false);
      }
    }
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, []);

  const tradingDays = getTradingDaysInMonth(calYear, calMonth);

  const handlePrevMonth = () => {
    if (calMonth === 1) { setCalMonth(12); setCalYear(calYear - 1); }
    else { setCalMonth(calMonth - 1); }
  };
  const handleNextMonth = () => {
    if (calMonth === 12) { setCalMonth(1); setCalYear(calYear + 1); }
    else { setCalMonth(calMonth + 1); }
  };

  const handleDayClick = (day: number) => {
    const ds = `${calYear}-${calMonth.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
    onDateChange(ds);
    setShowCalendar(false);
  };

  const firstDayOfMonth = new Date(calYear, calMonth - 1, 1).getDay();
  const daysInMonth = new Date(calYear, calMonth, 0).getDate();
  const todayStr = new Date().toISOString().split('T')[0];

  return (
    <div className="bg-white rounded-lg border border-[#E5E6EB] p-3 mb-4 flex flex-wrap items-center gap-3">
      {/* 日期选择器 */}
      <div className="relative flex-shrink-0" ref={calRef}>
        <button
          onClick={() => setShowCalendar(!showCalendar)}
          className="flex items-center gap-1.5 px-3 py-1.5 text-xs border border-[#E5E6EB] rounded hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
        >
          <i className="ri-calendar-line text-[#86909C]" />
          <span className="font-medium text-[#1D2129]">{targetDate}</span>
          <i className={`ri-arrow-down-s-line text-[#86909C] transition-transform ${showCalendar ? 'rotate-180' : ''}`} />
        </button>

        {showCalendar && (
          <div className="absolute top-full left-0 mt-1 z-50 bg-white rounded-lg border border-[#E5E6EB] p-3 w-[280px]" style={{ boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}>
            <div className="flex items-center justify-between mb-2">
              <button onClick={handlePrevMonth} className="w-6 h-6 flex items-center justify-center rounded hover:bg-[#F7F8FA] cursor-pointer">
                <i className="ri-arrow-left-s-line text-[#86909C]" />
              </button>
              <span className="text-xs font-medium text-[#1D2129]">{calYear}年{calMonth}月</span>
              <button onClick={handleNextMonth} className="w-6 h-6 flex items-center justify-center rounded hover:bg-[#F7F8FA] cursor-pointer">
                <i className="ri-arrow-right-s-line text-[#86909C]" />
              </button>
            </div>
            <div className="grid grid-cols-7 gap-1 text-center mb-1">
              {['日','一','二','三','四','五','六'].map(d => (
                <span key={d} className="text-[10px] text-[#86909C] py-0.5">{d}</span>
              ))}
            </div>
            <div className="grid grid-cols-7 gap-1">
              {Array.from({ length: firstDayOfMonth }).map((_, i) => (
                <div key={`pad-${i}`} />
              ))}
              {Array.from({ length: daysInMonth }).map((_, i) => {
                const day = i + 1;
                const ds = `${calYear}-${calMonth.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
                const isTrade = tradingDays.includes(day);
                const isSelected = ds === targetDate;
                const isToday = ds === todayStr;
                return (
                  <button
                    key={day}
                    onClick={() => isTrade ? handleDayClick(day) : undefined}
                    className={`h-7 w-full flex items-center justify-center rounded text-xs transition-colors relative ${
                      !isTrade ? 'text-[#C9CDD4] cursor-not-allowed bg-[#F7F8FA]' :
                      isSelected ? 'bg-[#165DFF] text-white font-medium' :
                      isToday ? 'bg-[#165DFF]/10 text-[#165DFF] font-medium' :
                      'text-[#1D2129] hover:bg-[#F7F8FA] cursor-pointer'
                    }`}
                  >
                    {day}
                    {isToday && !isSelected && <span className="absolute bottom-0.5 w-1 h-1 rounded-full bg-[#165DFF]" />}
                  </button>
                );
              })}
            </div>
          </div>
        )}
      </div>

      {/* 运行日期 */}
      <div className="flex items-center gap-1.5 text-xs text-[#94A3B8] flex-shrink-0">
        <span className="text-[#86909C]">运行日期:</span>
        <span className="font-medium">{runDateText}</span>
      </div>

      <div className="flex-1" />

      {/* 右侧操作按钮 */}
      <div className="flex items-center gap-2 flex-shrink-0">
        <button className="flex items-center gap-1 px-2.5 py-1.5 text-xs text-[#86909C] border border-[#E5E6EB] rounded hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">
          <i className="ri-refresh-line" />
          刷新
        </button>
        <button className="flex items-center gap-1 px-3 py-1.5 text-xs border border-[#165DFF] text-[#165DFF] rounded hover:bg-[#165DFF]/5 transition-colors cursor-pointer whitespace-nowrap">
          <i className="ri-download-line" />
          导出数据
        </button>
      </div>
    </div>
  );
}