import { useState, useMemo } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import SpotTradingLayout from '@/pages/spot-trading/components/SpotTradingLayout';
import ConfirmModal from '@/components/ConfirmModal';
import Toast from '@/components/Toast';

interface UnitDetail {
  id: string;
  group: string;
  plant: string;
  unitType: string;
  unitName: string;
  status: '在运' | '调停' | '检修' | '固定出力';
  capacity: number;
}

const mockUnitDetails: UnitDetail[] = [
  { id: 'U001', group: '华能集团', plant: '石洞口一厂', unitType: '燃煤机组', unitName: '#1机组', status: '在运', capacity: 300 },
  { id: 'U002', group: '华能集团', plant: '石洞口一厂', unitType: '燃煤机组', unitName: '#2机组', status: '在运', capacity: 300 },
  { id: 'U003', group: '华能集团', plant: '石洞口二厂', unitType: '燃煤机组', unitName: '#1机组', status: '在运', capacity: 600 },
  { id: 'U004', group: '华能集团', plant: '石洞口二厂', unitType: '燃煤机组', unitName: '#2机组', status: '调停', capacity: 600 },
  { id: 'U005', group: '华能集团', plant: '外高桥一厂', unitType: '燃煤机组', unitName: '#1机组', status: '在运', capacity: 320 },
  { id: 'U006', group: '华能集团', plant: '外高桥一厂', unitType: '燃煤机组', unitName: '#2机组', status: '检修', capacity: 320 },
  { id: 'U007', group: '华能集团', plant: '外高桥二厂', unitType: '燃气机组', unitName: '#1机组', status: '在运', capacity: 900 },
  { id: 'U008', group: '华能集团', plant: '外高桥二厂', unitType: '燃气机组', unitName: '#2机组', status: '固定出力', capacity: 900 },
  { id: 'U009', group: '华能集团', plant: '外高桥三厂', unitType: '燃煤机组', unitName: '#1机组', status: '在运', capacity: 1000 },
  { id: 'U010', group: '华能集团', plant: '外高桥三厂', unitType: '燃煤机组', unitName: '#2机组', status: '在运', capacity: 1000 },
  { id: 'U011', group: '大唐集团', plant: '漕泾电厂', unitType: '燃煤机组', unitName: '#1机组', status: '在运', capacity: 1000 },
  { id: 'U012', group: '大唐集团', plant: '漕泾电厂', unitType: '燃煤机组', unitName: '#2机组', status: '调停', capacity: 1000 },
  { id: 'U013', group: '国电投', plant: '吴泾电厂', unitType: '燃煤机组', unitName: '#1机组', status: '在运', capacity: 660 },
  { id: 'U014', group: '国电投', plant: '吴泾电厂', unitType: '燃煤机组', unitName: '#2机组', status: '检修', capacity: 660 },
  { id: 'U015', group: '申能集团', plant: '临港燃机', unitType: '燃气机组', unitName: '#1机组', status: '在运', capacity: 400 },
  { id: 'U016', group: '申能集团', plant: '临港燃机', unitType: '燃气机组', unitName: '#2机组', status: '固定出力', capacity: 400 },
];

interface SummaryState {
  runningCount: number;
  runningCapacity: number;
  standbyCount: number;
  standbyCapacity: number;
  maintenanceCount: number;
  maintenanceCapacity: number;
  fixedCount: number;
  fixedCapacity: number;
}

export default function UnitInfoDetailPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const date = searchParams.get('date') || '2026-05-07';
  const mode = searchParams.get('mode') || 'view';
  const isEdit = mode === 'edit';

  // Summary states
  const [provinceSummary, setProvinceSummary] = useState<SummaryState>({
    runningCount: 32, runningCapacity: 12800,
    standbyCount: 5, standbyCapacity: 1200,
    maintenanceCount: 3, maintenanceCapacity: 800,
    fixedCount: 8, fixedCapacity: 2400,
  });

  const [huangNengSummary, setHuangNengSummary] = useState<SummaryState>({
    runningCount: 10, runningCapacity: 4100,
    standbyCount: 1, standbyCapacity: 600,
    maintenanceCount: 1, maintenanceCapacity: 320,
    fixedCount: 1, fixedCapacity: 900,
  });

  // Detail list
  const [unitDetails, setUnitDetails] = useState<UnitDetail[]>(mockUnitDetails);

  // Filters for detail list
  const [filterGroup, setFilterGroup] = useState('');
  const [filterPlant, setFilterPlant] = useState('');
  const [filterUnitName, setFilterUnitName] = useState('');
  const [filterStatus, setFilterStatus] = useState('');

  // Edit modal
  const [editUnit, setEditUnit] = useState<UnitDetail | null>(null);
  const [editStatus, setEditStatus] = useState('');
  const [editCapacity, setEditCapacity] = useState('');
  const [editCapacityError, setEditCapacityError] = useState('');

  // Confirm modals
  const [showCancelModal, setShowCancelModal] = useState(false);
  const [showSaveSuccess, setShowSaveSuccess] = useState(false);

  // Toast
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  // Validation errors for summary
  const [summaryErrors, setSummaryErrors] = useState<Record<string, string>>({});

  const filteredDetails = useMemo(() => {
    return unitDetails.filter(u => {
      if (filterGroup && !u.group.includes(filterGroup)) return false;
      if (filterPlant && !u.plant.includes(filterPlant)) return false;
      if (filterUnitName && !u.unitName.includes(filterUnitName)) return false;
      if (filterStatus && u.status !== filterStatus) return false;
      return true;
    });
  }, [unitDetails, filterGroup, filterPlant, filterUnitName, filterStatus]);

  const validateSummary = (key: string, value: number) => {
    if (value < 0) {
      setSummaryErrors(prev => ({ ...prev, [key]: '数值不可为负数' }));
      return false;
    }
    setSummaryErrors(prev => {
      const next = { ...prev };
      delete next[key];
      return next;
    });
    return true;
  };

  const handleSummaryChange = (
    setter: React.Dispatch<React.SetStateAction<SummaryState>>,
    key: keyof SummaryState,
    value: string
  ) => {
    const num = parseInt(value, 10) || 0;
    if (validateSummary(key, num)) {
      setter(prev => ({ ...prev, [key]: num }));
    }
  };

  const handleEdit = (unit: UnitDetail) => {
    if (!isEdit) return;
    setEditUnit(unit);
    setEditStatus(unit.status);
    setEditCapacity(String(unit.capacity));
    setEditCapacityError('');
  };

  const confirmEdit = () => {
    if (!editUnit) return;
    const cap = parseInt(editCapacity, 10);
    if (isNaN(cap) || cap < 0) {
      setEditCapacityError('装机容量不可为负数');
      return;
    }
    setUnitDetails(prev =>
      prev.map(u => (u.id === editUnit.id ? { ...u, status: editStatus as UnitDetail['status'], capacity: cap } : u))
    );
    setEditUnit(null);
    setToast({ message: '机组信息修改成功', type: 'success' });
  };

  const handleSave = () => {
    if (Object.keys(summaryErrors).length > 0) {
      setToast({ message: '请修正汇总数据中的错误', type: 'error' });
      return;
    }
    setShowSaveSuccess(true);
  };

  const confirmSave = () => {
    setShowSaveSuccess(false);
    setToast({ message: '保存成功，数据已生效', type: 'success' });
    setTimeout(() => navigate('/spot-trading/data-mgmt/unit-info'), 1500);
  };

  const handleCancel = () => {
    setShowCancelModal(true);
  };

  const confirmCancel = () => {
    setShowCancelModal(false);
    navigate('/spot-trading/data-mgmt/unit-info');
  };

  const renderSummarySection = (
    title: string,
    data: SummaryState,
    setter: React.Dispatch<React.SetStateAction<SummaryState>>
  ) => (
    <div className="bg-white rounded-xl border border-[#E5E6EB] p-4 flex-1">
      <h3 className="text-sm font-bold text-[#1D2129] mb-3">{title}</h3>
      <div className="space-y-2">
        {([
          { key: 'running', label: '在运', countKey: 'runningCount' as keyof SummaryState, capKey: 'runningCapacity' as keyof SummaryState },
          { key: 'standby', label: '调停', countKey: 'standbyCount' as keyof SummaryState, capKey: 'standbyCapacity' as keyof SummaryState },
          { key: 'maintenance', label: '检修', countKey: 'maintenanceCount' as keyof SummaryState, capKey: 'maintenanceCapacity' as keyof SummaryState },
          { key: 'fixed', label: '固定出力', countKey: 'fixedCount' as keyof SummaryState, capKey: 'fixedCapacity' as keyof SummaryState },
        ] as const).map(item => (
          <div key={item.key} className="flex items-center gap-3">
            <span className="text-xs text-[#4E5969] w-16">{item.label}</span>
            <div className="flex items-center gap-2 flex-1">
              <div className="flex items-center gap-1 flex-1">
                <input
                  type="number"
                  value={data[item.countKey]}
                  onChange={(e) => handleSummaryChange(setter, item.countKey, e.target.value)}
                  readOnly={!isEdit}
                  className={`w-16 text-xs px-2 py-1 rounded-md border text-right ${
                    summaryErrors[item.countKey]
                      ? 'border-[#F53F3F] bg-red-50'
                      : 'border-[#E5E6EB] bg-white'
                  } ${!isEdit ? 'bg-gray-50 text-[#86909C] cursor-default' : 'text-[#1D2129]'}`}
                />
                <span className="text-[10px] text-[#86909C]">台</span>
              </div>
              <div className="flex items-center gap-1 flex-1">
                <input
                  type="number"
                  value={data[item.capKey]}
                  onChange={(e) => handleSummaryChange(setter, item.capKey, e.target.value)}
                  readOnly={!isEdit}
                  className={`w-20 text-xs px-2 py-1 rounded-md border text-right ${
                    summaryErrors[item.capKey]
                      ? 'border-[#F53F3F] bg-red-50'
                      : 'border-[#E5E6EB] bg-white'
                  } ${!isEdit ? 'bg-gray-50 text-[#86909C] cursor-default' : 'text-[#1D2129]'}`}
                />
                <span className="text-[10px] text-[#86909C]">MW</span>
              </div>
            </div>
            {summaryErrors[item.countKey] && (
              <span className="text-[10px] text-[#F53F3F]">{summaryErrors[item.countKey]}</span>
            )}
            {summaryErrors[item.capKey] && (
              <span className="text-[10px] text-[#F53F3F]">{summaryErrors[item.capKey]}</span>
            )}
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <SpotTradingLayout>
      <div className="w-full max-w-full space-y-4">
        {/* Top bar */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button
              onClick={() => navigate('/spot-trading/data-mgmt/unit-info')}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-arrow-left-line" />
              返回列表
            </button>
            <h1 className="text-lg font-bold text-[#1D2129]">
              机组详情 <span className="text-sm font-normal text-[#86909C]">（{date}）</span>
              <span className={`ml-2 text-[10px] px-2 py-0.5 rounded-full ${
                isEdit ? 'bg-[#FF7D00]/10 text-[#FF7D00]' : 'bg-[#00C48C]/10 text-[#00C48C]'
              }`}>
                {isEdit ? '可编辑' : '只读'}
              </span>
            </h1>
          </div>
          {isEdit && (
            <div className="flex items-center gap-2">
              <button
                onClick={handleCancel}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
              >
                <i className="ri-close-line" />
                取消
              </button>
              <button
                onClick={handleSave}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-blue-600 transition-colors cursor-pointer whitespace-nowrap"
              >
                <i className="ri-check-line" />
                保存
              </button>
            </div>
          )}
        </div>

        {/* Summary section */}
        <div className="flex flex-col lg:flex-row gap-4">
          {renderSummarySection('全省机组状态汇总', provinceSummary, setProvinceSummary)}
          {renderSummarySection('华能公司机组状态汇总', huangNengSummary, setHuangNengSummary)}
        </div>

        {/* Detail list */}
        <div className="bg-white rounded-xl border border-[#E5E6EB] p-4">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-bold text-[#1D2129]">单台机组明细</h3>
            <div className="flex items-center gap-2">
              <select
                value={filterGroup}
                onChange={(e) => setFilterGroup(e.target.value)}
                className="text-xs px-2 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none"
              >
                <option value="">全部集团</option>
                <option value="华能集团">华能集团</option>
                <option value="大唐集团">大唐集团</option>
                <option value="国电投">国电投</option>
                <option value="申能集团">申能集团</option>
              </select>
              <input
                type="text"
                placeholder="电厂名称"
                value={filterPlant}
                onChange={(e) => setFilterPlant(e.target.value)}
                className="text-xs px-2 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none w-28 placeholder:text-[#86909C]"
              />
              <input
                type="text"
                placeholder="机组名称"
                value={filterUnitName}
                onChange={(e) => setFilterUnitName(e.target.value)}
                className="text-xs px-2 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none w-28 placeholder:text-[#86909C]"
              />
              <select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value)}
                className="text-xs px-2 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none"
              >
                <option value="">全部状态</option>
                <option value="在运">在运</option>
                <option value="调停">调停</option>
                <option value="检修">检修</option>
                <option value="固定出力">固定出力</option>
              </select>
              <button
                onClick={() => { setFilterGroup(''); setFilterPlant(''); setFilterUnitName(''); setFilterStatus(''); }}
                className="flex items-center gap-1 px-2 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
              >
                <i className="ri-refresh-line" />
                重置
              </button>
            </div>
          </div>

          <div className="overflow-x-auto" style={{ overflowX: 'auto' }}>
            <table className="w-full text-xs" style={{ minWidth: 'max-content' }}>
              <thead>
                <tr className="border-b border-[#E5E6EB] bg-[#F7F8FA]">
                  <th className="text-left py-2 px-3 font-medium text-[#86909C]">集团</th>
                  <th className="text-left py-2 px-3 font-medium text-[#86909C]">电厂名称</th>
                  <th className="text-left py-2 px-3 font-medium text-[#86909C]">机组类型</th>
                  <th className="text-left py-2 px-3 font-medium text-[#86909C]">机组名称</th>
                  <th className="text-center py-2 px-3 font-medium text-[#86909C]">机组状态</th>
                  <th className="text-right py-2 px-3 font-medium text-[#86909C]">装机容量</th>
                  <th className="text-center py-2 px-3 font-medium text-[#86909C]">操作</th>
                </tr>
              </thead>
              <tbody>
                {filteredDetails.map((unit) => (
                  <tr key={unit.id} className="border-b border-[#E5E6EB]/50 hover:bg-[#F7F8FA]/60">
                    <td className="py-2 px-3 text-[#1D2129]">{unit.group}</td>
                    <td className="py-2 px-3 text-[#1D2129]">{unit.plant}</td>
                    <td className="py-2 px-3 text-[#86909C]">{unit.unitType}</td>
                    <td className="py-2 px-3 text-[#1D2129] font-medium">{unit.unitName}</td>
                    <td className="py-2 px-3 text-center">
                      <span className={`text-[10px] px-2 py-0.5 rounded-full ${
                        unit.status === '在运'
                          ? 'bg-[#00C48C]/10 text-[#00C48C]'
                          : unit.status === '调停'
                          ? 'bg-[#FF7D00]/10 text-[#FF7D00]'
                          : unit.status === '检修'
                          ? 'bg-[#F53F3F]/10 text-[#F53F3F]'
                          : 'bg-[#165DFF]/10 text-[#165DFF]'
                      }`}>
                        {unit.status}
                      </span>
                    </td>
                    <td className="py-2 px-3 text-right text-[#1D2129] font-medium">
                      {unit.capacity} <span className="text-[#86909C]">MW</span>
                    </td>
                    <td className="py-2 px-3 text-center">
                      {isEdit ? (
                        <button
                          onClick={() => handleEdit(unit)}
                          className="text-amber-500 hover:text-amber-600 transition-colors cursor-pointer"
                          title="编辑"
                        >
                          <i className="ri-edit-line" />
                        </button>
                      ) : (
                        <span className="text-gray-300 cursor-default">
                          <i className="ri-edit-line" />
                        </span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Edit unit modal */}
      {editUnit && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
          <div className="bg-white rounded-xl p-6 w-full max-w-sm mx-4 shadow-xl">
            <h3 className="text-sm font-bold text-[#1D2129] mb-4">编辑机组信息</h3>
            <div className="space-y-3 mb-5">
              <div className="flex items-center justify-between">
                <span className="text-xs text-[#86909C]">电厂</span>
                <span className="text-xs text-[#1D2129] font-medium">{editUnit.plant} {editUnit.unitName}</span>
              </div>
              <div>
                <label className="block text-xs text-[#86909C] mb-1.5">机组状态</label>
                <select
                  value={editStatus}
                  onChange={(e) => setEditStatus(e.target.value)}
                  className="w-full text-xs px-3 py-2 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]"
                >
                  <option value="在运">在运</option>
                  <option value="调停">调停</option>
                  <option value="检修">检修</option>
                  <option value="固定出力">固定出力</option>
                </select>
              </div>
              <div>
                <label className="block text-xs text-[#86909C] mb-1.5">装机容量（MW）</label>
                <input
                  type="number"
                  value={editCapacity}
                  onChange={(e) => {
                    setEditCapacity(e.target.value);
                    const val = parseInt(e.target.value, 10);
                    if (isNaN(val) || val < 0) {
                      setEditCapacityError('装机容量不可为负数');
                    } else {
                      setEditCapacityError('');
                    }
                  }}
                  className={`w-full text-xs px-3 py-2 rounded-md border outline-none focus:border-[#165DFF] ${
                    editCapacityError ? 'border-[#F53F3F] bg-red-50' : 'border-[#E5E6EB] bg-white'
                  } text-[#1D2129]`}
                />
                {editCapacityError && (
                  <p className="text-[10px] text-[#F53F3F] mt-1">{editCapacityError}</p>
                )}
              </div>
            </div>
            <div className="flex gap-3 justify-end">
              <button
                onClick={() => setEditUnit(null)}
                className="px-4 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
              >
                取消
              </button>
              <button
                onClick={confirmEdit}
                disabled={!!editCapacityError}
                className={`px-4 py-1.5 rounded-md text-xs transition-colors whitespace-nowrap ${
                  editCapacityError
                    ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                    : 'bg-[#165DFF] text-white hover:bg-blue-600 cursor-pointer'
                }`}
              >
                确认
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Cancel modal */}
      {showCancelModal && (
        <ConfirmModal
          title="确认离开"
          message="未保存的修改将丢失，是否确认离开？"
          onConfirm={confirmCancel}
          onCancel={() => setShowCancelModal(false)}
        />
      )}

      {/* Save success modal */}
      {showSaveSuccess && (
        <ConfirmModal
          title="保存确认"
          message="数据校验通过，确认保存并生效？"
          onConfirm={confirmSave}
          onCancel={() => setShowSaveSuccess(false)}
        />
      )}

      {/* Toast */}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          onClose={() => setToast(null)}
        />
      )}
    </SpotTradingLayout>
  );
}
