export interface ReferenceDay {
  date: string;
  weather: string;
  avgTemp: number;
  maxTemp: number;
  minTemp: number;
  consumption: number;
  halfHourly: number[];
  dayType: 'workday' | 'rest' | 'holiday';
  similarity: number;
}

function generateHalfHourly(base: number, pattern: string): number[] {
  const data: number[] = [];
  for (let i = 0; i < 48; i++) {
    const hour = i / 2;
    let value = base;
    if (pattern === 'workday') {
      if (hour >= 8 && hour <= 11) value += 3000 + Math.random() * 500;
      else if (hour >= 13 && hour <= 17) value += 3500 + Math.random() * 600;
      else if (hour >= 19 && hour <= 21) value += 2500 + Math.random() * 400;
      else value += Math.sin(hour * 0.5) * 200;
    } else if (pattern === 'rest') {
      if (hour >= 10 && hour <= 12) value += 2000 + Math.random() * 300;
      else if (hour >= 14 && hour <= 18) value += 1800 + Math.random() * 400;
      else if (hour >= 19 && hour <= 22) value += 2200 + Math.random() * 300;
      else value += Math.sin(hour * 0.4) * 150;
    } else {
      if (hour >= 9 && hour <= 12) value += 1500 + Math.random() * 200;
      else if (hour >= 14 && hour <= 17) value += 1200 + Math.random() * 300;
      else value += Math.sin(hour * 0.3) * 100;
    }
    data.push(Math.round(value + Math.random() * 200));
  }
  return data;
}

function genRefDay(date: string, weather: string, avgT: number, maxT: number, minT: number, base: number, pattern: 'workday' | 'rest' | 'holiday', similarity: number): ReferenceDay {
  return {
    date,
    weather,
    avgTemp: avgT,
    maxTemp: maxT,
    minTemp: minT,
    consumption: Math.round(base * 48 + Math.random() * 5000),
    halfHourly: generateHalfHourly(base, pattern),
    dayType: pattern,
    similarity,
  };
}

