import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import SpotTradingLayout from '@/pages/spot-trading/components/SpotTradingLayout';
import { unitInfoData } from '@/mocks/dataMgmtData';
import ConfirmModal from '@/components/ConfirmModal';
import Toast from '@/components/Toast';

export default function UnitInfoPage() {
  const navigate = useNavigate();

  // Filter states
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  // Selection for batch delete
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modal states
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [deleteItemDate, setDeleteItemDate] = useState<string | null>(null);
  const [showBatchDeleteModal, setShowBatchDeleteModal] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newDate, setNewDate] = useState('');

  // Toast
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  const todayStr = '2026-05-07';

  const isFuture = (date: string) => date >= todayStr;

  // Filtered data
  const filteredData = useMemo(() => {
    let data = [...unitInfoData];
    if (startDate) {
      data = data.filter(item => item.date >= startDate);
    }
    if (endDate) {
      data = data.filter(item => item.date <= endDate);
    }
    return data;
  }, [startDate, endDate]);

  // Pagination
  const totalPages = Math.ceil(filteredData.length / pageSize);
  const pageData = filteredData.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const handleSearch = () => {
    setCurrentPage(1);
    setSelectedIds(new Set());
  };

  const handleReset = () => {
    setStartDate('');
    setEndDate('');
    setCurrentPage(1);
    setSelectedIds(new Set());
  };

  const toggleSelect = (date: string) => {
    const next = new Set(selectedIds);
    if (next.has(date)) {
      next.delete(date);
    } else {
      next.add(date);
    }
    setSelectedIds(next);
  };

  const toggleSelectAll = () => {
    const selectable = pageData.filter(item => isFuture(item.date)).map(item => item.date);
    const allSelected = selectable.every(id => selectedIds.has(id));
    const next = new Set(selectedIds);
    if (allSelected) {
      selectable.forEach(id => next.delete(id));
    } else {
      selectable.forEach(id => next.add(id));
    }
    setSelectedIds(next);
  };

  const handleDelete = (date: string) => {
    if (!isFuture(date)) return;
    setDeleteItemDate(date);
    setShowDeleteModal(true);
  };

  const confirmDelete = () => {
    if (deleteItemDate) {
      setToast({ message: `已删除 ${deleteItemDate} 的维护记录`, type: 'success' });
      setDeleteItemDate(null);
    }
    setShowDeleteModal(false);
  };

  const selectedDates = Array.from(selectedIds);
  const hasHistorySelected = selectedDates.some(d => !isFuture(d));
  const batchDeletableCount = selectedDates.filter(d => isFuture(d)).length;

  const handleBatchDelete = () => {
    if (hasHistorySelected || batchDeletableCount === 0) return;
    setShowBatchDeleteModal(true);
  };

  const confirmBatchDelete = () => {
    setToast({ message: `已批量删除 ${batchDeletableCount} 条未来日期记录`, type: 'success' });
    setSelectedIds(new Set());
    setShowBatchDeleteModal(false);
  };

  const handleExport = () => {
    setToast({ message: 'Excel 导出成功', type: 'success' });
  };

  const handleImport = () => {
    setToast({ message: 'Excel 导入功能暂未接入后端', type: 'error' });
  };

  const handleTemplateDownload = () => {
    setToast({ message: '模板下载成功', type: 'success' });
  };

  const handleAdd = () => {
    setNewDate('');
    setShowAddModal(true);
  };

  const confirmAdd = () => {
    if (!newDate) {
      setToast({ message: '请先选择日期', type: 'error' });
      return;
    }
    setShowAddModal(false);
    navigate(`/spot-trading/data-mgmt/unit-info/detail?date=${newDate}&mode=edit`);
  };

  const handleView = (date: string) => {
    navigate(`/spot-trading/data-mgmt/unit-info/detail?date=${date}&mode=view`);
  };

  const handleMaintain = (date: string) => {
    navigate(`/spot-trading/data-mgmt/unit-info/detail?date=${date}&mode=edit`);
  };

  return (
    <SpotTradingLayout>
      <div className="w-full max-w-full">
        {/* Header */}
        <div className="flex items-center justify-between mb-5">
          <div>
            <h1 className="text-lg font-bold text-[#1D2129]">机组信息维护</h1>
            <p className="text-xs text-[#86909C] mt-1">全省机组每日维护记录与状态管理</p>
          </div>
        </div>

        {/* Filter + Action bar */}
        <div className="bg-white rounded-xl p-4 border border-[#E5E6EB] mb-4">
          <div className="flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-2">
              <span className="text-xs text-[#86909C]">起始日期</span>
              <input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="text-xs px-2.5 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]"
              />
            </div>
            <div className="flex items-center gap-2">
              <span className="text-xs text-[#86909C]">结束日期</span>
              <input
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                className="text-xs px-2.5 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]"
              />
            </div>
            <button
              onClick={handleSearch}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-blue-600 transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-search-line" />
              查询
            </button>
            <button
              onClick={handleReset}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-refresh-line" />
              重置
            </button>

            <div className="ml-auto flex items-center gap-2">
              <button
                onClick={handleAdd}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#00C48C]/15 text-[#00C48C] text-xs hover:bg-emerald-100 transition-colors cursor-pointer whitespace-nowrap"
              >
                <i className="ri-add-line" />
                新增
              </button>
              <button
                onClick={handleBatchDelete}
                disabled={batchDeletableCount === 0}
                title={hasHistorySelected ? '已发生的历史数据不可删除' : batchDeletableCount === 0 ? '请先勾选未来日期记录' : ''}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs transition-colors whitespace-nowrap cursor-pointer ${
                  batchDeletableCount > 0 && !hasHistorySelected
                    ? 'bg-[#F53F3F]/15 text-[#F53F3F] hover:bg-red-100'
                    : 'bg-gray-100 text-gray-400 cursor-not-allowed'
                }`}
              >
                <i className="ri-delete-bin-line" />
                批量删除
              </button>
              <button
                onClick={handleImport}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF]/15 text-[#165DFF] text-xs hover:bg-[#165DFF]/25 transition-colors cursor-pointer whitespace-nowrap"
              >
                <i className="ri-file-upload-line" />
                Excel导入
              </button>
              <button
                onClick={handleExport}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF]/15 text-[#165DFF] text-xs hover:bg-[#165DFF]/25 transition-colors cursor-pointer whitespace-nowrap"
              >
                <i className="ri-download-line" />
                导出
              </button>
              <button
                onClick={handleTemplateDownload}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
              >
                <i className="ri-file-list-line" />
                模板下载
              </button>
            </div>
          </div>
        </div>

        {/* Table */}
        <div className="bg-white rounded-xl border border-[#E5E6EB] overflow-x-auto" style={{ overflowX: 'auto' }}>
          <table className="w-full text-xs" style={{ minWidth: 'max-content' }}>
            <thead>
              <tr className="border-b border-[#E5E6EB] bg-[#F7F8FA]">
                <th className="text-center py-2.5 px-2 font-medium text-[#86909C] w-10">
                  <input
                    type="checkbox"
                    checked={pageData.filter(item => isFuture(item.date)).every(item => selectedIds.has(item.date)) && pageData.some(item => isFuture(item.date))}
                    onChange={toggleSelectAll}
                    className="cursor-pointer"
                  />
                </th>
                <th className="text-center py-2.5 px-2 font-medium text-[#86909C] w-10">序号</th>
                <th className="text-left py-2.5 px-3 font-medium text-[#86909C]">日期</th>
                <th className="text-center py-2.5 px-3 font-medium text-[#86909C]">全省在运机组</th>
                <th className="text-center py-2.5 px-3 font-medium text-[#86909C]">全省调停机组</th>
                <th className="text-center py-2.5 px-3 font-medium text-[#86909C]">全省检修机组</th>
                <th className="text-center py-2.5 px-3 font-medium text-[#86909C]">全省固定出力机组</th>
                <th className="text-center py-2.5 px-3 font-medium text-[#86909C]">数据来源</th>
                <th className="text-left py-2.5 px-3 font-medium text-[#86909C]">更新时间</th>
                <th className="text-center py-2.5 px-3 font-medium text-[#86909C]">操作</th>
              </tr>
            </thead>
            <tbody>
              {pageData.map((item, idx) => {
                const future = isFuture(item.date);
                return (
                  <tr key={item.date} className="border-b border-[#E5E6EB]/50 hover:bg-[#F7F8FA]/60">
                    <td className="py-2 px-2 text-center">
                      <input
                        type="checkbox"
                        checked={selectedIds.has(item.date)}
                        onChange={() => toggleSelect(item.date)}
                        disabled={!future}
                        className="cursor-pointer"
                      />
                    </td>
                    <td className="py-2 px-2 text-center text-[#86909C]">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="py-2 px-3 text-[#1D2129] font-medium whitespace-nowrap">{item.date}</td>
                    <td className="py-2 px-3 text-center">
                      <div className="flex items-center justify-center gap-1">
                        <span className="text-[#1D2129]">{item.runningCount}</span>
                        <span className="text-[#86909C]">台</span>
                        <span className="text-[#86909C] mx-0.5">/</span>
                        <span className="text-[#1D2129] font-medium">{item.runningCapacity}</span>
                        <span className="text-[#86909C]">MW</span>
                      </div>
                    </td>
                    <td className="py-2 px-3 text-center">
                      <div className="flex items-center justify-center gap-1">
                        <span className="text-[#1D2129]">{item.standbyCount}</span>
                        <span className="text-[#86909C]">台</span>
                        <span className="text-[#86909C] mx-0.5">/</span>
                        <span className="text-[#1D2129] font-medium">{item.standbyCapacity}</span>
                        <span className="text-[#86909C]">MW</span>
                      </div>
                    </td>
                    <td className="py-2 px-3 text-center">
                      <div className="flex items-center justify-center gap-1">
                        <span className="text-[#1D2129]">{item.maintenanceCount}</span>
                        <span className="text-[#86909C]">台</span>
                        <span className="text-[#86909C] mx-0.5">/</span>
                        <span className="text-[#1D2129] font-medium">{item.maintenanceCapacity}</span>
                        <span className="text-[#86909C]">MW</span>
                      </div>
                    </td>
                    <td className="py-2 px-3 text-center">
                      <div className="flex items-center justify-center gap-1">
                        <span className="text-[#1D2129]">{item.fixedCount}</span>
                        <span className="text-[#86909C]">台</span>
                        <span className="text-[#86909C] mx-0.5">/</span>
                        <span className="text-[#1D2129] font-medium">{item.fixedCapacity}</span>
                        <span className="text-[#86909C]">MW</span>
                      </div>
                    </td>
                    <td className="py-2 px-3 text-center">
                      <span className={`text-[10px] px-2 py-0.5 rounded-full ${
                        item.dataSource === '系统同步'
                          ? 'bg-[#165DFF]/10 text-[#165DFF]'
                          : 'bg-[#FF7D00]/10 text-[#FF7D00]'
                      }`}>
                        {item.dataSource}
                      </span>
                    </td>
                    <td className="py-2 px-3 text-[#86909C] whitespace-nowrap">{item.updatedAt}</td>
                    <td className="py-2 px-3 text-center">
                      <div className="flex items-center justify-center gap-2">
                        <button
                          onClick={() => handleView(item.date)}
                          className="text-[#165DFF] hover:text-blue-600 transition-colors cursor-pointer"
                          title="查看"
                        >
                          <i className="ri-eye-line" />
                        </button>
                        <button
                          onClick={() => handleMaintain(item.date)}
                          className="text-amber-500 hover:text-amber-600 transition-colors cursor-pointer"
                          title="维护"
                        >
                          <i className="ri-edit-line" />
                        </button>
                        <button
                          onClick={() => handleDelete(item.date)}
                          disabled={!future}
                          title={future ? '删除' : '历史数据不可删除，仅可编辑维护'}
                          className={`transition-colors ${
                            future
                              ? 'text-[#F53F3F] hover:text-red-600 cursor-pointer'
                              : 'text-gray-300 cursor-not-allowed'
                          }`}
                        >
                          <i className="ri-delete-bin-line" />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between px-4 py-3 border-t border-[#E5E6EB]">
              <span className="text-[11px] text-[#86909C]">
                共 {filteredData.length} 条，第 {currentPage} / {totalPages} 页
              </span>
              <div className="flex items-center gap-1">
                <button
                  onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                  disabled={currentPage === 1}
                  className="w-7 h-7 flex items-center justify-center rounded-md border border-[#E5E6EB] text-[#4E5969] hover:bg-[#F7F8FA] disabled:text-gray-300 disabled:cursor-not-allowed cursor-pointer transition-colors"
                >
                  <i className="ri-arrow-left-s-line" />
                </button>
                {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                  <button
                    key={page}
                    onClick={() => setCurrentPage(page)}
                    className={`w-7 h-7 flex items-center justify-center rounded-md text-[11px] cursor-pointer transition-colors ${
                      page === currentPage
                        ? 'bg-[#165DFF] text-white'
                        : 'border border-[#E5E6EB] text-[#4E5969] hover:bg-[#F7F8FA]'
                    }`}
                  >
                    {page}
                  </button>
                ))}
                <button
                  onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                  disabled={currentPage === totalPages}
                  className="w-7 h-7 flex items-center justify-center rounded-md border border-[#E5E6EB] text-[#4E5969] hover:bg-[#F7F8FA] disabled:text-gray-300 disabled:cursor-not-allowed cursor-pointer transition-colors"
                >
                  <i className="ri-arrow-right-s-line" />
                </button>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Delete confirm modal */}
      {showDeleteModal && (
        <ConfirmModal
          title="确认删除"
          message="删除后数据不可恢复，是否确认删除？"
          onConfirm={confirmDelete}
          onCancel={() => { setShowDeleteModal(false); setDeleteItemDate(null); }}
        />
      )}

      {/* Batch delete confirm modal */}
      {showBatchDeleteModal && (
        <ConfirmModal
          title="批量删除确认"
          message={`已勾选 ${batchDeletableCount} 条未来日期记录，删除后数据不可恢复，是否确认删除？`}
          onConfirm={confirmBatchDelete}
          onCancel={() => setShowBatchDeleteModal(false)}
        />
      )}

      {/* Add date modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
          <div className="bg-white rounded-xl p-6 w-full max-w-sm mx-4 shadow-xl">
            <h3 className="text-sm font-bold text-[#1D2129] mb-4">新增维护记录</h3>
            <div className="mb-5">
              <label className="block text-xs text-[#86909C] mb-1.5">选择日期</label>
              <input
                type="date"
                value={newDate}
                onChange={(e) => setNewDate(e.target.value)}
                className="w-full text-xs px-3 py-2 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]"
              />
              <p className="text-[11px] text-[#86909C] mt-1.5">系统将自动复制所选日期前一交易日的机组数据作为初始值</p>
            </div>
            <div className="flex gap-3 justify-end">
              <button
                onClick={() => setShowAddModal(false)}
                className="px-4 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
              >
                取消
              </button>
              <button
                onClick={confirmAdd}
                className="px-4 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-blue-600 transition-colors cursor-pointer whitespace-nowrap"
              >
                确认
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Toast */}
      {toast && (
        <Toast
          message={toast.message}
          type={toast.type}
          onClose={() => setToast(null)}
        />
      )}
    </SpotTradingLayout>
  );
}
