import { useState, useCallback } from 'react';
import ConfirmModal from '@/components/ConfirmModal';

interface CoefficientAdjustProps {
  data: Array<{
    time: string;
    forecastLoad: number;
    coefficient: number;
    operator: '+' | '-' | '*' | '/';
    calcBid: number;
  }>;
  coefficients: number[];
  onUpdateCoefficient: (idx: number, value: number) => void;
  onUpdateOperator: (idx: number, value: '+' | '-' | '*' | '/') => void;
  onSave: () => void;
  hasUnsaved: boolean;
}

const TABLE_RANGES = [
  { label: '00:30-08:00', start: 2, end: 34 },
  { label: '08:30-16:00', start: 34, end: 66 },
  { label: '16:30-24:00', start: 66, end: 98 },
];

const OP_LABELS: Record<string, string> = {
  '+': '+',
  '-': '-',
  '*': '×',
  '/': '÷',
};

export default function CoefficientAdjust({
  data, coefficients, onUpdateCoefficient, onUpdateOperator, onSave, hasUnsaved,
}: CoefficientAdjustProps) {
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [showSaveSuccess, setShowSaveSuccess] = useState(false);
  const [errors, setErrors] = useState<Record<number, string>>({});
  const [hoverRow, setHoverRow] = useState<number | null>(null);

  // Batch selection
  const [selectedRows, setSelectedRows] = useState<Set<number>>(new Set());
  const [showBatchPanel, setShowBatchPanel] = useState(false);
  const [batchOp, setBatchOp] = useState<'+' | '-' | '*' | '/'>('*');
  const [batchValue, setBatchValue] = useState('');
  const [batchError, setBatchError] = useState('');

  const validate = useCallback(() => {
    const newErrors: Record<number, string> = {};
    coefficients.forEach((v, i) => {
      if (isNaN(v) || v === 0) {
        newErrors[i] = '系数不能为空';
      } else if (v <= 0) {
        newErrors[i] = '系数必须为正数';
      } else {
        const decimals = (v.toString().split('.')[1] || '').length;
        if (decimals > 2) {
          newErrors[i] = '至多两位小数';
        }
      }
    });
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }, [coefficients]);

  const handleSaveClick = () => {
    if (!validate()) {
      const firstErr = Object.keys(errors).map(Number).sort((a, b) => a - b)[0];
      if (firstErr !== undefined) {
        const el = document.getElementById(`coeff-input-${firstErr}`);
        el?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
      return;
    }
    setShowSaveConfirm(true);
  };

  const handleConfirmSave = () => {
    setShowSaveConfirm(false);
    onSave();
    setShowSaveSuccess(true);
    setTimeout(() => setShowSaveSuccess(false), 3000);
  };

  const handleInputChange = (idx: number, raw: string) => {
    const num = parseFloat(raw);
    if (raw === '') {
      onUpdateCoefficient(idx, 0);
      setErrors(prev => ({ ...prev, [idx]: '系数不能为空' }));
      return;
    }
    if (isNaN(num)) {
      return;
    }
    if (num < 0) {
      onUpdateCoefficient(idx, 0);
      setErrors(prev => ({ ...prev, [idx]: '系数仅允许输入正数' }));
      return;
    }
    const rounded = Math.round(num * 100) / 100;
    onUpdateCoefficient(idx, rounded);
    setErrors(prev => {
      const next = { ...prev };
      delete next[idx];
      return next;
    });
  };

  const toggleRowSelect = (idx: number) => {
    setSelectedRows(prev => {
      const next = new Set(prev);
      if (next.has(idx)) next.delete(idx);
      else next.add(idx);
      return next;
    });
  };

  const selectAllInRange = (start: number, end: number) => {
    const rangeSet = new Set<number>();
    for (let i = start; i < Math.min(end, data.length); i++) rangeSet.add(i);
    const allSelected = Array.from(rangeSet).every(i => selectedRows.has(i));
    setSelectedRows(prev => {
      const next = new Set(prev);
      if (allSelected) {
        rangeSet.forEach(i => next.delete(i));
      } else {
        rangeSet.forEach(i => next.add(i));
      }
      return next;
    });
  };

  const applyBatchFormula = () => {
    const val = parseFloat(batchValue);
    if (isNaN(val)) { setBatchError('请输入有效数值'); return; }
    if (val < 0) { setBatchError('不可为负数'); return; }
    if (selectedRows.size === 0) { setBatchError('请先勾选至少一个时段'); return; }
    setBatchError('');
    selectedRows.forEach(idx => {
      onUpdateOperator(idx, batchOp);
      onUpdateCoefficient(idx, Math.round(val * 100) / 100);
    });
    setErrors(prev => {
      const next = { ...prev };
      selectedRows.forEach(idx => delete next[idx]);
      return next;
    });
  };

  const renderTable = (startIdx: number, endIdx: number, rangeLabel: string) => {
    const rows = data.slice(startIdx, Math.min(endIdx, data.length));
    const rangeAllSelected = rows.length > 0 && rows.every((_, i) => selectedRows.has(startIdx + i));
    return (
      <div className="flex-1 min-w-[320px]">
        <div className="flex items-center justify-between mb-1.5">
          <div className="text-xs text-[#86909C] font-medium">{rangeLabel}</div>
          <button
            onClick={() => selectAllInRange(startIdx, endIdx)}
            className="text-[10px] text-[#165DFF] hover:text-blue-700 cursor-pointer whitespace-nowrap"
          >
            {rangeAllSelected ? '取消全选' : '全选'}
          </button>
        </div>
        <div className="border border-[#E5E6EB] rounded-lg overflow-hidden">
          <div className="overflow-y-auto max-h-[520px]">
            <table className="w-full text-xs">
              <thead className="sticky top-0 z-10">
                <tr className="bg-[#F7F8FA]">
                  <th className="px-1 py-1.5 text-center text-[#86909C] font-medium border-b border-[#E5E6EB] w-6">
                    <input
                      type="checkbox"
                      checked={rangeAllSelected}
                      onChange={() => selectAllInRange(startIdx, endIdx)}
                      className="cursor-pointer"
                    />
                  </th>
                  <th className="px-2 py-1.5 text-left text-[#86909C] font-medium border-b border-[#E5E6EB] w-12">时间</th>
                  <th className="px-2 py-1.5 text-right text-[#86909C] font-medium border-b border-[#E5E6EB]">预测负荷</th>
                  <th className="px-2 py-1.5 text-center text-[#86909C] font-medium border-b border-[#E5E6EB] w-14">公式</th>
                  <th className="px-2 py-1.5 text-right text-[#86909C] font-medium border-b border-[#E5E6EB]">系数</th>
                  <th className="px-2 py-1.5 text-right text-[#86909C] font-medium border-b border-[#E5E6EB]">报量</th>
                </tr>
              </thead>
              <tbody>
                {rows.map((row, relIdx) => {
                  const idx = startIdx + relIdx;
                  const err = errors[idx];
                  const isSelected = selectedRows.has(idx);
                  return (
                    <tr
                      key={idx}
                      className={`${idx % 2 === 0 ? 'bg-white' : 'bg-[#F7F8FA]'} ${hoverRow === idx ? 'bg-[#E8F4FD]' : ''} ${isSelected ? 'bg-[#165DFF]/5' : ''}`}
                      onMouseEnter={() => setHoverRow(idx)}
                      onMouseLeave={() => setHoverRow(null)}
                    >
                      <td className="px-1 py-1 text-center border-b border-[#E5E6EB]/50">
                        <input
                          type="checkbox"
                          checked={isSelected}
                          onChange={() => toggleRowSelect(idx)}
                          className="cursor-pointer"
                        />
                      </td>
                      <td className="px-2 py-1 text-[#86909C] font-mono border-b border-[#E5E6EB]/50">{row.time}</td>
                      <td className="px-2 py-1 text-right text-[#4E5969] font-mono border-b border-[#E5E6EB]/50">{row.forecastLoad}</td>
                      <td className="px-2 py-1 text-center border-b border-[#E5E6EB]/50">
                        <select
                          value={row.operator}
                          onChange={e => onUpdateOperator(idx, e.target.value as '+' | '-' | '*' | '/')}
                          className="text-xs px-1 py-0.5 rounded border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF] w-12 text-center cursor-pointer"
                        >
                          <option value="+">+</option>
                          <option value="-">-</option>
                          <option value="*">×</option>
                          <option value="/">÷</option>
                        </select>
                      </td>
                      <td className="px-2 py-1 border-b border-[#E5E6EB]/50">
                        <input
                          id={`coeff-input-${idx}`}
                          type="text"
                          value={coefficients[idx] || ''}
                          onChange={e => handleInputChange(idx, e.target.value)}
                          className={`w-16 text-right text-xs font-mono bg-transparent border rounded px-1 py-0.5 focus:outline-none focus:border-[#165DFF] ${
                            err ? 'border-red-400 text-red-600' : 'border-[#E5E6EB] text-[#1D2129]'
                          }`}
                          placeholder="0.92"
                        />
                        {err && <div className="text-[9px] text-red-500 mt-0.5">{err}</div>}
                      </td>
                      <td className="px-2 py-1 text-right text-[#4E5969] font-mono border-b border-[#E5E6EB]/50">
                        {row.calcBid.toFixed(2)}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="bg-white rounded-lg border border-[#E5E6EB] p-4 mb-4">
      <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
        <div className="flex items-center gap-3">
          <h3 className="text-sm font-bold text-[#1D2129]">系数调整</h3>
          <span className="text-xs text-[#86909C]">
            <i className="ri-error-warning-line mr-0.5 text-amber-500" />
            公式符号 +、-、×、÷ 配合系数进行计算，批量勾选后可统一设置
          </span>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowBatchPanel(v => !v)}
            className="flex items-center gap-1 px-3 py-1.5 text-xs border border-[#E5E6EB] rounded hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
          >
            <i className={`ri-${showBatchPanel ? 'close' : 'calculator'}-line`} />
            {showBatchPanel ? '关闭批量' : '批量公式'}
          </button>
          {hasUnsaved && (
            <span className="text-xs text-amber-600 flex items-center gap-1">
              <i className="ri-edit-circle-line" />
              有未保存修改
            </span>
          )}
          <button
            onClick={handleSaveClick}
            className="px-4 py-1.5 text-xs bg-[#165DFF] text-white rounded hover:bg-[#165DFF]/80 transition-colors cursor-pointer whitespace-nowrap"
          >
            <i className="ri-save-line mr-1" />
            保存
          </button>
        </div>
      </div>

      {/* Batch formula panel */}
      {showBatchPanel && (
        <div className="flex items-center gap-3 mb-4 p-3 bg-[#F7F8FA] rounded-lg flex-wrap">
          <span className="text-xs text-[#4E5969] font-medium">
            <i className="ri-checkbox-multiple-line mr-1" />
            已选 {selectedRows.size} 个时段
          </span>
          <span className="text-xs text-[#86909C]">批量设置公式：</span>
          <select
            value={batchOp}
            onChange={e => setBatchOp(e.target.value as '+' | '-' | '*' | '/')}
            className="text-xs px-2 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF] w-14 text-center"
          >
            <option value="+">+</option>
            <option value="-">-</option>
            <option value="*">×</option>
            <option value="/">÷</option>
          </select>
          <input
            type="number"
            step="0.01"
            value={batchValue}
            onChange={e => { setBatchValue(e.target.value); setBatchError(''); }}
            placeholder="数值"
            className="w-24 text-xs px-2 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]"
          />
          <button
            onClick={applyBatchFormula}
            className="flex items-center gap-1 px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-blue-600 transition-colors cursor-pointer whitespace-nowrap"
          >
            <i className="ri-check-line" />一键应用
          </button>
          {batchError && <span className="text-[11px] text-[#F53F3F]">{batchError}</span>}
        </div>
      )}

      <div className="flex gap-3 flex-wrap">
        {TABLE_RANGES.map(r => renderTable(r.start, r.end, r.label))}
      </div>

      {showSaveConfirm && (
        <ConfirmModal
          title="确认保存系数"
          message="您即将保存当前96点段系数配置，保存后将同步更新申报电量数据，是否确认？"
          onConfirm={handleConfirmSave}
          onCancel={() => setShowSaveConfirm(false)}
          confirmText="确认保存"
        />
      )}

      {showSaveSuccess && (
        <div className="fixed top-16 right-6 z-50 bg-emerald-50 border border-emerald-200 text-emerald-700 px-4 py-2 rounded-lg text-sm flex items-center gap-2 animate-fade-in">
          <i className="ri-checkbox-circle-line" />
          系数保存成功
        </div>
      )}
    </div>
  );
}