import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import AdminLayout from '../../components/AdminLayout';
import ConfirmModal from '@/components/ConfirmModal';
import Toast from '@/components/Toast';
import { adminUsers, departments, roles } from '@/mocks/adminData';
import type { AdminUser } from '@/mocks/adminData';

export default function UserListPage() {
  const navigate = useNavigate();
  const [users, setUsers] = useState<AdminUser[]>(adminUsers);
  const [searchName, setSearchName] = useState('');
  const [searchAccount, setSearchAccount] = useState('');
  const [filterDept, setFilterDept] = useState('全部');
  const [filterRole, setFilterRole] = useState('全部');
  const [filterStatus, setFilterStatus] = useState('全部');
  const [dateRange, setDateRange] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  // Modal states
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showViewModal, setShowViewModal] = useState(false);
  const [showRoleModal, setShowRoleModal] = useState(false);
  const [showResetPwdModal, setShowResetPwdModal] = useState(false);
  const [showToggleModal, setShowToggleModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [selectedUser, setSelectedUser] = useState<AdminUser | null>(null);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  // Form states
  const [formData, setFormData] = useState({
    account: '', name: '', department: departments[1], phone: '', password: '', email: '', remark: '', role: roles[1],
  });
  const [formErrors, setFormErrors] = useState<Record<string, string>>();

  const filteredUsers = useMemo(() => {
    let result = users;
    if (searchName) result = result.filter(u => u.name.includes(searchName));
    if (searchAccount) result = result.filter(u => u.account.includes(searchAccount));
    if (filterDept !== '全部') result = result.filter(u => u.department === filterDept);
    if (filterRole !== '全部') result = result.filter(u => u.role === filterRole);
    if (filterStatus !== '全部') result = result.filter(u => (u.status === 'enabled' ? '启用' : '禁用') === filterStatus);
    return result;
  }, [users, searchName, searchAccount, filterDept, filterRole, filterStatus]);

  const totalPages = Math.ceil(filteredUsers.length / pageSize);
  const pagedUsers = filteredUsers.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const showToast = (message: string, type: 'success' | 'error') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const validateForm = () => {
    const errors: Record<string, string> = {};
    if (!formData.account.trim()) errors.account = '请输入用户账号';
    if (!formData.name.trim()) errors.name = '请输入用户姓名';
    if (!formData.department) errors.department = '请选择所属部门';
    if (!formData.phone.trim()) errors.phone = '请输入手机号';
    if (!/^[1][3-9]\d{9}$/.test(formData.phone)) errors.phone = '手机号格式不正确';
    if (showAddModal && !formData.password.trim()) errors.password = '请输入初始密码';
    if (formData.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) errors.email = '邮箱格式不正确';
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleAdd = () => {
    if (!validateForm()) return;
    if (users.some(u => u.account === formData.account)) {
      setFormErrors(prev => ({ ...prev, account: '该账号已存在' }));
      return;
    }
    const newUser: AdminUser = {
      id: String(users.length + 1),
      account: formData.account,
      name: formData.name,
      department: formData.department,
      role: formData.role,
      status: 'enabled',
      phone: formData.phone,
      email: formData.email,
      createdAt: '2026-05-08 10:00',
      lastLogin: '-',
      remark: formData.remark,
    };
    setUsers(prev => [newUser, ...prev]);
    setShowAddModal(false);
    setFormData({ account: '', name: '', department: departments[1], phone: '', password: '', email: '', remark: '', role: roles[1] });
    setFormErrors({});
    showToast('新增用户成功', 'success');
  };

  const handleEdit = () => {
    if (!selectedUser || !validateForm()) return;
    setUsers(prev => prev.map(u => u.id === selectedUser.id ? { ...u, name: formData.name, department: formData.department, phone: formData.phone, email: formData.email, remark: formData.remark } : u));
    setShowEditModal(false);
    setFormErrors({});
    showToast('编辑用户成功', 'success');
  };

  const handleToggleStatus = () => {
    if (!selectedUser) return;
    const newStatus = selectedUser.status === 'enabled' ? 'disabled' : 'enabled';
    setUsers(prev => prev.map(u => u.id === selectedUser.id ? { ...u, status: newStatus } : u));
    setShowToggleModal(false);
    showToast(`用户已${newStatus === 'enabled' ? '启用' : '禁用'}`, 'success');
  };

  const handleDelete = () => {
    if (!selectedUser) return;
    setUsers(prev => prev.filter(u => u.id !== selectedUser.id));
    setShowDeleteModal(false);
    showToast('用户删除成功', 'success');
  };

  const handleResetPwd = () => {
    setShowResetPwdModal(false);
    showToast('密码重置成功，已发送新密码至用户手机', 'success');
  };

  const handleAssignRole = () => {
    if (!selectedUser) return;
    setUsers(prev => prev.map(u => u.id === selectedUser.id ? { ...u, role: formData.role } : u));
    setShowRoleModal(false);
    showToast('角色分配成功', 'success');
  };

  const openModal = (type: string, user: AdminUser) => {
    setSelectedUser(user);
    setFormData({
      account: user.account, name: user.name, department: user.department, phone: user.phone,
      password: '', email: user.email, remark: user.remark, role: user.role,
    });
    setFormErrors({});
    switch (type) {
      case 'view': setShowViewModal(true); break;
      case 'edit': setShowEditModal(true); break;
      case 'role': setShowRoleModal(true); break;
      case 'reset': setShowResetPwdModal(true); break;
      case 'toggle': setShowToggleModal(true); break;
      case 'delete': setShowDeleteModal(true); break;
    }
  };

  const exportUsers = () => {
    const csv = [
      ['序号', '用户账号', '用户姓名', '所属部门', '关联角色', '用户状态', '手机号', '邮箱', '创建时间', '最后登录时间', '备注'],
      ...filteredUsers.map((u, i) => [i + 1, u.account, u.name, u.department, u.role, u.status === 'enabled' ? '启用' : '禁用', u.phone, u.email, u.createdAt, u.lastLogin, u.remark]),
    ].map(row => row.join(',')).join('\n');
    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `用户列表_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
    showToast('导出成功', 'success');
  };

  const getStatusStyle = (status: string) => {
    return status === 'enabled'
      ? 'bg-[#00C48C]/10 text-[#00C48C]'
      : 'bg-[#86909C]/10 text-[#86909C]';
  };

  return (
    <AdminLayout>
      <div className="space-y-4 text-[#1D2129]">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">用户列表管理</h1>
            <p className="text-sm text-[#86909C] mt-1">管理平台所有用户账号、权限与状态</p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={exportUsers}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-download-line" />
              批量导出
            </button>
            <button
              onClick={() => {
                setFormData({ account: '', name: '', department: departments[1], phone: '', password: '', email: '', remark: '', role: roles[1] });
                setFormErrors({});
                setShowAddModal(true);
              }}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/80 transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-add-line" />
              新增用户
            </button>
          </div>
        </div>

        {/* Filter Area */}
        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex flex-wrap items-end gap-3">
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">用户姓名</label>
              <input
                type="text"
                value={searchName}
                onChange={e => setSearchName(e.target.value)}
                placeholder="请输入姓名"
                className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[140px]"
              />
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">用户账号</label>
              <input
                type="text"
                value={searchAccount}
                onChange={e => setSearchAccount(e.target.value)}
                placeholder="请输入账号"
                className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[140px]"
              />
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">所属部门</label>
              <select
                value={filterDept}
                onChange={e => setFilterDept(e.target.value)}
                className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[140px] bg-white"
              >
                {departments.map(d => <option key={d} value={d}>{d}</option>)}
              </select>
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">角色</label>
              <select
                value={filterRole}
                onChange={e => setFilterRole(e.target.value)}
                className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[140px] bg-white"
              >
                {roles.map(r => <option key={r} value={r}>{r}</option>)}
              </select>
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">用户状态</label>
              <select
                value={filterStatus}
                onChange={e => setFilterStatus(e.target.value)}
                className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[100px] bg-white"
              >
                <option value="全部">全部</option>
                <option value="启用">启用</option>
                <option value="禁用">禁用</option>
              </select>
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">创建时间</label>
              <input
                type="date"
                value={dateRange}
                onChange={e => setDateRange(e.target.value)}
                className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[140px]"
              />
            </div>
            <div className="flex gap-2 ml-auto">
              <button
                onClick={() => { setSearchName(''); setSearchAccount(''); setFilterDept('全部'); setFilterRole('全部'); setFilterStatus('全部'); setDateRange(''); }}
                className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
              >
                重置
              </button>
              <button
                onClick={() => setCurrentPage(1)}
                className="px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/80 transition-colors cursor-pointer whitespace-nowrap"
              >
                查询
              </button>
            </div>
          </div>
        </div>

        {/* Table */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#F7F8FA] sticky top-0">
                <tr>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">序号</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">用户账号</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">用户姓名</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">所属部门</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">关联角色</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">用户状态</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">创建时间</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">最后登录时间</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">操作</th>
                </tr>
              </thead>
              <tbody>
                {pagedUsers.map((user, idx) => (
                  <tr key={user.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : 'bg-white'}`}>
                    <td className="px-3 py-3 text-[#4E5969]">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="px-3 py-3 text-[#1D2129] font-medium">{user.account}</td>
                    <td className="px-3 py-3 text-[#4E5969]">{user.name}</td>
                    <td className="px-3 py-3 text-[#4E5969]">{user.department}</td>
                    <td className="px-3 py-3 text-[#4E5969]">{user.role}</td>
                    <td className="px-3 py-3">
                      <span className={`text-[10px] px-2 py-0.5 rounded-full ${getStatusStyle(user.status)}`}>
                        {user.status === 'enabled' ? '启用' : '禁用'}
                      </span>
                    </td>
                    <td className="px-3 py-3 text-[#86909C]">{user.createdAt}</td>
                    <td className="px-3 py-3 text-[#86909C]">{user.lastLogin}</td>
                    <td className="px-3 py-3">
                      <div className="flex items-center gap-1">
                        <button onClick={() => openModal('view', user)} className="p-1 rounded hover:bg-[#F7F8FA] text-[#86909C] hover:text-[#165DFF] cursor-pointer" title="查看">
                          <i className="ri-eye-line" />
                        </button>
                        <button onClick={() => openModal('edit', user)} className="p-1 rounded hover:bg-[#F7F8FA] text-[#86909C] hover:text-[#165DFF] cursor-pointer" title="编辑">
                          <i className="ri-edit-line" />
                        </button>
                        <button onClick={() => openModal('role', user)} className="p-1 rounded hover:bg-[#F7F8FA] text-[#86909C] hover:text-[#165DFF] cursor-pointer" title="分配角色">
                          <i className="ri-shield-user-line" />
                        </button>
                        <button onClick={() => openModal('reset', user)} className="p-1 rounded hover:bg-[#F7F8FA] text-[#86909C] hover:text-[#FF7D00] cursor-pointer" title="重置密码">
                          <i className="ri-key-2-line" />
                        </button>
                        <button onClick={() => openModal('toggle', user)} className="p-1 rounded hover:bg-[#F7F8FA] text-[#86909C] hover:text-[#00C48C] cursor-pointer" title={user.status === 'enabled' ? '禁用' : '启用'}>
                          <i className={user.status === 'enabled' ? 'ri-forbid-line' : 'ri-check-line'} />
                        </button>
                        <button onClick={() => openModal('delete', user)} className="p-1 rounded hover:bg-[#F7F8FA] text-[#86909C] hover:text-[#F53F3F] cursor-pointer" title="删除">
                          <i className="ri-delete-bin-line" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
                {pagedUsers.length === 0 && (
                  <tr><td colSpan={9} className="px-3 py-8 text-center text-[#86909C]">暂无数据</td></tr>
                )}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          <div className="flex items-center justify-between px-3 py-3 border-t border-[#E5E6EB]">
            <span className="text-xs text-[#86909C]">共 {filteredUsers.length} 条，每页 {pageSize} 条</span>
            <div className="flex items-center gap-1">
              <button
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="px-2 py-1 rounded text-xs border border-[#E5E6EB] hover:bg-[#F7F8FA] disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer"
              >
                上一页
              </button>
              {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                const page = i + 1;
                return (
                  <button
                    key={page}
                    onClick={() => setCurrentPage(page)}
                    className={`w-7 h-7 rounded text-xs cursor-pointer ${
                      currentPage === page ? 'bg-[#165DFF] text-white' : 'border border-[#E5E6EB] hover:bg-[#F7F8FA]'
                    }`}
                  >
                    {page}
                  </button>
                );
              })}
              <button
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages || totalPages === 0}
                className="px-2 py-1 rounded text-xs border border-[#E5E6EB] hover:bg-[#F7F8FA] disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer"
              >
                下一页
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Add Modal */}
      {showAddModal && (
        <ConfirmModal title="新增用户" message="" onConfirm={handleAdd} onCancel={() => setShowAddModal(false)}>
          <div className="grid grid-cols-2 gap-3">
            <div className="col-span-2">
              <label className="text-xs text-[#1D2129] block mb-1">用户账号 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.account} onChange={e => setFormData(p => ({ ...p, account: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" placeholder="请输入用户账号" />
              {formErrors.account && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.account}</p>}
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">用户姓名 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.name} onChange={e => setFormData(p => ({ ...p, name: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" placeholder="请输入姓名" />
              {formErrors.name && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.name}</p>}
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">所属部门 <span className="text-[#F53F3F]">*</span></label>
              <select value={formData.department} onChange={e => setFormData(p => ({ ...p, department: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] bg-white">
                {departments.filter(d => d !== '全部').map(d => <option key={d} value={d}>{d}</option>)}
              </select>
              {formErrors.department && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.department}</p>}
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">手机号 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.phone} onChange={e => setFormData(p => ({ ...p, phone: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" placeholder="请输入手机号" />
              {formErrors.phone && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.phone}</p>}
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">初始密码 <span className="text-[#F53F3F]">*</span></label>
              <input type="password" value={formData.password} onChange={e => setFormData(p => ({ ...p, password: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" placeholder="请输入初始密码" />
              {formErrors.password && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.password}</p>}
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">角色 <span className="text-[#F53F3F]">*</span></label>
              <select value={formData.role} onChange={e => setFormData(p => ({ ...p, role: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] bg-white">
                {roles.filter(r => r !== '全部').map(r => <option key={r} value={r}>{r}</option>)}
              </select>
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">邮箱</label>
              <input value={formData.email} onChange={e => setFormData(p => ({ ...p, email: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" placeholder="请输入邮箱" />
              {formErrors.email && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.email}</p>}
            </div>
            <div className="col-span-2">
              <label className="text-xs text-[#1D2129] block mb-1">备注</label>
              <textarea value={formData.remark} onChange={e => setFormData(p => ({ ...p, remark: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] resize-none h-16" placeholder="请输入备注" />
            </div>
          </div>
        </ConfirmModal>
      )}

      {/* Edit Modal */}
      {showEditModal && selectedUser && (
        <ConfirmModal title="编辑用户" message="" onConfirm={handleEdit} onCancel={() => setShowEditModal(false)}>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">用户账号</label>
              <input value={formData.account} disabled className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs bg-[#F7F8FA] text-[#86909C]" />
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">用户姓名 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.name} onChange={e => setFormData(p => ({ ...p, name: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" />
              {formErrors.name && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.name}</p>}
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">所属部门 <span className="text-[#F53F3F]">*</span></label>
              <select value={formData.department} onChange={e => setFormData(p => ({ ...p, department: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] bg-white">
                {departments.filter(d => d !== '全部').map(d => <option key={d} value={d}>{d}</option>)}
              </select>
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">手机号 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.phone} onChange={e => setFormData(p => ({ ...p, phone: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" />
              {formErrors.phone && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.phone}</p>}
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">邮箱</label>
              <input value={formData.email} onChange={e => setFormData(p => ({ ...p, email: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" />
              {formErrors.email && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.email}</p>}
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">关联角色</label>
              <input value={selectedUser.role} disabled className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs bg-[#F7F8FA] text-[#86909C]" />
            </div>
            <div className="col-span-2">
              <label className="text-xs text-[#1D2129] block mb-1">备注</label>
              <textarea value={formData.remark} onChange={e => setFormData(p => ({ ...p, remark: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] resize-none h-16" />
            </div>
          </div>
        </ConfirmModal>
      )}

      {/* View Modal */}
      {showViewModal && selectedUser && (
        <ConfirmModal title="用户详情" message="" onConfirm={() => setShowViewModal(false)} onCancel={() => setShowViewModal(false)} showCancel={false} confirmText="关闭">
          <div className="grid grid-cols-2 gap-3 text-xs">
            <div><span className="text-[#86909C]">用户账号：</span><span className="text-[#1D2129]">{selectedUser.account}</span></div>
            <div><span className="text-[#86909C]">用户姓名：</span><span className="text-[#1D2129]">{selectedUser.name}</span></div>
            <div><span className="text-[#86909C]">所属部门：</span><span className="text-[#1D2129]">{selectedUser.department}</span></div>
            <div><span className="text-[#86909C]">关联角色：</span><span className="text-[#1D2129]">{selectedUser.role}</span></div>
            <div><span className="text-[#86909C]">用户状态：</span><span className={`${selectedUser.status === 'enabled' ? 'text-[#00C48C]' : 'text-[#86909C]'}`}>{selectedUser.status === 'enabled' ? '启用' : '禁用'}</span></div>
            <div><span className="text-[#86909C]">手机号：</span><span className="text-[#1D2129]">{selectedUser.phone}</span></div>
            <div><span className="text-[#86909C]">邮箱：</span><span className="text-[#1D2129]">{selectedUser.email || '-'}</span></div>
            <div><span className="text-[#86909C]">创建时间：</span><span className="text-[#1D2129]">{selectedUser.createdAt}</span></div>
            <div className="col-span-2"><span className="text-[#86909C]">最后登录时间：</span><span className="text-[#1D2129]">{selectedUser.lastLogin}</span></div>
            <div className="col-span-2"><span className="text-[#86909C]">备注：</span><span className="text-[#1D2129]">{selectedUser.remark || '-'}</span></div>
          </div>
        </ConfirmModal>
      )}

      {/* Role Assignment Modal */}
      {showRoleModal && selectedUser && (
        <ConfirmModal title="分配角色" message={`为用户 "${selectedUser.name}" (${selectedUser.account}) 分配角色`} onConfirm={handleAssignRole} onCancel={() => setShowRoleModal(false)}>
          <div className="mt-2">
            <label className="text-xs text-[#1D2129] block mb-2">选择角色</label>
            <select value={formData.role} onChange={e => setFormData(p => ({ ...p, role: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] bg-white">
              {roles.filter(r => r !== '全部').map(r => <option key={r} value={r}>{r}</option>)}
            </select>
          </div>
        </ConfirmModal>
      )}

      {/* Reset Password Modal */}
      {showResetPwdModal && selectedUser && (
        <ConfirmModal
          title="重置密码"
          message={`确定要重置用户 "${selectedUser.name}" (${selectedUser.account}) 的密码吗？重置后新密码将发送至用户手机。`}
          onConfirm={handleResetPwd}
          onCancel={() => setShowResetPwdModal(false)}
          confirmText="确认重置"
        />
      )}

      {/* Toggle Status Modal */}
      {showToggleModal && selectedUser && (
        <ConfirmModal
          title={selectedUser.status === 'enabled' ? '禁用用户' : '启用用户'}
          message={`确定要${selectedUser.status === 'enabled' ? '禁用' : '启用'}用户 "${selectedUser.name}" (${selectedUser.account}) 吗？${selectedUser.status === 'enabled' ? '禁用后该用户将无法登录平台。' : ''}`}
          onConfirm={handleToggleStatus}
          onCancel={() => setShowToggleModal(false)}
          confirmText="确认"
        />
      )}

      {/* Delete Modal */}
      {showDeleteModal && selectedUser && (
        <ConfirmModal
          title="删除用户"
          message={`确定要删除用户 "${selectedUser.name}" (${selectedUser.account}) 吗？此操作不可恢复，请谨慎操作！`}
          onConfirm={handleDelete}
          onCancel={() => setShowDeleteModal(false)}
          confirmText="确认删除"
        />
      )}

      {/* Toast */}
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </AdminLayout>
  );
}