import { useState, useMemo, useCallback } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import SpotTradingLayout from '@/pages/spot-trading/components/SpotTradingLayout';
import ConfirmModal from '@/components/ConfirmModal';
import Toast from '@/components/Toast';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
} from 'recharts';

interface PointData {
  time: string;
  power: number;
  price: number;
}

function generateInitialData(direction: '购电' | '售电'): PointData[] {
  const data: PointData[] = [];
  for (let i = 0; i < 96; i++) {
    const hour = Math.floor(i / 4);
    const minute = (i % 4) * 15;
    const time = `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
    // Different curves for purchase vs sell
    const basePower = direction === '购电'
      ? 1200 + Math.sin((i / 96) * Math.PI * 2 - Math.PI / 2) * 400
      : 800 + Math.sin((i / 96) * Math.PI * 2 - Math.PI / 2) * 250;
    const noise = Math.random() * 30 - 15;
    const power = Math.max(0, Math.round(basePower + noise));
    // Price range: Shanghai market roughly 200-500
    const basePrice = direction === '购电'
      ? 350 + Math.sin((i / 96) * Math.PI * 2) * 80
      : 380 + Math.sin((i / 96) * Math.PI * 2) * 60;
    const priceNoise = Math.random() * 20 - 10;
    const price = Math.max(200, Math.round(basePrice + priceNoise));
    data.push({ time, power, price });
  }
  return data;
}

// Shanghai market price limits
const MIN_PRICE = 200;
const MAX_PRICE = 500;

export default function InterprovincialDetailPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const date = searchParams.get('date') || '2026-05-07';
  const mode = searchParams.get('mode') || 'view';
  const isEdit = mode === 'edit';
  const isBlank = searchParams.get('blank') === 'true';
  const similarDay = searchParams.get('similarDay');

  const [direction, setDirection] = useState<'购电' | '售电'>('购电');
  const [pointData, setPointData] = useState<PointData[]>(() => {
    if (isBlank) {
      return Array.from({ length: 96 }, (_, i) => {
        const hour = Math.floor(i / 4);
        const minute = (i % 4) * 15;
        return {
          time: `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`,
          power: 0,
          price: 0,
        };
      });
    }
    return generateInitialData('购电');
  });
  const [hasChanges, setHasChanges] = useState(false);

  // Batch edit
  const [selectedPoints, setSelectedPoints] = useState<Set<number>>(new Set());
  const [batchPowerValue, setBatchPowerValue] = useState('');
  const [batchPriceValue, setBatchPriceValue] = useState('');
  const [batchError, setBatchError] = useState('');
  const [showBatchPanel, setShowBatchPanel] = useState(false);

  // Validation errors
  const [pointErrors, setPointErrors] = useState<Record<number, { power?: string; price?: string }>>({});

  // Price out-of-range warning
  const [showPriceWarning, setShowPriceWarning] = useState(false);

  // Modals & toast
  const [showCancelModal, setShowCancelModal] = useState(false);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  // Stats
  const stats = useMemo(() => {
    const powers = pointData.map(p => p.power);
    const prices = pointData.map(p => p.price);
    const totalPower = powers.reduce((sum, v) => sum + v, 0);
    const maxPower = Math.max(...powers);
    const minPower = Math.min(...powers);
    const avgPrice = prices.length > 0 ? Math.round(prices.reduce((sum, v) => sum + v, 0) / prices.length) : 0;
    return { totalPower, maxPower, minPower, avgPrice };
  }, [pointData]);

  // Chart data
  const chartData = useMemo(
    () =>
      pointData.map((p, idx) => ({
        idx: idx + 1,
        time: p.time,
        power: p.power,
        price: p.price,
      })),
    [pointData]
  );

  const validatePower = (val: number): string | null => {
    if (val < 0) return '电量不可为负数';
    return null;
  };

  const validatePrice = (val: number): string | null => {
    if (val < 0) return '电价不可为负数';
    if (val < MIN_PRICE) return `电价低于下限 ${MIN_PRICE}`;
    if (val > MAX_PRICE) return `电价超出上限 ${MAX_PRICE}`;
    return null;
  };

  const handlePowerChange = useCallback(
    (index: number, valueStr: string) => {
      const val = parseFloat(valueStr);
      if (isNaN(val)) return;
      const error = validatePower(val);
      setPointErrors(prev => {
        const next = { ...prev };
        if (!next[index]) next[index] = {};
        if (error) {
          next[index] = { ...next[index], power: error };
        } else {
          const updated = { ...next[index] };
          delete updated.power;
          if (Object.keys(updated).length === 0) {
            delete next[index];
          } else {
            next[index] = updated;
          }
        }
        return next;
      });
      setPointData(prev => {
        const next = [...prev];
        next[index] = { ...next[index], power: val };
        return next;
      });
      setHasChanges(true);
    },
    []
  );

  const handlePriceChange = useCallback(
    (index: number, valueStr: string) => {
      const val = parseFloat(valueStr);
      if (isNaN(val)) return;
      const error = validatePrice(val);
      setPointErrors(prev => {
        const next = { ...prev };
        if (!next[index]) next[index] = {};
        if (error) {
          next[index] = { ...next[index], price: error };
        } else {
          const updated = { ...next[index] };
          delete updated.price;
          if (Object.keys(updated).length === 0) {
            delete next[index];
          } else {
            next[index] = updated;
          }
        }
        return next;
      });
      setPointData(prev => {
        const next = [...prev];
        next[index] = { ...next[index], price: val };
        return next;
      });
      setHasChanges(true);
    },
    []
  );

  const handleDirectionChange = (newDir: '购电' | '售电') => {
    if (newDir === direction) return;
    setDirection(newDir);
    // Clear data and regenerate
    setPointData(generateInitialData(newDir));
    setPointErrors({});
    setSelectedPoints(new Set());
    setHasChanges(true);
    setToast({ message: `已切换为${newDir}方向，数据已重置`, type: 'success' });
  };

  const togglePointSelect = (index: number) => {
    setSelectedPoints(prev => {
      const next = new Set(prev);
      if (next.has(index)) {
        next.delete(index);
      } else {
        next.add(index);
      }
      return next;
    });
  };

  const selectAllPoints = () => {
    if (selectedPoints.size === 96) {
      setSelectedPoints(new Set());
    } else {
      setSelectedPoints(new Set(Array.from({ length: 96 }, (_, i) => i)));
    }
  };

  const applyBatchEdit = () => {
    const powerVal = batchPowerValue ? parseFloat(batchPowerValue) : null;
    const priceVal = batchPriceValue ? parseFloat(batchPriceValue) : null;

    if (selectedPoints.size === 0) {
      setBatchError('请先勾选至少一个时段');
      return;
    }

    if (powerVal !== null && (isNaN(powerVal) || powerVal < 0)) {
      setBatchError('电量不可为负数');
      return;
    }
    if (priceVal !== null && (isNaN(priceVal) || priceVal < 0)) {
      setBatchError('电价不可为负数');
      return;
    }
    if (priceVal !== null && (priceVal < MIN_PRICE || priceVal > MAX_PRICE)) {
      setBatchError(`电价需在 ${MIN_PRICE}-${MAX_PRICE} 范围内`);
      return;
    }

    setBatchError('');
    setPointData(prev => {
      const next = [...prev];
      selectedPoints.forEach(idx => {
        const updated: PointData = { ...next[idx] };
        if (powerVal !== null) updated.power = powerVal;
        if (priceVal !== null) updated.price = priceVal;
        next[idx] = updated;
      });
      return next;
    });
    // Clear errors for updated points
    setPointErrors(prev => {
      const next = { ...prev };
      selectedPoints.forEach(idx => {
        if (next[idx]) {
          const updated = { ...next[idx] };
          if (powerVal !== null && validatePower(powerVal) === null) delete updated.power;
          if (priceVal !== null && validatePrice(priceVal) === null) delete updated.price;
          if (Object.keys(updated).length === 0) {
            delete next[idx];
          } else {
            next[idx] = updated;
          }
        }
      });
      return next;
    });
    setHasChanges(true);
    setToast({ message: `已成功批量修改 ${selectedPoints.size} 个时段`, type: 'success' });
  };

  const hasPriceOutOfRange = useMemo(() => {
    return pointData.some(p => p.price < MIN_PRICE || p.price > MAX_PRICE);
  }, [pointData]);

  const handleSave = () => {
    if (Object.keys(pointErrors).length > 0) {
      setToast({ message: '存在数据错误，请修正后再保存', type: 'error' });
      return;
    }
    if (hasPriceOutOfRange) {
      setShowPriceWarning(true);
      return;
    }
    setShowSaveConfirm(true);
  };

  const confirmSave = () => {
    setShowSaveConfirm(false);
    setShowPriceWarning(false);
    setHasChanges(false);
    setToast({ message: '保存成功，数据已生效并同步至上游模块', type: 'success' });
    setTimeout(() => {
      navigate('/spot-trading/data-mgmt/interprovincial');
    }, 1500);
  };

  const handleCancel = () => {
    if (hasChanges) {
      setShowCancelModal(true);
    } else {
      navigate('/spot-trading/data-mgmt/interprovincial');
    }
  };

  const confirmCancel = () => {
    setShowCancelModal(false);
    navigate('/spot-trading/data-mgmt/interprovincial');
  };

  return (
    <SpotTradingLayout>
      <div className="w-full max-w-full space-y-4">
        {/* Top bar */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button
              onClick={() => navigate('/spot-trading/data-mgmt/interprovincial')}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-arrow-left-line" />
              返回列表
            </button>
            <h1 className="text-lg font-bold text-[#1D2129]">
              省间现货详情
              <span className="text-sm font-normal text-[#86909C] ml-1">（{date}）</span>
              <span
                className={`ml-2 text-[10px] px-2 py-0.5 rounded-full ${
                  isEdit
                    ? 'bg-[#FF7D00]/10 text-[#FF7D00]'
                    : 'bg-[#00C48C]/10 text-[#00C48C]'
                }`}
              >
                {isEdit ? '可编辑' : '只读'}
              </span>
            </h1>
          </div>
          {isEdit && (
            <div className="flex items-center gap-2">
              <button
                onClick={handleCancel}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
              >
                <i className="ri-close-line" />
                取消
              </button>
              <button
                onClick={handleSave}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-blue-600 transition-colors cursor-pointer whitespace-nowrap"
              >
                <i className="ri-check-line" />
                保存
              </button>
            </div>
          )}
        </div>

        {/* Similar day notice */}
        {similarDay && (
          <div className="flex items-center gap-2 bg-[#165DFF]/5 border border-[#165DFF]/20 rounded-lg px-3 py-2">
            <i className="ri-information-line text-[#165DFF] text-xs" />
            <span className="text-xs text-[#165DFF]">
              已复用相似日 {similarDay} 的省间现货数据作为初始值，可在此基础上修改
            </span>
          </div>
        )}

        {/* Direction selector */}
        <div className="flex items-center gap-3 bg-white rounded-xl border border-[#E5E6EB] p-3">
          <span className="text-xs text-[#86909C]">交易方向</span>
          {isEdit ? (
            <div className="flex items-center gap-1 rounded-md bg-[#F7F8FA] p-0.5">
              <button
                onClick={() => handleDirectionChange('购电')}
                className={`px-3 py-1 rounded-md text-xs transition-colors cursor-pointer whitespace-nowrap ${
                  direction === '购电'
                    ? 'bg-white text-[#165DFF] shadow-sm'
                    : 'text-[#86909C] hover:text-[#4E5969]'
                }`}
              >
                购电
              </button>
              <button
                onClick={() => handleDirectionChange('售电')}
                className={`px-3 py-1 rounded-md text-xs transition-colors cursor-pointer whitespace-nowrap ${
                  direction === '售电'
                    ? 'bg-white text-[#FF7D00] shadow-sm'
                    : 'text-[#86909C] hover:text-[#4E5969]'
                }`}
              >
                售电
              </button>
            </div>
          ) : (
            <span className={`text-xs px-2 py-0.5 rounded-full ${
              direction === '购电'
                ? 'bg-[#165DFF]/10 text-[#165DFF]'
                : 'bg-[#FF7D00]/10 text-[#FF7D00]'
            }`}>
              {direction}
            </span>
          )}
        </div>

        {/* Stats bar */}
        <div className="flex items-center gap-4 bg-white rounded-xl border border-[#E5E6EB] p-3">
          <div className="flex items-center gap-2 flex-1">
            <span className="text-xs text-[#86909C]">总电量</span>
            <span className="text-sm font-bold text-[#1D2129]">{stats.totalPower.toLocaleString()}</span>
            <span className="text-[10px] text-[#86909C]">MWh</span>
          </div>
          <div className="w-px h-6 bg-[#E5E6EB]" />
          <div className="flex items-center gap-2 flex-1">
            <span className="text-xs text-[#86909C]">加权均价</span>
            <span className="text-sm font-bold text-[#1D2129]">{stats.avgPrice}</span>
            <span className="text-[10px] text-[#86909C]">元/MWh</span>
          </div>
          <div className="w-px h-6 bg-[#E5E6EB]" />
          <div className="flex items-center gap-2 flex-1">
            <span className="text-xs text-[#86909C]">分时最大值</span>
            <span className="text-sm font-bold text-[#1D2129]">{stats.maxPower.toLocaleString()}</span>
            <span className="text-[10px] text-[#86909C]">MWh</span>
          </div>
          <div className="w-px h-6 bg-[#E5E6EB]" />
          <div className="flex items-center gap-2 flex-1">
            <span className="text-xs text-[#86909C]">分时最小值</span>
            <span className="text-sm font-bold text-[#1D2129]">{stats.minPower.toLocaleString()}</span>
            <span className="text-[10px] text-[#86909C]">MWh</span>
          </div>
        </div>

        {/* Dual-axis curve chart */}
        <div className="bg-white rounded-xl border border-[#E5E6EB] p-4">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-bold text-[#1D2129]">省间现货电量/电价双轴曲线（96点段）</h3>
            <div className="flex items-center gap-3 text-xs">
              <span className="flex items-center gap-1"><span className="w-3 h-1 bg-[#165DFF] rounded-full" />电量 (MWh)</span>
              <span className="flex items-center gap-1"><span className="w-3 h-1 bg-[#FF7D00] rounded-full" />电价 (元/MWh)</span>
            </div>
          </div>
          <ResponsiveContainer width="100%" height={260}>
            <LineChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
              <XAxis
                dataKey="time"
                tick={{ fontSize: 10, fill: '#86909C' }}
                interval={11}
                axisLine={{ stroke: '#E5E6EB' }}
                tickLine={false}
              />
              <YAxis
                yAxisId="power"
                tick={{ fontSize: 10, fill: '#165DFF' }}
                axisLine={{ stroke: '#165DFF' }}
                tickLine={false}
                width={50}
              />
              <YAxis
                yAxisId="price"
                orientation="right"
                tick={{ fontSize: 10, fill: '#FF7D00' }}
                axisLine={{ stroke: '#FF7D00' }}
                tickLine={false}
                width={50}
              />
              <Tooltip
                contentStyle={{
                  fontSize: 12,
                  borderRadius: 8,
                  backgroundColor: '#fff',
                  border: '1px solid #E5E6EB',
                  color: '#1D2129',
                  padding: '8px 12px',
                }}
                formatter={(value: number, name: string) => {
                  if (name === '电量') return [`${value} MWh`, name];
                  return [`${value} 元/MWh`, name];
                }}
                labelFormatter={(_: unknown, payload: Array<{ payload: { time: string } }>) => {
                  if (payload && payload[0]) {
                    return `时点: ${payload[0].payload.time}`;
                  }
                  return '';
                }}
              />
              <Legend wrapperStyle={{ fontSize: 12 }} />
              <Line
                yAxisId="power"
                type="monotone"
                dataKey="power"
                stroke="#165DFF"
                strokeWidth={1.5}
                dot={false}
                activeDot={{ r: 3, fill: '#165DFF', strokeWidth: 0 }}
                name="电量"
              />
              <Line
                yAxisId="price"
                type="monotone"
                dataKey="price"
                stroke="#FF7D00"
                strokeWidth={1.5}
                dot={false}
                activeDot={{ r: 3, fill: '#FF7D00', strokeWidth: 0 }}
                name="电价"
              />
            </LineChart>
          </ResponsiveContainer>
        </div>

        {/* 96-point table */}
        <div className="bg-white rounded-xl border border-[#E5E6EB] p-4">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-bold text-[#1D2129]">分时明细表格（96点段）</h3>
            {isEdit && (
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setShowBatchPanel(v => !v)}
                  className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap"
                >
                  <i className={`ri-${showBatchPanel ? 'close' : 'checkbox-multiple'}-line`} />
                  {showBatchPanel ? '关闭批量' : '批量修改'}
                </button>
                <span className="text-[11px] text-[#86909C]">已选 {selectedPoints.size} 个时段</span>
              </div>
            )}
          </div>

          {isEdit && showBatchPanel && (
            <div className="flex items-center gap-3 mb-4 p-3 bg-[#F7F8FA] rounded-lg">
              <span className="text-xs text-[#4E5969]">批量设置：</span>
              <input
                type="number"
                value={batchPowerValue}
                onChange={(e) => { setBatchPowerValue(e.target.value); setBatchError(''); }}
                placeholder="电量"
                className="w-24 text-xs px-2 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]"
              />
              <span className="text-[10px] text-[#86909C]">MWh</span>
              <input
                type="number"
                value={batchPriceValue}
                onChange={(e) => { setBatchPriceValue(e.target.value); setBatchError(''); }}
                placeholder="电价"
                className="w-24 text-xs px-2 py-1.5 rounded-md border border-[#E5E6EB] bg-white text-[#1D2129] outline-none focus:border-[#165DFF]"
              />
              <span className="text-[10px] text-[#86909C]">元/MWh</span>
              <button
                onClick={applyBatchEdit}
                className="flex items-center gap-1 px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-blue-600 transition-colors cursor-pointer whitespace-nowrap"
              >
                <i className="ri-check-line" />
                一键应用
              </button>
              {batchError && (
                <span className="text-[11px] text-[#F53F3F]">{batchError}</span>
              )}
            </div>
          )}

          <div className="overflow-x-auto" style={{ overflowX: 'auto' }}>
            <table className="w-full text-xs" style={{ minWidth: 'max-content' }}>
              <thead>
                <tr className="border-b border-[#E5E6EB] bg-[#F7F8FA]">
                  {isEdit && showBatchPanel && (
                    <th className="text-center py-2 px-2 font-medium text-[#86909C] w-8">
                      <input
                        type="checkbox"
                        checked={selectedPoints.size === 96}
                        onChange={selectAllPoints}
                        className="cursor-pointer"
                      />
                    </th>
                  )}
                  <th className="text-center py-2 px-2 font-medium text-[#86909C]">序号</th>
                  <th className="text-center py-2 px-2 font-medium text-[#86909C]">时点</th>
                  <th className="text-right py-2 px-3 font-medium text-[#86909C]">申报电量 (MWh)</th>
                  <th className="text-right py-2 px-3 font-medium text-[#86909C]">申报电价 (元/MWh)</th>
                  <th className="text-center py-2 px-2 font-medium text-[#86909C]">状态</th>
                </tr>
              </thead>
              <tbody>
                {pointData.map((point, idx) => {
                  const errors = pointErrors[idx];
                  return (
                    <tr
                      key={idx}
                      className={`border-b border-[#E5E6EB]/50 ${
                        isEdit && selectedPoints.has(idx) ? 'bg-[#165DFF]/5' : 'hover:bg-[#F7F8FA]/60'
                      }`}
                    >
                      {isEdit && showBatchPanel && (
                        <td className="py-1.5 px-2 text-center">
                          <input
                            type="checkbox"
                            checked={selectedPoints.has(idx)}
                            onChange={() => togglePointSelect(idx)}
                            className="cursor-pointer"
                          />
                        </td>
                      )}
                      <td className="py-1.5 px-2 text-center text-[#86909C]">{idx + 1}</td>
                      <td className="py-1.5 px-2 text-center text-[#1D2129] whitespace-nowrap">{point.time}</td>
                      <td className="py-1.5 px-3 text-right">
                        {isEdit ? (
                          <div className="flex items-center justify-end gap-1">
                            <input
                              type="number"
                              value={point.power}
                              onChange={(e) => handlePowerChange(idx, e.target.value)}
                              className={`w-20 text-xs px-2 py-1 rounded-md border text-right outline-none focus:border-[#165DFF] ${
                                errors?.power
                                  ? 'border-[#F53F3F] bg-red-50'
                                  : 'border-[#E5E6EB] bg-white'
                              } text-[#1D2129]`}
                            />
                            <span className="text-[10px] text-[#86909C]">MWh</span>
                          </div>
                        ) : (
                          <span className="text-[#1D2129] font-medium">{point.power.toLocaleString()}</span>
                        )}
                      </td>
                      <td className="py-1.5 px-3 text-right">
                        {isEdit ? (
                          <div className="flex items-center justify-end gap-1">
                            <input
                              type="number"
                              value={point.price}
                              onChange={(e) => handlePriceChange(idx, e.target.value)}
                              className={`w-20 text-xs px-2 py-1 rounded-md border text-right outline-none focus:border-[#165DFF] ${
                                errors?.price
                                  ? 'border-[#F53F3F] bg-red-50'
                                  : point.price < MIN_PRICE || point.price > MAX_PRICE
                                  ? 'border-[#FF7D00] bg-orange-50'
                                  : 'border-[#E5E6EB] bg-white'
                              } text-[#1D2129]`}
                            />
                            <span className="text-[10px] text-[#86909C]">元</span>
                          </div>
                        ) : (
                          <span className="text-[#1D2129] font-medium">{point.price.toLocaleString()}</span>
                        )}
                      </td>
                      <td className="py-1.5 px-2 text-center">
                        {errors?.power || errors?.price ? (
                          <span className="text-[10px] text-[#F53F3F]">
                            {errors.power || errors.price}
                          </span>
                        ) : (
                          <span className="text-[10px] text-[#00C48C]">
                            <i className="ri-check-line mr-0.5" />
                            正常
                          </span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Cancel modal */}
      {showCancelModal && (
        <ConfirmModal
          title="确认离开"
          message="未保存的修改将丢失，是否确认离开？"
          onConfirm={confirmCancel}
          onCancel={() => setShowCancelModal(false)}
        />
      )}

      {/* Save confirm modal */}
      {showSaveConfirm && (
        <ConfirmModal
          title="保存确认"
          message="数据校验通过，确认保存并生效？保存后将同步至市场预测模块。"
          onConfirm={confirmSave}
          onCancel={() => setShowSaveConfirm(false)}
        />
      )}

      {/* Price out of range warning */}
      {showPriceWarning && (
        <ConfirmModal
          title="电价超出市场规则上下限"
          message={`部分时段电价超出上海市场规定范围（${MIN_PRICE}-${MAX_PRICE} 元/MWh），是否确认保存？`}
          onConfirm={() => setShowSaveConfirm(true)}
          onCancel={() => setShowPriceWarning(false)}
        />
      )}

      {/* Toast */}
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </SpotTradingLayout>
  );
}