import { useState, useMemo } from 'react';
import AdminLayout from '../components/AdminLayout';
import ConfirmModal from '@/components/ConfirmModal';
import Toast from '@/components/Toast';
import { menuTreeData } from '@/mocks/adminData';
import type { MenuItem } from '@/mocks/adminData';

export default function MenuMgmtPage() {
  const [menus, setMenus] = useState<MenuItem[]>(menuTreeData);
  const [expanded, setExpanded] = useState<Record<string, boolean>>({
    '2': true, '3': true, '4': true, '5': true,
    '11': true, '14': true, '15': true,
  });
  const [search, setSearch] = useState('');
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [selectedMenu, setSelectedMenu] = useState<MenuItem | null>(null);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  const [formData, setFormData] = useState({
    name: '', path: '', icon: '', parentId: '', sort: 1, type: 'menu' as 'directory' | 'menu' | 'button',
    permission: '', enabled: true, isExternal: false,
  });
  const [formErrors, setFormErrors] = useState<Record<string, string>>();

  const allMenus = useMemo(() => {
    const flat: MenuItem[] = [];
    const walk = (items: MenuItem[]) => {
      items.forEach(item => {
        flat.push(item);
        if (item.children) walk(item.children);
      });
    };
    walk(menus);
    return flat;
  }, [menus]);

  const filteredMenus = useMemo(() => {
    if (!search) return menus;
    return allMenus.filter(m => m.name.includes(search) || m.path.includes(search));
  }, [menus, search, allMenus]);

  const showToast = (message: string, type: 'success' | 'error') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const toggleExpand = (id: string) => {
    setExpanded(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const validateForm = () => {
    const errors: Record<string, string> = {};
    if (!formData.name.trim()) errors.name = '请输入菜单名称';
    if (!formData.path.trim()) errors.path = '请输入路由地址';
    if (!formData.permission.trim()) errors.permission = '请输入权限标识';
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleAdd = () => {
    if (!validateForm()) return;
    const newMenu: MenuItem = {
      id: String(Date.now()),
      name: formData.name,
      path: formData.path,
      icon: formData.icon || 'ri-file-line',
      parentId: formData.parentId || null,
      sort: formData.sort,
      type: formData.type,
      permission: formData.permission,
      enabled: formData.enabled,
      isExternal: formData.isExternal,
    };
    if (!newMenu.parentId) {
      setMenus(prev => [...prev, newMenu]);
    } else {
      setMenus(prev => prev.map(m => {
        if (m.id === newMenu.parentId) {
          return { ...m, children: [...(m.children || []), newMenu] };
        }
        return m;
      }));
    }
    setShowAddModal(false);
    resetForm();
    showToast('菜单新增成功', 'success');
  };

  const handleEdit = () => {
    if (!selectedMenu || !validateForm()) return;
    const updateMenu = (items: MenuItem[]): MenuItem[] => {
      return items.map(item => {
        if (item.id === selectedMenu.id) {
          return { ...item, name: formData.name, path: formData.path, icon: formData.icon, sort: formData.sort, type: formData.type, permission: formData.permission, enabled: formData.enabled, isExternal: formData.isExternal };
        }
        if (item.children) {
          return { ...item, children: updateMenu(item.children) };
        }
        return item;
      });
    };
    setMenus(prev => updateMenu(prev));
    setShowEditModal(false);
    showToast('菜单编辑成功', 'success');
  };

  const handleDelete = () => {
    if (!selectedMenu) return;
    const removeMenu = (items: MenuItem[]): MenuItem[] => {
      return items.filter(item => item.id !== selectedMenu.id).map(item => {
        if (item.children) {
          return { ...item, children: removeMenu(item.children) };
        }
        return item;
      });
    };
    setMenus(prev => removeMenu(prev));
    setShowDeleteModal(false);
    showToast('菜单删除成功', 'success');
  };

  const openEdit = (menu: MenuItem) => {
    setSelectedMenu(menu);
    setFormData({
      name: menu.name, path: menu.path, icon: menu.icon, parentId: menu.parentId || '',
      sort: menu.sort, type: menu.type, permission: menu.permission,
      enabled: menu.enabled, isExternal: menu.isExternal,
    });
    setFormErrors({});
    setShowEditModal(true);
  };

  const openDelete = (menu: MenuItem) => {
    setSelectedMenu(menu);
    setShowDeleteModal(true);
  };

  const resetForm = () => {
    setFormData({ name: '', path: '', icon: '', parentId: '', sort: 1, type: 'menu', permission: '', enabled: true, isExternal: false });
    setFormErrors({});
  };

  const getTypeLabel = (type: string) => {
    switch (type) {
      case 'directory': return '目录';
      case 'menu': return '菜单';
      case 'button': return '按钮';
      default: return type;
    }
  };

  const getTypeStyle = (type: string) => {
    switch (type) {
      case 'directory': return 'bg-[#165DFF]/10 text-[#165DFF]';
      case 'menu': return 'bg-[#00C48C]/10 text-[#00C48C]';
      case 'button': return 'bg-[#FF7D00]/10 text-[#FF7D00]';
      default: return 'bg-[#F7F8FA] text-[#86909C]';
    }
  };

  const renderTree = (items: MenuItem[], depth = 0) => {
    return items.map(menu => {
      const isExpanded = expanded[menu.id];
      const hasChildren = !!menu.children && menu.children.length > 0;
      const paddingLeft = depth * 24 + 12;

      return (
        <div key={menu.id}>
          <div
            className={`flex items-center gap-2 px-3 py-2.5 border-b border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${depth > 0 ? 'bg-[#FAFBFC]' : 'bg-white'}`}
            style={{ paddingLeft }}
          >
            {hasChildren ? (
              <button onClick={() => toggleExpand(menu.id)} className="w-4 h-4 flex items-center justify-center cursor-pointer text-[#86909C]">
                <i className={`ri-arrow-right-s-line transition-transform ${isExpanded ? 'rotate-90' : ''}`} />
              </button>
            ) : (
              <span className="w-4 h-4" />
            )}
            <i className={`${menu.icon} text-sm text-[#86909C] w-4 h-4 flex items-center justify-center`} />
            <span className="text-xs text-[#1D2129] font-medium flex-1">{menu.name}</span>
            <span className="text-[10px] text-[#86909C] w-[120px]">{menu.path}</span>
            <span className={`text-[10px] px-1.5 py-0.5 rounded-full ${getTypeStyle(menu.type)}`}>{getTypeLabel(menu.type)}</span>
            <span className="text-[10px] text-[#86909C] w-[80px] text-center">{menu.permission}</span>
            <span className="text-[10px] text-[#86909C] w-[40px] text-center">{menu.sort}</span>
            <span className={`text-[10px] px-1.5 py-0.5 rounded-full w-[40px] text-center ${menu.enabled ? 'bg-[#00C48C]/10 text-[#00C48C]' : 'bg-[#86909C]/10 text-[#86909C]'}`}>
              {menu.enabled ? '启用' : '禁用'}
            </span>
            <div className="flex items-center gap-1 w-[100px] justify-end">
              <button onClick={() => openEdit(menu)} className="p-1 rounded hover:bg-[#165DFF]/10 text-[#86909C] hover:text-[#165DFF] cursor-pointer" title="编辑">
                <i className="ri-edit-line text-xs" />
              </button>
              <button onClick={() => openDelete(menu)} className="p-1 rounded hover:bg-[#F53F3F]/10 text-[#86909C] hover:text-[#F53F3F] cursor-pointer" title="删除">
                <i className="ri-delete-bin-line text-xs" />
              </button>
            </div>
          </div>
          {hasChildren && isExpanded && renderTree(menu.children!, depth + 1)}
        </div>
      );
    });
  };

  const parentOptions = allMenus.filter(m => m.type === 'directory');

  return (
    <AdminLayout>
      <div className="space-y-4 text-[#1D2129]">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">菜单管理</h1>
            <p className="text-sm text-[#86909C] mt-1">管理平台全量菜单，支持增删改、排序调整，与角色权限实时联动</p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => { resetForm(); setShowAddModal(true); }}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/80 transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-add-line" />
              新增菜单
            </button>
          </div>
        </div>

        {/* Search */}
        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex items-center gap-3">
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">菜单名称/路径</label>
              <input type="text" value={search} onChange={e => setSearch(e.target.value)} placeholder="搜索菜单" className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[200px]" />
            </div>
            <div className="ml-auto">
              <button onClick={() => setSearch('')} className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">重置</button>
            </div>
          </div>
        </div>

        {/* Menu Tree Table */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          {/* Header */}
          <div className="flex items-center gap-2 px-3 py-2.5 bg-[#F7F8FA] border-b border-[#E5E6EB] text-xs font-medium text-[#1D2129]">
            <span className="w-4" />
            <span className="w-4" />
            <span className="flex-1">菜单名称</span>
            <span className="w-[120px]">路由地址</span>
            <span className="w-[50px] text-center">类型</span>
            <span className="w-[80px] text-center">权限标识</span>
            <span className="w-[40px] text-center">排序</span>
            <span className="w-[40px] text-center">状态</span>
            <span className="w-[100px] text-right">操作</span>
          </div>
          <div className="max-h-[500px] overflow-y-auto">
            {search ? (
              filteredMenus.length > 0 ? (
                filteredMenus.map(menu => (
                  <div key={menu.id} className="flex items-center gap-2 px-3 py-2.5 border-b border-[#E5E6EB] hover:bg-[#F7F8FA]">
                    <span className="w-4" />
                    <i className={`${menu.icon} text-sm text-[#86909C] w-4 h-4 flex items-center justify-center`} />
                    <span className="text-xs text-[#1D2129] font-medium flex-1">{menu.name}</span>
                    <span className="text-[10px] text-[#86909C] w-[120px]">{menu.path}</span>
                    <span className={`text-[10px] px-1.5 py-0.5 rounded-full w-[50px] text-center ${getTypeStyle(menu.type)}`}>{getTypeLabel(menu.type)}</span>
                    <span className="text-[10px] text-[#86909C] w-[80px] text-center">{menu.permission}</span>
                    <span className="text-[10px] text-[#86909C] w-[40px] text-center">{menu.sort}</span>
                    <span className={`text-[10px] px-1.5 py-0.5 rounded-full w-[40px] text-center ${menu.enabled ? 'bg-[#00C48C]/10 text-[#00C48C]' : 'bg-[#86909C]/10 text-[#86909C]'}`}>
                      {menu.enabled ? '启用' : '禁用'}
                    </span>
                    <div className="flex items-center gap-1 w-[100px] justify-end">
                      <button onClick={() => openEdit(menu)} className="p-1 rounded hover:bg-[#165DFF]/10 text-[#86909C] hover:text-[#165DFF] cursor-pointer"><i className="ri-edit-line text-xs" /></button>
                      <button onClick={() => openDelete(menu)} className="p-1 rounded hover:bg-[#F53F3F]/10 text-[#86909C] hover:text-[#F53F3F] cursor-pointer"><i className="ri-delete-bin-line text-xs" /></button>
                    </div>
                  </div>
                ))
              ) : (
                <div className="px-3 py-8 text-center text-xs text-[#86909C]">未找到匹配菜单</div>
              )
            ) : (
              renderTree(menus)
            )}
          </div>
        </div>
      </div>

      {/* Add Modal */}
      {showAddModal && (
        <ConfirmModal title="新增菜单" message="" onConfirm={handleAdd} onCancel={() => setShowAddModal(false)}>
          <div className="grid grid-cols-2 gap-3">
            <div className="col-span-2">
              <label className="text-xs text-[#1D2129] block mb-1">菜单名称 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.name} onChange={e => setFormData(p => ({ ...p, name: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" placeholder="请输入菜单名称" />
              {formErrors.name && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.name}</p>}
            </div>
            <div className="col-span-2">
              <label className="text-xs text-[#1D2129] block mb-1">路由地址 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.path} onChange={e => setFormData(p => ({ ...p, path: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" placeholder="例如：/admin/users/list" />
              {formErrors.path && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.path}</p>}
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">图标</label>
              <input value={formData.icon} onChange={e => setFormData(p => ({ ...p, icon: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" placeholder="例如：ri-file-line" />
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">上级菜单</label>
              <select value={formData.parentId} onChange={e => setFormData(p => ({ ...p, parentId: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] bg-white">
                <option value="">无（一级菜单）</option>
                {parentOptions.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
              </select>
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">排序</label>
              <input type="number" value={formData.sort} onChange={e => setFormData(p => ({ ...p, sort: Number(e.target.value) }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" />
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">菜单类型</label>
              <select value={formData.type} onChange={e => setFormData(p => ({ ...p, type: e.target.value as 'directory' | 'menu' | 'button' }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] bg-white">
                <option value="directory">目录</option>
                <option value="menu">菜单</option>
                <option value="button">按钮</option>
              </select>
            </div>
            <div className="col-span-2">
              <label className="text-xs text-[#1D2129] block mb-1">权限标识 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.permission} onChange={e => setFormData(p => ({ ...p, permission: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" placeholder="例如：user_mgmt" />
              {formErrors.permission && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.permission}</p>}
            </div>
            <div className="col-span-2 flex items-center gap-4">
              <label className="flex items-center gap-2 text-xs text-[#1D2129] cursor-pointer">
                <input type="checkbox" checked={formData.enabled} onChange={e => setFormData(p => ({ ...p, enabled: e.target.checked }))} />
                启用
              </label>
              <label className="flex items-center gap-2 text-xs text-[#1D2129] cursor-pointer">
                <input type="checkbox" checked={formData.isExternal} onChange={e => setFormData(p => ({ ...p, isExternal: e.target.checked }))} />
                外链
              </label>
            </div>
          </div>
        </ConfirmModal>
      )}

      {/* Edit Modal */}
      {showEditModal && selectedMenu && (
        <ConfirmModal title="编辑菜单" message="" onConfirm={handleEdit} onCancel={() => setShowEditModal(false)}>
          <div className="grid grid-cols-2 gap-3">
            <div className="col-span-2">
              <label className="text-xs text-[#1D2129] block mb-1">菜单名称 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.name} onChange={e => setFormData(p => ({ ...p, name: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" />
              {formErrors.name && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.name}</p>}
            </div>
            <div className="col-span-2">
              <label className="text-xs text-[#1D2129] block mb-1">路由地址 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.path} onChange={e => setFormData(p => ({ ...p, path: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" />
              {formErrors.path && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.path}</p>}
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">图标</label>
              <input value={formData.icon} onChange={e => setFormData(p => ({ ...p, icon: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" />
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">上级菜单</label>
              <select value={formData.parentId} onChange={e => setFormData(p => ({ ...p, parentId: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] bg-white">
                <option value="">无（一级菜单）</option>
                {parentOptions.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
              </select>
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">排序</label>
              <input type="number" value={formData.sort} onChange={e => setFormData(p => ({ ...p, sort: Number(e.target.value) }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" />
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">菜单类型</label>
              <select value={formData.type} onChange={e => setFormData(p => ({ ...p, type: e.target.value as 'directory' | 'menu' | 'button' }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] bg-white">
                <option value="directory">目录</option>
                <option value="menu">菜单</option>
                <option value="button">按钮</option>
              </select>
            </div>
            <div className="col-span-2">
              <label className="text-xs text-[#1D2129] block mb-1">权限标识 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.permission} onChange={e => setFormData(p => ({ ...p, permission: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" />
              {formErrors.permission && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.permission}</p>}
            </div>
            <div className="col-span-2 flex items-center gap-4">
              <label className="flex items-center gap-2 text-xs text-[#1D2129] cursor-pointer">
                <input type="checkbox" checked={formData.enabled} onChange={e => setFormData(p => ({ ...p, enabled: e.target.checked }))} />
                启用
              </label>
              <label className="flex items-center gap-2 text-xs text-[#1D2129] cursor-pointer">
                <input type="checkbox" checked={formData.isExternal} onChange={e => setFormData(p => ({ ...p, isExternal: e.target.checked }))} />
                外链
              </label>
            </div>
          </div>
        </ConfirmModal>
      )}

      {/* Delete Modal */}
      {showDeleteModal && selectedMenu && (
        <ConfirmModal
          title="删除菜单"
          message={`确定要删除菜单 "${selectedMenu.name}" 吗？${selectedMenu.children && selectedMenu.children.length > 0 ? '该菜单下存在子菜单，删除后将一并移除。' : ''}此操作不可恢复！`}
          onConfirm={handleDelete}
          onCancel={() => setShowDeleteModal(false)}
          confirmText="确认删除"
        />
      )}

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </AdminLayout>
  );
}