import { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import ConfirmModal from '@/components/ConfirmModal';
import HelpCenterModal from '@/components/HelpCenterModal';
import { spotTradingMenu } from '@/mocks/spotTradingMenu';

interface SpotTradingLayoutProps {
  children: React.ReactNode;
}

const breadcrumbMap: Record<string, string[]> = {
  '/spot-trading': ['首页（战情室）'],
  '/spot-trading/trade-decision/position': ['交易决策依据', '持仓决策依据'],
  '/spot-trading/trade-decision/rolling': ['交易决策依据', '滚搓决策依据'],
  '/spot-trading/trade-decision/bid': ['交易决策依据', '报量决策依据'],
  '/spot-trading/consumption-bid/forecast': ['用电量预测与报量策略', '用电量预测'],
  '/spot-trading/analysis/bid': ['分析复盘', '报量收益分析'],
  '/spot-trading/analysis/position': ['分析复盘', '持仓分析'],
  '/spot-trading/analysis/daily-bill': ['分析复盘', '日账单'],
  '/spot-trading/data-mgmt/unit-info': ['数据管理', '机组信息维护'],
  '/spot-trading/data-mgmt/unit-info/detail': ['数据管理', '机组信息维护', '机组详情'],
  '/spot-trading/data-mgmt/external-power': ['数据管理', '外来电预测维护'],
  '/spot-trading/data-mgmt/interprovincial': ['数据管理', '省间现货预测维护'],
  '/spot-trading/data-mgmt/reserve': ['数据管理', '备用信息维护'],
  '/spot-trading/data-mgmt/gas-clearing': ['数据管理', '燃机出清量维护'],
};

function getBreadcrumb(path: string) {
  return breadcrumbMap[path] || ['首页（战情室）'];
}

export default function SpotTradingLayout({ children }: SpotTradingLayoutProps) {
  const navigate = useNavigate();
  const location = useLocation();
  const [showLogout, setShowLogout] = useState(false);
  const [showHelp, setShowHelp] = useState(false);
  const [expandedMenus, setExpandedMenus] = useState<Record<string, boolean>>({
    'trade-decision': true,
    'consumption-bid': true,
    'analysis': true,
    'data-mgmt': true,
  });

  const userName = localStorage.getItem('hn_user') || '管理员';
  const breadcrumbs = getBreadcrumb(location.pathname);

  useEffect(() => {
    spotTradingMenu.forEach(item => {
      if (item.children?.some(c => c.path === location.pathname)) {
        setExpandedMenus(prev => ({ ...prev, [item.id]: true }));
      }
    });
  }, [location.pathname]);

  const handleLogout = () => {
    localStorage.removeItem('hn_user');
    setShowLogout(false);
    navigate('/');
  };

  const toggleMenu = (id: string) => {
    setExpandedMenus(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const isActive = (path: string) => location.pathname === path;
  const isParentActive = (item: typeof spotTradingMenu[0]) => {
    if (isActive(item.path)) return true;
    if (item.children) {
      return item.children.some(child => isActive(child.path));
    }
    return false;
  };

  return (
    <div className="min-h-screen bg-[#F2F3F5] flex text-[#1D2129] overflow-x-hidden w-full max-w-full">
      {/* Left Sidebar */}
      <aside className="w-[220px] min-w-[220px] bg-white border-r border-[#E5E6EB] flex flex-col fixed left-0 top-0 bottom-0 z-30 overflow-y-auto overflow-x-hidden">
        {/* Logo Area */}
        <div className="h-14 flex items-center px-4 border-b border-[#E5E6EB] gap-2.5">
          <div className="w-8 h-8 bg-[#165DFF] rounded-lg flex items-center justify-center">
            <i className="ri-flashlight-line text-lg text-white" />
          </div>
          <div className="flex flex-col">
            <span className="text-xs font-bold text-[#1D2129] leading-tight">上海华能</span>
            <span className="text-[10px] text-[#86909C] leading-tight">电力交易平台</span>
          </div>
        </div>

        {/* Menu */}
        <nav className="flex-1 py-3">
          {spotTradingMenu.map(item => {
            const hasChildren = !!item.children;
            const active = isParentActive(item);
            const expanded = expandedMenus[item.id];

            return (
              <div key={item.id}>
                <button
                  onClick={() => {
                    if (hasChildren) {
                      toggleMenu(item.id);
                    } else {
                      navigate(item.path);
                    }
                  }}
                  className={`w-full flex items-center justify-between px-3 py-2.5 text-[13px] transition-colors cursor-pointer whitespace-nowrap rounded-md mx-2 ${
                    active
                      ? 'bg-[#165DFF]/10 text-[#165DFF] font-medium'
                      : 'text-[#4E5969] hover:text-[#1D2129] hover:bg-[#F7F8FA]'
                  }`}
                >
                  <div className="flex items-center gap-2.5">
                    <i className={`${item.icon} w-4 h-4 flex items-center justify-center text-base`} />
                    <span className="truncate">{item.name}</span>
                  </div>
                  {hasChildren && (
                    <i
                      className={`ri-arrow-down-s-line transition-transform text-xs ${expanded ? 'rotate-180' : ''}`}
                    />
                  )}
                </button>

                {hasChildren && expanded && (
                  <div className="mt-0.5">
                    {item.children.map(child => (
                      <button
                        key={child.id}
                        onClick={() => navigate(child.path)}
                        className={`w-full flex items-center gap-2 pl-10 pr-3 py-2 text-[12px] transition-colors cursor-pointer whitespace-nowrap rounded-md mx-2 ${
                          isActive(child.path)
                            ? 'bg-[#165DFF]/10 text-[#165DFF] font-medium'
                            : 'text-[#86909C] hover:text-[#4E5969] hover:bg-[#F7F8FA]'
                        }`}
                      >
                        <i className={`${child.icon} w-3.5 h-3.5 flex items-center justify-center text-sm`} />
                        <span className="truncate">{child.name}</span>
                      </button>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </nav>

        {/* User Info */}
        <div className="p-3 border-t border-[#E5E6EB]">
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 bg-[#165DFF]/10 rounded-full flex items-center justify-center">
              <i className="ri-user-line text-xs text-[#165DFF]" />
            </div>
            <div className="flex flex-col">
              <span className="text-xs font-medium text-[#1D2129]">{userName}</span>
              <span className="text-[10px] text-[#86909C]">交易专员</span>
            </div>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <div className="ml-[220px] flex flex-col min-h-screen overflow-x-hidden" style={{ width: 'calc(100vw - 220px)', maxWidth: 'calc(100vw - 220px)' }}>
        {/* Top Header */}
        <header className="h-14 bg-white border-b border-[#E5E6EB] flex items-center justify-between px-5 sticky top-0 z-20">
          {/* Left: Breadcrumb */}
          <div className="flex items-center gap-2">
            <div className="flex items-center gap-1.5 text-xs text-[#86909C]">
              <i className="ri-home-4-line" />
              {breadcrumbs.map((crumb, idx) => (
                <span key={idx} className="flex items-center gap-1.5">
                  {idx > 0 && <i className="ri-arrow-right-s-line text-[10px]" />}
                  <span className={idx === breadcrumbs.length - 1 ? 'text-[#1D2129] font-medium' : ''}>{crumb}</span>
                </span>
              ))}
            </div>
          </div>

          {/* Right: Actions */}
          <div className="flex items-center gap-1">
            <button
              onClick={() => navigate('/dashboard')}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs text-[#4E5969] hover:text-[#165DFF] hover:bg-[#165DFF]/5 rounded-md transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-apps-line" />
              返回选择系统
            </button>
            <button
              onClick={() => setShowHelp(true)}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs text-[#4E5969] hover:text-[#165DFF] hover:bg-[#165DFF]/5 rounded-md transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-questionnaire-line" />
              帮助中心
            </button>
            <button className="flex items-center gap-1.5 px-3 py-1.5 text-xs text-[#4E5969] hover:text-[#165DFF] hover:bg-[#165DFF]/5 rounded-md transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-notification-3-line" />
              消息中心
            </button>
            <button
              onClick={() => setShowLogout(true)}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs text-[#4E5969] hover:text-[#165DFF] hover:bg-[#165DFF]/5 rounded-md transition-colors cursor-pointer whitespace-nowrap"
            >
              <i className="ri-logout-box-r-line" />
              退出登录
            </button>
          </div>
        </header>

        {/* Page Content */}
        <main className="flex-1 p-5 bg-[#F2F3F5] overflow-x-hidden w-full max-w-full">
          {children}
        </main>

        {/* Footer */}
        <footer className="py-2.5 px-5 bg-white border-t border-[#E5E6EB]">
          <p className="text-[11px] text-[#86909C] text-center">上海华能电力交易智能决策平台</p>
        </footer>
      </div>

      {/* Help Center Modal */}
      {showHelp && (
        <HelpCenterModal
          isOpen={showHelp}
          onClose={() => setShowHelp(false)}
          currentPath={location.pathname}
        />
      )}

      {/* Logout Confirm Modal */}
      {showLogout && (
        <ConfirmModal
          title="确认退出"
          message="确定要退出登录吗？"
          onConfirm={handleLogout}
          onCancel={() => setShowLogout(false)}
        />
      )}
    </div>
  );
}