import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import AdminLayout from '../components/AdminLayout';
import ConfirmModal from '@/components/ConfirmModal';
import Toast from '@/components/Toast';
import { rolesData, permissionTree } from '@/mocks/adminData';
import type { Role, PermissionNode } from '@/mocks/adminData';

export default function RoleMgmtPage() {
  const navigate = useNavigate();
  const [roles, setRoles] = useState<Role[]>(rolesData);
  const [search, setSearch] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  // Modals
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showPermissionModal, setShowPermissionModal] = useState(false);
  const [selectedRole, setSelectedRole] = useState<Role | null>(null);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);

  const [formData, setFormData] = useState({ name: '', code: '', description: '' });
  const [formErrors, setFormErrors] = useState<Record<string, string>>();
  const [selectedPermissions, setSelectedPermissions] = useState<Set<string>>(new Set());

  const filteredRoles = useMemo(() => {
    if (!search) return roles;
    return roles.filter(r => r.name.includes(search) || r.code.includes(search));
  }, [roles, search]);

  const totalPages = Math.ceil(filteredRoles.length / pageSize);
  const pagedRoles = filteredRoles.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const showToast = (message: string, type: 'success' | 'error') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const validateForm = () => {
    const errors: Record<string, string> = {};
    if (!formData.name.trim()) errors.name = '请输入角色名称';
    if (!formData.code.trim()) errors.code = '请输入角色标识';
    if (roles.some(r => r.code === formData.code && r.id !== (selectedRole?.id || ''))) errors.code = '角色标识已存在';
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleAdd = () => {
    if (!validateForm()) return;
    const newRole: Role = {
      id: String(Date.now()),
      name: formData.name,
      code: formData.code,
      description: formData.description,
      userCount: 0,
      status: 'enabled',
      createdAt: '2026-05-08',
      isPreset: false,
      permissions: [],
    };
    setRoles(prev => [...prev, newRole]);
    setShowAddModal(false);
    resetForm();
    showToast('新增角色成功', 'success');
  };

  const handleEdit = () => {
    if (!selectedRole || !validateForm()) return;
    setRoles(prev => prev.map(r => r.id === selectedRole.id ? { ...r, name: formData.name, code: formData.code, description: formData.description } : r));
    setShowEditModal(false);
    showToast('编辑角色成功', 'success');
  };

  const handleDelete = () => {
    if (!selectedRole) return;
    setRoles(prev => prev.filter(r => r.id !== selectedRole.id));
    setShowDeleteModal(false);
    showToast('角色删除成功', 'success');
  };

  const handlePermissionSave = () => {
    if (!selectedRole) return;
    setRoles(prev => prev.map(r => r.id === selectedRole.id ? { ...r, permissions: Array.from(selectedPermissions) } : r));
    setShowPermissionModal(false);
    showToast('权限配置已生效', 'success');
  };

  const openEdit = (role: Role) => {
    setSelectedRole(role);
    setFormData({ name: role.name, code: role.code, description: role.description });
    setFormErrors({});
    setShowEditModal(true);
  };

  const openDelete = (role: Role) => {
    setSelectedRole(role);
    setShowDeleteModal(true);
  };

  const openPermission = (role: Role) => {
    setSelectedRole(role);
    setSelectedPermissions(new Set(role.permissions));
    setShowPermissionModal(true);
  };

  const resetForm = () => {
    setFormData({ name: '', code: '', description: '' });
    setFormErrors({});
  };

  const togglePermission = (id: string) => {
    setSelectedPermissions(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const toggleAll = () => {
    const allIds = new Set<string>();
    const collect = (nodes: PermissionNode[]) => {
      nodes.forEach(n => {
        allIds.add(n.id);
        if (n.children) collect(n.children);
      });
    };
    collect(permissionTree);
    if (selectedPermissions.size === allIds.size) {
      setSelectedPermissions(new Set());
    } else {
      setSelectedPermissions(allIds);
    }
  };

  const isAllSelected = () => {
    let count = 0;
    const countNodes = (nodes: PermissionNode[]) => {
      nodes.forEach(n => {
        count++;
        if (n.children) countNodes(n.children);
      });
    };
    countNodes(permissionTree);
    return selectedPermissions.size === count && count > 0;
  };

  const getStatusStyle = (status: string) => {
    return status === 'enabled'
      ? 'bg-[#00C48C]/10 text-[#00C48C]'
      : 'bg-[#86909C]/10 text-[#86909C]';
  };

  const renderPermissionTree = (nodes: PermissionNode[], depth = 0) => {
    return nodes.map(node => (
      <div key={node.id} style={{ paddingLeft: depth * 20 }}>
        <label className="flex items-center gap-2 py-1.5 cursor-pointer text-xs text-[#1D2129]">
          <input
            type="checkbox"
            checked={selectedPermissions.has(node.id)}
            onChange={() => togglePermission(node.id)}
            className="w-3.5 h-3.5 rounded border border-[#E5E6EB] accent-[#165DFF]"
          />
          <span>{node.name}</span>
        </label>
        {node.children && renderPermissionTree(node.children, depth + 1)}
      </div>
    ));
  };

  return (
    <AdminLayout>
      <div className="space-y-4 text-[#1D2129]">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">角色管理</h1>
            <p className="text-sm text-[#86909C] mt-1">管理平台角色，配置菜单、按钮、数据权限</p>
          </div>
          <button
            onClick={() => { resetForm(); setShowAddModal(true); }}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/80 transition-colors cursor-pointer whitespace-nowrap"
          >
            <i className="ri-add-line" />
            新增角色
          </button>
        </div>

        {/* Search */}
        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex items-center gap-3">
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">角色名称/标识</label>
              <input type="text" value={search} onChange={e => setSearch(e.target.value)} placeholder="搜索角色" className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[200px]" />
            </div>
            <div className="ml-auto">
              <button onClick={() => setSearch('')} className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">重置</button>
            </div>
          </div>
        </div>

        {/* Table */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#F7F8FA] sticky top-0">
                <tr>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">序号</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">角色名称</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">角色标识</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">关联用户数</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">角色状态</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">创建时间</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">操作</th>
                </tr>
              </thead>
              <tbody>
                {pagedRoles.map((role, idx) => (
                  <tr key={role.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : 'bg-white'}`}>
                    <td className="px-3 py-3 text-[#4E5969]">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="px-3 py-3 text-[#1D2129] font-medium">
                      {role.name}
                      {role.isPreset && <span className="ml-1 text-[10px] px-1.5 py-0.5 rounded-full bg-[#165DFF]/10 text-[#165DFF]">预设</span>}
                    </td>
                    <td className="px-3 py-3 text-[#86909C] font-mono">{role.code}</td>
                    <td className="px-3 py-3 text-[#4E5969]">{role.userCount} 人</td>
                    <td className="px-3 py-3">
                      <span className={`text-[10px] px-2 py-0.5 rounded-full ${getStatusStyle(role.status)}`}>
                        {role.status === 'enabled' ? '启用' : '禁用'}
                      </span>
                    </td>
                    <td className="px-3 py-3 text-[#86909C]">{role.createdAt}</td>
                    <td className="px-3 py-3">
                      <div className="flex items-center gap-1">
                        <button onClick={() => openEdit(role)} className="p-1 rounded hover:bg-[#165DFF]/10 text-[#86909C] hover:text-[#165DFF] cursor-pointer" title="编辑">
                          <i className="ri-edit-line text-xs" />
                        </button>
                        <button onClick={() => openPermission(role)} className="p-1 rounded hover:bg-[#00C48C]/10 text-[#86909C] hover:text-[#00C48C] cursor-pointer" title="权限配置">
                          <i className="ri-shield-check-line text-xs" />
                        </button>
                        {!role.isPreset && (
                          <button onClick={() => openDelete(role)} className="p-1 rounded hover:bg-[#F53F3F]/10 text-[#86909C] hover:text-[#F53F3F] cursor-pointer" title="删除">
                            <i className="ri-delete-bin-line text-xs" />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
                {pagedRoles.length === 0 && <tr><td colSpan={7} className="px-3 py-8 text-center text-[#86909C]">暂无数据</td></tr>}
              </tbody>
            </table>
          </div>
          <div className="flex items-center justify-between px-3 py-3 border-t border-[#E5E6EB]">
            <span className="text-xs text-[#86909C]">共 {filteredRoles.length} 条，每页 {pageSize} 条</span>
            <div className="flex items-center gap-1">
              <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="px-2 py-1 rounded text-xs border border-[#E5E6EB] hover:bg-[#F7F8FA] disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer">上一页</button>
              {Array.from({ length: Math.min(5, totalPages) }, (_, i) => (
                <button key={i + 1} onClick={() => setCurrentPage(i + 1)} className={`w-7 h-7 rounded text-xs cursor-pointer ${currentPage === i + 1 ? 'bg-[#165DFF] text-white' : 'border border-[#E5E6EB] hover:bg-[#F7F8FA]'}`}>{i + 1}</button>
              ))}
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages || totalPages === 0} className="px-2 py-1 rounded text-xs border border-[#E5E6EB] hover:bg-[#F7F8FA] disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer">下一页</button>
            </div>
          </div>
        </div>
      </div>

      {/* Add Modal */}
      {showAddModal && (
        <ConfirmModal title="新增角色" message="" onConfirm={handleAdd} onCancel={() => setShowAddModal(false)}>
          <div className="space-y-3">
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">角色名称 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.name} onChange={e => setFormData(p => ({ ...p, name: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" placeholder="请输入角色名称" />
              {formErrors.name && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.name}</p>}
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">角色标识 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.code} onChange={e => setFormData(p => ({ ...p, code: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" placeholder="例如：trade_manager" />
              {formErrors.code && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.code}</p>}
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">角色描述</label>
              <textarea value={formData.description} onChange={e => setFormData(p => ({ ...p, description: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] resize-none h-16" placeholder="请输入角色描述" />
            </div>
          </div>
        </ConfirmModal>
      )}

      {/* Edit Modal */}
      {showEditModal && selectedRole && (
        <ConfirmModal title="编辑角色" message="" onConfirm={handleEdit} onCancel={() => setShowEditModal(false)}>
          <div className="space-y-3">
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">角色名称 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.name} onChange={e => setFormData(p => ({ ...p, name: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF]" />
              {formErrors.name && <p className="text-[10px] text-[#F53F3F] mt-1">{formErrors.name}</p>}
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">角色标识 <span className="text-[#F53F3F]">*</span></label>
              <input value={formData.code} disabled className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs bg-[#F7F8FA] text-[#86909C]" />
            </div>
            <div>
              <label className="text-xs text-[#1D2129] block mb-1">角色描述</label>
              <textarea value={formData.description} onChange={e => setFormData(p => ({ ...p, description: e.target.value }))} className="w-full px-3 py-2 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] resize-none h-16" />
            </div>
          </div>
        </ConfirmModal>
      )}

      {/* Delete Modal */}
      {showDeleteModal && selectedRole && (
        <ConfirmModal
          title="删除角色"
          message={`确定要删除角色 "${selectedRole.name}" 吗？该角色下关联 ${selectedRole.userCount} 个用户，删除后这些用户将失去该角色权限。此操作不可恢复！`}
          onConfirm={handleDelete}
          onCancel={() => setShowDeleteModal(false)}
          confirmText="确认删除"
        />
      )}

      {/* Permission Modal */}
      {showPermissionModal && selectedRole && (
        <ConfirmModal
          title={`权限配置 - ${selectedRole.name}`}
          message=""
          onConfirm={handlePermissionSave}
          onCancel={() => setShowPermissionModal(false)}
          confirmText="保存配置"
        >
          <div className="max-h-[400px] overflow-y-auto">
            <div className="flex items-center gap-2 mb-3 pb-2 border-b border-[#E5E6EB]">
              <button onClick={toggleAll} className="text-xs text-[#165DFF] hover:underline cursor-pointer whitespace-nowrap">
                {isAllSelected() ? '取消全选' : '全选'}
              </button>
              <button
                onClick={() => {
                  const next = new Set<string>();
                  setSelectedPermissions(next);
                }}
                className="text-xs text-[#86909C] hover:text-[#F53F3F] cursor-pointer whitespace-nowrap"
              >
                反选
              </button>
            </div>
            {renderPermissionTree(permissionTree)}
          </div>
        </ConfirmModal>
      )}

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </AdminLayout>
  );
}