import { useState } from 'react';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip,
  ResponsiveContainer, Legend,
} from 'recharts';
import EnergySalesLayout from '../../components/EnergySalesLayout';
import { savingOverviewList, type SavingOverview } from '@/mocks/energySalesData';

export default function SavingOverviewPage() {
  const [searchName, setSearchName] = useState('');
  const [filterType, setFilterType] = useState<'all' | 'hasPpa' | 'noPpa'>('all');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  const filtered = savingOverviewList.filter(s => {
    const nameMatch = !searchName || s.userName.includes(searchName);
    const typeMatch = filterType === 'all' || (filterType === 'hasPpa' ? s.hasPpa : !s.hasPpa);
    return nameMatch && typeMatch;
  });

  const totalPages = Math.ceil(filtered.length / pageSize);
  const paged = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  // Chart data
  const chartData = filtered.slice(0, 10).map(s => ({
    name: s.userName.slice(0, 8) + '...',
    thermalSaving: s.thermalSaving,
    greenSaving: s.greenSaving,
    totalSaving: s.totalSaving,
  }));

  const totalSaving = filtered.reduce((sum, s) => sum + s.totalSaving, 0);
  const totalThermalSaving = filtered.reduce((sum, s) => sum + s.thermalSaving, 0);
  const totalGreenSaving = filtered.reduce((sum, s) => sum + s.greenSaving, 0);

  return (
    <EnergySalesLayout>
      <div className="space-y-5 text-[#1D2129]">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">电费节省概况（不分时段）</h1>
            <p className="text-sm text-[#86909C] mt-1">全场景电费节省自动计算与展示</p>
          </div>
          <button className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
            <i className="ri-download-2-line" />
            导出Excel
          </button>
        </div>

        {/* Summary Cards */}
        <div className="grid grid-cols-3 gap-4">
          <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
            <p className="text-xs text-[#86909C]">火电节约电费合计</p>
            <p className="text-xl font-bold text-[#FF7D00] mt-1">{(totalThermalSaving / 10000).toFixed(2)} <span className="text-xs font-normal text-[#86909C]">万元</span></p>
          </div>
          <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
            <p className="text-xs text-[#86909C]">绿电节约电费合计</p>
            <p className="text-xl font-bold text-[#00C48C] mt-1">{(totalGreenSaving / 10000).toFixed(2)} <span className="text-xs font-normal text-[#86909C]">万元</span></p>
          </div>
          <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
            <p className="text-xs text-[#86909C]">总节约电费合计</p>
            <p className="text-xl font-bold text-[#165DFF] mt-1">{(totalSaving / 10000).toFixed(2)} <span className="text-xs font-normal text-[#86909C]">万元</span></p>
          </div>
        </div>

        {/* Chart */}
        <div className="bg-white rounded-lg p-5 border border-[#E5E6EB]">
          <h3 className="text-sm font-bold text-[#1D2129] mb-4">用户电费节省对比</h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
              <XAxis dataKey="name" tick={{ fontSize: 10, fill: '#86909C' }} />
              <YAxis tick={{ fontSize: 10, fill: '#86909C' }} />
              <Tooltip contentStyle={{ fontSize: 12, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB' }} />
              <Legend wrapperStyle={{ fontSize: 12 }} />
              <Bar dataKey="thermalSaving" fill="#FF7D00" radius={[4, 4, 0, 0]} name="火电节约" />
              <Bar dataKey="greenSaving" fill="#00C48C" radius={[4, 4, 0, 0]} name="绿电节约" />
            </BarChart>
          </ResponsiveContainer>
        </div>

        {/* Filter */}
        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">用户名称</label>
              <input type="text" value={searchName} onChange={e => setSearchName(e.target.value)} placeholder="请输入用户名称" className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[180px]" />
            </div>
            <div>
              <label className="text-xs text-[#86909C] mb-1 block">PPA类型</label>
              <select value={filterType} onChange={e => setFilterType(e.target.value as 'all' | 'hasPpa' | 'noPpa')} className="px-3 py-2 text-xs border border-[#E5E6EB] rounded-md focus:outline-none focus:border-[#165DFF] w-[120px]">
                <option value="all">全部</option>
                <option value="hasPpa">有PPA</option>
                <option value="noPpa">无PPA</option>
              </select>
            </div>
            <button className="flex items-center gap-1.5 px-4 py-2 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/90 transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-search-line" />
              查询
            </button>
            <button onClick={() => { setSearchName(''); setFilterType('all'); }} className="flex items-center gap-1.5 px-3 py-2 rounded-md border border-[#E5E6EB] text-[#4E5969] text-xs hover:border-[#165DFF] hover:text-[#165DFF] transition-colors cursor-pointer whitespace-nowrap">
              <i className="ri-refresh-line" />
              重置
            </button>
          </div>
        </div>

        {/* Table */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#F7F8FA]">
                <tr>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-0 bg-[#F7F8FA] z-10">序号</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969] sticky left-[48px] bg-[#F7F8FA] z-10">用户名称</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">月份</th>
                  <th className="px-4 py-3 text-left font-medium text-[#4E5969]">用户类型</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">火电度电差</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">火电节约电费</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">绿电度电差</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">绿电节约电费</th>
                  <th className="px-4 py-3 text-right font-medium text-[#4E5969]">总节约电费</th>
                </tr>
              </thead>
              <tbody>
                {paged.map((s, idx) => (
                  <tr key={s.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : ''}`}>
                    <td className="px-4 py-3 sticky left-0 bg-white z-10">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="px-4 py-3 sticky left-[48px] bg-white z-10 font-medium">{s.userName}</td>
                    <td className="px-4 py-3 text-[#4E5969]">{s.month}</td>
                    <td className="px-4 py-3">
                      <span className="px-2 py-0.5 bg-[#165DFF]/10 text-[#165DFF] rounded-full text-[10px]">{s.userType}</span>
                    </td>
                    <td className="px-4 py-3 text-right text-[#00C48C]">{s.thermalPowerDiff.toFixed(3)}</td>
                    <td className="px-4 py-3 text-right font-medium text-[#1D2129]">{(s.thermalSaving / 10000).toFixed(2)}</td>
                    <td className="px-4 py-3 text-right text-[#00C48C]">{s.greenPowerDiff.toFixed(3)}</td>
                    <td className="px-4 py-3 text-right font-medium text-[#00C48C]">{(s.greenSaving / 10000).toFixed(2)}</td>
                    <td className="px-4 py-3 text-right font-bold text-[#165DFF]">{(s.totalSaving / 10000).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="flex items-center justify-between px-4 py-3 border-t border-[#E5E6EB]">
            <span className="text-xs text-[#86909C]">共 {filtered.length} 条，每页 {pageSize} 条</span>
            <div className="flex items-center gap-1">
              <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"><i className="ri-arrow-left-s-line" /></button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
                <button key={p} onClick={() => setCurrentPage(p)} className={`px-3 py-1 text-xs rounded cursor-pointer ${p === currentPage ? 'bg-[#165DFF] text-white' : 'border border-[#E5E6EB] hover:border-[#165DFF]'}`}>{p}</button>
              ))}
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="px-2 py-1 text-xs border border-[#E5E6EB] rounded hover:border-[#165DFF] disabled:opacity-40 cursor-pointer"><i className="ri-arrow-right-s-line" /></button>
            </div>
          </div>
        </div>
      </div>
    </EnergySalesLayout>
  );
}