import { useState, useMemo } from 'react';
import AdminLayout from '../../components/AdminLayout';
import { loginLogs } from '@/mocks/adminData';

export default function LoginLogPage() {
  const [searchAccount, setSearchAccount] = useState('');
  const [filterStatus, setFilterStatus] = useState('全部');
  const [dateRange, setDateRange] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  const filteredLogs = useMemo(() => {
    let result = loginLogs;
    if (searchAccount) result = result.filter(l => l.account.includes(searchAccount) || l.name.includes(searchAccount));
    if (filterStatus !== '全部') result = result.filter(l => (l.status === 'success' ? '成功' : '失败') === filterStatus);
    return result;
  }, [searchAccount, filterStatus]);

  const totalPages = Math.ceil(filteredLogs.length / pageSize);
  const pagedLogs = filteredLogs.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const exportLogs = () => {
    const csv = [
      ['序号', '用户账号', '用户姓名', '登录时间', '登出时间', '登录IP', '登录设备', '登录状态', '失败原因'],
      ...filteredLogs.map((l, i) => [i + 1, l.account, l.name, l.loginTime, l.logoutTime || '-', l.ip, l.device, l.status === 'success' ? '成功' : '失败', l.failReason || '-']),
    ].map(row => row.join(',')).join('\n');
    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `登录日志_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  };

  return (
    <AdminLayout>
      <div className="space-y-4 text-[#1D2129]">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">登录日志</h1>
            <p className="text-sm text-[#86909C] mt-1">所有用户登录/登出记录审计</p>
          </div>
          <button onClick={exportLogs} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">
            <i className="ri-download-line" />
            导出
          </button>
        </div>

        {/* Filter */}
        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex flex-wrap items-end gap-3">
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">用户账号/姓名</label>
              <input type="text" value={searchAccount} onChange={e => setSearchAccount(e.target.value)} placeholder="请输入" className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[140px]" />
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">登录状态</label>
              <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[100px] bg-white">
                <option value="全部">全部</option>
                <option value="成功">成功</option>
                <option value="失败">失败</option>
              </select>
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">登录时间</label>
              <input type="date" value={dateRange} onChange={e => setDateRange(e.target.value)} className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[140px]" />
            </div>
            <div className="flex gap-2 ml-auto">
              <button onClick={() => { setSearchAccount(''); setFilterStatus('全部'); setDateRange(''); }} className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">重置</button>
              <button onClick={() => setCurrentPage(1)} className="px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/80 transition-colors cursor-pointer whitespace-nowrap">查询</button>
            </div>
          </div>
        </div>

        {/* Table */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#F7F8FA] sticky top-0">
                <tr>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">序号</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">用户账号</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">用户姓名</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">登录时间</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">登出时间</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">登录IP</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">登录设备</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">状态</th>
                </tr>
              </thead>
              <tbody>
                {pagedLogs.map((log, idx) => (
                  <tr key={log.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : 'bg-white'}`}>
                    <td className="px-3 py-3 text-[#4E5969]">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="px-3 py-3 text-[#1D2129] font-medium">{log.account}</td>
                    <td className="px-3 py-3 text-[#4E5969]">{log.name}</td>
                    <td className="px-3 py-3 text-[#86909C]">{log.loginTime}</td>
                    <td className="px-3 py-3 text-[#86909C]">{log.logoutTime || '-'}</td>
                    <td className="px-3 py-3 text-[#86909C]">{log.ip}</td>
                    <td className="px-3 py-3 text-[#4E5969]">{log.device}</td>
                    <td className="px-3 py-3">
                      <span className={`text-[10px] px-2 py-0.5 rounded-full ${log.status === 'success' ? 'bg-[#00C48C]/10 text-[#00C48C]' : 'bg-[#F53F3F]/10 text-[#F53F3F]'}`}>
                        {log.status === 'success' ? '成功' : '失败'}
                      </span>
                      {log.failReason && <p className="text-[10px] text-[#F53F3F] mt-0.5">{log.failReason}</p>}
                    </td>
                  </tr>
                ))}
                {pagedLogs.length === 0 && <tr><td colSpan={8} className="px-3 py-8 text-center text-[#86909C]">暂无数据</td></tr>}
              </tbody>
            </table>
          </div>
          <div className="flex items-center justify-between px-3 py-3 border-t border-[#E5E6EB]">
            <span className="text-xs text-[#86909C]">共 {filteredLogs.length} 条，每页 {pageSize} 条</span>
            <div className="flex items-center gap-1">
              <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="px-2 py-1 rounded text-xs border border-[#E5E6EB] hover:bg-[#F7F8FA] disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer">上一页</button>
              {Array.from({ length: Math.min(5, totalPages) }, (_, i) => (
                <button key={i + 1} onClick={() => setCurrentPage(i + 1)} className={`w-7 h-7 rounded text-xs cursor-pointer ${currentPage === i + 1 ? 'bg-[#165DFF] text-white' : 'border border-[#E5E6EB] hover:bg-[#F7F8FA]'}`}>{i + 1}</button>
              ))}
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages || totalPages === 0} className="px-2 py-1 rounded text-xs border border-[#E5E6EB] hover:bg-[#F7F8FA] disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer">下一页</button>
            </div>
          </div>
        </div>
      </div>
    </AdminLayout>
  );
}