import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { systems } from '@/mocks/systems';
import ConfirmModal from '@/components/ConfirmModal';

export default function DashboardPage() {
  const navigate = useNavigate();
  const [showLogout, setShowLogout] = useState(false);

  const userName = localStorage.getItem('hn_user') || 'demo_pm';

  const handleLogout = () => {
    localStorage.removeItem('hn_user');
    setShowLogout(false);
    navigate('/');
  };

  const handleCardClick = (path: string) => {
    navigate(path);
  };

  const firstRow = systems.slice(0, 3);
  const secondRow = systems.slice(3);

  const renderCard = (system: typeof systems[0]) => (
    <button
      key={system.id}
      onClick={() => handleCardClick(system.path)}
      className="group bg-white rounded-card p-0 w-[320px] cursor-pointer transition-all duration-300 hover:-translate-y-2 hover:shadow-xl active:scale-[0.97] text-left overflow-hidden border border-[#E5E6EB]"
    >
      <div className="w-full h-[160px] overflow-hidden">
        <img
          src={system.image}
          alt={system.nameCn}
          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
        />
      </div>
      <div className="py-8 px-6 text-center">
        <h3 className="text-xl font-bold text-[#1D2129] mb-1">{system.nameCn}</h3>
        <p className="text-sm text-[#86909C]">{system.nameEn}</p>
      </div>
    </button>
  );

  return (
    <div className="min-h-screen bg-[#F2F3F5] flex flex-col">
      {/* Top Navigation */}
      <header className="fixed top-0 left-0 right-0 z-40 h-16 bg-white/90 backdrop-blur-sm border-b border-[#E5E6EB] flex items-center justify-between px-4 md:px-10">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-[#165DFF]/15 rounded-lg flex items-center justify-center">
            <i className="ri-flashlight-line text-lg text-[#165DFF]" />
          </div>
          <span className="text-sm font-bold text-[#1D2129]">上海华能电力交易平台</span>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2 text-sm text-[#86909C]">
            <i className="ri-user-line" />
            <span>{userName}</span>
          </div>
          <button
            onClick={() => setShowLogout(true)}
            className="text-sm text-[#F53F3F] hover:text-[#F53F3F]/80 transition-colors cursor-pointer whitespace-nowrap"
          >
            退出登录
          </button>
        </div>
      </header>

      {/* Cards Area - Centered */}
      <main className="flex-1 flex flex-col items-center justify-center pt-20 pb-16 px-4">
        <div className="flex flex-col items-center gap-6">
          {/* First Row - 3 cards */}
          <div className="flex flex-wrap justify-center gap-6">
            {firstRow.map(renderCard)}
          </div>
          {/* Second Row - 2 cards */}
          <div className="flex flex-wrap justify-center gap-6">
            {secondRow.map(renderCard)}
          </div>
        </div>
      </main>

      {/* Footer */}
      <footer className="fixed bottom-0 left-0 right-0 py-3 text-center bg-transparent">
        <p className="text-xs text-[#86909C]">&copy; 上海华能 版权所有</p>
      </footer>

      {/* Logout Confirm Modal */}
      {showLogout && (
        <ConfirmModal
          title="确认退出"
          message="确定要退出登录吗？"
          onConfirm={handleLogout}
          onCancel={() => setShowLogout(false)}
        />
      )}
    </div>
  );
}
