export function getEnergySalesBreadcrumb(path: string): string[] {
  const bc = ['首页'];

  const flatMap: Record<string, string> = {
    '/energy-sales/user-info': '用户信息管理',
    '/energy-sales/contract-info': '合同信息管理',
    '/energy-sales/user-portrait': '用户画像管理',
    '/energy-sales/monthly-report': '月度用能分析报告',
    '/energy-sales/trade-demand': '零售用户月度交易需求管理',
    '/energy-sales/bill-mgmt': '电费账单管理',
    '/energy-sales/settlement/base-info': '偏差基础信息管理',
    '/energy-sales/settlement/cost-spread': '月度成本价差管理',
    '/energy-sales/settlement/upload-mgmt': '结算单上传管理',
    '/energy-sales/settlement/saving-overview': '电费节省概况（不分时段）',
    '/energy-sales/settlement/saving-time': '电费节省概况（分时段）',
    '/energy-sales/settlement/deviation-board': '偏差考核分析看板',
    '/energy-sales/green-power/channel': '绿电通道费管理',
    '/energy-sales/green-power/alloc': '绿电分配管理',
    '/energy-sales/green-power/contract': '绿电合同管理',
    '/energy-sales/daily-trade': '日交易数据管理',
  };

  if (flatMap[path] && path !== '/energy-sales') {
    bc.push(flatMap[path]);
  }

  return bc;
}