export function getHelpItemById(id: string): HelpItem | undefined {
  for (const section of helpCenterSections) {
    for (const item of section.items) {
      if (item.id === id) return item;
    }
  }
  return undefined;
}

export function getPageHelpId(pathname: string): string {
  const map: Record<string, string> = {
    '/spot-trading': 'dashboard-core-indicators',
    '/spot-trading/trade-decision/position': 'position-decision',
    '/spot-trading/trade-decision/rolling': 'rolling-decision',
    '/spot-trading/trade-decision/bid': 'bid-decision',
    '/spot-trading/consumption-bid/forecast': 'consumption-forecast',
    '/spot-trading/analysis/bid': 'bid-analysis',
    '/spot-trading/analysis/position': 'position-analysis',
    '/spot-trading/analysis/daily-bill': 'daily-bill',
    '/spot-trading/data-mgmt/unit-info': 'unit-info',
    '/spot-trading/data-mgmt/external-power': 'external-power',
    '/spot-trading/data-mgmt/interprovincial': 'interprovincial',
    '/spot-trading/data-mgmt/reserve': 'reserve',
    '/spot-trading/data-mgmt/gas-clearing': 'gas-clearing',
  };
  return map[pathname] || 'dashboard-core-indicators';
}
