import { useState, useMemo } from 'react';
import AdminLayout from '../../components/AdminLayout';
import { auditLogs } from '@/mocks/adminData';

export default function AuditLogPage() {
  const [searchOperator, setSearchOperator] = useState('');
  const [filterModule, setFilterModule] = useState('全部');
  const [filterRisk, setFilterRisk] = useState('全部');
  const [dateRange, setDateRange] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 10;

  const modules = ['全部', '用户管理', '角色管理', '交易决策', '日志审计', '系统配置', '菜单管理', '系统监控'];
  const riskLevels = ['全部', '高', '中', '低'];

  const filteredLogs = useMemo(() => {
    let result = auditLogs;
    if (searchOperator) result = result.filter(l => l.operator.includes(searchOperator));
    if (filterModule !== '全部') result = result.filter(l => l.module === filterModule);
    if (filterRisk !== '全部') {
      const levelMap: Record<string, string> = { '高': 'high', '中': 'medium', '低': 'low' };
      result = result.filter(l => l.riskLevel === levelMap[filterRisk]);
    }
    return result;
  }, [searchOperator, filterModule, filterRisk]);

  const totalPages = Math.ceil(filteredLogs.length / pageSize);
  const pagedLogs = filteredLogs.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const exportLogs = () => {
    const csv = [
      ['序号', '操作人', '操作人角色', '操作时间', 'IP地址', '操作模块', '操作类型', '操作内容', '操作结果', '风险等级'],
      ...filteredLogs.map((l, i) => [i + 1, l.operator, l.operatorRole, l.operationTime, l.ip, l.module, l.actionType, l.content, l.result === 'success' ? '成功' : '失败', l.riskLevel === 'high' ? '高' : l.riskLevel === 'medium' ? '中' : '低']),
    ].map(row => row.join(',')).join('\n');
    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `操作审计日志_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  };

  const getRiskStyle = (level: string) => {
    switch (level) {
      case 'high': return 'bg-[#F53F3F]/10 text-[#F53F3F]';
      case 'medium': return 'bg-[#FF7D00]/10 text-[#FF7D00]';
      default: return 'bg-[#00B4FF]/10 text-[#00B4FF]';
    }
  };

  return (
    <AdminLayout>
      <div className="space-y-4 text-[#1D2129]">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">操作审计日志</h1>
            <p className="text-sm text-[#86909C] mt-1">平台高风险操作记录审计，只读不可修改，满足国企审计要求</p>
          </div>
          <button onClick={exportLogs} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">
            <i className="ri-download-line" />
            导出
          </button>
        </div>

        {/* Filter */}
        <div className="bg-white rounded-lg p-4 border border-[#E5E6EB]">
          <div className="flex flex-wrap items-end gap-3">
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">操作人</label>
              <input type="text" value={searchOperator} onChange={e => setSearchOperator(e.target.value)} placeholder="请输入" className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[140px]" />
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">操作模块</label>
              <select value={filterModule} onChange={e => setFilterModule(e.target.value)} className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[140px] bg-white">
                {modules.map(m => <option key={m} value={m}>{m}</option>)}
              </select>
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">风险等级</label>
              <select value={filterRisk} onChange={e => setFilterRisk(e.target.value)} className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[100px] bg-white">
                {riskLevels.map(l => <option key={l} value={l}>{l}</option>)}
              </select>
            </div>
            <div className="flex flex-col gap-1">
              <label className="text-xs text-[#86909C]">操作时间</label>
              <input type="date" value={dateRange} onChange={e => setDateRange(e.target.value)} className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs focus:outline-none focus:border-[#165DFF] w-[140px]" />
            </div>
            <div className="flex gap-2 ml-auto">
              <button onClick={() => { setSearchOperator(''); setFilterModule('全部'); setFilterRisk('全部'); setDateRange(''); }} className="px-3 py-1.5 rounded-md border border-[#E5E6EB] text-xs text-[#4E5969] hover:bg-[#F7F8FA] transition-colors cursor-pointer whitespace-nowrap">重置</button>
              <button onClick={() => setCurrentPage(1)} className="px-3 py-1.5 rounded-md bg-[#165DFF] text-white text-xs hover:bg-[#165DFF]/80 transition-colors cursor-pointer whitespace-nowrap">查询</button>
            </div>
          </div>
        </div>

        {/* Table */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#F7F8FA] sticky top-0">
                <tr>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">序号</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">操作人</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">角色</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">操作时间</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">IP地址</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">操作模块</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">操作类型</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">操作内容</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">结果</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">风险等级</th>
                </tr>
              </thead>
              <tbody>
                {pagedLogs.map((log, idx) => (
                  <tr key={log.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : 'bg-white'}`}>
                    <td className="px-3 py-3 text-[#4E5969]">{(currentPage - 1) * pageSize + idx + 1}</td>
                    <td className="px-3 py-3 text-[#1D2129] font-medium">{log.operator}</td>
                    <td className="px-3 py-3 text-[#86909C]">{log.operatorRole}</td>
                    <td className="px-3 py-3 text-[#86909C]">{log.operationTime}</td>
                    <td className="px-3 py-3 text-[#86909C]">{log.ip}</td>
                    <td className="px-3 py-3 text-[#4E5969]">{log.module}</td>
                    <td className="px-3 py-3">
                      <span className="text-[10px] px-2 py-0.5 rounded-full bg-[#165DFF]/10 text-[#165DFF]">{log.actionType}</span>
                    </td>
                    <td className="px-3 py-3 text-[#4E5969] max-w-[200px] truncate" title={log.content}>{log.content}</td>
                    <td className="px-3 py-3">
                      <span className={`text-[10px] px-2 py-0.5 rounded-full ${log.result === 'success' ? 'bg-[#00C48C]/10 text-[#00C48C]' : 'bg-[#F53F3F]/10 text-[#F53F3F]'}`}>
                        {log.result === 'success' ? '成功' : '失败'}
                      </span>
                    </td>
                    <td className="px-3 py-3">
                      <span className={`text-[10px] px-2 py-0.5 rounded-full ${getRiskStyle(log.riskLevel)}`}>
                        {log.riskLevel === 'high' ? '高' : log.riskLevel === 'medium' ? '中' : '低'}
                      </span>
                    </td>
                  </tr>
                ))}
                {pagedLogs.length === 0 && <tr><td colSpan={10} className="px-3 py-8 text-center text-[#86909C]">暂无数据</td></tr>}
              </tbody>
            </table>
          </div>
          <div className="flex items-center justify-between px-3 py-3 border-t border-[#E5E6EB]">
            <span className="text-xs text-[#86909C]">共 {filteredLogs.length} 条，每页 {pageSize} 条</span>
            <div className="flex items-center gap-1">
              <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="px-2 py-1 rounded text-xs border border-[#E5E6EB] hover:bg-[#F7F8FA] disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer">上一页</button>
              {Array.from({ length: Math.min(5, totalPages) }, (_, i) => (
                <button key={i + 1} onClick={() => setCurrentPage(i + 1)} className={`w-7 h-7 rounded text-xs cursor-pointer ${currentPage === i + 1 ? 'bg-[#165DFF] text-white' : 'border border-[#E5E6EB] hover:bg-[#F7F8FA]'}`}>{i + 1}</button>
              ))}
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages || totalPages === 0} className="px-2 py-1 rounded text-xs border border-[#E5E6EB] hover:bg-[#F7F8FA] disabled:opacity-40 disabled:cursor-not-allowed cursor-pointer">下一页</button>
            </div>
          </div>
        </div>
      </div>
    </AdminLayout>
  );
}