import { useState, useRef } from 'react';
import AdminLayout from '../../components/AdminLayout';
import Toast from '@/components/Toast';

interface HolidayFile {
  id: string;
  name: string;
  year: string;
  uploadTime: string;
  status: 'active' | 'inactive';
  size: string;
}

const mockHolidayFiles: HolidayFile[] = [
  { id: '1', name: '2026年节假日安排.xlsx', year: '2026', uploadTime: '2026-01-15 09:30:00', status: 'active', size: '24.5 KB' },
  { id: '2', name: '2026年节假日安排.pdf', year: '2026', uploadTime: '2026-01-15 09:32:00', status: 'active', size: '156.2 KB' },
  { id: '3', name: '2025年节假日安排.xlsx', year: '2025', uploadTime: '2025-01-10 08:15:00', status: 'inactive', size: '22.1 KB' },
];

export default function HolidayConfigPage() {
  const [files, setFiles] = useState<HolidayFile[]>(mockHolidayFiles);
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [selectedYear, setSelectedYear] = useState('2026');

  const showToast = (message: string, type: 'success' | 'error') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const handleFileSelect = (file: File | null) => {
    if (!file) return;
    setUploading(true);
    setTimeout(() => {
      const newFile: HolidayFile = {
        id: String(Date.now()),
        name: file.name,
        year: selectedYear,
        uploadTime: new Date().toISOString().replace('T', ' ').slice(0, 19),
        status: 'active',
        size: `${(file.size / 1024).toFixed(1)} KB`,
      };
      setFiles(prev => [newFile, ...prev]);
      setUploading(false);
      showToast(`文件 "${file.name}" 上传成功`, 'success');
    }, 1500);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files[0];
    if (file) handleFileSelect(file);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    if (file) handleFileSelect(file);
    e.target.value = '';
  };

  const handleDelete = (id: string) => {
    setFiles(prev => prev.filter(f => f.id !== id));
    showToast('文件已删除', 'success');
  };

  const handleToggleStatus = (id: string) => {
    setFiles(prev => prev.map(f => f.id === id ? { ...f, status: f.status === 'active' ? 'inactive' : 'active' as 'active' | 'inactive' } : f));
    showToast('状态已更新', 'success');
  };

  const getFileIcon = (name: string) => {
    if (name.endsWith('.xlsx') || name.endsWith('.xls')) return 'ri-file-excel-line text-[#00C48C]';
    if (name.endsWith('.pdf')) return 'ri-file-pdf-line text-[#F53F3F]';
    if (name.endsWith('.csv')) return 'ri-file-text-line text-[#FF7D00]';
    return 'ri-file-line text-[#86909C]';
  };

  return (
    <AdminLayout>
      <div className="space-y-4 text-[#1D2129]">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-[#1D2129]">节假日配置</h1>
            <p className="text-sm text-[#86909C] mt-1">上传和管理年度节假日安排文件，用于交易负荷预测中的日期类型判断</p>
          </div>
        </div>

        {/* Upload Area */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] p-5">
          <div className="flex items-center gap-4 mb-4">
            <div className="flex items-center gap-2">
              <span className="text-xs text-[#1D2129] font-medium">年度选择</span>
              <div className="relative">
                <select
                  value={selectedYear}
                  onChange={e => setSelectedYear(e.target.value)}
                  className="text-xs px-3 py-1.5 pr-7 rounded border border-[#E5E6EB] bg-white text-[#1D2129] outline-none cursor-pointer appearance-none"
                >
                  <option value="2026">2026</option>
                  <option value="2025">2025</option>
                  <option value="2024">2024</option>
                  <option value="2027">2027</option>
                </select>
                <i className="ri-arrow-down-s-line absolute right-2 top-1/2 -translate-y-1/2 text-[#86909C] text-xs pointer-events-none" />
              </div>
            </div>
          </div>

          <div
            onClick={() => fileInputRef.current?.click()}
            onDragOver={e => { e.preventDefault(); setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={handleDrop}
            className={`border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-colors ${
              dragOver
                ? 'border-[#165DFF] bg-[#165DFF]/5'
                : 'border-[#E5E6EB] bg-[#F7F8FA] hover:border-[#C9CDD4] hover:bg-[#F2F3F5]'
            }`}
          >
            <div className="w-12 h-12 mx-auto mb-3 rounded-full bg-[#165DFF]/10 flex items-center justify-center">
              <i className="ri-upload-cloud-2-line text-[#165DFF] text-xl" />
            </div>
            <p className="text-sm text-[#1D2129] font-medium mb-1">
              {uploading ? '文件上传中...' : '点击或拖拽文件至此处上传'}
            </p>
            <p className="text-xs text-[#86909C]">支持格式：.xlsx, .xls, .csv, .pdf，单个文件不超过 5MB</p>
            <input
              ref={fileInputRef}
              type="file"
              accept=".xlsx,.xls,.csv,.pdf"
              onChange={handleInputChange}
              className="hidden"
            />
          </div>
        </div>

        {/* File List */}
        <div className="bg-white rounded-lg border border-[#E5E6EB] overflow-hidden">
          <div className="px-4 py-3 border-b border-[#E5E6EB] flex items-center justify-between">
            <div className="flex items-center gap-2">
              <div className="w-6 h-6 flex items-center justify-center">
                <i className="ri-folder-3-line text-[#165DFF] text-sm" />
              </div>
              <h3 className="text-sm font-bold text-[#1D2129]">节假日文件列表</h3>
              <span className="text-[10px] px-2 py-0.5 rounded-full bg-[#165DFF]/10 text-[#165DFF]">
                {files.length} 个文件
              </span>
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead className="bg-[#F7F8FA] sticky top-0">
                <tr>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">序号</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">文件名</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">年度</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">文件大小</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">上传时间</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">状态</th>
                  <th className="px-3 py-3 text-left font-medium text-[#1D2129] whitespace-nowrap">操作</th>
                </tr>
              </thead>
              <tbody>
                {files.map((file, idx) => (
                  <tr key={file.id} className={`border-t border-[#E5E6EB] hover:bg-[#F7F8FA] transition-colors ${idx % 2 === 1 ? 'bg-[#FAFBFC]' : 'bg-white'}`}>
                    <td className="px-3 py-3 text-[#4E5969]">{idx + 1}</td>
                    <td className="px-3 py-3">
                      <div className="flex items-center gap-2">
                        <i className={`${getFileIcon(file.name)} text-base`} />
                        <span className="text-[#1D2129] font-medium">{file.name}</span>
                      </div>
                    </td>
                    <td className="px-3 py-3 text-[#4E5969]">{file.year}</td>
                    <td className="px-3 py-3 text-[#4E5969]">{file.size}</td>
                    <td className="px-3 py-3 text-[#86909C]">{file.uploadTime}</td>
                    <td className="px-3 py-3">
                      <button
                        onClick={() => handleToggleStatus(file.id)}
                        className={`text-[10px] px-2 py-0.5 rounded-full transition-colors cursor-pointer whitespace-nowrap ${
                          file.status === 'active'
                            ? 'bg-[#00C48C]/10 text-[#00C48C]'
                            : 'bg-[#F7F8FA] text-[#86909C]'
                        }`}
                      >
                        {file.status === 'active' ? '生效中' : '已停用'}
                      </button>
                    </td>
                    <td className="px-3 py-3">
                      <div className="flex items-center gap-1">
                        <button
                          className="p-1 rounded hover:bg-[#165DFF]/10 text-[#86909C] hover:text-[#165DFF] cursor-pointer"
                          title="下载"
                        >
                          <i className="ri-download-line text-xs" />
                        </button>
                        <button
                          onClick={() => handleDelete(file.id)}
                          className="p-1 rounded hover:bg-[#F53F3F]/10 text-[#86909C] hover:text-[#F53F3F] cursor-pointer"
                          title="删除"
                        >
                          <i className="ri-delete-bin-line text-xs" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {files.length === 0 && (
            <div className="py-8 text-center">
              <div className="w-10 h-10 flex items-center justify-center mx-auto mb-2 rounded-full bg-[#F7F8FA]">
                <i className="ri-inbox-line text-[#86909C] text-lg" />
              </div>
              <p className="text-xs text-[#86909C]">暂无节假日配置文件</p>
            </div>
          )}
        </div>

        {/* Usage Note */}
        <div className="bg-[#165DFF]/5 rounded-lg border border-[#165DFF]/20 p-4">
          <div className="flex items-start gap-3">
            <i className="ri-information-line text-[#165DFF] text-base mt-0.5" />
            <div>
              <p className="text-xs text-[#1D2129] font-medium mb-1">使用说明</p>
              <p className="text-xs text-[#86909C] leading-relaxed">
                节假日配置文件用于用电量预测模块中的日期类型判断。上传的文件应包含年度法定节假日及调休安排信息。
                仅生效状态的文件会被系统用于日期类型判定。支持 Excel (.xlsx/.xls)、CSV (.csv) 和 PDF (.pdf) 格式。
              </p>
            </div>
          </div>
        </div>
      </div>

      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
    </AdminLayout>
  );
}