import { useMemo } from 'react';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend,
} from 'recharts';

interface Series {
  key: string;
  label: string;
  color: string;
  dash?: string;
  data: number[];
}

interface CurveChartProps {
  title: string;
  subtitle?: string;
  series: Series[];
  yAxisLabel?: string;
  onExport?: () => void;
}

export default function CurveChart({ title, subtitle, series, yAxisLabel, onExport }: CurveChartProps) {
  const labels = useMemo(() => {
    const arr: string[] = [];
    for (let i = 0; i < 48; i++) {
      const hour = Math.floor(i / 2);
      const minute = (i % 2) * 30;
      arr.push(`${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`);
    }
    return arr;
  }, []);

  const data = useMemo(() => {
    return labels.map((label, idx) => {
      const point: Record<string, number | string> = { time: label };
      series.forEach(s => {
        point[s.key] = s.data[idx] ?? 0;
      });
      return point;
    });
  }, [labels, series]);

  const yMax = useMemo(() => {
    let max = 0;
    series.forEach(s => {
      const m = Math.max(...s.data);
      if (m > max) max = m;
    });
    return Math.ceil(max / 5000) * 5000;
  }, [series]);

  return (
    <div className="bg-white rounded-lg border border-[#E5E6EB]">
      <div className="flex items-center justify-between px-4 pt-4 pb-2">
        <div className="flex items-center gap-2">
          <div className="w-6 h-6 flex items-center justify-center">
            <i className="ri-line-chart-line text-[#00C48C] text-sm" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-[#1D2129]">{title}</h3>
            {subtitle && <p className="text-[10px] text-[#64748B] mt-0.5">{subtitle}</p>}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={onExport}
            className="w-7 h-7 flex items-center justify-center rounded hover:bg-[#F7F8FA] text-[#86909C] hover:text-[#1D2129] transition-colors cursor-pointer"
          >
            <i className="ri-download-line text-sm" />
          </button>
        </div>
      </div>

      <ResponsiveContainer width="100%" height={280}>
        <LineChart data={data} margin={{ top: 5, right: 20, left: 10, bottom: 30 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#F2F3F5" />
          <XAxis
            dataKey="time"
            tick={{ fontSize: 9, fill: '#64748B' }}
            interval={2}
            angle={0}
            height={30}
          />
          <YAxis
            tick={{ fontSize: 9, fill: '#64748B' }}
            domain={[0, yMax]}
            tickCount={6}
            label={
              yAxisLabel
                ? { value: yAxisLabel, angle: -90, position: 'insideLeft', style: { fontSize: 10, fill: '#64748B' } }
                : undefined
            }
          />
          <Tooltip
            contentStyle={{ fontSize: 11, borderRadius: 6, backgroundColor: '#fff', border: '1px solid #E5E6EB', color: '#1D2129' }}
            labelStyle={{ fontSize: 10, color: '#94A3B8' }}
          />
          <Legend
            wrapperStyle={{ fontSize: 11, paddingTop: 10, color: '#94A3B8' }}
            iconType="line"
          />
          {series.map(s => (
            <Line
              key={s.key}
              type="monotone"
              dataKey={s.key}
              stroke={s.color}
              strokeWidth={s.key === 'prediction' ? 2 : 1.5}
              strokeDasharray={s.dash || undefined}
              dot={false}
              name={s.label}
              connectNulls
            />
          ))}
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}